INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36298, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「自然が豊か」の主語を示す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「自然を豊か」は文型が成り立たない。「豊かだ」は主語を取る形容動詞。"}, {"text": "へ", "is_correct": false, "explanation": "「自然へ豊か」は意味が通らない。方向の「へ」は豊かさの主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「自然から豊か」は不自然で、起点の「から」は形容動詞の主語には入らない。"}], "correct_answer": "が", "explanations": {"が": "「自然が豊か」の主語を示す「が」が入る。", "を": "「自然を豊か」は文型が成り立たない。「豊かだ」は主語を取る形容動詞。", "へ": "「自然へ豊か」は意味が通らない。方向の「へ」は豊かさの主語にならない。", "から": "「自然から豊か」は不自然で、起点の「から」は形容動詞の主語には入らない。"}, "error_tags": {"を": "目的語（対象）", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36298, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36298, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "山や川、空など、人の手が加わっていないもの。", "primary_collocate": null, "pronunciation": "しぜん", "ipa": "ɕizeɴ", "syllable_count": 3, "sentences": [{"text": "休みの日は、山や川など自然の中で過ごすのが好きだ。", "target_word": "自然", "complexity_tier": "T3", "furigana": "やすみのひは、やまやかわなどしぜんのなかですごすのがすきだ。", "sentence_source": "generated"}, {"text": "この町は自然が豊かで、空気がきれいだ。", "target_word": "自然", "complexity_tier": "T3", "furigana": "このまちはしぜんがゆたかで、くうきがきれいだ。", "sentence_source": "generated"}, {"text": "都会に住んでいると、自然に触れる機会が少ない。", "target_word": "自然", "complexity_tier": "T3", "furigana": "とかいにすんでいると、しぜんにふれるきかいがすくない。", "sentence_source": "generated"}, {"text": "人間は自然を守らなければならない。", "target_word": "自然", "complexity_tier": "T3", "furigana": "にんげんはしぜんをまもらなければならない。", "sentence_source": "generated"}, {"text": "自然の中を歩くと、心が落ち着く。", "target_word": "自然", "complexity_tier": "T3", "furigana": "しぜんのなかをあるくと、こころがおちつく。", "sentence_source": "generated"}, {"text": "森を切りすぎると、自然が壊れてしまう。", "target_word": "自然", "complexity_tier": "T3", "furigana": "もりをきりすぎると、しぜんがこわれてしまう。", "sentence_source": "generated"}, {"text": "公園には自然を学べる展示館がある。", "target_word": "自然", "complexity_tier": "T3", "furigana": "こうえんにはしぜんをまなべるてんじかんがある。", "sentence_source": "generated"}, {"text": "祖父は自然に囲まれた村で育った。", "target_word": "自然", "complexity_tier": "T3", "furigana": "そふはしぜんにかこまれたむらでそだった。", "sentence_source": "generated"}, {"text": "台風や地震は、自然の大きな力を感じさせる。", "target_word": "自然", "complexity_tier": "T3", "furigana": "たいふうやじしんは、しぜんのおおきなちからをかんじさせる。", "sentence_source": "generated"}, {"text": "写真家の彼は、四季の自然を撮り続けている。", "target_word": "自然", "complexity_tier": "T3", "furigana": "しゃしんかのかれは、しきのしぜんをとりつづけている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然", "label": "基本形"}, {"form": "自然の", "label": "連体形"}, {"form": "自然を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "山・川・空・森など人の手が加わっていない自然界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f6c10e-59f5-434b-8d2f-b32eae92b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36298, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然", "is_correct": true, "explanation": "「山や川など」を受けて、人の手が加わらない自然界を指す語が入る。"}, {"text": "会議", "is_correct": false, "explanation": "「会議の中で過ごす」は場所として不自然で、「山や川など」の並びにも合わない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布の中で過ごす」は場所として成り立たず、「山や川など」の並びにも合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気の中で過ごす」は場所として成り立たず、「山や川など」の並びにも合わない。眠気は体の感覚で、場所にならない。"}], "explanations": {"自然": "「山や川など」を受けて、人の手が加わらない自然界を指す語が入る。", "会議": "「会議の中で過ごす」は場所として不自然で、「山や川など」の並びにも合わない。", "財布": "「財布の中で過ごす」は場所として成り立たず、「山や川など」の並びにも合わない。", "眠気": "「眠気の中で過ごす」は場所として成り立たず、「山や川など」の並びにも合わない。眠気は体の感覚で、場所にならない。"}, "sentence_index": 0, "correct_answer": "自然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の自然は、一日中雨だ。", "explanation": "ここは〈天気〉の意味。天気の移り変わりは天候と言い、人の手が加わらない山や川を指す〈自然〉とは合わない。"}, {"text": "店内の自然を整えて、お客さんが快適に過ごせるようにしている。", "explanation": "ここは〈環境〉の意味。店内の居心地を整えるのは〈環境〉で、人の手が加わらない山や川を指す〈自然〉とは合わない。"}, {"text": "この箱の自然は十個だ。", "explanation": "ここは〈数〉の意味。箱の中の個数は〈数〉で、山や川などを指す〈自然〉には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36298, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然", "is_correct": true, "explanation": "「自然を学べる」は、自然界について学ぶ展示館という意味になる。"}, {"text": "相手", "is_correct": false, "explanation": "「相手を学べる」は意味が通らない。相手は人を指し、学ぶ対象にならない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気を学べる」は成り立たない。眠気は体の感覚で、学問の対象にならない。"}, {"text": "忘れ物", "is_correct": false, "explanation": "「忘れ物を学べる」は不自然。忘れ物は物を指し、学びの対象ではない。"}], "explanations": {"自然": "「自然を学べる」は、自然界について学ぶ展示館という意味になる。", "相手": "「相手を学べる」は意味が通らない。相手は人を指し、学ぶ対象にならない。", "眠気": "「眠気を学べる」は成り立たない。眠気は体の感覚で、学問の対象にならない。", "忘れ物": "「忘れ物を学べる」は不自然。忘れ物は物を指し、学びの対象ではない。"}, "sentence_index": 6, "correct_answer": "自然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の自然は、三十歳です。", "explanation": "ここは〈年齢〉の意味。年齢は年数で表すもので、山や川などを指す〈自然〉とは合わない。"}, {"text": "この店の自然は、とても新鮮だ。", "explanation": "ここは〈食材〉の意味。新鮮さは食べ物の状態を表し、人の手が加わらない山や川を指す〈自然〉には合わない。"}, {"text": "この品の自然は千円です。", "explanation": "ここは〈値段〉の意味。値段は品物の代金を表すもので、人の手が加わらない山や川を指す〈自然〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36298, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "温泉宿は、自然で囲まれて静かだ。", "corrected_sentence": "温泉宿は、自然に囲まれて静かだ。", "error_description": "「自然に囲まれる」の「に」が正しく、「で」は誤り。囲む対象を示す格助詞の選び方を誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36298, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "息子は自然を好きで、毎週末キャンプに行く。", "corrected_sentence": "息子は自然が好きで、毎週末キャンプに行く。", "error_description": "「〜が好きだ」の形で、「自然」には「が」を付ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1aff041-8e12-4be2-95f9-036736301c3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36300, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "部屋に流れてくる、と到達点を示し文に合う。"}, {"text": "が", "is_correct": false, "explanation": "部屋が主語になり、風が流れてきた文の形にならない。"}, {"text": "と", "is_correct": false, "explanation": "部屋と並ぶ意味になり、流れる先を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「部屋の流れてきた」は名詞修飾の形にならず成り立たない。"}], "correct_answer": "に", "explanations": {"に": "部屋に流れてくる、と到達点を示し文に合う。", "が": "部屋が主語になり、風が流れてきた文の形にならない。", "と": "部屋と並ぶ意味になり、流れる先を示せない。", "の": "「部屋の流れてきた」は名詞修飾の形にならず成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "の": "修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "止まる", "is_correct": true, "explanation": "水の動きが止まる意味で、流れるの対義語。"}, {"text": "眠る", "is_correct": false, "explanation": "水や空気の動きとは無関係で、対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移す動作で、流れることの反対語ではない。"}, {"text": "咲く", "is_correct": false, "explanation": "花が開く意味で、動きの反対とは言えない。"}], "correct_answer": "止まる", "explanations": {"止まる": "水の動きが止まる意味で、流れるの対義語。", "眠る": "水や空気の動きとは無関係で、対義語ではない。", "運ぶ": "物を移す動作で、流れることの反対語ではない。", "咲く": "花が開く意味で、動きの反対とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36300, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "淀む", "is_correct": true, "explanation": "水や空気が止まって滞る意味で、流れるの対義語。"}, {"text": "跳ねる", "is_correct": false, "explanation": "勢いよく飛ぶ動作で、動きの反対語ではない。"}, {"text": "光る", "is_correct": false, "explanation": "光を放つ意味で、動きの対義語ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を出す動作で、流れの対義語ではない。"}], "correct_answer": "淀む", "explanations": {"淀む": "水や空気が止まって滞る意味で、流れるの対義語。", "跳ねる": "勢いよく飛ぶ動作で、動きの反対語ではない。", "光る": "光を放つ意味で、動きの対義語ではない。", "叫ぶ": "声を出す動作で、流れの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36300, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水や空気が、止まらないで動いていくこと。", "primary_collocate": null, "pronunciation": "ながれる", "ipa": "nagaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "川の水は、海に向かってゆっくり流れている。", "target_word": "流れている", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は、海[うみ]に向[む]かってゆっくり流[なが]れている。", "sentence_source": "generated"}, {"text": "窓を開けると、涼しい風が部屋に流れてきた。", "target_word": "流れて", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、涼[すず]しい風[かぜ]が部屋[へや]に流[なが]れてきた。", "sentence_source": "generated"}, {"text": "坂道の上から下へ、雨水が流れていた。", "target_word": "流れて", "complexity_tier": "T3", "furigana": "坂道[さかみち]の上[うえ]から下[した]へ、雨水[あまみず]が流[なが]れていた。", "sentence_source": "generated"}, {"text": "水道の蛇口を開けると、冷たい水が流れる。", "target_word": "流れる", "complexity_tier": "T3", "furigana": "水道[すいどう]の蛇口[じゃぐち]を開[あ]けると、冷[つめ]たい水[みず]が流[なが]れる。", "sentence_source": "generated"}, {"text": "この川は町の真ん中を流れている。", "target_word": "流れている", "complexity_tier": "T3", "furigana": "この川[かわ]は町[まち]の真ん中[まんなか]を流[なが]れている。", "sentence_source": "generated"}, {"text": "換気扇をつけたので、新しい空気が部屋の中を流れるようになった。", "target_word": "流れる", "complexity_tier": "T3", "furigana": "換気扇[かんきせん]をつけたので、新[あたら]しい空気[くうき]が部屋[へや]の中[なか]を流[なが]れるようになった。", "sentence_source": "generated"}, {"text": "山の水は谷へ流れて、やがて大きな川になる。", "target_word": "流れて", "complexity_tier": "T3", "furigana": "山[やま]の水[みず]は谷[たに]へ流[なが]れて、やがて大[おお]きな川[かわ]になる。", "sentence_source": "generated"}, {"text": "流れる水の音を聞くと、心が落ち着く。", "target_word": "流れる", "complexity_tier": "T3", "furigana": "流[なが]れる水[みず]の音[おと]を聞[き]くと、心[こころ]が落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "排水口がつまっていて、水がうまく流れない。", "target_word": "流れない", "complexity_tier": "T3", "furigana": "排水口[はいすいこう]がつまっていて、水[みず]がうまく流[なが]れない。", "sentence_source": "generated"}, {"text": "夏の夜、エアコンの冷たい空気が床の上を流れていく。", "target_word": "流れていく", "complexity_tier": "T3", "furigana": "夏[なつ]の夜[よる]、エアコンの冷[つめ]たい空気[くうき]が床[ゆか]の上[うえ]を流[なが]れていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流れる", "label": "辞書形"}, {"form": "流れない", "label": "ない形"}, {"form": "流れます", "label": "ます形"}, {"form": "流れて", "label": "て形"}, {"form": "流れた", "label": "た形"}, {"form": "流れれば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "water or air moving along without stopping (river, tap water, breeze)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36300, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流れている", "is_correct": true, "explanation": "水が止まらず海へ動き続けている様子を表し、文に合う。"}, {"text": "凍っている", "is_correct": false, "explanation": "水が固まる意味になり、海へ向かってゆっくり進む文と合わない。"}, {"text": "乾いている", "is_correct": false, "explanation": "水が乾く意味になり、海へ向かう動きと合わない。"}, {"text": "眠っている", "is_correct": false, "explanation": "水は眠らないので、この文脈では成り立たない。"}], "explanations": {"流れている": "水が止まらず海へ動き続けている様子を表し、文に合う。", "凍っている": "水が固まる意味になり、海へ向かってゆっくり進む文と合わない。", "乾いている": "水が乾く意味になり、海へ向かう動きと合わない。", "眠っている": "水は眠らないので、この文脈では成り立たない。"}, "sentence_index": 0, "correct_answer": "流れている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールが坂道を流れていった。", "explanation": "ここは〈転がる〉の意味。ボールは転がるもので、水や空気のように流れるとは言わない。"}, {"text": "夜中に雷が流れた。", "explanation": "ここは〈鳴る〉の意味。雷は鳴るもので、流れるとは言わない。"}, {"text": "子どもが階段から流れた。", "explanation": "ここは〈落ちる〉の意味。人は流れるとは言わず、この使い方は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36300, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流れて", "is_correct": true, "explanation": "「谷へ流れて、やがて」と続く、て形で文に合う。"}, {"text": "凍って", "is_correct": false, "explanation": "水が固まる意味になり、谷へ流れていく文と合わない。"}, {"text": "叫んで", "is_correct": false, "explanation": "水は叫ばないので、この文脈では成り立たない。"}, {"text": "光って", "is_correct": false, "explanation": "水が光る意味になり、谷へ向かう文と合わない。"}], "explanations": {"流れて": "「谷へ流れて、やがて」と続く、て形で文に合う。", "凍って": "水が固まる意味になり、谷へ流れていく文と合わない。", "叫んで": "水は叫ばないので、この文脈では成り立たない。", "光って": "水が光る意味になり、谷へ向かう文と合わない。"}, "sentence_index": 6, "correct_answer": "流れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の桜が一斉に流れた。", "explanation": "ここは〈咲く〉の意味。花が開く様子は流れるとは言わない。"}, {"text": "パンがこんがり流れた。", "explanation": "ここは〈焼ける〉の意味。パンは焼けるもので、流れるとは言わない。"}, {"text": "ドアが静かに流れた。", "explanation": "ここは〈閉まる〉の意味。ドアは閉まるもので、流れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36300, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方になると、窓から涼しい風が流れてきる。", "corrected_sentence": "夕方になると、窓から涼しい風が流れてくる。", "error_description": "正しくは「流れてくる」。「てきる」は「くる」を「きる」に誤ったもので、動詞として成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "流れて", "is_correct": true, "explanation": "「流れてきた」の一部で、て形。文中の形に合う。"}, {"text": "流れない", "is_correct": false, "explanation": "ない形。「止まらない」の否定になり、文中の形ではない。"}, {"text": "流れた", "is_correct": false, "explanation": "た形。文中では「てきた」と続くため、て形が必要。"}, {"text": "流れます", "is_correct": false, "explanation": "ます形。「てきた」と続けられない。"}], "correct_form": "流れて", "base_form": "流れる", "form_label": "て形", "sentence_index": 1, "explanations": {"流れて": "「流れてきた」の一部で、て形。文中の形に合う。", "流れない": "ない形。「止まらない」の否定になり、文中の形ではない。", "流れた": "た形。文中では「てきた」と続くため、て形が必要。", "流れます": "ます形。「てきた」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36300, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谷の水が、やがて川で流れ込む。", "corrected_sentence": "谷の水が、やがて川に流れ込む。", "error_description": "「流れ込む」は行き先を「に」で示す。「で」は場所を示すので、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "流れる", "is_correct": true, "explanation": "辞書形。「流れる水の音」と名詞を修飾する形で文に合う。"}, {"text": "流れれば", "is_correct": false, "explanation": "ば形。条件を表し、名詞を修飾する形ではない。"}, {"text": "流れます", "is_correct": false, "explanation": "ます形。名詞「音」を修飾できず、文の形に合わない。"}, {"text": "流れなかった", "is_correct": false, "explanation": "ない形の過去。否定の過去で、文中の肯定の形と合わない。"}], "correct_form": "流れる", "base_form": "流れる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"流れる": "辞書形。「流れる水の音」と名詞を修飾する形で文に合う。", "流れれば": "ば形。条件を表し、名詞を修飾する形ではない。", "流れます": "ます形。名詞「音」を修飾できず、文の形に合わない。", "流れなかった": "ない形の過去。否定の過去で、文中の肯定の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36301, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "頬を流れると経路を示し、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "頬が主語になり、涙が流れる文の形にならない。"}, {"text": "と", "is_correct": false, "explanation": "頬と並ぶ意味になり、流れる経路を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「頬の流れて」は名詞修飾にならず、成り立たない。"}], "correct_answer": "を", "explanations": {"を": "頬を流れると経路を示し、文に合う。", "が": "頬が主語になり、涙が流れる文の形にならない。", "と": "頬と並ぶ意味になり、流れる経路を示せない。", "の": "「頬の流れて」は名詞修飾にならず、成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "の": "修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "止まる", "is_correct": true, "explanation": "時間の流れが止まる意味で、流れるの対義語にあたる。"}, {"text": "咲く", "is_correct": false, "explanation": "花が開く意味で、時間の流れの反対語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "体の状態を表す語で、流れの対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移す動作で、流れの反対語ではない。"}], "correct_answer": "止まる", "explanations": {"止まる": "時間の流れが止まる意味で、流れるの対義語にあたる。", "咲く": "花が開く意味で、時間の流れの反対語ではない。", "眠る": "体の状態を表す語で、流れの対義語ではない。", "運ぶ": "物を移す動作で、流れの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36301, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "淀む", "is_correct": true, "explanation": "空気が止まって滞る意味で、流れるの対義語。"}, {"text": "跳ねる", "is_correct": false, "explanation": "勢いよく飛ぶ動作で、動きの反対語ではない。"}, {"text": "光る", "is_correct": false, "explanation": "光を放つ意味で、動きの対義語ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を出す動作で、流れの対義語ではない。"}], "correct_answer": "淀む", "explanations": {"淀む": "空気が止まって滞る意味で、流れるの対義語。", "跳ねる": "勢いよく飛ぶ動作で、動きの反対語ではない。", "光る": "光を放つ意味で、動きの対義語ではない。", "叫ぶ": "声を出す動作で、流れの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36301, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体や気体などが、高いところから低いところへ、または一方向へ、とどまることなく移動する。また、時間や人の気持ちなどが、自然に過ぎていく。", "primary_collocate": null, "pronunciation": "ながれる", "ipa": "nagaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "山から流れる水を集めて、町の人は毎日使っている。", "target_word": "流れる", "complexity_tier": "T3", "furigana": "山[やま]から流[なが]れる水[みず]を集[あつ]めて、町[まち]の人[ひと]は毎日[まいにち]使[つか]っている。", "sentence_source": "generated"}, {"text": "涙が頬を流れて、止まらなかった。", "target_word": "流れて", "complexity_tier": "T3", "furigana": "涙[なみだ]が頬[ほお]を流[なが]れて、止[と]まらなかった。", "sentence_source": "generated"}, {"text": "あの町を離れてから、もう十年の月日が流れた。", "target_word": "流れた", "complexity_tier": "T3", "furigana": "あの町[まち]を離[はな]れてから、もう十年[じゅうねん]の月日[つきひ]が流[なが]れた。", "sentence_source": "generated"}, {"text": "休日は、ゆっくり時間が流れるように感じる。", "target_word": "流れる", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]は、ゆっくり時間[じかん]が流[なが]れるように感[かん]じる。", "sentence_source": "generated"}, {"text": "血が体の中を流れているのを、手首で感じた。", "target_word": "流れている", "complexity_tier": "T3", "furigana": "血[ち]が体[からだ]の中[なか]を流[なが]れているのを、手首[てくび]で感[かん]じた。", "sentence_source": "generated"}, {"text": "二人が出会ってから、五年の時が流れた。", "target_word": "流れた", "complexity_tier": "T3", "furigana": "二人[ふたり]が出会[であ]ってから、五年[ごねん]の時[とき]が流[なが]れた。", "sentence_source": "generated"}, {"text": "雨水は低いところに流れて、池にたまる。", "target_word": "流れて", "complexity_tier": "T3", "furigana": "雨水[あまみず]は低[ひく]いところに流[なが]れて、池[いけ]にたまる。", "sentence_source": "generated"}, {"text": "汗が顔を流れるほど、暑い日だった。", "target_word": "流れる", "complexity_tier": "T3", "furigana": "汗[あせ]が顔[かお]を流[なが]れるほど、暑[あつ]い日[ひ]だった。", "sentence_source": "generated"}, {"text": "時が流れるにつれて、悲しみも少しずつ薄くなった。", "target_word": "流れる", "complexity_tier": "T3", "furigana": "時[とき]が流[なが]れるにつれて、悲[かな]しみも少[すこ]しずつ薄[うす]くなった。", "sentence_source": "generated"}, {"text": "部屋には、のんびりした空気が流れていた。", "target_word": "流れていた", "complexity_tier": "T3", "furigana": "部屋[へや]には、のんびりした空気[くうき]が流[なが]れていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流れる", "label": "辞書形"}, {"form": "流れない", "label": "ない形"}, {"form": "流れます", "label": "ます形"}, {"form": "流れて", "label": "て形"}, {"form": "流れた", "label": "た形"}, {"form": "流れれば", "label": "ば形"}], "register": "neutral", "sense_fingerprint": "liquid or gas moving in one direction; also time or mood passing naturally", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36301, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流れる", "is_correct": true, "explanation": "山から流れてくる水を表し、文に合う。"}, {"text": "凍る", "is_correct": false, "explanation": "水が固まる意味で、集めて使う文脈に合わない。"}, {"text": "乾く", "is_correct": false, "explanation": "水が乾く意味で、集めて使う文脈に合わない。"}, {"text": "沈む", "is_correct": false, "explanation": "水が下に落ちる意味で、集めて使う文脈に合わない。"}], "explanations": {"流れる": "山から流れてくる水を表し、文に合う。", "凍る": "水が固まる意味で、集めて使う文脈に合わない。", "乾く": "水が乾く意味で、集めて使う文脈に合わない。", "沈む": "水が下に落ちる意味で、集めて使う文脈に合わない。"}, "sentence_index": 0, "correct_answer": "流れる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スケートで氷の上を流れた。", "explanation": "ここは〈滑る〉の意味。人が氷の上を進むときは滑ると言い、流れるとは言わない。"}, {"text": "コップが流れた。", "explanation": "ここは〈割れる〉の意味。コップは割れるもので、流れるとは言わない。"}, {"text": "ボールが床で流れた。", "explanation": "ここは〈跳ねる〉の意味。ボールは跳ねるもので、流れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36301, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流れて", "is_correct": true, "explanation": "「低いところに流れて、池にたまる」と続き、文に合う。"}, {"text": "凍って", "is_correct": false, "explanation": "水が固まる意味になり、低いところへ流れて池になる文と合わない。"}, {"text": "叫んで", "is_correct": false, "explanation": "雨水は叫ばないので、この文脈では成り立たない。"}, {"text": "光って", "is_correct": false, "explanation": "水が光る意味で、池にたまる文と合わない。"}], "explanations": {"流れて": "「低いところに流れて、池にたまる」と続き、文に合う。", "凍って": "水が固まる意味になり、低いところへ流れて池になる文と合わない。", "叫んで": "雨水は叫ばないので、この文脈では成り立たない。", "光って": "水が光る意味で、池にたまる文と合わない。"}, "sentence_index": 6, "correct_answer": "流れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パンがこんがり流れた。", "explanation": "ここは〈焼ける〉の意味。パンは焼けるもので、流れるとは言わない。"}, {"text": "庭の桜が一斉に流れた。", "explanation": "ここは〈咲く〉の意味。花が開く様子は流れるとは言わない。"}, {"text": "犬が大きく流れた。", "explanation": "ここは〈吠える〉の意味。犬は吠えるもので、流れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36301, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汗が額を流れるて、目にしみた。", "corrected_sentence": "汗が額を流れて、目にしみた。", "error_description": "「流れて」が正しいて形。「流れるて」は辞書形に「て」を続けた誤りで、成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "流れて", "is_correct": true, "explanation": "「流れて、止まらなかった」のて形で、文に合う。"}, {"text": "流れない", "is_correct": false, "explanation": "ない形。否定になり、文の流れと合わない。"}, {"text": "流れた", "is_correct": false, "explanation": "た形。「流れて、止まらなかった」と続けるには、て形が必要。"}, {"text": "流れます", "is_correct": false, "explanation": "ます形。「止まらなかった」と続けられない。"}], "correct_form": "流れて", "base_form": "流れる", "form_label": "て形", "sentence_index": 1, "explanations": {"流れて": "「流れて、止まらなかった」のて形で、文に合う。", "流れない": "ない形。否定になり、文の流れと合わない。", "流れた": "た形。「流れて、止まらなかった」と続けるには、て形が必要。", "流れます": "ます形。「止まらなかった」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36301, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "霧が谷間が流れていく。", "corrected_sentence": "霧が谷間を流れていく。", "error_description": "「谷間を流れていく」の「を」が正しい。「が」にすると谷間が主語になり、霧が動く意味にならない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "流れる", "is_correct": true, "explanation": "辞書形。「流れるほど」と続く形で、文に合う。"}, {"text": "流れれば", "is_correct": false, "explanation": "ば形。条件を表し、「ほど」に続く形ではない。"}, {"text": "流れます", "is_correct": false, "explanation": "ます形。「ほど」に続けられず、文の形に合わない。"}, {"text": "流れなかった", "is_correct": false, "explanation": "ない形の過去。否定の過去で、文の意味と合わない。"}], "correct_form": "流れる", "base_form": "流れる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"流れる": "辞書形。「流れるほど」と続く形で、文に合う。", "流れれば": "ば形。条件を表し、「ほど」に続く形ではない。", "流れます": "ます形。「ほど」に続けられず、文の形に合わない。", "流れなかった": "ない形の過去。否定の過去で、文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36302, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "頑固", "is_correct": true, "explanation": "かたくなに考えを変えない意味で、柔軟の対義語。"}, {"text": "静か", "is_correct": false, "explanation": "物音が少ない状態を表し、柔軟の反対語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "態度の細やかさを表し、柔軟の反対語ではない。"}, {"text": "大胆", "is_correct": false, "explanation": "思い切りのよさを表し、柔軟の反対語ではない。"}], "correct_answer": "頑固", "explanations": {"頑固": "かたくなに考えを変えない意味で、柔軟の対義語。", "静か": "物音が少ない状態を表し、柔軟の反対語ではない。", "丁寧": "態度の細やかさを表し、柔軟の反対語ではない。", "大胆": "思い切りのよさを表し、柔軟の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36302, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "頑固", "is_correct": true, "explanation": "考えを変えないかたくなさを表し、柔軟の対義語。"}, {"text": "陽気", "is_correct": false, "explanation": "明るい性格を表し、柔軟の反対語ではない。"}, {"text": "几帳面", "is_correct": false, "explanation": "きちんとした性格を表し、反対語ではない。"}, {"text": "謙虚", "is_correct": false, "explanation": "控えめな態度を表し、反対語ではない。"}], "correct_answer": "頑固", "explanations": {"頑固": "考えを変えないかたくなさを表し、柔軟の対義語。", "陽気": "明るい性格を表し、柔軟の反対語ではない。", "几帳面": "きちんとした性格を表し、反対語ではない。", "謙虚": "控えめな態度を表し、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36302, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "かたくなさがないこと。場面にあわせて考えを変えられること。", "primary_collocate": null, "pronunciation": "じゅうなん", "ipa": "dʑɯːnaɴ", "syllable_count": 4, "sentences": [{"text": "彼は柔軟な考え方をするので、新しい意見も受け入れてくれる。", "target_word": "柔軟な", "complexity_tier": "T3", "furigana": "彼[かれ]は柔軟[じゅうなん]な考[かんが]え方[かた]をするので、新[あたら]しい意見[いけん]も受[う]け入[い]れてくれる。", "sentence_source": "generated"}, {"text": "予定が変わったときは、柔軟に対応してほしい。", "target_word": "柔軟に", "complexity_tier": "T3", "furigana": "予定[よてい]が変[か]わったときは、柔軟[じゅうなん]に対応[たいおう]してほしい。", "sentence_source": "generated"}, {"text": "先生は生徒の意見を聞いて、柔軟に計画を変えた。", "target_word": "柔軟に", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の意見[いけん]を聞[き]いて、柔軟[じゅうなん]に計画[けいかく]を変[か]えた。", "sentence_source": "generated"}, {"text": "この会社は働き方が柔軟で、家で仕事をすることもできる。", "target_word": "柔軟で", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は働[はたら]き方[かた]が柔軟[じゅうなん]で、家[いえ]で仕事[しごと]をすることもできる。", "sentence_source": "generated"}, {"text": "発想が柔軟な人は、失敗してもすぐ別の方法を探す。", "target_word": "柔軟な", "complexity_tier": "T3", "furigana": "発想[はっそう]が柔軟[じゅうなん]な人[ひと]は、失敗[しっぱい]してもすぐ別[べつ]の方法[ほうほう]を探[さが]す。", "sentence_source": "generated"}, {"text": "ルールを守ることは大切だが、ときには柔軟に考える必要がある。", "target_word": "柔軟に", "complexity_tier": "T3", "furigana": "ルールを守[まも]ることは大切[たいせつ]だが、ときには柔軟[じゅうなん]に考[かんが]える必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "母は私の話を聞いて、柔軟な態度で意見を変えてくれた。", "target_word": "柔軟な", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の話[はなし]を聞[き]いて、柔軟[じゅうなん]な態度[たいど]で意見[いけん]を変[か]えてくれた。", "sentence_source": "generated"}, {"text": "店長は客の要望に合わせて、柔軟なサービスを考えた。", "target_word": "柔軟な", "complexity_tier": "T3", "furigana": "店長[てんちょう]は客[きゃく]の要望[ようぼう]に合[あ]わせて、柔軟[じゅうなん]なサービスを考[かんが]えた。", "sentence_source": "generated"}, {"text": "彼女は柔軟だから、急な変更にも困らない。", "target_word": "柔軟だ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は柔軟[じゅうなん]だから、急[きゅう]な変更[へんこう]にも困[こま]らない。", "sentence_source": "generated"}, {"text": "年を取っても柔軟な心を持ち続けたい。", "target_word": "柔軟な", "complexity_tier": "T3", "furigana": "年[とし]を取[と]っても柔軟[じゅうなん]な心[こころ]を持[も]ち続[つづ]けたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "柔軟だ", "label": "終止形"}, {"form": "柔軟な", "label": "連体形"}, {"form": "柔軟に", "label": "連用形"}, {"form": "柔軟で", "label": "で形"}, {"form": "柔軟だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "not stubborn; able to change one''s thinking to suit the situation", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36302, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柔軟な", "is_correct": true, "explanation": "「柔軟な考え方」と名詞を修飾する形で、文に合う。"}, {"text": "柔軟だ", "is_correct": false, "explanation": "終止形で、名詞「考え方」の前に置けない。"}, {"text": "柔軟で", "is_correct": false, "explanation": "て形で、名詞の前に続けると文が成り立たない。"}, {"text": "柔軟に", "is_correct": false, "explanation": "連用形で、名詞「考え方」を修飾できない。"}], "explanations": {"柔軟な": "「柔軟な考え方」と名詞を修飾する形で、文に合う。", "柔軟だ": "終止形で、名詞「考え方」の前に置けない。", "柔軟で": "て形で、名詞の前に続けると文が成り立たない。", "柔軟に": "連用形で、名詞「考え方」を修飾できない。"}, "sentence_index": 0, "correct_answer": "柔軟な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパンは柔軟で、ふわふわしている。", "explanation": "ここは〈柔らかい〉の意味。パンは柔らかいと言い、柔軟とは言わない。"}, {"text": "昨日の海は柔軟だった。", "explanation": "ここは〈穏やか〉の意味。海は柔軟にはならず、この言い方は不自然。"}, {"text": "今日の空模様は柔軟で、急に雨が降った。", "explanation": "ここは〈変わりやすい〉の意味。空模様は変わりやすいと言い、考えや行動を柔軟に変えるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36302, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柔軟な", "is_correct": true, "explanation": "「柔軟な態度」と名詞を修飾する形で、文に合う。"}, {"text": "柔軟だが", "is_correct": false, "explanation": "逆接の形で、名詞「態度」の前に続かず文が成り立たない。"}, {"text": "柔軟だろう", "is_correct": false, "explanation": "推量形で、名詞の前には入らない。"}, {"text": "柔軟の", "is_correct": false, "explanation": "「の」は形状詞の後に続かず、文が成り立たない。"}], "explanations": {"柔軟な": "「柔軟な態度」と名詞を修飾する形で、文に合う。", "柔軟だが": "逆接の形で、名詞「態度」の前に続かず文が成り立たない。", "柔軟だろう": "推量形で、名詞の前には入らない。", "柔軟の": "「の」は形状詞の後に続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "柔軟な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝は柔軟な部屋で過ごしたい。", "explanation": "ここは〈明るい〉の意味。部屋は柔軟にはならず、この言い方は不自然。"}, {"text": "図書館は柔軟だった。", "explanation": "ここは〈静か〉の意味。図書館は柔軟にはならない。"}, {"text": "今朝は柔軟だった。", "explanation": "ここは〈寒い〉の意味。天気や気温を柔軟とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36302, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の進め方は柔軟だ変えてよい。", "corrected_sentence": "会議の進め方は柔軟に変えてよい。", "error_description": "「柔軟に」の連用形が必要。「柔軟だ」は終止形で、動詞の前に置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "柔軟に", "is_correct": true, "explanation": "連用形で、「対応してほしい」を修飾する形。"}, {"text": "柔軟だ", "is_correct": false, "explanation": "終止形で、「対応」の前に置けない。"}, {"text": "柔軟で", "is_correct": false, "explanation": "て形で、「対応してほしい」と続かない。"}, {"text": "柔軟な", "is_correct": false, "explanation": "連体形で、動詞「対応してほしい」を修飾できない。"}], "correct_form": "柔軟に", "base_form": "柔軟", "form_label": "連用形", "sentence_index": 1, "explanations": {"柔軟に": "連用形で、「対応してほしい」を修飾する形。", "柔軟だ": "終止形で、「対応」の前に置けない。", "柔軟で": "て形で、「対応してほしい」と続かない。", "柔軟な": "連体形で、動詞「対応してほしい」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36302, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は柔軟を態度で意見を受け入れる。", "corrected_sentence": "彼女は柔軟な態度で意見を受け入れる。", "error_description": "形状詞の「柔軟」は「を」ではなく、名詞を修飾する「な」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "柔軟な", "is_correct": true, "explanation": "連体形で、名詞「サービス」を修飾する形。"}, {"text": "柔軟に", "is_correct": false, "explanation": "連用形で、名詞「サービス」を修飾できない。"}, {"text": "柔軟だが", "is_correct": false, "explanation": "逆接の形で、名詞「サービス」の前に続かず文が成り立たない。"}, {"text": "柔軟だろう", "is_correct": false, "explanation": "推量形で、名詞の前に入らない。"}], "correct_form": "柔軟な", "base_form": "柔軟", "form_label": "連体形", "sentence_index": 7, "explanations": {"柔軟な": "連体形で、名詞「サービス」を修飾する形。", "柔軟に": "連用形で、名詞「サービス」を修飾できない。", "柔軟だが": "逆接の形で、名詞「サービス」の前に続かず文が成り立たない。", "柔軟だろう": "推量形で、名詞の前に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
