INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36304, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをつかまえることです。例えば、虫を手でつかまえます。", "primary_collocate": null, "pronunciation": "とらえる", "ipa": "toɾaeɾɯ", "syllable_count": 4, "sentences": [{"text": "子どもが網で蝶を捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "子(こ)どもが網(あみ)で蝶(ちょう)を捕(と)らえた。", "sentence_source": "generated"}, {"text": "猫がネズミを捕らえて、得意そうに見せに来た。", "target_word": "捕らえて", "complexity_tier": "T3", "furigana": "猫(ねこ)がネズミを捕(と)らえて、得意(とくい)そうに見(み)せに来(き)た。", "sentence_source": "generated"}, {"text": "警察は逃げた犯人をやっと捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "警察(けいさつ)は逃(に)げた犯人(はんにん)をやっと捕(と)らえた。", "sentence_source": "generated"}, {"text": "漁師は大きな魚を網で捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "漁師(りょうし)は大(おお)きな魚(さかな)を網(あみ)で捕(と)らえた。", "sentence_source": "generated"}, {"text": "カエルは長い舌で虫を捕らえる。", "target_word": "捕らえる", "complexity_tier": "T3", "furigana": "カエルは長(なが)い舌(した)で虫(むし)を捕(と)らえる。", "sentence_source": "generated"}, {"text": "鳥を捕らえるために、森に罠を仕掛けた。", "target_word": "捕らえる", "complexity_tier": "T3", "furigana": "鳥(とり)を捕(と)らえるために、森(もり)に罠(わな)を仕掛(しか)けた。", "sentence_source": "generated"}, {"text": "彼は逃げようとする犬をとっさに捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "彼(かれ)は逃(に)げようとする犬(いぬ)をとっさに捕(と)らえた。", "sentence_source": "generated"}, {"text": "逃げたサルを捕らえたのは、近所の人たちだった。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "逃(に)げたサルを捕(と)らえたのは、近所(きんじょ)の人(ひと)たちだった。", "sentence_source": "generated"}, {"text": "小さなトカゲを素手で捕らえて、弟に見せた。", "target_word": "捕らえて", "complexity_tier": "T3", "furigana": "小(ちい)さなトカゲを素手(すで)で捕(と)らえて、弟(おとうと)に見(み)せた。", "sentence_source": "generated"}, {"text": "クモは巣に掛かった虫を素早く捕らえる。", "target_word": "捕らえる", "complexity_tier": "T3", "furigana": "クモは巣(す)に掛(か)かった虫(むし)を素早(すばや)く捕(と)らえる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕らえる", "label": "dictionary form"}, {"form": "捕らえた", "label": "past"}, {"form": "捕らえて", "label": "te-form"}, {"form": "捕らえない", "label": "negative"}, {"form": "捕らえます", "label": "polite"}], "register": "neutral", "sense_fingerprint": "動物や人を手や道具でつかまえる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c39368-b1a1-4be5-ad73-c3324aee30fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36304, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捕らえた", "is_correct": true, "explanation": "網で蝶をつかまえた意味で、文の動詞として正しい。"}, {"text": "祝った", "is_correct": false, "explanation": "お祝いする意味で、蝶を対象にすると文が成り立たない。"}, {"text": "冷やした", "is_correct": false, "explanation": "温度を下げる意味で、網で蝶を扱う文には合わない。"}, {"text": "組み立てた", "is_correct": false, "explanation": "部品を組む意味で、生き物をつかまえる文には使えない。"}], "explanations": {"捕らえた": "網で蝶をつかまえた意味で、文の動詞として正しい。", "祝った": "お祝いする意味で、蝶を対象にすると文が成り立たない。", "冷やした": "温度を下げる意味で、網で蝶を扱う文には合わない。", "組み立てた": "部品を組む意味で、生き物をつかまえる文には使えない。"}, "sentence_index": 0, "correct_answer": "捕らえた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は本棚の本を捕らえて、一冊ずつ数えた。", "explanation": "ここは〈数える〉の意味。捕らえるは逃げるものをつかまえる意味で、本を一冊ずつ数える動作には使わない。"}, {"text": "父は重い荷物を捕らえて、二階へ運んだ。", "explanation": "ここは〈運ぶ〉の意味。捕らえるは逃げるものをつかまえることで、荷物を運ぶ動作には使わない。"}, {"text": "落ちた鍵を捕らえて、ポケットに入れた。", "explanation": "ここは〈拾う〉の意味。捕らえるは逃げるものをつかまえることで、落ちたものを拾う動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36304, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捕らえた", "is_correct": true, "explanation": "逃げる犬をつかまえた意味で、とっさの動作として自然。"}, {"text": "翻訳した", "is_correct": false, "explanation": "言語を別の言語に訳す意味で、犬には使えない。"}, {"text": "発明した", "is_correct": false, "explanation": "新しい物を考え出す意味で、犬を対象にすると文が成り立たない。"}, {"text": "整理した", "is_correct": false, "explanation": "物を片付ける意味で、逃げる犬には合わない。"}], "explanations": {"捕らえた": "逃げる犬をつかまえた意味で、とっさの動作として自然。", "翻訳した": "言語を別の言語に訳す意味で、犬には使えない。", "発明した": "新しい物を考え出す意味で、犬を対象にすると文が成り立たない。", "整理した": "物を片付ける意味で、逃げる犬には合わない。"}, "sentence_index": 6, "correct_answer": "捕らえた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は壁を捕らえて、白いペンキを塗った。", "explanation": "ここは〈塗る〉の意味。捕らえるは逃げるものをつかまえる意味で、壁にペンキを塗る動作には使わない。"}, {"text": "母は洗った毛布を捕らえて、きれいにたたんだ。", "explanation": "ここは〈たたむ〉の意味。捕らえるは逃げるものをつかまえる意味で、毛布をたたむ動作には使わない。"}, {"text": "会議の前に、担当者は書類を捕らえて、声に出して読んだ。", "explanation": "ここは〈読む〉の意味。捕らえるは逃げるものをつかまえる意味で、書類を声に出して読む動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36304, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもが網で蝶を捕らえって、喜んだ。", "corrected_sentence": "子どもが網で蝶を捕らえて、喜んだ。", "error_description": "て形は「捕らえて」。「捕らえって」の「って」は誤りで、て形の「て」だけで続ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "捕らえて", "is_correct": true, "explanation": "て形で、後の「得意そうに見せに来た」へつながる。"}, {"text": "捕らえる", "is_correct": false, "explanation": "辞書形で文を言い切るため、後ろに「、」で続く形に合わない。"}, {"text": "捕らえない", "is_correct": false, "explanation": "否定形で、ネズミを捕まえたという内容と合わない。"}, {"text": "捕らえよう", "is_correct": false, "explanation": "意向形で、実際に捕まえた事実と合わない。"}], "correct_form": "捕らえて", "base_form": "捕らえる", "form_label": "て形", "sentence_index": 1, "explanations": {"捕らえて": "て形で、後の「得意そうに見せに来た」へつながる。", "捕らえる": "辞書形で文を言い切るため、後ろに「、」で続く形に合わない。", "捕らえない": "否定形で、ネズミを捕まえたという内容と合わない。", "捕らえよう": "意向形で、実際に捕まえた事実と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36304, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は逃げようとする猫にとっさに捕らえた。", "corrected_sentence": "彼は逃げようとする猫をとっさに捕らえた。", "error_description": "捕らえる対象は「を」で示す。「猫に」では対象が示せず、「猫に捕らえた」は不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "捕らえた", "is_correct": true, "explanation": "過去形で「のは〜だった」の述語として正しい。"}, {"text": "捕らえられた", "is_correct": false, "explanation": "受け身の過去形で、サルが人に捕まえられた意味になり、文の主語と合わない。"}, {"text": "捕らえよう", "is_correct": false, "explanation": "意向形は名詞「のは」を修飾できず、文が成り立たない。"}, {"text": "捕らえろ", "is_correct": false, "explanation": "命令形は名詞を修飾する節に入れず、文が成り立たない。"}], "correct_form": "捕らえた", "base_form": "捕らえる", "form_label": "過去形", "sentence_index": 7, "explanations": {"捕らえた": "過去形で「のは〜だった」の述語として正しい。", "捕らえられた": "受け身の過去形で、サルが人に捕まえられた意味になり、文の主語と合わない。", "捕らえよう": "意向形は名詞「のは」を修飾できず、文が成り立たない。", "捕らえろ": "命令形は名詞を修飾する節に入れず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
