INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36305, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "動いているものを自分の手や力でしっかりとつかむこと。また、人の心や考えを引きつけること。", "primary_collocate": null, "pronunciation": "とらえる", "ipa": "toɾaeɾɯ", "syllable_count": 4, "sentences": [{"text": "選手は飛んできたボールを片手で捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "選手(せんしゅ)は飛(と)んできたボールを片手(かたて)で捕(と)らえた。", "sentence_source": "generated"}, {"text": "彼の歌声は、聴く人の心を捕らえて離さない。", "target_word": "捕らえて", "complexity_tier": "T3", "furigana": "彼(かれ)の歌声(うたごえ)は、聴(き)く人(ひと)の心(こころ)を捕(と)らえて離(はな)さない。", "sentence_source": "generated"}, {"text": "美しい景色が旅行客の心を捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "美(うつく)しい景色(けしき)が旅行客(りょこうきゃく)の心(こころ)を捕(と)らえた。", "sentence_source": "generated"}, {"text": "犬は投げられた棒を空中で捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "犬(いぬ)は投(な)げられた棒(ぼう)を空中(くうちゅう)で捕(と)らえた。", "sentence_source": "generated"}, {"text": "その物語は、読者の心を最初の一行から捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "その物語(ものがたり)は、読者(どくしゃ)の心(こころ)を最初(さいしょ)の一行(いちぎょう)から捕(と)らえた。", "sentence_source": "generated"}, {"text": "新しい商品は、若者の心を捕らえて大ヒットした。", "target_word": "捕らえて", "complexity_tier": "T3", "furigana": "新(あたら)しい商品(しょうひん)は、若者(わかもの)の心(こころ)を捕(と)らえて大(だい)ヒットした。", "sentence_source": "generated"}, {"text": "鷹は空から降りて、走るウサギを捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "鷹(たか)は空(そら)から降(お)りて、走(はし)るウサギを捕(と)らえた。", "sentence_source": "generated"}, {"text": "彼の話し方は、聴衆の心を捕らえるのがうまい。", "target_word": "捕らえる", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はな)し方(かた)は、聴衆(ちょうしゅう)の心(こころ)を捕(と)らえるのがうまい。", "sentence_source": "generated"}, {"text": "ゴールキーパーは強いシュートをしっかり捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "ゴールキーパーは強(つよ)いシュートをしっかり捕(と)らえた。", "sentence_source": "generated"}, {"text": "映画の最後の場面が、観客の心を捕らえた。", "target_word": "捕らえた", "complexity_tier": "T3", "furigana": "映画(えいが)の最後(さいご)の場面(ばめん)が、観客(かんきゃく)の心(こころ)を捕(と)らえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕らえる", "label": "dictionary form"}, {"form": "捕らえた", "label": "past"}, {"form": "捕らえて", "label": "te-form"}, {"form": "捕らえない", "label": "negative"}, {"form": "捕らえます", "label": "polite"}], "register": "neutral", "sense_fingerprint": "動くものをしっかりつかむ、人の心を引きつける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c39368-b1a1-4be5-ad73-c3324aee30fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36305, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捕らえた", "is_correct": true, "explanation": "飛んでくるボールを手でつかんだ意味で、「片手で」と合う。"}, {"text": "眠らせた", "is_correct": false, "explanation": "寝かせる意味で、ボールを対象にすると文が成り立たない。"}, {"text": "結んだ", "is_correct": false, "explanation": "紐などを結ぶ意味で、ボールを片手で結ぶ文にはならない。"}, {"text": "干した", "is_correct": false, "explanation": "乾かす意味で、ボールには使えない。"}], "explanations": {"捕らえた": "飛んでくるボールを手でつかんだ意味で、「片手で」と合う。", "眠らせた": "寝かせる意味で、ボールを対象にすると文が成り立たない。", "結んだ": "紐などを結ぶ意味で、ボールを片手で結ぶ文にはならない。", "干した": "乾かす意味で、ボールには使えない。"}, "sentence_index": 0, "correct_answer": "捕らえた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店員は古い電球を捕らえて、新しいものと取り替えた。", "explanation": "ここは〈取り替える〉の意味。捕らえるは動いているものをつかむ意味で、古い電球を取り替える動作には使わない。"}, {"text": "父は重い箱を両手で捕らえた。", "explanation": "ここは〈支える〉の意味。捕らえるは動いているものをつかむ意味で、動かない箱を支える文には使わない。"}, {"text": "父は売り場の商品を捕らえて、一つ選んだ。", "explanation": "ここは〈選ぶ〉の意味。捕らえるは動いているものをつかむ意味で、売り場の商品を選ぶ動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36305, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捕らえた", "is_correct": true, "explanation": "走るウサギを空からつかまえた意味で、文の動詞として正しい。"}, {"text": "暗記した", "is_correct": false, "explanation": "覚える意味で、ウサギを対象にすると文が成り立たない。"}, {"text": "漂白した", "is_correct": false, "explanation": "白くする意味で、生き物には使えない。"}, {"text": "予習した", "is_correct": false, "explanation": "授業の前に学ぶ意味で、ウサギを対象にすると文が成り立たない。"}], "explanations": {"捕らえた": "走るウサギを空からつかまえた意味で、文の動詞として正しい。", "暗記した": "覚える意味で、ウサギを対象にすると文が成り立たない。", "漂白した": "白くする意味で、生き物には使えない。", "予習した": "授業の前に学ぶ意味で、ウサギを対象にすると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "捕らえた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は食器を捕らえて、流しで洗った。", "explanation": "ここは〈洗う〉の意味。捕らえるは逃げるものをつかまえる意味で、食器を洗う動作には使わない。"}, {"text": "父は贈り物を捕らえて、丁寧に包んだ。", "explanation": "ここは〈包む〉の意味。捕らえるは逃げるものをつかまえることで、物を包む動作には使わない。"}, {"text": "洗濯物を捕らえて、ベランダに干した。", "explanation": "ここは〈干す〉の意味。捕らえるは逃げるものをつかまえることで、洗濯物を干す動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36305, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の話は、聴く人の心が捕らえて離さない。", "corrected_sentence": "彼の話は、聴く人の心を捕らえて離さない。", "error_description": "捕らえる対象は「を」で示す。「心が」では主語になり、「捕らえて離さない」の目的語にならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "捕らえて", "is_correct": true, "explanation": "て形で、後の「離さない」へつながる。"}, {"text": "捕らえた", "is_correct": false, "explanation": "過去形で、後の「離さない」へ続かない。"}, {"text": "捕らえない", "is_correct": false, "explanation": "否定形で、心を引きつける意味と逆になる。"}, {"text": "捕らえよう", "is_correct": false, "explanation": "意向形で、「離さない」へ続かず意味も合わない。"}], "correct_form": "捕らえて", "base_form": "捕らえる", "form_label": "て形", "sentence_index": 1, "explanations": {"捕らえて": "て形で、後の「離さない」へつながる。", "捕らえた": "過去形で、後の「離さない」へ続かない。", "捕らえない": "否定形で、心を引きつける意味と逆になる。", "捕らえよう": "意向形で、「離さない」へ続かず意味も合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36305, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゴールキーパーは強いシュートをしっかり捕らえで、ボールを守った。", "corrected_sentence": "ゴールキーパーは強いシュートをしっかり捕らえて、ボールを守った。", "error_description": "て形は「捕らえて」。「捕らえで」は濁音の「で」が誤りで、清音の「て」で続ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "捕らえる", "is_correct": true, "explanation": "辞書形で「〜のが」に続き、「捕らえるのがうまい」と名詞化して結べる。"}, {"text": "捕らえて", "is_correct": false, "explanation": "て形で、「〜のが」に続く形にならない。"}, {"text": "捕らえなかった", "is_correct": false, "explanation": "否定の過去形で、「〜のがうまい」の対象として意味が合わない。"}, {"text": "捕らえよう", "is_correct": false, "explanation": "意向形は「のがうまい」の前に置けず、文が成り立たない。"}], "correct_form": "捕らえる", "base_form": "捕らえる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"捕らえる": "辞書形で「〜のが」に続き、「捕らえるのがうまい」と名詞化して結べる。", "捕らえて": "て形で、「〜のが」に続く形にならない。", "捕らえなかった": "否定の過去形で、「〜のがうまい」の対象として意味が合わない。", "捕らえよう": "意向形は「のがうまい」の前に置けず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36306, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "誤解", "is_correct": true, "explanation": "理解の対義語。「よくわかる」の反対で「誤って解釈する」意味。"}, {"text": "移動", "is_correct": false, "explanation": "場所を変える意味で、理解とは対義関係にない。"}, {"text": "参加", "is_correct": false, "explanation": "加わる意味で、理解とは対義関係にない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届ける意味で、理解とは対義関係にない。"}], "correct_answer": "誤解", "explanations": {"誤解": "理解の対義語。「よくわかる」の反対で「誤って解釈する」意味。", "移動": "場所を変える意味で、理解とは対義関係にない。", "参加": "加わる意味で、理解とは対義関係にない。", "配達": "物を届ける意味で、理解とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36306, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "誤解", "is_correct": true, "explanation": "理解の対義語。「よくわかる」の反対で「誤って解釈する」意味。"}, {"text": "倉庫", "is_correct": false, "explanation": "物をしまう建物で、理解とは関係がない。"}, {"text": "感謝", "is_correct": false, "explanation": "ありがたく思う気持ちで、理解の対義語ではない。"}, {"text": "遠慮", "is_correct": false, "explanation": "控えめにする意味で、理解とは対義関係にない。"}], "correct_answer": "誤解", "explanations": {"誤解": "理解の対義語。「よくわかる」の反対で「誤って解釈する」意味。", "倉庫": "物をしまう建物で、理解とは関係がない。", "感謝": "ありがたく思う気持ちで、理解の対義語ではない。", "遠慮": "控えめにする意味で、理解とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36306, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを、よくわかること。", "primary_collocate": null, "pronunciation": "りかい", "ipa": "ɾikai", "syllable_count": 3, "sentences": [{"text": "算数の授業で、分数の考え方を理解できて嬉しかった。", "target_word": "理解", "complexity_tier": "T3", "furigana": "算数[さんすう]の授業[じゅぎょう]で、分数[ぶんすう]の考[かんが]え方[かた]を理解[りかい]できて嬉[うれ]しかった。", "sentence_source": "generated"}, {"text": "彼の言っていることが、私にはうまく理解できない。", "target_word": "理解", "complexity_tier": "T3", "furigana": "彼[かれ]の言[い]っていることが、私[わたし]にはうまく理解[りかい]できない。", "sentence_source": "generated"}, {"text": "外国で暮らすと、違う習慣への理解が深まる。", "target_word": "理解", "complexity_tier": "T3", "furigana": "外国[がいこく]で暮[く]らすと、違[ちが]う習慣[しゅうかん]への理解[りかい]が深[ふか]まる。", "sentence_source": "generated"}, {"text": "先生は生徒の悩みをよく理解している。", "target_word": "理解", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の悩[なや]みをよく理解[りかい]している。", "sentence_source": "generated"}, {"text": "話が速すぎて、理解が追いつかなかった。", "target_word": "理解", "complexity_tier": "T3", "furigana": "話[はなし]が速[はや]すぎて、理解[りかい]が追[お]いつかなかった。", "sentence_source": "generated"}, {"text": "説明を聞いても、結果の理由がまったく理解できなかった。", "target_word": "理解", "complexity_tier": "T3", "furigana": "説明[せつめい]を聞[き]いても、結果[けっか]の理由[りゆう]がまったく理解[りかい]できなかった。", "sentence_source": "generated"}, {"text": "地図の見方を理解すれば、一人で旅行もできる。", "target_word": "理解", "complexity_tier": "T3", "furigana": "地図[ちず]の見方[みかた]を理解[りかい]すれば、一人[ひとり]で旅行[りょこう]もできる。", "sentence_source": "generated"}, {"text": "質問をして、内容を理解してから次に進んだ。", "target_word": "理解", "complexity_tier": "T3", "furigana": "質問[しつもん]をして、内容[ないよう]を理解[りかい]してから次[つぎ]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "子どもにも理解できるように、やさしい言葉で話した。", "target_word": "理解", "complexity_tier": "T3", "furigana": "子[こ]どもにも理解[りかい]できるように、やさしい言葉[ことば]で話[はな]した。", "sentence_source": "generated"}, {"text": "この映画は、二回見てやっと理解できた。", "target_word": "理解", "complexity_tier": "T3", "furigana": "この映画[えいが]は、二回[にかい]見[み]てやっと理解[りかい]できた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理解", "label": "基本形"}, {"form": "理解する", "label": "終止形"}, {"form": "理解し", "label": "連用形"}, {"form": "理解した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "何かを、よくわかること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36306, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理解", "is_correct": true, "explanation": "「分数の考え方を理解できて」で、よくわかったという意味に合う。"}, {"text": "延期", "is_correct": false, "explanation": "「考え方を延期できて」は意味が通らない。"}, {"text": "破損", "is_correct": false, "explanation": "「考え方を破損」は壊れる意味で、考え方には使えない。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除く意味で、「考え方を撤去」は文脈に合わない。"}], "explanations": {"理解": "「分数の考え方を理解できて」で、よくわかったという意味に合う。", "延期": "「考え方を延期できて」は意味が通らない。", "破損": "「考え方を破損」は壊れる意味で、考え方には使えない。", "撤去": "取り除く意味で、「考え方を撤去」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "理解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は工場に新しい機械を理解した。", "explanation": "ここは〈導入〉の意味。機械などを入れる意味は導入で、理解は内容を正しく知ることなので合わない。"}, {"text": "彼は問題を解くために理解を絞った。", "explanation": "ここは〈知恵〉の意味。「知恵を絞る」は考えを働かせる言い方で、理解を絞るとは言わない。"}, {"text": "係の人は会場の椅子に理解して、しばらく休んだ。", "explanation": "ここは〈座る〉の意味。椅子に腰を下ろす動作に、理解は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36306, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理解", "is_correct": true, "explanation": "「地図の見方を理解すれば」で、見方をよくわかれば、という意味に合う。"}, {"text": "放置", "is_correct": false, "explanation": "「見方を放置すれば」は意味が通らない。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼む意味で、「見方を注文」は不自然。"}, {"text": "清掃", "is_correct": false, "explanation": "きれいにする意味で、地図の見方には合わない。"}], "explanations": {"理解": "「地図の見方を理解すれば」で、見方をよくわかれば、という意味に合う。", "放置": "「見方を放置すれば」は意味が通らない。", "注文": "品物を頼む意味で、「見方を注文」は不自然。", "清掃": "きれいにする意味で、地図の見方には合わない。"}, "sentence_index": 6, "correct_answer": "理解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の行き先の理解がつかない。", "explanation": "ここは〈見当〉の意味。理解は意味を正しく知ることで、「〜がつく」とは言わない。"}, {"text": "寒い夜、彼は厚手の帽子を理解して出かけた。", "explanation": "ここは〈かぶる〉の意味。頭に身につける動作には理解は使わないので合わない。"}, {"text": "試験の理解を整えた。", "explanation": "ここは〈準備〉の意味。整えるのは準備で、理解は内容を知ることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36306, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の言っていることに理解できない。", "corrected_sentence": "彼の言っていることを理解できない。", "error_description": "「理解する」は目的語に「を」をとる。「に」は誤りで、正しくは「言っていることを理解できない」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36306, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はその仕組みをすぐに理解った。", "corrected_sentence": "彼はその仕組みをすぐに理解した。", "error_description": "過去形は「理解した」。「理解った」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36307, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "誤解", "is_correct": true, "explanation": "理解の対義語。「正しく知る」の反対で「誤って知る」意味。"}, {"text": "公開", "is_correct": false, "explanation": "情報を広く示す意味で、理解の対義語ではない。"}, {"text": "節約", "is_correct": false, "explanation": "お金や物を無駄なく使う意味で、理解とは対義関係にない。"}, {"text": "移動", "is_correct": false, "explanation": "場所を変える意味で、理解とは対義関係にない。"}], "correct_answer": "誤解", "explanations": {"誤解": "理解の対義語。「正しく知る」の反対で「誤って知る」意味。", "公開": "情報を広く示す意味で、理解の対義語ではない。", "節約": "お金や物を無駄なく使う意味で、理解とは対義関係にない。", "移動": "場所を変える意味で、理解とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36307, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "形容詞「深い」の主語を示す「が」。「理解が深い」となる。"}, {"text": "を", "is_correct": false, "explanation": "「理解を深い」は形容詞の主語として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」で、「理解で深い」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、「理解から深い」は不自然。"}], "correct_answer": "が", "explanations": {"が": "形容詞「深い」の主語を示す「が」。「理解が深い」となる。", "を": "「理解を深い」は形容詞の主語として成り立たない。", "で": "手段や場所を示す「で」で、「理解で深い」は成り立たない。", "から": "起点を示す「から」で、「理解から深い」は不自然。"}, "error_tags": {"を": "格の誤り", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "誤解", "is_correct": true, "explanation": "理解の対義語。「正しく知る」の反対で「誤って知る」意味。"}, {"text": "倉庫", "is_correct": false, "explanation": "物をしまう建物で、理解とは関係がない。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを振り返る意味で、理解の対義語ではない。"}, {"text": "遠慮", "is_correct": false, "explanation": "控えめにする意味で、理解とは対義関係にない。"}], "correct_answer": "誤解", "explanations": {"誤解": "理解の対義語。「正しく知る」の反対で「誤って知る」意味。", "倉庫": "物をしまう建物で、理解とは関係がない。", "反省": "自分の行いを振り返る意味で、理解の対義語ではない。", "遠慮": "控えめにする意味で、理解とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36307, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の意味や内容、理由などを正しく知ること。", "primary_collocate": null, "pronunciation": "りかい", "ipa": "ɾikai", "syllable_count": 3, "sentences": [{"text": "企業はこれらの色彩が持つ記号的意味を深く理解し、自社のアイデンティティを消費者の心に効果的に植え付けようとしている。", "target_word": "理解", "complexity_tier": "T4", "furigana": "企業[きぎょう]はこれらの色彩[しきさい]が持[も]つ記号的[きごうてき]意味[いみ]を深[ふか]く理解[りかい]し、自社[じしゃ]のアイデンティティを消費者[しょうひしゃ]の心[こころ]に効果的[こうかてき]に植[う]え付[つ]けようとしている。", "sentence_source": "mined"}, {"text": "先生の説明を聞いて、やっと文法の仕組みを理解できた。", "target_word": "理解", "complexity_tier": "T3", "furigana": "先生[せんせい]の説明[せつめい]を聞[き]いて、やっと文法[ぶんぽう]の仕組[しく]みを理解[りかい]できた。", "sentence_source": "generated"}, {"text": "相手の気持ちを理解しようとすることが、友情の第一歩だ。", "target_word": "理解", "complexity_tier": "T3", "furigana": "相手[あいて]の気持[きも]ちを理解[りかい]しようとすることが、友情[ゆうじょう]の第一歩[だいいっぽ]だ。", "sentence_source": "generated"}, {"text": "この本は難しすぎて、内容の半分も理解できなかった。", "target_word": "理解", "complexity_tier": "T3", "furigana": "この本[ほん]は難[むずか]しすぎて、内容[ないよう]の半分[はんぶん]も理解[りかい]できなかった。", "sentence_source": "generated"}, {"text": "親は私が留学したい理由を理解してくれた。", "target_word": "理解", "complexity_tier": "T3", "furigana": "親[おや]は私[わたし]が留学[りゅうがく]したい理由[りゆう]を理解[りかい]してくれた。", "sentence_source": "generated"}, {"text": "説明書をよく読まないと、機械の使い方は理解できない。", "target_word": "理解", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]をよく読[よ]まないと、機械[きかい]の使[つか]い方[かた]は理解[りかい]できない。", "sentence_source": "generated"}, {"text": "事故の原因について、専門家の理解は一致している。", "target_word": "理解", "complexity_tier": "T4", "furigana": "事故[じこ]の原因[げんいん]について、専門家[せんもんか]の理解[りかい]は一致[いっち]している。", "sentence_source": "generated"}, {"text": "彼は日本の文化に対する理解が深い。", "target_word": "理解", "complexity_tier": "T3", "furigana": "彼[かれ]は日本[にほん]の文化[ぶんか]に対[たい]する理解[りかい]が深[ふか]い。", "sentence_source": "generated"}, {"text": "この問題を理解するには、まず基本の用語を覚える必要がある。", "target_word": "理解", "complexity_tier": "T3", "furigana": "この問題[もんだい]を理解[りかい]するには、まず基本[きほん]の用語[ようご]を覚[おぼ]える必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "読者の理解を助けるために、図を多く入れた。", "target_word": "理解", "complexity_tier": "T3", "furigana": "読者[どくしゃ]の理解[りかい]を助[たす]けるために、図[ず]を多[おお]く入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理解", "label": "基本形"}, {"form": "理解する", "label": "終止形"}, {"form": "理解し", "label": "連用形"}, {"form": "理解した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "物事の意味や内容、理由などを正しく知ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 色彩 (Zipf 3.83), 記号 (Zipf 3.85), アイデンティティ (Zipf 3.53), 植え付けよ (Zipf 3.26)']::text[], '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36307, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理解", "is_correct": true, "explanation": "「深く理解し」で、意味を正しく知る働きを表す。文脈に合う。"}, {"text": "放電", "is_correct": false, "explanation": "「深く放電し」は電気を放つ意味で、記号的意味の文脈には使えない。"}, {"text": "点灯", "is_correct": false, "explanation": "「深く点灯し」は明かりをともす意味で、記号的意味の文脈には合わない。"}, {"text": "破損", "is_correct": false, "explanation": "「深く破損し」は壊れる意味で、意味や内容には使えない。"}], "explanations": {"理解": "「深く理解し」で、意味を正しく知る働きを表す。文脈に合う。", "放電": "「深く放電し」は電気を放つ意味で、記号的意味の文脈には使えない。", "点灯": "「深く点灯し」は明かりをともす意味で、記号的意味の文脈には合わない。", "破損": "「深く破損し」は壊れる意味で、意味や内容には使えない。"}, "sentence_index": 0, "correct_answer": "理解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は運転免許を理解した。", "explanation": "ここは〈取得〉の意味。免許を手に入れる意味は取得で、理解は物事の内容を正しく知ることなので合わない。"}, {"text": "彼は朝食のパンを理解して、コーヒーを飲んだ。", "explanation": "ここは〈食べる〉の意味。パンを食べる動作に理解は使わないので合わない。"}, {"text": "冷える朝、彼は厚手のコートを理解して出かけた。", "explanation": "ここは〈着る〉の意味。身に着ける動作には理解は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36307, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理解", "is_correct": true, "explanation": "「専門家の理解は一致している」で、専門家の知識の内容が一致しているという意味に合う。"}, {"text": "駐車", "is_correct": false, "explanation": "「専門家の駐車は一致している」は文が成り立たない。"}, {"text": "配送", "is_correct": false, "explanation": "物を届ける意味で、専門家の判断や見解には合わない。"}, {"text": "貯金", "is_correct": false, "explanation": "お金をためる意味で、ここの文脈には合わない。"}], "explanations": {"理解": "「専門家の理解は一致している」で、専門家の知識の内容が一致しているという意味に合う。", "駐車": "「専門家の駐車は一致している」は文が成り立たない。", "配送": "物を届ける意味で、専門家の判断や見解には合わない。", "貯金": "お金をためる意味で、ここの文脈には合わない。"}, "sentence_index": 6, "correct_answer": "理解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の行き先の理解がつかない。", "explanation": "ここは〈見当〉の意味（推測がつく）。理解は意味を正しく知ることで、「〜がつく」とは言わない。"}, {"text": "来月の旅行の理解を立てた。", "explanation": "ここは〈計画〉の意味。計画は立てるものだが、理解を立てるとは言わない。"}, {"text": "試験の理解を整えた。", "explanation": "ここは〈準備〉の意味。整えるのは準備や段取りで、理解は内容を知ることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36307, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の論文を読んで、研究の方法に理解した。", "corrected_sentence": "彼の論文を読んで、研究の方法を理解した。", "error_description": "「理解する」は目的語に「を」をとる。「に」は誤りで、正しくは「研究の方法を理解した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36307, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は内容を理解しよう努力した。", "corrected_sentence": "彼は内容を理解しようと努力した。", "error_description": "「努力しよう」の形では「と」が必要。「理解しよう努力した」は「と」が抜けた誤りで、正しくは「理解しようと努力した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
