INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36308, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても大事なこと。", "primary_collocate": null, "pronunciation": "じゅうよう", "ipa": "dʑɯːjoː", "syllable_count": 4, "sentences": [{"text": "試験の前日は、しっかり寝ることが重要です。", "target_word": "重要", "complexity_tier": "T3", "furigana": "試験[しけん]の前日[ぜんじつ]は、しっかり寝[ね]ることが重要[じゅうよう]です。", "sentence_source": "generated"}, {"text": "これは会議で話す重要な点です。", "target_word": "重要", "complexity_tier": "T3", "furigana": "これは会議[かいぎ]で話[はな]す重要[じゅうよう]な点[てん]です。", "sentence_source": "generated"}, {"text": "健康のために、毎日の食事は重要だ。", "target_word": "重要", "complexity_tier": "T3", "furigana": "健康[けんこう]のために、毎日[まいにち]の食事[しょくじ]は重要[じゅうよう]だ。", "sentence_source": "generated"}, {"text": "契約書では、日付の書き方が重要です。", "target_word": "重要", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]では、日付[ひづけ]の書[か]き方[かた]が重要[じゅうよう]です。", "sentence_source": "generated"}, {"text": "面接では、初めの印象がとても重要です。", "target_word": "重要", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、初[はじ]めの印象[いんしょう]がとても重要[じゅうよう]です。", "sentence_source": "generated"}, {"text": "重要な電話がかかってくるので、席をはなれられません。", "target_word": "重要", "complexity_tier": "T3", "furigana": "重要[じゅうよう]な電話[でんわ]がかかってくるので、席[せき]をはなれられません。", "sentence_source": "generated"}, {"text": "小さい作業でも、全体には重要な役割がある。", "target_word": "重要", "complexity_tier": "T3", "furigana": "小[ちい]さい作業[さぎょう]でも、全体[ぜんたい]には重要[じゅうよう]な役割[やくわり]がある。", "sentence_source": "generated"}, {"text": "水は、人が生きるために重要な物だ。", "target_word": "重要", "complexity_tier": "T3", "furigana": "水[みず]は、人[ひと]が生[い]きるために重要[じゅうよう]な物[もの]だ。", "sentence_source": "generated"}, {"text": "パスワードは重要な情報なので、人に教えないでください。", "target_word": "重要", "complexity_tier": "T3", "furigana": "パスワードは重要[じゅうよう]な情報[じょうほう]なので、人[ひと]に教[おし]えないでください。", "sentence_source": "generated"}, {"text": "計画を立てることも大切だが、続けることはもっと重要だ。", "target_word": "重要", "complexity_tier": "T3", "furigana": "計画[けいかく]を立[た]てることも大切[たいせつ]だが、続[つづ]けることはもっと重要[じゅうよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重要", "label": "基本形"}, {"form": "重要な", "label": "連体形"}, {"form": "重要で", "label": "連用形"}, {"form": "重要だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "物事の価値や影響が大きく、欠かせないさま。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b68666-ebe4-44b0-8208-b74bdbb1eb7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36308, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重要", "is_correct": true, "explanation": "「しっかり寝ることが重要です」の空欄。大事だという意味で文に合う。"}, {"text": "派手", "is_correct": false, "explanation": "「寝ることが派手です」は意味が通らず、空欄に入らない。"}, {"text": "陽気", "is_correct": false, "explanation": "「寝ることが陽気です」は成り立たない。"}, {"text": "豪華", "is_correct": false, "explanation": "「寝ることが豪華です」は文脈に合わない。"}], "explanations": {"重要": "「しっかり寝ることが重要です」の空欄。大事だという意味で文に合う。", "派手": "「寝ることが派手です」は意味が通らず、空欄に入らない。", "陽気": "「寝ることが陽気です」は成り立たない。", "豪華": "「寝ることが豪華です」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "重要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その箱は重要で、一人では運べなかった。", "explanation": "ここは〈重い〉の意味。重さを表す「重い」にあたり、大事さを表す重要とは言わない。"}, {"text": "彼に会えて、とても重要だ。", "explanation": "ここは〈嬉しい〉の意味。喜びの気持ちを表す語で、重要と言うと意味が変わる。"}, {"text": "この料理は重要で、口がひりひりした。", "explanation": "ここは〈辛い〉の意味。味の辛さは「辛い」で表し、重要では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36308, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重要", "is_correct": true, "explanation": "「全体には重要な役割がある」の空欄。大事だという意味で文に合う。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔な役割」は意味が通らず、空欄に入らない。"}, {"text": "柔らか", "is_correct": false, "explanation": "「柔らかな役割」は不自然で、この文に合わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "「頑丈な役割」は成り立たない。"}], "explanations": {"重要": "「全体には重要な役割がある」の空欄。大事だという意味で文に合う。", "清潔": "「清潔な役割」は意味が通らず、空欄に入らない。", "柔らか": "「柔らかな役割」は不自然で、この文に合わない。", "頑丈": "「頑丈な役割」は成り立たない。"}, "sentence_index": 6, "correct_answer": "重要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母の形見を重要に保管しています。", "explanation": "ここは〈大切〉の意味。大切に保管するとは言うが、重要に保管とは言わない。"}, {"text": "子どもを重要に育てた。", "explanation": "ここは〈大事〉の意味。大事に育てるとは言うが、重要に育てるとは言わない。"}, {"text": "彼の話を重要に聞いた。", "explanation": "ここは〈真剣〉の意味。真剣に聞くとは言うが、重要に聞くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36308, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この約束は重要の点なので、守ってください。", "corrected_sentence": "この約束は重要な点なので、守ってください。", "error_description": "正しくは「重要な点」。「重要」の後は「な」で名詞に続ける。「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重要な", "is_correct": true, "explanation": "文中の「重要な点」の形。連体形で、名詞「点」を修飾する。"}, {"text": "重要で", "is_correct": false, "explanation": "中止形で、名詞の「点」に直接続けるには不自然。"}, {"text": "重要だ", "is_correct": false, "explanation": "終止形で、名詞を修飾する形ではない。"}, {"text": "重要に", "is_correct": false, "explanation": "連用形で、名詞を修飾しない。"}], "correct_form": "重要な", "base_form": "重要", "form_label": "連体形", "sentence_index": 1, "explanations": {"重要な": "文中の「重要な点」の形。連体形で、名詞「点」を修飾する。", "重要で": "中止形で、名詞の「点」に直接続けるには不自然。", "重要だ": "終止形で、名詞を修飾する形ではない。", "重要に": "連用形で、名詞を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36308, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この作業は重要に役割がある。", "corrected_sentence": "この作業は重要な役割がある。", "error_description": "正しくは「重要な役割」。「重要」は名詞に続けるとき「な」を使う。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重要な", "is_correct": true, "explanation": "文中の「重要な物」の形。連体形で、名詞「物」を修飾する。"}, {"text": "重要でない", "is_correct": false, "explanation": "否定形で、文の肯定の述べ方とは形が違う。"}, {"text": "重要だった", "is_correct": false, "explanation": "過去形で、現在の文と合わない。"}, {"text": "重要なら", "is_correct": false, "explanation": "仮定形で、文に条件を表す語がない。"}], "correct_form": "重要な", "base_form": "重要", "form_label": "連体形", "sentence_index": 7, "explanations": {"重要な": "文中の「重要な物」の形。連体形で、名詞「物」を修飾する。", "重要でない": "否定形で、文の肯定の述べ方とは形が違う。", "重要だった": "過去形で、現在の文と合わない。", "重要なら": "仮定形で、文に条件を表す語がない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36310, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一緒」を副詞的に使うときに続く「に」。「一緒に宿題をする」となる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、「一緒で宿題をしましょう」は文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すが、「一緒を宿題をしましょう」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手を表すが、「一緒と宿題をしましょう」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「一緒」を副詞的に使うときに続く「に」。「一緒に宿題をする」となる。", "で": "手段や場所を表すが、「一緒で宿題をしましょう」は文が成り立たない。", "を": "目的語を表すが、「一緒を宿題をしましょう」は文が成り立たない。", "と": "相手を表すが、「一緒と宿題をしましょう」は文が成り立たない。"}, "error_tags": {"に": "副詞的用法", "で": "手段・場所", "を": "目的語", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "別々", "is_correct": true, "explanation": "別の場所や別の行動を表し、「一緒」の対義語として類語辞典に挙がる。"}, {"text": "静か", "is_correct": false, "explanation": "音が少ない様子。一緒の対義語ではない。"}, {"text": "大切", "is_correct": false, "explanation": "重要であること。一緒の対義語ではない。"}, {"text": "無理", "is_correct": false, "explanation": "できないこと。一緒の対義語ではない。"}], "correct_answer": "別々", "explanations": {"別々": "別の場所や別の行動を表し、「一緒」の対義語として類語辞典に挙がる。", "静か": "音が少ない様子。一緒の対義語ではない。", "大切": "重要であること。一緒の対義語ではない。", "無理": "できないこと。一緒の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36310, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一緒」を副詞的に使うときに続く「に」。「一緒に来てくれて」となる。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、「一緒が来てくれて」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「一緒へ来てくれて」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表すが、「一緒の来てくれて」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「一緒」を副詞的に使うときに続く「に」。「一緒に来てくれて」となる。", "が": "主語を表すが、「一緒が来てくれて」では文が成り立たない。", "へ": "方向を表すが、「一緒へ来てくれて」は文が成り立たない。", "の": "連体修飾を表すが、「一緒の来てくれて」は文が成り立たない。"}, "error_tags": {"に": "副詞的用法", "が": "主語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "別々", "is_correct": true, "explanation": "別の場所や別の行動を表し、「一緒」の対義語として類語辞典に挙がる。"}, {"text": "丁寧", "is_correct": false, "explanation": "ていねいな様子。一緒の対義語ではない。"}, {"text": "穏やか", "is_correct": false, "explanation": "おだやかな様子。一緒の対義語ではない。"}, {"text": "活発", "is_correct": false, "explanation": "元気よく動く様子。一緒の対義語ではない。"}], "correct_answer": "別々", "explanations": {"別々": "別の場所や別の行動を表し、「一緒」の対義語として類語辞典に挙がる。", "丁寧": "ていねいな様子。一緒の対義語ではない。", "穏やか": "おだやかな様子。一緒の対義語ではない。", "活発": "元気よく動く様子。一緒の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36310, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二人以上の人が、同じ場所にいたり、同じことをしたりすることを言います。", "primary_collocate": null, "pronunciation": "いっしょ", "ipa": "iɕːo", "syllable_count": 3, "sentences": [{"text": "先生と一緒に、教室をそうじしました。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "先生[せんせい]と一緒[いっしょ]に、教室[きょうしつ]をそうじしました。", "sentence_source": "generated"}, {"text": "一緒に宿題をしましょう。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "一緒[いっしょ]に宿題[しゅくだい]をしましょう。", "sentence_source": "generated"}, {"text": "私は姉と一緒の部屋で寝ています。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "私[わたし]は姉[あね]と一緒[いっしょ]の部屋[へや]で寝[ね]ています。", "sentence_source": "generated"}, {"text": "犬と一緒に、毎日川のそばを散歩する。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "犬[いぬ]と一緒[いっしょ]に、毎日[まいにち]川[かわ]のそばを散歩[さんぽ]する。", "sentence_source": "generated"}, {"text": "旅行は友だちと一緒に行くと楽しい。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "旅行[りょこう]は友[とも]だちと一緒[いっしょ]に行[い]くと楽[たの]しい。", "sentence_source": "generated"}, {"text": "家族と一緒に、毎晩ごはんを食べます。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "家族[かぞく]と一緒[いっしょ]に、毎晩[まいばん]ごはんを食[た]べます。", "sentence_source": "generated"}, {"text": "彼女と一緒に、新しい店を開く予定だ。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "彼女[かのじょ]と一緒[いっしょ]に、新[あたら]しい店[みせ]を開[ひら]く予定[よてい]だ。", "sentence_source": "generated"}, {"text": "一緒に来てくれて、ありがとうございました。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "一緒[いっしょ]に来[き]てくれて、ありがとうございました。", "sentence_source": "generated"}, {"text": "駅で友だちと会って、一緒に電車に乗った。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "駅[えき]で友[とも]だちと会[あ]って、一緒[いっしょ]に電車[でんしゃ]に乗[の]った。", "sentence_source": "generated"}, {"text": "この問題は、友だちと一緒に考えましょう。", "target_word": "一緒", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、友[とも]だちと一緒[いっしょ]に考[かんが]えましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一緒", "label": "基本形"}, {"form": "一緒に", "label": "に形（副詞的用法）"}, {"form": "一緒の", "label": "連体形（の）"}, {"form": "一緒だ", "label": "断定形"}], "register": "neutral", "sense_fingerprint": "二人以上が同じ場所にいる、または同じことをすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3b14ba-f350-4b70-835c-74054ef8b390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36310, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一緒", "is_correct": true, "explanation": "先生と共に教室をそうじしたという意味になり、文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて回ること。「散歩に教室をそうじした」では文が成り立たない。"}, {"text": "相談", "is_correct": false, "explanation": "話し合う意味で、「相談に教室をそうじした」とは続かない。"}, {"text": "訓練", "is_correct": false, "explanation": "繰り返し身につける行為で、「訓練に教室をそうじした」は文に合わない。"}], "explanations": {"一緒": "先生と共に教室をそうじしたという意味になり、文に合う。", "散歩": "歩いて回ること。「散歩に教室をそうじした」では文が成り立たない。", "相談": "話し合う意味で、「相談に教室をそうじした」とは続かない。", "訓練": "繰り返し身につける行為で、「訓練に教室をそうじした」は文に合わない。"}, "sentence_index": 0, "correct_answer": "一緒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎日、ひとりで川のそばを一緒に散歩する。", "explanation": "ここは〈単独〉（ひとりで行うこと）の意味になってしまう。一緒は二人以上が共に行うことを表すので、ひとりで散歩する文には合わない。"}, {"text": "この犬は一緒に一匹だけで川を渡った。", "explanation": "ここは〈単独〉（ひとりで行うこと）の意味になってしまう。一緒は二つ以上が共にすることを表すので、一匹だけで渡った場面には使わない。"}, {"text": "私は一緒に、ひとりで旅行の計画を立てた。", "explanation": "ここは〈単独〉（ひとりで行うこと）の意味になってしまう。一緒は複数の人が共に行うことを表すので、ひとりで計画を立てた場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36310, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一緒", "is_correct": true, "explanation": "彼女と共に新しい店を開く予定という意味になり、文に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "遠くへ出かける意味で、「旅行に新しい店を開く」では文が成り立たない。"}, {"text": "練習", "is_correct": false, "explanation": "繰り返し身につける行為で、店を開く文とは続かない。"}, {"text": "見学", "is_correct": false, "explanation": "見て回る意味で、「見学に新しい店を開く」では文が成り立たない。"}], "explanations": {"一緒": "彼女と共に新しい店を開く予定という意味になり、文に合う。", "旅行": "遠くへ出かける意味で、「旅行に新しい店を開く」では文が成り立たない。", "練習": "繰り返し身につける行為で、店を開く文とは続かない。", "見学": "見て回る意味で、「見学に新しい店を開く」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "一緒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ひとりで部屋にこもって、一緒に本を読んだ。", "explanation": "ここは〈単独〉（ひとりで行うこと）の意味になってしまう。一緒は共にする相手がいることを表すので、ひとりで読んだ場面には使わない。"}, {"text": "この問題は一緒に一人だけで解いた。", "explanation": "ここは〈単独〉（ひとりで行うこと）の意味になってしまう。一緒は二人以上が共に行うことを表すので、一人だけで解いた場面には使わない。"}, {"text": "部長が一人で、一緒に仕事を任された。", "explanation": "ここは〈単独〉（ひとりで受けること）の意味になってしまう。一緒は二人以上が共に行うことを表すので、一人で任された場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36310, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉と一緒が部屋で眠っている。", "corrected_sentence": "姉と一緒の部屋で眠っている。", "error_description": "「一緒」を名詞の前で「〜の」として使うときは「一緒の部屋」。「一緒が」は「が」を続ける誤りで、ここは「の」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36310, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちと一緒を駅まで行った。", "corrected_sentence": "友だちと一緒に駅まで行った。", "error_description": "「一緒」を副詞的に使うときは「に」を続ける。「一緒を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36312, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「終わる」の主語を示す助詞で、「仕事が終わってから」と続けて文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「終わる」は主語の「が」を取る自動詞で、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「終わる」は「が」で主語を示すので、「仕事に終わって」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」で、「終わる」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「終わる」の主語を示す助詞で、「仕事が終わってから」と続けて文に合う。", "を": "「終わる」は主語の「が」を取る自動詞で、「を」は合わない。", "に": "「終わる」は「が」で主語を示すので、「仕事に終わって」は文が成り立たない。", "と": "並列や相手を示す「と」で、「終わる」の主語にはならない。"}, "error_tags": {"を": "「終わる」は主語の「が」を取る自動詞で、「を」は合わない。", "に": "「終わる」は「が」で主語を示すので、「仕事に終わって」は文が成り立たない。", "と": "並列や相手を示す「と」で、「終わる」の主語にはならない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
