INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36312, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人がお金をもらってする、すること。", "primary_collocate": null, "pronunciation": "しごと", "ipa": "ɕiɡoto", "syllable_count": 3, "sentences": [{"text": "父は毎朝六時に家を出て、駅前の会社で仕事をしています。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "父[ちち]は毎朝[まいあさ]六時[ろくじ]に家[いえ]を出[で]て、駅前[えきまえ]の会社[かいしゃ]で仕事[しごと]をしています。", "sentence_source": "generated"}, {"text": "仕事が終わってから、同僚と夕飯を食べに行きました。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "仕事[しごと]が終[お]わってから、同僚[どうりょう]と夕飯[ゆうはん]を食[た]べに行[い]きました。", "sentence_source": "generated"}, {"text": "今月は仕事が忙しくて、友達と会う時間がありません。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "今月[こんげつ]は仕事[しごと]が忙[いそが]しくて、友[とも]だちと会[あ]う時間[じかん]がありません。", "sentence_source": "generated"}, {"text": "姉は病院で働いていて、仕事の内容は患者さんの世話です。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "姉[あね]は病院[びょういん]で働[はたら]いていて、仕事[しごと]の内容[ないよう]は患者[かんじゃ]さんの世話[せわ]です。", "sentence_source": "generated"}, {"text": "新しい仕事を探すために、毎日求人の情報を調べています。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]を探[さが]すために、毎日[まいにち]求人[きゅうじん]の情報[じょうほう]を調[しら]べています。", "sentence_source": "generated"}, {"text": "母は仕事で疲れているので、土曜日は家でゆっくり休みます。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "母[はは]は仕事[しごと]で疲[つか]れているので、土曜日[どようび]は家[いえ]でゆっくり休[やす]みます。", "sentence_source": "generated"}, {"text": "彼は仕事を休んで、子どもの運動会を見に行きました。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]を休[やす]んで、子[こ]どもの運動会[うんどうかい]を見[み]に行[い]きました。", "sentence_source": "generated"}, {"text": "この仕事はお金がたくさんもらえるが、とても大変です。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "この仕事[しごと]はお金[かね]がたくさんもらえるが、とても大変[たいへん]です。", "sentence_source": "generated"}, {"text": "山田さんは仕事が早いので、みんなに頼りにされています。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "山田[やまだ]さんは仕事[しごと]が早[はや]いので、みんなに頼[たよ]りにされています。", "sentence_source": "generated"}, {"text": "仕事の帰りに、スーパーで野菜と肉を買いました。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "仕事[しごと]の帰[かえ]りに、スーパーで野菜[やさい]と肉[にく]を買[か]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕事", "label": "基本形"}], "register": "中立", "sense_fingerprint": "お金をもらってする職業上の作業・勤め", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36312, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕事", "is_correct": true, "explanation": "会社で行う職業上の作業を指し、「仕事をしています」と続いて文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "気晴らしに歩くことで、会社でお金をもらって行う作業としては合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "遠くへ出かけることで、会社で行う作業の内容としては文に合わない。"}, {"text": "日記", "is_correct": false, "explanation": "毎日の出来事を書く記録で、会社での作業としては文に合わない。"}], "explanations": {"仕事": "会社で行う職業上の作業を指し、「仕事をしています」と続いて文に合う。", "散歩": "気晴らしに歩くことで、会社でお金をもらって行う作業としては合わない。", "旅行": "遠くへ出かけることで、会社で行う作業の内容としては文に合わない。", "日記": "毎日の出来事を書く記録で、会社での作業としては文に合わない。"}, "sentence_index": 0, "correct_answer": "仕事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先月もらった仕事は、家族の食事代に使いました。", "explanation": "ここは〈報酬〉の意味。仕事は働く活動のことで、使うのはもらったお金であり仕事そのものは使えないので合わない。"}, {"text": "毎月の仕事を、病院に届けています。", "explanation": "ここは〈寄付〉の意味。仕事は働いて行うことで、病院に届けるお金の寄付とは違うので合わない。"}, {"text": "彼の仕事は、とても明るくて、みんなに好かれています。", "explanation": "ここは〈性格〉の意味。仕事は働く活動やお金をもらってすることを指し、人の性質を言うときには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36312, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕事", "is_correct": true, "explanation": "会社などで働く仕事を指し、「仕事を休んで」と続けると文に合う。"}, {"text": "給料", "is_correct": false, "explanation": "もらうお金のことで、休むという動作の対象にはならず文が成り立たない。"}, {"text": "名刺", "is_correct": false, "explanation": "自分の名前などを書いた札で、休むという行為の対象にならない。"}, {"text": "役職", "is_correct": false, "explanation": "会社内の地位のことで、休む対象としては不自然で文に合わない。"}], "explanations": {"仕事": "会社などで働く仕事を指し、「仕事を休んで」と続けると文に合う。", "給料": "もらうお金のことで、休むという動作の対象にはならず文が成り立たない。", "名刺": "自分の名前などを書いた札で、休むという行為の対象にならない。", "役職": "会社内の地位のことで、休む対象としては不自然で文に合わない。"}, "sentence_index": 6, "correct_answer": "仕事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仕事が治ってから、スーパーで野菜と肉を買いました。", "explanation": "ここは〈病気〉の意味。仕事は働く活動で、治るものではないので合わない。"}, {"text": "スーパーで野菜と肉と仕事を買いました。", "explanation": "ここは〈商品〉の意味。仕事は働いて行うことで、店で買うものではないので合わない。"}, {"text": "明日の仕事は晴れです。", "explanation": "ここは〈天気〉の意味。仕事は働く活動で、天候を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36312, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は仕事に休んで、家で寝ています。", "corrected_sentence": "兄は仕事を休んで、家で寝ています。", "error_description": "「休む」の対象を示す助詞は「を」。「に」が誤りで、正しくは「仕事を休んで」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36312, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仕事を帰りに、スーパーで野菜を買いました。", "corrected_sentence": "仕事の帰りに、スーパーで野菜を買いました。", "error_description": "「仕事」に続けて「帰り」を言うときの助詞は「の」。「を」は誤りで、正しくは「仕事の帰り」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36313, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「する」の対象を示す助詞で、「仕事をしています」と続いて文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「する」の対象は「を」で示す。「が」では「仕事がしています」となり文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「する」の対象を表すことはできない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「する」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「する」の対象を示す助詞で、「仕事をしています」と続いて文に合う。", "が": "「する」の対象は「を」で示す。「が」では「仕事がしています」となり文が成り立たない。", "へ": "方向を示す助詞で、「する」の対象を表すことはできない。", "から": "起点を示す助詞で、「する」の対象にはならない。"}, "error_tags": {"が": "「する」の対象は「を」で示す。「が」では「仕事がしています」となり文が成り立たない。", "へ": "方向を示す助詞で、「する」の対象を表すことはできない。", "から": "起点を示す助詞で、「する」の対象にはならない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
