INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36313, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "職業や生計のために行う活動。また、やるべきこと。", "primary_collocate": null, "pronunciation": "しごと", "ipa": "ɕigoto", "syllable_count": 3, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "仕事", "complexity_tier": "T4", "furigana": "しかし、農薬[のうやく]を使[つか]わずに野菜[やさい]を育[そだ]てるという仕事[しごと]を通[つう]じて、彼[かれ]は自然[しぜん]の厳[きび]しさと、土[つち]が命[いのち]を育[はぐく]むという壮大[そうだい]な仕組[しく]みを、自[みずか]らの肌[はだ]で実感[じっかん]していくことになります。", "sentence_source": "mined"}, {"text": "父は銀行で働いていて、毎日遅くまで仕事をしています。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "父[ちち]は銀行[ぎんこう]で働[はたら]いていて、毎日[まいにち]遅[おそ]くまで仕事[しごと]をしています。", "sentence_source": "generated"}, {"text": "新しい仕事を探すために、先月、会社をやめました。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]を探[さが]すために、先月[せんげつ]、会社[かいしゃ]をやめました。", "sentence_source": "generated"}, {"text": "今日は仕事が多くて、昼ご飯を食べる時間もありませんでした。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "今日[きょう]は仕事[しごと]が多[おお]くて、昼[ひる]ご飯[はん]を食[た]べる時間[じかん]もありませんでした。", "sentence_source": "generated"}, {"text": "彼女は仕事と育児を両立させながら、資格の勉強も続けている。", "target_word": "仕事", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は仕事[しごと]と育児[いくじ]を両立[りょうりつ]させながら、資格[しかく]の勉強[べんきょう]も続[つづ]けている。", "sentence_source": "generated"}, {"text": "掃除は子どもたちの仕事で、毎朝順番に床をふきます。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "掃除[そうじ]は子[こ]どもたちの仕事[しごと]で、毎朝[まいあさ]順番[じゅんばん]に床[ゆか]をふきます。", "sentence_source": "generated"}, {"text": "仕事が終わったら、同僚と食事に行く約束をしている。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "仕事[しごと]が終[お]わったら、同僚[どうりょう]と食事[しょくじ]に行[い]く約束[やくそく]をしている。", "sentence_source": "generated"}, {"text": "将来は、動物に関わる仕事に就きたいと思っています。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "将来[しょうらい]は、動物[どうぶつ]に関[かか]わる仕事[しごと]に就[つ]きたいと思[おも]っています。", "sentence_source": "generated"}, {"text": "休みの日まで仕事のメールを読むのは、やめたほうがいい。", "target_word": "仕事", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]まで仕事[しごと]のメールを読[よ]むのは、やめたほうがいい。", "sentence_source": "generated"}, {"text": "今回の仕事は納期が短いので、チーム全員で分担して進めます。", "target_word": "仕事", "complexity_tier": "T4", "furigana": "今回[こんかい]の仕事[しごと]は納期[のうき]が短[みじか]いので、チーム全員[ぜんいん]で分担[ぶんたん]して進[すす]めます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕事", "label": "基本形"}], "register": "中立", "sense_fingerprint": "職業・生計のための活動、または割り当てられたやるべきこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 農薬 (Zipf 3.66), 厳し (Zipf 3.6), 育む (Zipf 3.02), 壮大 (Zipf 3.84)']::text[], 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36313, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕事", "is_correct": true, "explanation": "「野菜を育てるという仕事」として、働いて行う活動を指し、文に合う。"}, {"text": "休暇", "is_correct": false, "explanation": "休みを取る期間のことで、野菜を育てる活動を通じて実感するという文脈に合わない。"}, {"text": "名刺", "is_correct": false, "explanation": "自分の名前などを書いた札で、「野菜を育てるという名刺」は文が成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場のことで、「野菜を育てるという会議」は文が成り立たない。"}], "explanations": {"仕事": "「野菜を育てるという仕事」として、働いて行う活動を指し、文に合う。", "休暇": "休みを取る期間のことで、野菜を育てる活動を通じて実感するという文脈に合わない。", "名刺": "自分の名前などを書いた札で、「野菜を育てるという名刺」は文が成り立たない。", "会議": "話し合いの場のことで、「野菜を育てるという会議」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "仕事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は仕事が早いので、十分ほどで楽になりました。", "explanation": "ここは〈効き目〉の意味。仕事は働く活動やするべきことを指し、薬の効きの速さには使わないので合わない。"}, {"text": "試合の仕事は、三対一でした。", "explanation": "ここは〈結果〉の意味。仕事は職業や、やるべきことを指し、試合の点数や勝敗の結果には使わないので合わない。"}, {"text": "庭の仕事が、夕日で赤く光っています。", "explanation": "ここは〈光〉の意味。仕事は人の活動やするべきことを指し、光の様子には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36313, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕事", "is_correct": true, "explanation": "「仕事が終わったら、同僚と食事に行く」と続き、働いて行う活動の意味で文に合う。"}, {"text": "給料", "is_correct": false, "explanation": "もらうお金のことで、「給料が終わったら」と言えないため文に合わない。"}, {"text": "名刺", "is_correct": false, "explanation": "自分の名前などを書いた札で、終わるという文脈に合わない。"}, {"text": "身長", "is_correct": false, "explanation": "体の高さのことで、「身長が終わったら」は文が成り立たない。"}], "explanations": {"仕事": "「仕事が終わったら、同僚と食事に行く」と続き、働いて行う活動の意味で文に合う。", "給料": "もらうお金のことで、「給料が終わったら」と言えないため文に合わない。", "名刺": "自分の名前などを書いた札で、終わるという文脈に合わない。", "身長": "体の高さのことで、「身長が終わったら」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "仕事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪の仕事で、三日間寝込みました。", "explanation": "ここは〈病気〉の意味。仕事は働いて行う活動で、病気の状態を指さないので合わない。"}, {"text": "最近、体の仕事がよくて、元気です。", "explanation": "ここは〈調子〉の意味。仕事は働く活動やすることを指し、体の具合の良し悪しには使わないので合わない。"}, {"text": "仕事が吹いて、洗濯物が飛ばされました。", "explanation": "ここは〈風〉の意味。仕事は人が働いて行う活動を指し、風が吹くという自然現象には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36313, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先月から、新しい仕事に探しています。", "corrected_sentence": "先月から、新しい仕事を探しています。", "error_description": "「探す」の対象を示す助詞は「を」。「仕事に」は誤りで、正しくは「仕事を探しています」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36313, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は朝から仕事を働いて、夜遅くに帰ります。", "corrected_sentence": "父は朝から仕事をして、夜遅くに帰ります。", "error_description": "「働く」は「を」を取らない自動詞。「仕事を働く」は誤りで、正しくは「仕事をする」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36314, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「誤解は」の「は」。誤解を主題として示し、「解けた」と続く正しい助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「誤解へ解けた」は方向を示す形になり、解消の対象として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「誤解より解けた」と続かず、文の構造に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「誤解と解けた」は並列や共同の意味になり、自動詞「解ける」と合わない。"}], "correct_answer": "は", "explanations": {"は": "「誤解は」の「は」。誤解を主題として示し、「解けた」と続く正しい助詞。", "へ": "「誤解へ解けた」は方向を示す形になり、解消の対象として成り立たない。", "より": "比較の「より」は「誤解より解けた」と続かず、文の構造に合わない。", "と": "「誤解と解けた」は並列や共同の意味になり、自動詞「解ける」と合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "と": "並列・共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "「誤解」の対義語。相手の言ったことや考えを正しく受け取ること。"}, {"text": "信頼", "is_correct": false, "explanation": "相手を信じる気持ちを表す語で、誤解と対になる関係ではない。"}, {"text": "失望", "is_correct": false, "explanation": "期待がはずれて落胆することで、誤解の対義語にはならない。"}, {"text": "感謝", "is_correct": false, "explanation": "ありがたく思う気持ちで、受け取り方の正誤を表す誤解とは対にならない。"}], "correct_answer": "理解", "explanations": {"理解": "「誤解」の対義語。相手の言ったことや考えを正しく受け取ること。", "信頼": "相手を信じる気持ちを表す語で、誤解と対になる関係ではない。", "失望": "期待がはずれて落胆することで、誤解の対義語にはならない。", "感謝": "ありがたく思う気持ちで、受け取り方の正誤を表す誤解とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36314, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「誤解を解く」の目的語を示す「を」。解くべき対象を直接示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「誤解に解く」は対象を示す形にならず、「解く」の目的語として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「誤解で解く」は手段の意味になり、解く対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「誤解の解くために」は連体の形にならず、「ために」に続かない。"}], "correct_answer": "を", "explanations": {"を": "「誤解を解く」の目的語を示す「を」。解くべき対象を直接示す正しい格助詞。", "に": "「誤解に解く」は対象を示す形にならず、「解く」の目的語として成り立たない。", "で": "「誤解で解く」は手段の意味になり、解く対象を示せない。", "の": "「誤解の解くために」は連体の形にならず、「ために」に続かない。"}, "error_tags": {"に": "対象の格", "で": "手段", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "「誤解」の対義語。相手の言ったことや考えを正しく受け取ること。"}, {"text": "想像", "is_correct": false, "explanation": "実際にないことを思い描くことで、誤解の対義語ではない。"}, {"text": "予測", "is_correct": false, "explanation": "先のことを推し量ることで、誤解と対になる語ではない。"}, {"text": "賛成", "is_correct": false, "explanation": "同意を表す語で、受け取り方の誤りを表す誤解とは対にならない。"}], "correct_answer": "理解", "explanations": {"理解": "「誤解」の対義語。相手の言ったことや考えを正しく受け取ること。", "想像": "実際にないことを思い描くことで、誤解の対義語ではない。", "予測": "先のことを推し量ることで、誤解と対になる語ではない。", "賛成": "同意を表す語で、受け取り方の誤りを表す誤解とは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36314, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "相手の言ったことや考えを、間違って理解してしまうこと。", "primary_collocate": null, "pronunciation": "ごかい", "ipa": "ɡokai", "syllable_count": 3, "sentences": [{"text": "私の言い方が悪くて、友だちに誤解されてしまった。", "target_word": "誤解されて", "complexity_tier": "T3", "furigana": "私[わたし]の言[い]い方[かた]が悪[わる]くて、友[とも]だちに誤解[ごかい]されてしまった。", "sentence_source": "generated"}, {"text": "話し合ったおかげで、二人の誤解は解けた。", "target_word": "誤解", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]ったおかげで、二人[ふたり]の誤解[ごかい]は解[と]けた。", "sentence_source": "generated"}, {"text": "短いメールは誤解を招くことがある。", "target_word": "誤解", "complexity_tier": "T3", "furigana": "短[みじか]いメールは誤解[ごかい]を招[まね]くことがある。", "sentence_source": "generated"}, {"text": "彼は私の言葉を誤解して、怒って帰ってしまった。", "target_word": "誤解して", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]の言葉[ことば]を誤解[ごかい]して、怒[おこ]って帰[かえ]ってしまった。", "sentence_source": "generated"}, {"text": "誤解がないように、もう一度ゆっくり説明する。", "target_word": "誤解", "complexity_tier": "T3", "furigana": "誤解[ごかい]がないように、もう一度[いちど]ゆっくり説明[せつめい]する。", "sentence_source": "generated"}, {"text": "「行かなくてもいい」は、「来るな」という意味に誤解されやすい。", "target_word": "誤解され", "complexity_tier": "T3", "furigana": "「行[い]かなくてもいい」は、「来[く]るな」という意味[いみ]に誤解[ごかい]されやすい。", "sentence_source": "generated"}, {"text": "彼女は私の冗談を本気だと誤解した。", "target_word": "誤解した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]の冗談[じょうだん]を本気[ほんき]だと誤解[ごかい]した。", "sentence_source": "generated"}, {"text": "誤解を解くために、先生に事情を話した。", "target_word": "誤解", "complexity_tier": "T3", "furigana": "誤解[ごかい]を解[と]くために、先生[せんせい]に事情[じじょう]を話[はな]した。", "sentence_source": "generated"}, {"text": "言葉が足りなかったので、小さな誤解が生まれた。", "target_word": "誤解", "complexity_tier": "T3", "furigana": "言葉[ことば]が足[た]りなかったので、小[ちい]さな誤解[ごかい]が生[う]まれた。", "sentence_source": "generated"}, {"text": "相手の話を最後まで聞かないと、誤解してしまうことがある。", "target_word": "誤解して", "complexity_tier": "T3", "furigana": "相手[あいて]の話[はなし]を最後[さいご]まで聞[き]かないと、誤解[ごかい]してしまうことがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誤解", "label": "名詞形"}, {"form": "誤解する", "label": "辞書形"}, {"form": "誤解した", "label": "た形"}, {"form": "誤解して", "label": "て形"}, {"form": "誤解される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "misunderstanding what another person said or meant", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36314, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誤解されて", "is_correct": true, "explanation": "受身のて形。「友だちに」は誤解する側ではなく誤解される側なので、「〜てしまった」と続く正しい形。"}, {"text": "誤解する", "is_correct": false, "explanation": "辞書形のままでは「友だちに＿しまった」と続かず、文として成り立たない。"}, {"text": "誤解し", "is_correct": false, "explanation": "連用形は「しまった」と重なって「誤解ししまった」になり、不自然。"}, {"text": "誤解された", "is_correct": false, "explanation": "過去形では「誤解されたしまった」となり、「てしまった」の形を作れない。"}], "explanations": {"誤解されて": "受身のて形。「友だちに」は誤解する側ではなく誤解される側なので、「〜てしまった」と続く正しい形。", "誤解する": "辞書形のままでは「友だちに＿しまった」と続かず、文として成り立たない。", "誤解し": "連用形は「しまった」と重なって「誤解ししまった」になり、不自然。", "誤解された": "過去形では「誤解されたしまった」となり、「てしまった」の形を作れない。"}, "sentence_index": 0, "correct_answer": "誤解されて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その地図は誤解が三か所あり、直して配り直した。", "explanation": "ここは〈誤り・誤記〉の意味。誤解は人が相手の言動を取り違えることで、地図の記載の間違いには使わない。"}, {"text": "テレビ局の誤解で、ニュースの映像が逆さに映った。", "explanation": "ここは〈映像の乱れ〉の意味。誤解は人の受け取り違いで、機器が映す映像の不具合には使わない。"}, {"text": "電車の誤解で、ドアが開かなかった。", "explanation": "ここは〈誤作動〉の意味。誤解は人の理解の食い違いで、機械の動作の不具合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36314, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誤解した", "is_correct": true, "explanation": "過去の断定形。「本気だと誤解した」で文が締まる。"}, {"text": "誤解して", "is_correct": false, "explanation": "て形のままでは文が終わらず、述語として成り立たない。"}, {"text": "誤解させず", "is_correct": false, "explanation": "使役の否定形で「彼女が誤解させる」の意味になり、主語と合わず文が成立しない。"}, {"text": "誤解されず", "is_correct": false, "explanation": "受身の否定形で文が締まらず、「彼女は…本気だと」の述語にならない。"}], "explanations": {"誤解した": "過去の断定形。「本気だと誤解した」で文が締まる。", "誤解して": "て形のままでは文が終わらず、述語として成り立たない。", "誤解させず": "使役の否定形で「彼女が誤解させる」の意味になり、主語と合わず文が成立しない。", "誤解されず": "受身の否定形で文が締まらず、「彼女は…本気だと」の述語にならない。"}, "sentence_index": 6, "correct_answer": "誤解した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この測定には、わずかな誤解がある。", "explanation": "ここは〈誤差〉の意味。誤解は人の受け取り違いで、測定値のずれには使わない。"}, {"text": "この製品は、部品の誤解で、すぐに壊れた。", "explanation": "ここは〈欠陥〉の意味。誤解は人の理解の違いを指し、製品の設計上の欠陥や部品の不具合には使わない。"}, {"text": "カメラの誤解で、写真がぼやけてしまった。", "explanation": "ここは〈手ぶれ〉の意味。誤解は人の判断の誤りで、機械の動きによる写りの乱れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36314, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その子は、先生に誤解されしまった。", "corrected_sentence": "その子は、先生に誤解されてしまった。", "error_description": "誤った形は「誤解されしまった」。「しまった」の前に「て」が抜けている。正しくは「誤解されてしまった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36314, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は私の話に本気だと誤解した。", "corrected_sentence": "父は私の話を本気だと誤解した。", "error_description": "誤った形は「話に」の「に」。正しくは「話を」の「を」。「誤解する」は対象を「を」で取る動詞で、「に」では誤解の対象が示せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36315, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「事実を誤解させる」の目的語。他動詞の対象を示す正しい格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「事実へ誤解させる」は方向を示す形になり、誤解させる対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「事実に誤解させる」は相手を示す位置に合わず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「事実と誤解させる」は共同の意味になり、誤解させる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「事実を誤解させる」の目的語。他動詞の対象を示す正しい格助詞。", "へ": "「事実へ誤解させる」は方向を示す形になり、誤解させる対象を示せない。", "に": "「事実に誤解させる」は相手を示す位置に合わず不自然。", "と": "「事実と誤解させる」は共同の意味になり、誤解させる対象を示せない。"}, "error_tags": {"へ": "方向", "に": "相手・方向", "と": "共同・引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "「誤解」の対義語。物事や相手の意図を正しく受け取ること。"}, {"text": "承認", "is_correct": false, "explanation": "相手の存在や考えを認めることで、誤解の対義語ではない。"}, {"text": "失望", "is_correct": false, "explanation": "期待がはずれて落胆することで、誤解と対になる語ではない。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを省みることで、受け取り方の誤りを表す誤解とは対にならない。"}], "correct_answer": "理解", "explanations": {"理解": "「誤解」の対義語。物事や相手の意図を正しく受け取ること。", "承認": "相手の存在や考えを認めることで、誤解の対義語ではない。", "失望": "期待がはずれて落胆することで、誤解と対になる語ではない。", "反省": "自分の行いを省みることで、受け取り方の誤りを表す誤解とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36315, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使い方を誤解する」の目的語。「誤解する」は対象を「を」で取る。"}, {"text": "が", "is_correct": false, "explanation": "「使い方が誤解する」では主語の形になり、他動詞「誤解する」の目的語が欠けて不自然。"}, {"text": "の", "is_correct": false, "explanation": "「使い方の誤解する人」では「使い方」が連体修飾として働き、誤解の対象を示せない。"}, {"text": "か", "is_correct": false, "explanation": "「使い方か誤解する」は選択の意味になり、誤解する対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「使い方を誤解する」の目的語。「誤解する」は対象を「を」で取る。", "が": "「使い方が誤解する」では主語の形になり、他動詞「誤解する」の目的語が欠けて不自然。", "の": "「使い方の誤解する人」では「使い方」が連体修飾として働き、誤解の対象を示せない。", "か": "「使い方か誤解する」は選択の意味になり、誤解する対象を示せない。"}, "error_tags": {"が": "主語・主格", "の": "連体・所属", "か": "選択"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "「誤解」の対義語。相手の言ったことや考えを正しく受け取ること。"}, {"text": "想像", "is_correct": false, "explanation": "実際にないことを思い描くことで、誤解の対義語ではない。"}, {"text": "予測", "is_correct": false, "explanation": "先のことを推し量ることで、誤解と対になる語ではない。"}, {"text": "賛成", "is_correct": false, "explanation": "同意を表す語で、受け取り方の誤りを表す誤解とは対にならない。"}], "correct_answer": "理解", "explanations": {"理解": "「誤解」の対義語。相手の言ったことや考えを正しく受け取ること。", "想像": "実際にないことを思い描くことで、誤解の対義語ではない。", "予測": "先のことを推し量ることで、誤解と対になる語ではない。", "賛成": "同意を表す語で、受け取り方の誤りを表す誤解とは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36315, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "事実や意図を正しく理解せず、違ったふうに受け取ってしまうこと。", "primary_collocate": null, "pronunciation": "ごかい", "ipa": "ɡokai", "syllable_count": 3, "sentences": [{"text": "親切のつもりだったのに、彼は私の意図を誤解した。", "target_word": "誤解した", "complexity_tier": "T3", "furigana": "親切[しんせつ]のつもりだったのに、彼[かれ]は私[わたし]の意図[いと]を誤解[ごかい]した。", "sentence_source": "generated"}, {"text": "その記事は、事実を誤解させる書き方だった。", "target_word": "誤解させる", "complexity_tier": "T3", "furigana": "その記事[きじ]は、事実[じじつ]を誤解[ごかい]させる書[か]き方[かた]だった。", "sentence_source": "generated"}, {"text": "誤解のないよう、契約の内容を紙に書いておく。", "target_word": "誤解", "complexity_tier": "T3", "furigana": "誤解[ごかい]のないよう、契約[けいやく]の内容[ないよう]を紙[かみ]に書[か]いておく。", "sentence_source": "generated"}, {"text": "彼が冷たいというのは、みんなの誤解だ。", "target_word": "誤解", "complexity_tier": "T3", "furigana": "彼[かれ]が冷[つめ]たいというのは、みんなの誤解[ごかい]だ。", "sentence_source": "generated"}, {"text": "笑顔で話していたので、承知したと誤解してしまった。", "target_word": "誤解して", "complexity_tier": "T3", "furigana": "笑顔[えがお]で話[はな]していたので、承知[しょうち]したと誤解[ごかい]してしまった。", "sentence_source": "generated"}, {"text": "私が黙っていたのを、同意だと誤解されて困った。", "target_word": "誤解されて", "complexity_tier": "T3", "furigana": "私[わたし]が黙[だま]っていたのを、同意[どうい]だと誤解[ごかい]されて困[こま]った。", "sentence_source": "generated"}, {"text": "小さな誤解から、二人の仲が悪くなってしまった。", "target_word": "誤解", "complexity_tier": "T3", "furigana": "小[ちい]さな誤解[ごかい]から、二人[ふたり]の仲[なか]が悪[わる]くなってしまった。", "sentence_source": "generated"}, {"text": "説明書の図が分かりにくくて、使い方を誤解する人が多い。", "target_word": "誤解する", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]の図[ず]が分[わ]かりにくくて、使[つか]い方[かた]を誤解[ごかい]する人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "彼女の気持ちを誤解していたことに、やっと気づいた。", "target_word": "誤解して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の気持[きも]ちを誤解[ごかい]していたことに、やっと気[き]づいた。", "sentence_source": "generated"}, {"text": "事実を誤解したまま、人に話してはいけない。", "target_word": "誤解した", "complexity_tier": "T3", "furigana": "事実[じじつ]を誤解[ごかい]したまま、人[ひと]に話[はな]してはいけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誤解", "label": "名詞形"}, {"form": "誤解する", "label": "辞書形"}, {"form": "誤解した", "label": "た形"}, {"form": "誤解して", "label": "て形"}, {"form": "誤解される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "taking a fact or intention the wrong way instead of grasping it correctly", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36315, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誤解した", "is_correct": true, "explanation": "過去の断定形。「彼は私の意図を誤解した」で文が締まる。"}, {"text": "誤解して", "is_correct": false, "explanation": "て形では文が終わらず、「のに」の後の述語にならない。"}, {"text": "誤解せず", "is_correct": false, "explanation": "否定の連用形で文を締められず、主節として成り立たない。"}, {"text": "誤解されず", "is_correct": false, "explanation": "受身の否定形にすると「意図が誤解される」の関係になり、主語の「彼は」と合わない。"}], "explanations": {"誤解した": "過去の断定形。「彼は私の意図を誤解した」で文が締まる。", "誤解して": "て形では文が終わらず、「のに」の後の述語にならない。", "誤解せず": "否定の連用形で文を締められず、主節として成り立たない。", "誤解されず": "受身の否定形にすると「意図が誤解される」の関係になり、主語の「彼は」と合わない。"}, "sentence_index": 0, "correct_answer": "誤解した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その数字は誤解が多く、計算し直した。", "explanation": "ここは〈誤り・誤記〉の意味。誤解は人の理解の食い違いで、数字の書き間違いには使わない。"}, {"text": "この時計は、一日に誤解が三分ある。", "explanation": "ここは〈誤差〉の意味。誤解は人の受け取り違いで、時計の狂いの量には使わない。"}, {"text": "その電車は、事故のため誤解で三十分遅れた。", "explanation": "ここは〈遅延〉の意味。誤解は人の理解の食い違いで、電車の遅れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36315, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誤解", "is_correct": true, "explanation": "名詞。「小さな＋名詞＋から」の形で、原因を示せる。"}, {"text": "誤解する", "is_correct": false, "explanation": "動詞の辞書形で、「小さな」の後に名詞として続かない。"}, {"text": "誤解させ", "is_correct": false, "explanation": "使役の連用形で、名詞の位置に入らない。"}, {"text": "誤解されて", "is_correct": false, "explanation": "受身のて形で、「小さな」の後に続かない。"}], "explanations": {"誤解": "名詞。「小さな＋名詞＋から」の形で、原因を示せる。", "誤解する": "動詞の辞書形で、「小さな」の後に名詞として続かない。", "誤解させ": "使役の連用形で、名詞の位置に入らない。", "誤解されて": "受身のて形で、「小さな」の後に続かない。"}, "sentence_index": 6, "correct_answer": "誤解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その雑誌は、人名の誤解が三か所あった。", "explanation": "ここは〈誤植〉の意味。誤解は人の考えの取り違いで、印刷物の文字の間違いには使わない。"}, {"text": "床板の誤解で、ドアが閉まらなくなった。", "explanation": "ここは〈歪み〉の意味。誤解は人の受け取り違いで、木材や建具のゆがみには使わない。"}, {"text": "テストで、誤解を三つ書いてしまった。", "explanation": "ここは〈誤答〉の意味。答案の間違いには誤答を使い、誤解は人の理解の違いを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36315, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は私の言葉に誤解して、怒った。", "corrected_sentence": "彼は私の言葉を誤解して、怒った。", "error_description": "誤った形は「言葉に」の「に」。正しくは「言葉を」の「を」。「誤解して」は対象を「を」で取るので、「に」では誤解の対象が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36315, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小さな誤解したので、二人の仲が悪くなった。", "corrected_sentence": "小さな誤解が生じたので、二人の仲が悪くなった。", "error_description": "誤った形は「誤解した」。「小さな」は名詞にしか続かないので、動詞形の「誤解した」は「小さな」の後に置けない。名詞「誤解」に「が生じた」を続けて「小さな誤解が生じた」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36316, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寝る", "is_correct": true, "explanation": "「起きる」（目がさめて体を起こす）の対義語。眠ること。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の動作を表す動詞で、起きる（目覚め）の対義語ではない。"}, {"text": "押す", "is_correct": false, "explanation": "力を加える動作の動詞で、対義語の関係にはない。"}, {"text": "捨てる", "is_correct": false, "explanation": "物を手放す動詞で、起きるの対義語ではない。"}], "correct_answer": "寝る", "explanations": {"寝る": "「起きる」（目がさめて体を起こす）の対義語。眠ること。", "歩く": "移動の動作を表す動詞で、起きる（目覚め）の対義語ではない。", "押す": "力を加える動作の動詞で、対義語の関係にはない。", "捨てる": "物を手放す動詞で、起きるの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36316, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「十時ごろに起きる」の時点を示す「に」。時刻を表す正しい格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「十時ごろを起きる」は目的語にならず、「起きる」は自動詞なので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、時刻の「十時ごろへ」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、「十時ごろと起きる」では時刻を表せない。"}], "correct_answer": "に", "explanations": {"に": "「十時ごろに起きる」の時点を示す「に」。時刻を表す正しい格助詞。", "を": "「十時ごろを起きる」は目的語にならず、「起きる」は自動詞なので不自然。", "へ": "「へ」は方向を示すので、時刻の「十時ごろへ」は合わない。", "と": "「と」は並列や相手を示し、「十時ごろと起きる」では時刻を表せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寝る", "is_correct": true, "explanation": "「起きる」（目がさめて体を起こす）の対義語。眠ること。"}, {"text": "走る", "is_correct": false, "explanation": "移動の動作を表す動詞で、起きるの対義語ではない。"}, {"text": "届ける", "is_correct": false, "explanation": "物を相手に運ぶ動作の動詞で、対義語の関係にはない。"}, {"text": "集める", "is_correct": false, "explanation": "物をまとめる動作の動詞で、起きるの対義語ではない。"}], "correct_answer": "寝る", "explanations": {"寝る": "「起きる」（目がさめて体を起こす）の対義語。眠ること。", "走る": "移動の動作を表す動詞で、起きるの対義語ではない。", "届ける": "物を相手に運ぶ動作の動詞で、対義語の関係にはない。", "集める": "物をまとめる動作の動詞で、起きるの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36316, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ねている人が目をさまして、からだを起こすこと。", "primary_collocate": null, "pronunciation": "おきる", "ipa": "okiɾɯ", "syllable_count": 3, "sentences": [{"text": "毎朝六時に起きる。", "target_word": "起きる", "complexity_tier": "T3", "furigana": "毎朝(まいあさ)六時(ろくじ)に起(お)きる。", "sentence_source": "generated"}, {"text": "弟はまだ起きていない。", "target_word": "起きていない", "complexity_tier": "T3", "furigana": "弟(おとうと)はまだ起(お)きていない。", "sentence_source": "generated"}, {"text": "昨日は早く寝たので、今朝は五時に起きた。", "target_word": "起きた", "complexity_tier": "T3", "furigana": "昨日(きのう)は早(はや)く寝(ね)たので、今朝(けさ)は五時(ごじ)に起(お)きた。", "sentence_source": "generated"}, {"text": "目覚まし時計が鳴っても、兄は起きない。", "target_word": "起きない", "complexity_tier": "T3", "furigana": "目覚(めざ)まし時計(どけい)が鳴(な)っても、兄(あに)は起(お)きない。", "sentence_source": "generated"}, {"text": "母は私より早く起きて、朝ごはんを作る。", "target_word": "起きて", "complexity_tier": "T3", "furigana": "母(はは)は私(わたし)より早(はや)く起(お)きて、朝(あさ)ごはんを作(つく)る。", "sentence_source": "generated"}, {"text": "夜中に雷の音で起きてしまった。", "target_word": "起きてしまった", "complexity_tier": "T3", "furigana": "夜中(よなか)に雷(かみなり)の音(おと)で起(お)きてしまった。", "sentence_source": "generated"}, {"text": "明日は大事な試験なので、早く起きなければならない。", "target_word": "起きなければ", "complexity_tier": "T3", "furigana": "明日(あした)は大事(だいじ)な試験(しけん)なので、早(はや)く起(お)きなければならない。", "sentence_source": "generated"}, {"text": "日曜日は遅くまで寝て、十時ごろに起きる。", "target_word": "起きる", "complexity_tier": "T3", "furigana": "日曜日(にちようび)は遅(おそ)くまで寝(ね)て、十時(じゅうじ)ごろに起(お)きる。", "sentence_source": "generated"}, {"text": "赤ちゃんが起きる前に、静かに部屋を出た。", "target_word": "起きる", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんが起(お)きる前(まえ)に、静(しず)かに部屋(へや)を出(で)た。", "sentence_source": "generated"}, {"text": "病気の祖父は、もう自分で起きることができる。", "target_word": "起きる", "complexity_tier": "T3", "furigana": "病気(びょうき)の祖父(そふ)は、もう自分(じぶん)で起(お)きることができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起きる", "label": "終止形"}, {"form": "起きない", "label": "否定形"}, {"form": "起きます", "label": "丁寧形"}, {"form": "起きて", "label": "て形"}, {"form": "起きた", "label": "た形"}, {"form": "起きれば", "label": "仮定形"}, {"form": "起きよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "ねむりからさめて、からだを起こす（目がさめる・床から出る）意味の起きる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36316, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起きる", "is_correct": true, "explanation": "辞書形。「毎朝六時に起きる」と習慣を述べて文が締まる。"}, {"text": "起き", "is_correct": false, "explanation": "連用形では文を締められず、「毎朝六時に」の述語にならない。"}, {"text": "起きて", "is_correct": false, "explanation": "て形では文が終わらず、述語として成り立たない。"}, {"text": "起きれ", "is_correct": false, "explanation": "命令としても可能としても成り立たず、習慣を述べる文に合わない。"}], "explanations": {"起きる": "辞書形。「毎朝六時に起きる」と習慣を述べて文が締まる。", "起き": "連用形では文を締められず、「毎朝六時に」の述語にならない。", "起きて": "て形では文が終わらず、述語として成り立たない。", "起きれ": "命令としても可能としても成り立たず、習慣を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "起きる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝ている祖父を、そっと起きた。", "explanation": "ここは〈起こす〉の意味。起きるは自分が体を起こすことで、他人を目覚めさせるのは「起こす」。"}, {"text": "夜の町で大きな火事が起きた。", "explanation": "ここは〈発生〉の意味。目がさめて体を起こす意味ではないので、この義項では合わない。"}, {"text": "先生に呼ばれて、その場で起きた。", "explanation": "ここは〈立ち上がる〉の意味。寝ている状態から目がさめる動作ではないので「起きる」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36316, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起きなければ", "is_correct": true, "explanation": "仮定形＋「ならない」で「起きなければならない」（義務）になる正しい形。"}, {"text": "起きない", "is_correct": false, "explanation": "「起きないならない」となり、義務の「なければならない」の形にならない。"}, {"text": "起きた", "is_correct": false, "explanation": "「起きたならない」は成り立たず、義務の言い方にならない。"}, {"text": "起きよう", "is_correct": false, "explanation": "意志形では「起きようならない」となり、不自然。"}], "explanations": {"起きなければ": "仮定形＋「ならない」で「起きなければならない」（義務）になる正しい形。", "起きない": "「起きないならない」となり、義務の「なければならない」の形にならない。", "起きた": "「起きたならない」は成り立たず、義務の言い方にならない。", "起きよう": "意志形では「起きようならない」となり、不自然。"}, "sentence_index": 6, "correct_answer": "起きなければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この村では、毎年たくさんの子どもが起きる。", "explanation": "ここは〈生まれる〉の意味。「起きる」は目がさめる・発生する意味で、子どもの誕生には使わない。"}, {"text": "昼になると、客が起きて店が混んだ。", "explanation": "ここは〈増える〉の意味。「起きる」は人が寝床から体を起こすことや出来事の発生を指し、人数の増加には使わない。"}, {"text": "風船が起きて、大きくなった。", "explanation": "ここは〈膨らむ〉の意味。「起きる」は物の体積の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36316, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は目覚まし時計が鳴っても、起きなない。", "corrected_sentence": "祖母は目覚まし時計が鳴っても、起きない。", "error_description": "誤った形は「起きなない」（否定形の活用の誤り）。正しい否定形は「起きない」で、「なない」と重ねると日本語として不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "起きていない", "is_correct": true, "explanation": "「まだ〜ていない」で、まだその状態になっていないことを表す正しい形。"}, {"text": "起きて", "is_correct": false, "explanation": "て形では文が終わらず、「弟はまだ＿。」が成立しない。"}, {"text": "起きれば", "is_correct": false, "explanation": "仮定形は「〜ば」に続く必要があり、文として未完。"}, {"text": "起きたら", "is_correct": false, "explanation": "「たら」は条件を示して文を未完にするので、文を締められない。"}], "correct_form": "起きていない", "base_form": "起きる", "form_label": "〜ていない（否定の状態）", "sentence_index": 1, "explanations": {"起きていない": "「まだ〜ていない」で、まだその状態になっていないことを表す正しい形。", "起きて": "て形では文が終わらず、「弟はまだ＿。」が成立しない。", "起きれば": "仮定形は「〜ば」に続く必要があり、文として未完。", "起きたら": "「たら」は条件を示して文を未完にするので、文を締められない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36316, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は毎日、七時へ起きる。", "corrected_sentence": "私は毎日、七時に起きる。", "error_description": "誤った形は「七時へ」の「へ」。正しくは時刻を示す「に」。「へ」は方向を表すので、時刻に続く「起きる」とは合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "起きる", "is_correct": true, "explanation": "辞書形で、習慣として決まった時刻に目覚めることを表す。"}, {"text": "起きられ", "is_correct": false, "explanation": "可能形の語幹で、文を締められず「十時ごろに＿。」の述語にならない。"}, {"text": "起きず", "is_correct": false, "explanation": "否定の連用形で、文を締められず述語にならない。"}, {"text": "起きたり", "is_correct": false, "explanation": "並列の形で、文を締めくくれない。"}], "correct_form": "起きる", "base_form": "起きる", "form_label": "辞書形（習慣）", "sentence_index": 7, "explanations": {"起きる": "辞書形で、習慣として決まった時刻に目覚めることを表す。", "起きられ": "可能形の語幹で、文を締められず「十時ごろに＿。」の述語にならない。", "起きず": "否定の連用形で、文を締められず述語にならない。", "起きたり": "並列の形で、文を締めくくれない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36318, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「相手がいる」の主語を示す「が」。「いる」は存在する主体を「が」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所を示すが、「相手」は場所ではなく「いない」の主語になるので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「相手でいない」は文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。「相手をいなくて」は「いない」の主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「相手がいる」の主語を示す「が」。「いる」は存在する主体を「が」で示す。", "に": "「に」は場所を示すが、「相手」は場所ではなく「いない」の主語になるので合わない。", "で": "「で」は場所や手段を表す。「相手でいない」は文が成り立たない。", "を": "「を」は動作の対象を示す。「相手をいなくて」は「いない」の主語として成り立たない。"}, "error_tags": {"に": "場所", "で": "手段", "を": "対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36318, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ペアを組む相手」を話題として示す「は」。「くじで決める」の対象を提示している。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「決める」の対象にはならず、「相手へくじで決める」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「相手でくじで決める」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ。「相手のくじで決める」では決める対象が示せない。"}], "correct_answer": "は", "explanations": {"は": "「ペアを組む相手」を話題として示す「は」。「くじで決める」の対象を提示している。", "へ": "「へ」は方向を表すが、「決める」の対象にはならず、「相手へくじで決める」は成り立たない。", "で": "「で」は手段や場所を表す。「相手でくじで決める」は意味が通らない。", "の": "「の」は名詞どうしをつなぐ。「相手のくじで決める」では決める対象が示せない。"}, "error_tags": {"へ": "方向", "で": "手段", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36318, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あなたと一緒に何かをする人のことです。", "primary_collocate": null, "pronunciation": "あいて", "ipa": "ai̯te", "syllable_count": 3, "sentences": [{"text": "テニスの相手を探しているので、日曜日に一緒にやらないか。", "target_word": "相手", "complexity_tier": "T3", "furigana": "テニスの相手[あいて]を探[さが]しているので、日曜日[にちようび]に一緒[いっしょ]にやらないか。", "sentence_source": "generated"}, {"text": "彼は将棋の相手がいなくて、さびしそうだ。", "target_word": "相手", "complexity_tier": "T3", "furigana": "彼[かれ]は将棋[しょうぎ]の相手[あいて]がいなくて、さびしそうだ。", "sentence_source": "generated"}, {"text": "ダンスの相手が急に来られなくなって、困った。", "target_word": "相手", "complexity_tier": "T3", "furigana": "ダンスの相手[あいて]が急[きゅう]に来[こ]られなくなって、困[こま]った。", "sentence_source": "generated"}, {"text": "練習の相手になってくれて、ありがとう。", "target_word": "相手", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の相手[あいて]になってくれて、ありがとう。", "sentence_source": "generated"}, {"text": "英会話の相手がいると、上達が早い。", "target_word": "相手", "complexity_tier": "T3", "furigana": "英会話[えいかいわ]の相手[あいて]がいると、上達[じょうたつ]が早[はや]い。", "sentence_source": "generated"}, {"text": "毎朝のジョギングの相手は、いつも同じ大学の友人だ。", "target_word": "相手", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]のジョギングの相手[あいて]は、いつも同[おな]じ大学[だいがく]の友人[ゆうじん]だ。", "sentence_source": "generated"}, {"text": "卓球の相手が強すぎて、一度も勝てなかった。", "target_word": "相手", "complexity_tier": "T3", "furigana": "卓球[たっきゅう]の相手[あいて]が強[つよ]すぎて、一度[いちど]も勝[か]てなかった。", "sentence_source": "generated"}, {"text": "ペアを組む相手は、くじで決める。", "target_word": "相手", "complexity_tier": "T3", "furigana": "ペアを組[く]む相手[あいて]は、くじで決[き]める。", "sentence_source": "generated"}, {"text": "碁の相手がいなくなって、祖父は一人で石を並べている。", "target_word": "相手", "complexity_tier": "T3", "furigana": "碁[ご]の相手[あいて]がいなくなって、祖父[そふ]は一人[ひとり]で石[いし]を並[なら]べている。", "sentence_source": "generated"}, {"text": "先生がキャッチボールの相手をしてくれた。", "target_word": "相手", "complexity_tier": "T3", "furigana": "先生[せんせい]がキャッチボールの相手[あいて]をしてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "相手", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "スポーツや遊びなど、一緒に何かをする人（パートナー・対戦や練習の相手）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: さびし (Zipf 2.39)']::text[], '612eb789-5ace-4898-ab3a-9c8bb3bd2e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36318, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相手", "is_correct": true, "explanation": "ここは一緒にやる人を指す〈相手〉。「テニスの相手を探す」で、日曜日に一緒に練習する人を求めている。"}, {"text": "得点", "is_correct": false, "explanation": "得点は試合で入る点数で、探す対象にはならない。「テニスの得点を探している」は意味が通らない。"}, {"text": "反則", "is_correct": false, "explanation": "反則は規則違反の行為で、一緒にやる人を求める文の対象にならない。「テニスの反則を探す」は不自然。"}, {"text": "勝敗", "is_correct": false, "explanation": "勝敗は勝ちか負けかの結果で、人を探す文には入らない。「テニスの勝敗を探している」は成り立たない。"}], "explanations": {"相手": "ここは一緒にやる人を指す〈相手〉。「テニスの相手を探す」で、日曜日に一緒に練習する人を求めている。", "得点": "得点は試合で入る点数で、探す対象にはならない。「テニスの得点を探している」は意味が通らない。", "反則": "反則は規則違反の行為で、一緒にやる人を求める文の対象にならない。「テニスの反則を探す」は不自然。", "勝敗": "勝敗は勝ちか負けかの結果で、人を探す文には入らない。「テニスの勝敗を探している」は成り立たない。"}, "sentence_index": 0, "correct_answer": "相手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このボルトの相手は、どこにも見当たらない。", "explanation": "ここは〈ナット〉の意味。相手は一緒に何かをする人を指し、部品を表すことはない。"}, {"text": "テニスの相手を張り替えた。", "explanation": "ここは〈ラケット〉の意味。相手は人との関わりを指し、道具のラケットを表すことはない。"}, {"text": "その店は相手が多く、いつも満席だ。", "explanation": "ここは〈客〉の意味。相手は一緒に何かをする人を指し、店の利用者を表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36318, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相手", "is_correct": true, "explanation": "ここは対戦する相手を指す〈相手〉。「卓球の相手が強すぎて」で、対戦者の強さを述べている。"}, {"text": "目標", "is_correct": false, "explanation": "目標は目指す到達点で、「強すぎて勝てなかった」の主語にはならない。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序で、人の強さを表す文には入らない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は点数をつける行為で、「強すぎて勝てなかった」の主語として成り立たない。"}], "explanations": {"相手": "ここは対戦する相手を指す〈相手〉。「卓球の相手が強すぎて」で、対戦者の強さを述べている。", "目標": "目標は目指す到達点で、「強すぎて勝てなかった」の主語にはならない。", "手順": "手順は作業の順序で、人の強さを表す文には入らない。", "採点": "採点は点数をつける行為で、「強すぎて勝てなかった」の主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "相手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の相手は、公正に判定を下す。", "explanation": "ここは〈審判〉の意味。相手は対戦する側で、判定を下す役ではないので合わない。"}, {"text": "この毛布の相手は、とても暖かい。", "explanation": "ここは〈毛布〉の意味。相手は人との関わりを指し、布製品を表すことはない。"}, {"text": "相手が患者の脈を丁寧に測った。", "explanation": "ここは〈医者〉の意味。相手は一緒に何かをする人で、患者を診る人の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36318, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゴルフの相手を急に休むことになり、予定が崩れた。", "corrected_sentence": "ゴルフの相手が急に休むことになり、予定が崩れた。", "error_description": "「休む」は主語を取る動詞なので、相手には「が」を付ける。「を」は誤りで、正しくは「相手が休む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36318, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次の試合では、私が相手を担うことになった。", "corrected_sentence": "次の試合では、私が相手を務めることになった。", "error_description": "「相手」の役を引き受ける意味では「務める」が正しい。「担う」は責任や役割を負う意味で、「相手を担う」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36319, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「結婚する相手」を話題として示す「は」。自分で決めたいという内容の主題を提示している。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「相手で自分で決めたい」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「相手へ自分で決めたい」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「相手から自分で決めたい」は文の内容に合わない。"}], "correct_answer": "は", "explanations": {"は": "「結婚する相手」を話題として示す「は」。自分で決めたいという内容の主題を提示している。", "で": "「で」は場所や手段を表す。「相手で自分で決めたい」は意味が通らない。", "へ": "「へ」は方向を表す。「相手へ自分で決めたい」は成り立たない。", "から": "「から」は起点を表す。「相手から自分で決めたい」は文の内容に合わない。"}, "error_tags": {"で": "手段", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36319, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「約束を守らなかった」の主語を示す「が」。相手が約束を守らなかったことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。「相手を約束を守らなかった」は「を」が二つ並び、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「相手で約束を守らなかった」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、主語を示せず「相手へ約束を守らなかった」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「約束を守らなかった」の主語を示す「が」。相手が約束を守らなかったことを表す。", "を": "「を」は動作の対象を示す。「相手を約束を守らなかった」は「を」が二つ並び、文として成り立たない。", "で": "「で」は場所や手段を表す。「相手で約束を守らなかった」は意味が通らない。", "へ": "「へ」は方向を表すが、主語を示せず「相手へ約束を守らなかった」は成り立たない。"}, "error_tags": {"を": "対象", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36319, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分以外の人。特に、自分と関わり合いがある人を指します。", "primary_collocate": null, "pronunciation": "あいて", "ipa": "ai̯te", "syllable_count": 3, "sentences": [{"text": "相手の気持ちを考えて話すことが大切だ。", "target_word": "相手", "complexity_tier": "T3", "furigana": "相手[あいて]の気持[きも]ちを考[かんが]えて話[はな]すことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "結婚する相手は、自分で決めたいと思っている。", "target_word": "相手", "complexity_tier": "T3", "furigana": "結婚[けっこん]する相手[あいて]は、自分[じぶん]で決[き]めたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "相手が怒っているときは、まず静かに話を聞く。", "target_word": "相手", "complexity_tier": "T3", "furigana": "相手[あいて]が怒[おこ]っているときは、まず静[しず]かに話[はなし]を聞[き]く。", "sentence_source": "generated"}, {"text": "電話の相手の声が小さくて、よく聞こえなかった。", "target_word": "相手", "complexity_tier": "T3", "furigana": "電話[でんわ]の相手[あいて]の声[こえ]が小[ちい]さくて、よく聞[き]こえなかった。", "sentence_source": "generated"}, {"text": "交渉の相手に、こちらの条件を伝えた。", "target_word": "相手", "complexity_tier": "T3", "furigana": "交渉[こうしょう]の相手[あいて]に、こちらの条件[じょうけん]を伝[つた]えた。", "sentence_source": "generated"}, {"text": "相手にうそをつくと、信用をなくしてしまう。", "target_word": "相手", "complexity_tier": "T3", "furigana": "相手[あいて]にうそをつくと、信用[しんよう]をなくしてしまう。", "sentence_source": "generated"}, {"text": "初めて会う相手には、きちんとあいさつをする。", "target_word": "相手", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]う相手[あいて]には、きちんとあいさつをする。", "sentence_source": "generated"}, {"text": "取引の相手が約束を守らなかったので、契約をやめた。", "target_word": "相手", "complexity_tier": "T3", "furigana": "取引[とりひき]の相手[あいて]が約束[やくそく]を守[まも]らなかったので、契約[けいやく]をやめた。", "sentence_source": "generated"}, {"text": "相手の立場に立って考えれば、けんかは減る。", "target_word": "相手", "complexity_tier": "T3", "furigana": "相手[あいて]の立場[たちば]に立[た]って考[かんが]えれば、けんかは減[へ]る。", "sentence_source": "generated"}, {"text": "相談の相手を間違えると、話が広まってしまう。", "target_word": "相手", "complexity_tier": "T3", "furigana": "相談[そうだん]の相手[あいて]を間違[まちが]えると、話[はなし]が広[ひろ]まってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "相手", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "話・交渉・結婚など、自分が関わる自分以外の人（相手方）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '612eb789-5ace-4898-ab3a-9c8bb3bd2e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36319, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相手", "is_correct": true, "explanation": "ここは話す向こうの人を指す〈相手〉。相手の気持ちを考えて話す、という意味になる。"}, {"text": "連絡先", "is_correct": false, "explanation": "連絡先は連絡をとるための情報で、気持ちを持たないので「気持ちを考える」対象にならない。"}, {"text": "話題", "is_correct": false, "explanation": "話題は話の内容で、気持ちを考える対象としては合わない。「話題の気持ち」は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は書かれたものなので、その気持ちを考えて話す、という文は成り立たない。"}], "explanations": {"相手": "ここは話す向こうの人を指す〈相手〉。相手の気持ちを考えて話す、という意味になる。", "連絡先": "連絡先は連絡をとるための情報で、気持ちを持たないので「気持ちを考える」対象にならない。", "話題": "話題は話の内容で、気持ちを考える対象としては合わない。「話題の気持ち」は成り立たない。", "手紙": "手紙は書かれたものなので、その気持ちを考えて話す、という文は成り立たない。"}, "sentence_index": 0, "correct_answer": "相手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "落とし物の相手は、すぐに見つかった。", "explanation": "ここは〈持ち主〉の意味。相手は話や関わりのある人を指し、物の所有者には使わない。"}, {"text": "この小説の相手は、全部で三百ページある。", "explanation": "ここは〈分量〉の意味。相手は人との関わりを指し、本のページ数や長さを表すことはない。"}, {"text": "このナイフの相手は、とてもよく切れる。", "explanation": "ここは〈刃〉の意味。相手は人との関わりを指し、ナイフの切れる部分を表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36319, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相手", "is_correct": true, "explanation": "ここは自分と関わりのある相手を指す〈相手〉。初めて会う人への対応を述べている。"}, {"text": "荷物", "is_correct": false, "explanation": "荷物は運ぶ物で、会う対象ではないので「初めて会う荷物」は不自然。"}, {"text": "景色", "is_correct": false, "explanation": "景色は見るもので、「初めて会う景色」にあいさつをするのは合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は会う対象にならず、「初めて会う天気にあいさつ」は意味が通らない。"}], "explanations": {"相手": "ここは自分と関わりのある相手を指す〈相手〉。初めて会う人への対応を述べている。", "荷物": "荷物は運ぶ物で、会う対象ではないので「初めて会う荷物」は不自然。", "景色": "景色は見るもので、「初めて会う景色」にあいさつをするのは合わない。", "天気": "天気は会う対象にならず、「初めて会う天気にあいさつ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "相手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この服の相手は、一万円もした。", "explanation": "ここは〈値段〉の意味。相手は自分と関わりのある人を指し、品物の価格を表すことはない。"}, {"text": "この鍋の相手は、白菜と豆腐だ。", "explanation": "ここは〈具〉の意味。相手は自分と関わりのある人を指し、鍋に入れる食材を表すことはない。"}, {"text": "この扉の相手は、真鍮でできている。", "explanation": "ここは〈かぎ〉の意味。相手は自分と関わりのある人を指し、扉を開ける道具を表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36319, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "取引の相手を、すぐ謝った。", "corrected_sentence": "取引の相手に、すぐ謝った。", "error_description": "「謝る」は謝る先を「に」で示す。「相手を」は誤りで、正しくは「相手に謝る」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36319, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相手が立場に立って、話を組み立て直した。", "corrected_sentence": "相手の立場に立って、話を組み立て直した。", "error_description": "「立場」を修飾する「相手」には「の」が必要。「相手が立場」は不自然で、正しくは「相手の立場」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36321, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「尊重する」は相手の立場や考えを目的語に取るので、「意見を尊重する」のように「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「文化が尊重しないと」では「文化」が主語になり、尊重の目的語が立たない。"}, {"text": "に", "is_correct": false, "explanation": "「尊重に」は対象を示す形として不自然で、目的語を表す「を」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「尊重へ」は方向を表すが、尊重する対象は方向ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「尊重する」は相手の立場や考えを目的語に取るので、「意見を尊重する」のように「を」が入る。", "が": "「文化が尊重しないと」では「文化」が主語になり、尊重の目的語が立たない。", "に": "「尊重に」は対象を示す形として不自然で、目的語を表す「を」が必要。", "へ": "「尊重へ」は方向を表すが、尊重する対象は方向ではないので合わない。"}, "error_tags": {"が": "主格", "に": "対象・相手", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽視", "is_correct": true, "explanation": "軽視は相手を重んじず低く見ることで、尊重の対義語にあたる。"}, {"text": "協調", "is_correct": false, "explanation": "協調は力を合わせることで、尊重の対義語ではない。"}, {"text": "信頼", "is_correct": false, "explanation": "信頼は相手を信じることで、尊重の対義語にはあたらない。"}, {"text": "配慮", "is_correct": false, "explanation": "配慮は相手に気を配ることで、尊重に近い語であり反対の意味ではない。"}], "correct_answer": "軽視", "explanations": {"軽視": "軽視は相手を重んじず低く見ることで、尊重の対義語にあたる。", "協調": "協調は力を合わせることで、尊重の対義語ではない。", "信頼": "信頼は相手を信じることで、尊重の対義語にはあたらない。", "配慮": "配慮は相手に気を配ることで、尊重に近い語であり反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36321, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「習慣を尊重する」で、尊重の目的語に「を」が入る。"}, {"text": "で", "is_correct": false, "explanation": "「習慣で尊重して」は手段を表し、目的語の関係にならない。"}, {"text": "と", "is_correct": false, "explanation": "「習慣と尊重して」は共同の相手を示すが、尊重する対象を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「習慣の尊重して」では名詞の修飾になり、動詞「尊重して」の目的語が立たない。"}], "correct_answer": "を", "explanations": {"を": "「習慣を尊重する」で、尊重の目的語に「を」が入る。", "で": "「習慣で尊重して」は手段を表し、目的語の関係にならない。", "と": "「習慣と尊重して」は共同の相手を示すが、尊重する対象を表せない。", "の": "「習慣の尊重して」では名詞の修飾になり、動詞「尊重して」の目的語が立たない。"}, "error_tags": {"で": "手段", "と": "共同・相手", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽視", "is_correct": true, "explanation": "軽視は相手を重んじず低く見ることで、尊重の対義語にあたる。"}, {"text": "放任", "is_correct": false, "explanation": "放任は干渉せずに任せることで、尊重の対義語にはあたらない。"}, {"text": "誤解", "is_correct": false, "explanation": "誤解は正しく理解しないことで、尊重の対義語ではない。"}, {"text": "協議", "is_correct": false, "explanation": "協議は相談して話し合うことで、尊重と反対の関係にはない。"}], "correct_answer": "軽視", "explanations": {"軽視": "軽視は相手を重んじず低く見ることで、尊重の対義語にあたる。", "放任": "放任は干渉せずに任せることで、尊重の対義語にはあたらない。", "誤解": "誤解は正しく理解しないことで、尊重の対義語ではない。", "協議": "協議は相談して話し合うことで、尊重と反対の関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36321, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "相手の立場や考え方を大切にし、軽く見たりしないこと。", "primary_collocate": null, "pronunciation": "そんちょう", "ipa": "sontɕoː", "syllable_count": 4, "sentences": [{"text": "会社は社員の立場を尊重し、無理な仕事を頼まなかった。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]の立場[たちば]を尊重[そんちょう]し、無理[むり]な仕事[しごと]を頼[たの]まなかった。", "sentence_source": "generated"}, {"text": "文化の違いを尊重しないと、外国では失敗します。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "文化[ぶんか]の違[ちが]いを尊重[そんちょう]しないと、外国[がいこく]では失敗[しっぱい]します。", "sentence_source": "generated"}, {"text": "子どもの人権を尊重する社会をつくりたい。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "子[こ]どもの人権[じんけん]を尊重[そんちょう]する社会[しゃかい]をつくりたい。", "sentence_source": "generated"}, {"text": "相手の立場を尊重せず、自分の考えだけを押しつけた。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "相手[あいて]の立場[たちば]を尊重[そんちょう]せず、自分[じぶん]の考[かんが]えだけを押[お]しつけた。", "sentence_source": "generated"}, {"text": "少数の意見も尊重するのが、民主主義の考え方だ。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "少数[しょうすう]の意見[いけん]も尊重[そんちょう]するのが、民主主義[みんしゅしゅぎ]の考[かんが]え方[かた]だ。", "sentence_source": "generated"}, {"text": "宗教を尊重する姿勢は、旅行者にも必要です。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "宗教[しゅうきょう]を尊重[そんちょう]する姿勢[しせい]は、旅行者[りょこうしゃ]にも必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "部下の考え方を軽く見ず、尊重する上司が好まれる。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "部下[ぶか]の考[かんが]え方[かた]を軽[かる]く見[み]ず、尊重[そんちょう]する上司[じょうし]が好[この]まれる。", "sentence_source": "generated"}, {"text": "地元の人の習慣を尊重して、静かに見学しました。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "地元[じもと]の人[ひと]の習慣[しゅうかん]を尊重[そんちょう]して、静[しず]かに見学[けんがく]しました。", "sentence_source": "generated"}, {"text": "話し合いでは、反対する人の立場も尊重するべきだ。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いでは、反対[はんたい]する人[ひと]の立場[たちば]も尊重[そんちょう]するべきだ。", "sentence_source": "generated"}, {"text": "相手を軽く見ていたら、尊重しているとは言えない。", "target_word": "尊重", "complexity_tier": "T3", "furigana": "相手[あいて]を軽[かる]く見[み]ていたら、尊重[そんちょう]しているとは言[い]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "尊重", "label": "基本形"}, {"form": "尊重する", "label": "サ変動詞形"}, {"form": "尊重せず", "label": "否定連用形"}, {"form": "尊重し", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "相手の立場・権利・考え方を軽んじず、価値あるものとして扱うこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b68666-ebe4-44b0-8208-b74bdbb1eb7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36321, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尊重", "is_correct": true, "explanation": "「立場を尊重し」が入り、相手の立場を大切にする意味になって、後半の「無理な仕事を頼まなかった」と合う。"}, {"text": "測定", "is_correct": false, "explanation": "立場は長さや量のように測るものではないので、「立場を測定し」は成り立たない。"}, {"text": "摂取", "is_correct": false, "explanation": "摂取は栄養や食べ物を体に取り入れることで、「立場を摂取し」は不自然。"}, {"text": "清掃", "is_correct": false, "explanation": "清掃は場所や物をきれいにすることで、立場を対象にはできない。"}], "explanations": {"尊重": "「立場を尊重し」が入り、相手の立場を大切にする意味になって、後半の「無理な仕事を頼まなかった」と合う。", "測定": "立場は長さや量のように測るものではないので、「立場を測定し」は成り立たない。", "摂取": "摂取は栄養や食べ物を体に取り入れることで、「立場を摂取し」は不自然。", "清掃": "清掃は場所や物をきれいにすることで、立場を対象にはできない。"}, "sentence_index": 0, "correct_answer": "尊重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店長は売り上げを尊重して、接客の時間を減らすよう指示した。", "explanation": "ここは〈重視〉の意味。売り上げを優先して扱うなら重視を使う。尊重は相手の立場や考えを大切にすることで、数字の優先度には使わない。"}, {"text": "兄は弟の失敗を尊重して、大声で叱った。", "explanation": "ここは〈叱る〉の意味。叱るのは強く注意すること。尊重は相手の立場や考えを大切にすることで、叱る意味では合わない。"}, {"text": "この畑は土地の広さを尊重して、野菜を植えた。", "explanation": "ここは〈活かす〉の意味。土地の広さを生かして使う文で、尊重は人の立場や考えを重んじる語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36321, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊重", "is_correct": true, "explanation": "「尊重する上司」は、部下の考えを軽く見ない態度として前半と合う。"}, {"text": "放送", "is_correct": false, "explanation": "放送は電波で情報を伝えることで、考え方を対象にすると意味が通らない。"}, {"text": "展示", "is_correct": false, "explanation": "展示は物を人に見せることで、上司の態度を表す語として合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "採掘は地中から資源を掘り出すことで、人の態度を表す文には入らない。"}], "explanations": {"尊重": "「尊重する上司」は、部下の考えを軽く見ない態度として前半と合う。", "放送": "放送は電波で情報を伝えることで、考え方を対象にすると意味が通らない。", "展示": "展示は物を人に見せることで、上司の態度を表す語として合わない。", "採掘": "採掘は地中から資源を掘り出すことで、人の態度を表す文には入らない。"}, "sentence_index": 6, "correct_answer": "尊重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天候を尊重して、遠足を延期した。", "explanation": "ここは〈考慮〉の意味。天候などの事情を踏まえて判断するのが考慮で、尊重は人の立場や考えを大切にすることなので合わない。"}, {"text": "締め切りが近いので、テストの準備を尊重して、飲み会を断った。", "explanation": "ここは〈優先〉の意味。ほかより先に扱うことを言う文で、尊重は相手の立場や考えを大切にすることなので合わない。"}, {"text": "重い役割を尊重して、責任を果たした。", "explanation": "ここは〈担う〉の意味。役割を引き受けて果たす文で、尊重は立場や考えを大切にする語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36321, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの意見に尊重する学校をつくりたい。", "corrected_sentence": "子どもの意見を尊重する学校をつくりたい。", "error_description": "「尊重する」は目的語に「を」を取るので、「意見に」は誤り。尊重の直前は「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36321, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部下の意見を軽く見ず、尊重し上司は信頼される。", "corrected_sentence": "部下の意見を軽く見ず、尊重する上司は信頼される。", "error_description": "「尊重し」は連用形で、後ろの「上司」を修飾できない。連体形の「尊重する」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
