INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36324, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "何かを指して言うときに使う言葉。", "primary_collocate": null, "pronunciation": "そう", "ipa": "soː", "syllable_count": 2, "sentences": [{"text": "紙はそう持つと、破れにくい。", "target_word": "そう", "complexity_tier": "T3", "furigana": "紙(かみ)はそう持(も)つと、破(やぶ)れにくい。", "sentence_source": "generated"}, {"text": "コーチに言われたとおり、そう構えて待った。", "target_word": "そう", "complexity_tier": "T3", "furigana": "コーチに言[い]われたとおり、そう構[かま]えて待[ま]った。", "sentence_source": "generated"}, {"text": "友達が「鳥みたいだ」と言ったが、確かにそう見える。", "target_word": "そう", "complexity_tier": "T3", "furigana": "友達[ともだち]が「鳥[とり]みたいだ」と言[い]ったが、確[たし]かにそう見[み]える。", "sentence_source": "generated"}, {"text": "腕をそう上げて、ゆっくり息をはく。", "target_word": "そう", "complexity_tier": "T3", "furigana": "腕(うで)をそう上(あ)げて、ゆっくり息(いき)をはく。", "sentence_source": "generated"}, {"text": "「こういうふうに折ってください」と言われたので、紙をそう折った。", "target_word": "そう", "complexity_tier": "T3", "furigana": "「こういうふうに折[お]ってください」と言[い]われたので、紙[かみ]をそう折[お]った。", "sentence_source": "generated"}, {"text": "説明を聞いて、そう感じた人は多いだろう。", "target_word": "そう", "complexity_tier": "T3", "furigana": "説明[せつめい]を聞[き]いて、そう感[かん]じた人[ひと]は多[おお]いだろう。", "sentence_source": "generated"}, {"text": "先生に言われたとおり、答えをそう書いた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "先生[せんせい]に言[い]われたとおり、答[こた]えをそう書[か]いた。", "sentence_source": "generated"}, {"text": "弟は「これぐらいだ」とそう言いながら、手で大きな円をかいた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "弟(おとうと)は「これぐらいだ」とそう言(い)いながら、手(て)で大(おお)きな円(えん)をかいた。", "sentence_source": "generated"}, {"text": "ボタンをそう押すと、機械は動く。", "target_word": "そう", "complexity_tier": "T3", "furigana": "ボタンをそう押[お]すと、機械[きかい]は動[うご]く。", "sentence_source": "generated"}, {"text": "ボールはそう投げると、遠くまで飛ぶ。", "target_word": "そう", "complexity_tier": "T3", "furigana": "ボールはそう投(な)げると、遠(とお)くまで飛(と)ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "そう", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "目の前の様子や動作を指して「そのように」と示す副詞のそう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36324, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "そう", "is_correct": true, "explanation": "紙の持ち方を「そのように」と指す副詞で、「持つと」の前に入る。"}, {"text": "まるで", "is_correct": false, "explanation": "「まるで〜のよう」と比喩の形で使う語で、「まるで持つと」とは続かない。"}, {"text": "ぜひ", "is_correct": false, "explanation": "強い願望や依頼を表す副詞で、持ち方の条件を示す文には合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す語で、紙を持つ動作には合わない。"}], "explanations": {"そう": "紙の持ち方を「そのように」と指す副詞で、「持つと」の前に入る。", "まるで": "「まるで〜のよう」と比喩の形で使う語で、「まるで持つと」とは続かない。", "ぜひ": "強い願望や依頼を表す副詞で、持ち方の条件を示す文には合わない。", "ぐっすり": "眠りの深さを表す語で、紙を持つ動作には合わない。"}, "sentence_index": 0, "correct_answer": "そう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "紙はどう持つと、破れにくい。", "explanation": "ここは〈どう〉（疑問の語）の意味。〈そう〉は前に示した様子を指すが、〈どう〉は答えを求める語なので、断定の文には合わない。"}, {"text": "紙はそれほど持つと、破れにくい。", "explanation": "ここは〈それほど〉（程度）の意味。〈そう〉は様子や動作を指す語で、程度を表す〈それほど〉とは違う。"}, {"text": "合格して、そう嬉しかった。", "explanation": "ここは〈そんなに〉（程度）の意味。様子を指す〈そう〉の用法ではなく、〈そんなに嬉しかった〉と言うのが自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36324, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "そう", "is_correct": true, "explanation": "「答えをそう書いた」で、答えの書き方を指す副詞。"}, {"text": "なるほど", "is_correct": false, "explanation": "納得を表す感動詞的な副詞で、書く動作の様子を指せない。"}, {"text": "なんとも", "is_correct": false, "explanation": "「なんとも言えない」などの形で使う語で、動詞「書いた」を修飾する用法がない。"}, {"text": "いまいち", "is_correct": false, "explanation": "物事の出来が今ひとつであることを表す語で、書き方の様子を示さない。"}], "explanations": {"そう": "「答えをそう書いた」で、答えの書き方を指す副詞。", "なるほど": "納得を表す感動詞的な副詞で、書く動作の様子を指せない。", "なんとも": "「なんとも言えない」などの形で使う語で、動詞「書いた」を修飾する用法がない。", "いまいち": "物事の出来が今ひとつであることを表す語で、書き方の様子を示さない。"}, "sentence_index": 6, "correct_answer": "そう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紙はどんなに持つと、破れにくい。", "explanation": "ここは〈どんなに〉（程度）の意味。〈そう〉は前に示した様子を指すので、程度を問う〈どんなに〉とは合わない。"}, {"text": "紙はいつ持つと、破れにくい。", "explanation": "ここは〈いつ〉（時）の意味。〈そう〉は様子を指す語で、時を表す〈いつ〉とは違う。"}, {"text": "紙はどこで持つと、破れにくい。", "explanation": "ここは〈どこで〉（場所）の意味。〈そう〉は様子を指す語で、場所を表す〈どこで〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36324, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生にそうで言われて、彼は少し笑った。", "corrected_sentence": "先生にそう言われて、彼は少し笑った。", "error_description": "副詞の「そう」の後に「で」を付けた誤り。「そう言われて」と動詞の直前に直接置く。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36324, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宿題は、そうを書くのが正しい。", "corrected_sentence": "宿題は、そう書くのが正しい。", "error_description": "副詞の「そう」に「を」を付けた誤り。「そう書く」と動詞の直前に置く。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
