INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36325, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "前に話したことや、これから話すことを指し示すときに使う言葉。状況や物事を具体的に示す。", "primary_collocate": null, "pronunciation": "そう", "ipa": "soː", "syllable_count": 2, "sentences": [{"text": "「明日は雨だよ。」「私もそう思う。」", "target_word": "そう", "complexity_tier": "T3", "furigana": "「明日(あした)は雨(あめ)だよ。」「私(わたし)もそう思(おも)う。」", "sentence_source": "generated"}, {"text": "彼は「疲れた」と言ったが、私はそう感じなかった。", "target_word": "そう", "complexity_tier": "T3", "furigana": "彼(かれ)は「疲(つか)れた」と言(い)ったが、私(わたし)はそう感(かん)じなかった。", "sentence_source": "generated"}, {"text": "友達に聞くと、みんなそう答えた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "友達(ともだち)に聞(き)くと、みんなそう答(こた)えた。", "sentence_source": "generated"}, {"text": "部長がそう決めたのなら、従うしかない。", "target_word": "そう", "complexity_tier": "T3", "furigana": "部長(ぶちょう)がそう決(き)めたのなら、従(したが)うしかない。", "sentence_source": "generated"}, {"text": "「もう帰るの？」「うん、そうする。」", "target_word": "そう", "complexity_tier": "T3", "furigana": "「もう帰(かえ)るの？」「うん、そうする。」", "sentence_source": "generated"}, {"text": "この映画はおもしろいと聞いたが、見てみると本当にそう感じた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "この映画(えいが)はおもしろいと聞(き)いたが、見(み)てみると本当(ほんとう)にそう感(かん)じた。", "sentence_source": "generated"}, {"text": "先生はそう言うけれど、私にはまだ自信がない。", "target_word": "そう", "complexity_tier": "T3", "furigana": "先生(せんせい)はそう言(い)うけれど、私(わたし)にはまだ自信(じしん)がない。", "sentence_source": "generated"}, {"text": "彼がうそをついたなんて、とてもそうは思えない。", "target_word": "そう", "complexity_tier": "T3", "furigana": "彼(かれ)がうそをついたなんて、とてもそうは思(おも)えない。", "sentence_source": "generated"}, {"text": "値段が高いから買わない。そう決めて店を出た。", "target_word": "そう", "complexity_tier": "T3", "furigana": "値段(ねだん)が高(たか)いから買(か)わない。そう決(き)めて店(みせ)を出(で)た。", "sentence_source": "generated"}, {"text": "ここで待つように、母にそう言われた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "ここで待(ま)つように、母(はは)にそう言(い)われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "そう", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "すでに話に出た内容を「そのように」と受けて指し示す副詞のそう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36325, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "そう", "is_correct": true, "explanation": "前に出た「明日は雨だ」の内容を受けて「そのように」と言う副詞。"}, {"text": "まるで", "is_correct": false, "explanation": "比喩の「まるで〜のよう」と呼応する語で、「私もまるで思う」とは言わない。"}, {"text": "きっと", "is_correct": false, "explanation": "確信を表す副詞で、「私もきっと思う」では意味が通らず、受ける内容がない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す語で、思う内容には合わない。"}], "explanations": {"そう": "前に出た「明日は雨だ」の内容を受けて「そのように」と言う副詞。", "まるで": "比喩の「まるで〜のよう」と呼応する語で、「私もまるで思う」とは言わない。", "きっと": "確信を表す副詞で、「私もきっと思う」では意味が通らず、受ける内容がない。", "ぐっすり": "眠りの深さを表す語で、思う内容には合わない。"}, "sentence_index": 0, "correct_answer": "そう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は雨だと、それほど思う。", "explanation": "ここは〈それほど〉（程度）の意味。〈そう〉は前に話した内容を指すが、〈それほど〉は程度を表すため、この文では合わない。"}, {"text": "明日は雨になると、そうな思う。", "explanation": "ここは〈そうな〉（推量の形）の意味。前の内容を指す〈そう〉を、推量の形と混同している。"}, {"text": "『そうですか』と言って、彼は帰った。", "explanation": "相づちの感動詞で、前の内容を指す副詞の〈そう〉とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36325, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "そう", "is_correct": true, "explanation": "「先生はそう言う」で、前の内容を受けて「そのように」と言う副詞。"}, {"text": "ぜひ", "is_correct": false, "explanation": "願望や依頼を表す副詞で、言う内容を指す文には合わない。"}, {"text": "ぎゅっと", "is_correct": false, "explanation": "強く握る様子を表す語で、「言う」とは結びつかない。"}, {"text": "ずっしり", "is_correct": false, "explanation": "重さを表す語で、話す行為の様子には合わない。"}], "explanations": {"そう": "「先生はそう言う」で、前の内容を受けて「そのように」と言う副詞。", "ぜひ": "願望や依頼を表す副詞で、言う内容を指す文には合わない。", "ぎゅっと": "強く握る様子を表す語で、「言う」とは結びつかない。", "ずっしり": "重さを表す語で、話す行為の様子には合わない。"}, "sentence_index": 6, "correct_answer": "そう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "合格して、そう嬉しかった。", "explanation": "ここは〈そんなに〉（程度）の意味。前の内容を指す〈そう〉ではなく、〈そんなに嬉しかった〉が自然。"}, {"text": "ここで待つように、母にそんなに言われた。", "explanation": "ここは〈そんなに〉（程度）の意味。前の内容を指す〈そう〉ではなく、程度を表す〈そんなに〉。"}, {"text": "友達は、そう安心したので、答えを変えた。", "explanation": "ここは〈そんなに〉（程度）の意味。前の内容を指す〈そう〉の用法ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36325, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "『明日は休みだ』と聞いて、私もそうに思った。", "corrected_sentence": "『明日は休みだ』と聞いて、私もそう思った。", "error_description": "副詞の「そう」に「に」を付けた誤り。「そう思う」と直接動詞に続ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36325, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達はそうが答えたので、安心した。", "corrected_sentence": "友達はそう答えたので、安心した。", "error_description": "副詞の「そう」に「が」を付けた誤り。「そう答えた」と動詞の直前に直接置く。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
