INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36326, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「こと」に続けて「をよく知らない」と、知る対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すため、知る対象を示す文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、知る対象には使わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、知る対象を示す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "「こと」に続けて「をよく知らない」と、知る対象を示す「を」。", "に": "「に」は方向や相手を示すため、知る対象を示す文には合わない。", "で": "「で」は場所や手段を示すため、知る対象には使わない。", "へ": "「へ」は方向を示すため、知る対象を示す文には合わない。"}, "error_tags": {"に": "方向・相手", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36326, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "何かを頭の中でわかるようになること。", "primary_collocate": null, "pronunciation": "しる", "ipa": "ɕiɾɯ", "syllable_count": 2, "sentences": [{"text": "彼の名前を知っている人は少ない。", "target_word": "知っている", "complexity_tier": "T3", "furigana": "彼(かれ)の名前(なまえ)を知(し)っている人(ひと)は少(すく)ない。", "sentence_source": "generated"}, {"text": "私はその事実を知らなかった。", "target_word": "知らなかった", "complexity_tier": "T3", "furigana": "私(わたし)はその事実(じじつ)を知(し)らなかった。", "sentence_source": "generated"}, {"text": "試験の結果を知るのが、少しこわい。", "target_word": "知る", "complexity_tier": "T3", "furigana": "試験(しけん)の結果(けっか)を知(し)るのが、少(すこ)しこわい。", "sentence_source": "generated"}, {"text": "この道は子どものころから知っている。", "target_word": "知っている", "complexity_tier": "T3", "furigana": "この道(みち)は子(こ)どものころから知(し)っている。", "sentence_source": "generated"}, {"text": "彼女がどんな人か知りたいので、話しかけてみた。", "target_word": "知りたい", "complexity_tier": "T3", "furigana": "彼女(かのじょ)がどんな人(ひと)か知(し)りたいので、話(はな)しかけてみた。", "sentence_source": "generated"}, {"text": "自分の力を知ることが、成長の第一歩だ。", "target_word": "知る", "complexity_tier": "T3", "furigana": "自分(じぶん)の力(ちから)を知(し)ることが、成長(せいちょう)の第一歩(だいいっぽ)だ。", "sentence_source": "generated"}, {"text": "答えを知っていても、手をあげなかった。", "target_word": "知っていて", "complexity_tier": "T3", "furigana": "答(こた)えを知(し)っていても、手(て)をあげなかった。", "sentence_source": "generated"}, {"text": "私はこの町のことをよく知らない。", "target_word": "知らない", "complexity_tier": "T3", "furigana": "私(わたし)はこの町(まち)のことをよく知(し)らない。", "sentence_source": "generated"}, {"text": "彼のことを知れば知るほど、好きになる。", "target_word": "知れば", "complexity_tier": "T3", "furigana": "彼(かれ)のことを知(し)れば知(し)るほど、好(す)きになる。", "sentence_source": "generated"}, {"text": "その店の場所を知らなかったので、地図で調べた。", "target_word": "知らなかった", "complexity_tier": "T3", "furigana": "その店(みせ)の場所(ばしょ)を知(し)らなかったので、地図(ちず)で調(しら)べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知る", "label": "終止形"}, {"form": "知らない", "label": "否定形"}, {"form": "知ります", "label": "丁寧形"}, {"form": "知って", "label": "て形"}, {"form": "知った", "label": "た形"}, {"form": "知れば", "label": "仮定形"}, {"form": "知りたい", "label": "願望形"}], "register": "neutral", "sense_fingerprint": "物事や人について、頭の中でわかっている・わかるようになる意味の知る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36326, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知っている", "is_correct": true, "explanation": "人の名前を頭の中で把握している状態を表す。"}, {"text": "食べている", "is_correct": false, "explanation": "飲食の動作を表す語で、名前を把握する意味には合わない。"}, {"text": "運んでいる", "is_correct": false, "explanation": "物を移動させる動作を表す語で、名前には結びつかない。"}, {"text": "投げている", "is_correct": false, "explanation": "物を放る動作を表す語で、「名前を投げている人」は意味が通らない。"}], "explanations": {"知っている": "人の名前を頭の中で把握している状態を表す。", "食べている": "飲食の動作を表す語で、名前を把握する意味には合わない。", "運んでいる": "物を移動させる動作を表す語で、名前には結びつかない。", "投げている": "物を放る動作を表す語で、「名前を投げている人」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "知っている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は友達に新しい予定を知った。", "explanation": "ここは〈知らせた〉の意味。知るは自分が理解することで、人に伝える使い方は合わない。"}, {"text": "その店は地元で知る人ぞ知る名店だ。", "explanation": "「知る人ぞ知る」は一部の人にだけ知られているという慣用句で、頭の中で理解する意味ではない。"}, {"text": "大学で新しい友達と知った。", "explanation": "ここは〈知り合った〉の意味。知るだけでは人と親しくなる意味が出ない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36326, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知っていて", "is_correct": true, "explanation": "答えを頭の中で把握している状態を表し、「知っていても」の形で譲歩を示す。"}, {"text": "押していて", "is_correct": false, "explanation": "ボタンなどを押す動作の語で、答えを知る意味には合わない。"}, {"text": "切っていて", "is_correct": false, "explanation": "物を切断する動作の語で、答えには結びつかない。"}, {"text": "開けていて", "is_correct": false, "explanation": "戸や箱を開く動作の語で、答えの把握を表さない。"}], "explanations": {"知っていて": "答えを頭の中で把握している状態を表し、「知っていても」の形で譲歩を示す。", "押していて": "ボタンなどを押す動作の語で、答えを知る意味には合わない。", "切っていて": "物を切断する動作の語で、答えには結びつかない。", "開けていて": "戸や箱を開く動作の語で、答えの把握を表さない。"}, "sentence_index": 6, "correct_answer": "知っていて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その問題の答えを、友達にすぐ知った。", "explanation": "ここは〈知らせた〉の意味。知るは自分が理解することで、人に伝える使い方は合わない。"}, {"text": "知らぬ間に、雨が降っていた。", "explanation": "「知らぬ間に」は気づかないうちにの慣用句で、頭の中で理解する意味ではない。"}, {"text": "鏡で自分の顔を知った。", "explanation": "ここは〈見た〉の意味。目で確認する動作を、理解する意味の〈知る〉で言うのは不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36326, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その事実は、みんなが知らている。", "corrected_sentence": "その事実は、みんなが知っている。", "error_description": "「知る」の〜ている形は「知っている」。「知らている」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36326, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その道の近道を知っていれは、遅れずに着いた。", "corrected_sentence": "その道の近道を知っていれば、遅れずに着いた。", "error_description": "仮定の形は「知っていれば」。「れは」は誤った形で、「ば」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
