INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36327, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「あの店を知った」で、知る対象を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や相手を示すため、「あの店と知った」では知る対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、知る対象を示す文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を連体修飾する助詞で、知る対象を直接示す「を」の代わりにはならない。"}], "correct_answer": "を", "explanations": {"を": "「あの店を知った」で、知る対象を示す「を」。", "と": "「と」は引用や相手を示すため、「あの店と知った」では知る対象を示せない。", "より": "「より」は比較を示すため、知る対象を示す文には合わない。", "の": "「の」は名詞を連体修飾する助詞で、知る対象を直接示す「を」の代わりにはならない。"}, "error_tags": {"と": "引用・相手", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36327, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "見たり聞いたりして、新しいことを頭の中に入れて理解する。", "primary_collocate": null, "pronunciation": "しる", "ipa": "ɕiɾɯ", "syllable_count": 2, "sentences": [{"text": "ニュースで事故のことを知った。", "target_word": "知った", "complexity_tier": "T3", "furigana": "ニュースで事故(じこ)のことを知(し)った。", "sentence_source": "generated"}, {"text": "手紙を読んで、友達の引っこしを知った。", "target_word": "知った", "complexity_tier": "T3", "furigana": "手紙(てがみ)を読(よ)んで、友達(ともだち)の引(ひ)っこしを知(し)った。", "sentence_source": "generated"}, {"text": "本を読んで、日本の歴史を知ることができた。", "target_word": "知る", "complexity_tier": "T3", "furigana": "本(ほん)を読(よ)んで、日本(にほん)の歴史(れきし)を知(し)ることができた。", "sentence_source": "generated"}, {"text": "旅行に行って、世界には色々な文化があると知った。", "target_word": "知った", "complexity_tier": "T3", "furigana": "旅行(りょこう)に行(い)って、世界(せかい)には色々(いろいろ)な文化(ぶんか)があると知(し)った。", "sentence_source": "generated"}, {"text": "彼のうわさを聞いて、初めて本当のことを知った。", "target_word": "知った", "complexity_tier": "T3", "furigana": "彼(かれ)のうわさを聞(き)いて、初(はじ)めて本当(ほんとう)のことを知(し)った。", "sentence_source": "generated"}, {"text": "テレビで、その病気のことを初めて知った。", "target_word": "知った", "complexity_tier": "T3", "furigana": "テレビで、その病気(びょうき)のことを初(はじ)めて知(し)った。", "sentence_source": "generated"}, {"text": "外国で暮らして、日本のよさを知った。", "target_word": "知った", "complexity_tier": "T3", "furigana": "外国(がいこく)で暮(く)らして、日本(にほん)のよさを知(し)った。", "sentence_source": "generated"}, {"text": "友達から教えてもらって、あの店を知った。", "target_word": "知った", "complexity_tier": "T3", "furigana": "友達(ともだち)から教(おし)えてもらって、あの店(みせ)を知(し)った。", "sentence_source": "generated"}, {"text": "新聞で試合の結果を知り、すぐにお祝いの電話をかけた。", "target_word": "知り", "complexity_tier": "T3", "furigana": "新聞(しんぶん)で試合(しあい)の結果(けっか)を知(し)り、すぐにお祝(いわ)いの電話(でんわ)をかけた。", "sentence_source": "generated"}, {"text": "大学で学んで、広い世界を知った。", "target_word": "知った", "complexity_tier": "T3", "furigana": "大学(だいがく)で学(まな)んで、広(ひろ)い世界(せかい)を知(し)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知る", "label": "終止形"}, {"form": "知らない", "label": "否定形"}, {"form": "知ります", "label": "丁寧形"}, {"form": "知って", "label": "て形"}, {"form": "知った", "label": "た形"}, {"form": "知れば", "label": "仮定形"}, {"form": "知りたい", "label": "願望形"}], "register": "neutral", "sense_fingerprint": "見聞きや経験を通して、新しい事実を初めて理解する意味の知る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3b05b5a-526b-46f9-a217-42197a8670f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36327, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知った", "is_correct": true, "explanation": "ニュースを通して事故を新たに理解した、という意味の過去形。"}, {"text": "運んだ", "is_correct": false, "explanation": "物を移動させる動作の語で、情報を得る意味には合わない。"}, {"text": "投げた", "is_correct": false, "explanation": "物を放る動作の語で、事故のことを知る文には合わない。"}, {"text": "切った", "is_correct": false, "explanation": "物を切断する動作の語で、事故のことを知る意味にはならない。"}], "explanations": {"知った": "ニュースを通して事故を新たに理解した、という意味の過去形。", "運んだ": "物を移動させる動作の語で、情報を得る意味には合わない。", "投げた": "物を放る動作の語で、事故のことを知る文には合わない。", "切った": "物を切断する動作の語で、事故のことを知る意味にはならない。"}, "sentence_index": 0, "correct_answer": "知った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生にテストの結果を知った。", "explanation": "ここは〈知らせた〉の意味。知るは自分が理解することで、人に伝える使い方は合わない。"}, {"text": "その結果は、知る由もなかった。", "explanation": "「知る由もない」は方法がないという慣用句で、新しく理解したことを述べる意味ではない。"}, {"text": "大学の友達と知った。", "explanation": "ここは〈知り合った〉の意味。知るだけでは人と親しくなる意味が出ない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36327, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知った", "is_correct": true, "explanation": "外国での暮らしを通して、日本のよさを新たに理解したという意味。"}, {"text": "押した", "is_correct": false, "explanation": "ボタンなどを押す動作の語で、よさを理解する意味には合わない。"}, {"text": "開けた", "is_correct": false, "explanation": "戸や箱を開く動作の語で、理解の意味にはならない。"}, {"text": "焼いた", "is_correct": false, "explanation": "食べ物を火で加熱する動作の語で、よさを理解する文には合わない。"}], "explanations": {"知った": "外国での暮らしを通して、日本のよさを新たに理解したという意味。", "押した": "ボタンなどを押す動作の語で、よさを理解する意味には合わない。", "開けた": "戸や箱を開く動作の語で、理解の意味にはならない。", "焼いた": "食べ物を火で加熱する動作の語で、よさを理解する文には合わない。"}, "sentence_index": 6, "correct_answer": "知った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その結果は、知らぬ間に出ていた。", "explanation": "「知らぬ間に」は気づかないうちにの慣用句で、新しく理解したことを述べる意味ではない。"}, {"text": "雨が降ったことを、家族に知らせた。", "explanation": "ここは〈知らせた〉の意味。人に伝える使い方で、自分が理解する〈知る〉とは違う。"}, {"text": "その店の値段を、友達に知らせた。", "explanation": "ここは〈知らせた〉の意味。人に伝える使い方で、理解する〈知る〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36327, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅の掲示板で運休を知らた。", "corrected_sentence": "駅の掲示板で運休を知った。", "error_description": "「知る」の過去形は「知った」。「知らた」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36327, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩から合格発表の日を知りた。", "corrected_sentence": "先輩から合格発表の日を知った。", "error_description": "過去形は「知った」。「知りた」は「知りたい」の語幹で、過去の意味にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd216158c-8c42-40e1-8135-4f857634592a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
