INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36328, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」の目的語を示す「を」。「姿勢を見て」で自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「見る」の目的語にはならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、ここでは見る対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の意味で、この文には比べる対象がない。"}], "correct_answer": "を", "explanations": {"を": "「見る」の目的語を示す「を」。「姿勢を見て」で自然に続く。", "が": "「が」は主語を示すが、「見る」の目的語にはならないので合わない。", "に": "「に」は場所や相手を示すが、ここでは見る対象を表せない。", "より": "「より」は比較の意味で、この文には比べる対象がない。"}, "error_tags": {"が": "主語", "に": "到達点・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36328, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体や心の持ち方。立ったり座ったりするときの形。", "primary_collocate": null, "pronunciation": "しせい", "ipa": "ɕiseː", "syllable_count": 3, "sentences": [{"text": "背筋を伸ばして良い姿勢で座ると、疲れにくい。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "背筋[せすじ]を伸[の]ばして良[よ]い姿勢[しせい]で座[すわ]ると、疲[つか]れにくい。", "sentence_source": "generated"}, {"text": "長い時間同じ姿勢でいたので、足がしびれた。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "長[なが]い時間[じかん]同[おな]じ姿勢[しせい]でいたので、足[あし]がしびれた。", "sentence_source": "generated"}, {"text": "先生は生徒の話を最後まで聞く姿勢を大切にしている。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の話[はなし]を最後[さいご]まで聞[き]く姿勢[しせい]を大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "彼は何事にも前向きな姿勢で取り組む。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "彼[かれ]は何事[なにごと]にも前向[まえむ]きな姿勢[しせい]で取[と]り組[く]む。", "sentence_source": "generated"}, {"text": "悪い姿勢で本を読むと、目も背中も痛くなる。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "悪[わる]い姿勢[しせい]で本[ほん]を読[よ]むと、目[め]も背中[せなか]も痛[いた]くなる。", "sentence_source": "generated"}, {"text": "会社は環境を守る姿勢を、はっきりと示した。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は環境[かんきょう]を守[まも]る姿勢[しせい]を、はっきりと示[しめ]した。", "sentence_source": "generated"}, {"text": "ヨガの先生が、正しい姿勢を一つずつ教えてくれた。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "ヨガの先生[せんせい]が、正[ただ]しい姿勢[しせい]を一[ひと]つずつ教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "彼女の学ぶ姿勢を見て、周りの人も勉強を始めた。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の学[まな]ぶ姿勢[しせい]を見[み]て、周[まわ]りの人[ひと]も勉強[べんきょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "寝る姿勢を変えたら、朝の腰の痛みがなくなった。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "寝[ね]る姿勢[しせい]を変[か]えたら、朝[あさ]の腰[こし]の痛[いた]みがなくなった。", "sentence_source": "generated"}, {"text": "政府は問題を解決する姿勢を見せなかったので、批判が出た。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "政府[せいふ]は問題[もんだい]を解決[かいけつ]する姿勢[しせい]を見[み]せなかったので、批判[ひはん]が出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "姿勢", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "体の構え方、または物事に向かう心の構え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36328, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "姿勢", "is_correct": true, "explanation": "体の構えを指し、「良い〜で座ると」に入る語。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、座り方の文脈に入れると気象の話になり意味が通らない。"}, {"text": "機会", "is_correct": false, "explanation": "機会は場面やきっかけを指し、「良い機会で座る」は体の座り方とつながらない。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の段取りのことで、座るときの体の形は表せない。"}], "explanations": {"姿勢": "体の構えを指し、「良い〜で座ると」に入る語。", "天気": "天気は空模様のことで、座り方の文脈に入れると気象の話になり意味が通らない。", "機会": "機会は場面やきっかけを指し、「良い機会で座る」は体の座り方とつながらない。", "手順": "手順は作業の段取りのことで、座るときの体の形は表せない。"}, "sentence_index": 0, "correct_answer": "姿勢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖に映った山の姿勢がとても美しかった。", "explanation": "ここは〈姿〉（見た目）の意味。姿勢は人の体や心の持ち方を指すので、山の見た目には使えない。"}, {"text": "この工事は姿勢が三か月かかる。", "explanation": "ここは〈期間〉の意味。姿勢は体や心の持ち方で、工事にかかる時間の長さは表せない。"}, {"text": "今年の夏は姿勢が不順で、野菜の値段が上がった。", "explanation": "ここは〈天候〉の意味。「不順」は気候について言う語で、体や心の持ち方の姿勢には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36328, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "姿勢", "is_correct": true, "explanation": "体の構えを指し、「正しい〜を教えてくれた」の目的語として自然な語。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人の歳を表すもので、ヨガの体の形を教える文の目的語には合わない。"}, {"text": "残高", "is_correct": false, "explanation": "残高は預金などの金額のことで、体の構えの説明には使えない。"}, {"text": "郵便番号", "is_correct": false, "explanation": "郵便番号は住所に付く数字で、ヨガの先生が教える内容として意味が通らない。"}], "explanations": {"姿勢": "体の構えを指し、「正しい〜を教えてくれた」の目的語として自然な語。", "年齢": "年齢は人の歳を表すもので、ヨガの体の形を教える文の目的語には合わない。", "残高": "残高は預金などの金額のことで、体の構えの説明には使えない。", "郵便番号": "郵便番号は住所に付く数字で、ヨガの先生が教える内容として意味が通らない。"}, "sentence_index": 6, "correct_answer": "姿勢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅までの姿勢が遠いので、タクシーを使った。", "explanation": "ここは〈距離〉の意味。姿勢は体や心の持ち方で、道のりの長さは表せない。"}, {"text": "この部屋の姿勢は十二畳だ。", "explanation": "ここは〈面積〉の意味。姿勢は体の構えのことで、部屋の広さを表す語としては使えない。"}, {"text": "この車は姿勢が速くて、すぐ着いた。", "explanation": "ここは〈速度〉の意味。姿勢は体や心の持ち方で、車の速さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36328, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "面接の前に、姿勢で正して深呼吸した。", "corrected_sentence": "面接の前に、姿勢を正して深呼吸した。", "error_description": "「正す」は目的語を「を」で取る。「姿勢で」は手段の意味になるので誤り。正しくは「姿勢を正す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36328, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "椅子に座るときは、姿勢を正しくください。", "corrected_sentence": "椅子に座るときは、姿勢を正してください。", "error_description": "「正す」のて形は「正して」。「正しく」は形容詞の連用形で、「ください」に続けると命令の形にならないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36330, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「個人が自分で払う」の「が」は、払う主体を示す主格の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示す。「個人を自分で払う」では払う主体にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や位置を示す。「個人に自分で払う」では主体を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「個人へ自分で払う」では主体を表せない。"}], "correct_answer": "が", "explanations": {"が": "「個人が自分で払う」の「が」は、払う主体を示す主格の助詞。", "を": "「を」は対象を示す。「個人を自分で払う」では払う主体にならない。", "に": "「に」は相手や位置を示す。「個人に自分で払う」では主体を表せない。", "へ": "「へ」は方向を示す。「個人へ自分で払う」では主体を表せない。"}, "error_tags": {"を": "対象", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
