INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36330, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一人ひとりの人。", "primary_collocate": null, "pronunciation": "こじん", "ipa": "kodʑiɴ", "syllable_count": 3, "sentences": [{"text": "この店では、個人ごとに好みを聞いてから料理を出す。", "target_word": "個人", "complexity_tier": "T3", "furigana": "この店では、個人[こじん]ごとに好みを聞いてから料理を出す。", "sentence_source": "generated"}, {"text": "旅行の費用は、個人が自分で払うことになっている。", "target_word": "個人", "complexity_tier": "T3", "furigana": "旅行[りょこう]の費用[ひよう]は、個人[こじん]が自分[じぶん]で払[はら]うことになっている。", "sentence_source": "generated"}, {"text": "好きな食べ物は個人によって違う。", "target_word": "個人", "complexity_tier": "T3", "furigana": "好[す]きな食[た]べ物[もの]は個人[こじん]によって違[ちが]う。", "sentence_source": "generated"}, {"text": "趣味は個人の自由なので、他人が口を出すことではない。", "target_word": "個人", "complexity_tier": "T3", "furigana": "趣味[しゅみ]は個人[こじん]の自由[じゆう]なので、他人[たにん]が口[くち]を出[だ]すことではない。", "sentence_source": "generated"}, {"text": "彼は会社の代表ではなく、個人として意見を述べた。", "target_word": "個人", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]の代表[だいひょう]ではなく、個人[こじん]として意見[いけん]を述[の]べた。", "sentence_source": "generated"}, {"text": "この美術館は、個人から団体まで誰でも見学できる。", "target_word": "個人", "complexity_tier": "T3", "furigana": "この美術館[びじゅつかん]は、個人[こじん]から団体[だんたい]まで誰[だれ]でも見学[けんがく]できる。", "sentence_source": "generated"}, {"text": "被害にあった個人には、国から補償金が支払われた。", "target_word": "個人", "complexity_tier": "T3", "furigana": "被害[ひがい]にあった個人[こじん]には、国[くに]から補償金[ほしょうきん]が支払[しはら]われた。", "sentence_source": "generated"}, {"text": "医者として話す前に、まず個人として彼女の話を聞いた。", "target_word": "個人", "complexity_tier": "T3", "furigana": "医者[いしゃ]として話[はな]す前[まえ]に、まず個人[こじん]として彼女[かのじょ]の話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "個人の力は小さいが、集まれば大きな力になる。", "target_word": "個人", "complexity_tier": "T3", "furigana": "個人[こじん]の力[ちから]は小[ちい]さいが、集[あつ]まれば大[おお]きな力[ちから]になる。", "sentence_source": "generated"}, {"text": "町の祭りには、個人や会社から多くの寄付が寄せられた。", "target_word": "個人", "complexity_tier": "T3", "furigana": "町[まち]の祭[まつ]りには、個人[こじん]や会社[かいしゃ]から多[おお]くの寄付[きふ]が寄[よ]せられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "個人", "label": "基本形"}, {"form": "個人の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "会社や団体ではなく、一人ひとりの人そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36330, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "個人", "is_correct": true, "explanation": "「個人ごと」は一人ひとりの客ごとを表し、好みを聞く単位として合う。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は調理に使う道具で、好みを聞く単位にはならない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は料理を盛る器で、好みを聞く単位としては不自然。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、好みを聞く相手や単位としては成り立たない。"}], "explanations": {"個人": "「個人ごと」は一人ひとりの客ごとを表し、好みを聞く単位として合う。", "包丁": "包丁は調理に使う道具で、好みを聞く単位にはならない。", "皿": "皿は料理を盛る器で、好みを聞く単位としては不自然。", "鍋": "鍋は調理器具で、好みを聞く相手や単位としては成り立たない。"}, "sentence_index": 0, "correct_answer": "個人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町内会は、個人として補助金を申請した。", "explanation": "ここは〈団体〉の意味。個人は一人の人を指し、町内会のような集まりには団体を使う。"}, {"text": "予約は一個人につき二名まで受け付けます。", "explanation": "ここは〈名〉の数え方。個人は一人の人を指す語で、人数を数える単位には名を使う。"}, {"text": "この会社は、個人として登記を済ませた。", "explanation": "ここは〈法人〉の意味。会社は法人として登記するもので、個人としては登記できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36330, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "個人", "is_correct": true, "explanation": "個人は一人ひとりの人を表す。被害にあった一人の人に補償が支払われるという文脈に合う。"}, {"text": "補償金", "is_correct": false, "explanation": "補償金は支払われる金銭を指す。「被害にあった補償金」では支払われる相手を表せない。"}, {"text": "支払い", "is_correct": false, "explanation": "支払いは金銭を渡す行為を指す。被害にあった人を表せない。"}, {"text": "治療", "is_correct": false, "explanation": "治療は病気や怪我を治す行為を指す。「被害にあった治療」では人を表せない。"}], "explanations": {"個人": "個人は一人ひとりの人を表す。被害にあった一人の人に補償が支払われるという文脈に合う。", "補償金": "補償金は支払われる金銭を指す。「被害にあった補償金」では支払われる相手を表せない。", "支払い": "支払いは金銭を渡す行為を指す。被害にあった人を表せない。", "治療": "治療は病気や怪我を治す行為を指す。「被害にあった治療」では人を表せない。"}, "sentence_index": 6, "correct_answer": "個人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "個人は、寒さや暑さに慣れて生き延びてきた。", "explanation": "ここは〈人間〉の意味。個人は一人ひとりの人を指し、種としての人間や人類には使わない。"}, {"text": "彼の個人は、話し方にも服装にもよく表れている。", "explanation": "ここは〈個性〉の意味。個人は人そのものを指し、話し方や服装に表れる特徴には個性を使う。"}, {"text": "事故の個人は、まず警察に事情を説明した。", "explanation": "ここは〈当事者〉の意味。個人は立場を表さず、事件に関わる当の人を言うときは当事者を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36330, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は個人な判断で行動した。", "corrected_sentence": "彼女は個人の判断で行動した。", "error_description": "誤りは「個人な」。「個人」は名詞なので形容動詞の「な」は付かない。正しくは「個人の判断」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36330, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の祭りでは、個人な寄付が多く寄せられた。", "corrected_sentence": "町の祭りでは、個人の寄付が多く寄せられた。", "error_description": "誤りは「個人な」。「個人」は名詞なので形容動詞の「な」は付かない。正しくは「個人の寄付」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36331, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36331, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「個人と個人」の「と」は、二つの個人を並べて結ぶ並列の格助詞。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示す。「個人の個人のつながり」では二つを並べられない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。「個人を個人のつながり」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や位置を示す。「個人に個人のつながり」では並べる意味にならない。"}], "correct_answer": "と", "explanations": {"と": "「個人と個人」の「と」は、二つの個人を並べて結ぶ並列の格助詞。", "の": "「の」は所属や修飾を示す。「個人の個人のつながり」では二つを並べられない。", "を": "「を」は動作の対象を示す。「個人を個人のつながり」では文が成り立たない。", "に": "「に」は相手や位置を示す。「個人に個人のつながり」では並べる意味にならない。"}, "error_tags": {"の": "連体修飾", "を": "対象", "に": "位置・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36331, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある集団の中の、一人の人間。", "primary_collocate": null, "pronunciation": "こじん", "ipa": "kodʑiɴ", "syllable_count": 3, "sentences": [{"text": "反逆は、集団の圧力に抗う個人の意志から生まれる。", "target_word": "個人", "complexity_tier": "T3", "furigana": "反逆[はんぎゃく]は、集団[しゅうだん]の圧力[あつりょく]に抗[あらが]う個人[こじん]の意志[いし]から生[う]まれる。", "sentence_source": "generated"}, {"text": "組織の力も大切だが、最後は個人の努力が結果を左右する。", "target_word": "個人", "complexity_tier": "T3", "furigana": "組織[そしき]の力[ちから]も大切[たいせつ]だが、最後[さいご]は個人[こじん]の努力[どりょく]が結果[けっか]を左右[さゆう]する。", "sentence_source": "generated"}, {"text": "会社は、多くの個人が集まってできた集団だ。", "target_word": "個人", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、多[おお]くの個人[こじん]が集[あつ]まってできた集団[しゅうだん]だ。", "sentence_source": "generated"}, {"text": "団体の決定に、個人が逆らうのは簡単ではない。", "target_word": "個人", "complexity_tier": "T3", "furigana": "団体[だんたい]の決定[けってい]に、個人[こじん]が逆[さか]らうのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "国は、個人の権利を守るために法律を作っている。", "target_word": "個人", "complexity_tier": "T3", "furigana": "国[くに]は、個人[こじん]の権利[けんり]を守[まも]るために法律[ほうりつ]を作[つく]っている。", "sentence_source": "generated"}, {"text": "全体の利益と個人の利益がぶつかることもある。", "target_word": "個人", "complexity_tier": "T3", "furigana": "全体[ぜんたい]の利益[りえき]と個人[こじん]の利益[りえき]がぶつかることもある。", "sentence_source": "generated"}, {"text": "大きな集団の中で、個人の声は消えてしまいがちだ。", "target_word": "個人", "complexity_tier": "T3", "furigana": "大[おお]きな集団[しゅうだん]の中[なか]で、個人[こじん]の声[こえ]は消[き]えてしまいがちだ。", "sentence_source": "generated"}, {"text": "社会は、個人と個人のつながりで成り立っている。", "target_word": "個人", "complexity_tier": "T3", "furigana": "社会[しゃかい]は、個人[こじん]と個人[こじん]のつながりで成[な]り立[た]っている。", "sentence_source": "generated"}, {"text": "軍隊では、個人よりも部隊としての行動が優先される。", "target_word": "個人", "complexity_tier": "T3", "furigana": "軍隊[ぐんたい]では、個人[こじん]よりも部隊[ぶたい]としての行動[こうどう]が優先[ゆうせん]される。", "sentence_source": "generated"}, {"text": "学校は、生徒という個人を、集団の中で育てる場所でもある。", "target_word": "個人", "complexity_tier": "T3", "furigana": "学校[がっこう]は、生徒[せいと]という個人[こじん]を、集団[しゅうだん]の中[なか]で育[そだ]てる場所[ばしょ]でもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "個人", "label": "基本形"}, {"form": "個人の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "組織・集団・社会を構成する一人ひとりの人間（集団と対比される存在）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36331, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "個人", "is_correct": true, "explanation": "個人は集団の中の一人ひとりを指す。集団の圧力に抗う主体として合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は空模様を指し、意志の持ち主にならないので「雨の意志」は成り立たない。"}, {"text": "机", "is_correct": false, "explanation": "机は家具で、意志を持つ主体にならないので「机の意志」は成り立たない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、意志の主体にならないので「鍋の意志」は成り立たない。"}], "explanations": {"個人": "個人は集団の中の一人ひとりを指す。集団の圧力に抗う主体として合う。", "雨": "雨は空模様を指し、意志の持ち主にならないので「雨の意志」は成り立たない。", "机": "机は家具で、意志を持つ主体にならないので「机の意志」は成り立たない。", "鍋": "鍋は調理器具で、意志の主体にならないので「鍋の意志」は成り立たない。"}, "sentence_index": 0, "correct_answer": "個人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その会社は、個人として税務署に届け出た。", "explanation": "ここは〈法人〉の意味。個人は一人の人を指し、会社などの組織の登録主体には法人を使う。"}, {"text": "この池には、個人の金魚が三十匹いる。", "explanation": "ここは〈個体〉の意味。個人は人に使う語で、金魚などの生き物一匹には個体を使う。"}, {"text": "この注文の個人は三つです。", "explanation": "ここは〈個数〉の意味。個人は一人の人を指し、注文した品物の数には個数を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36331, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "個人", "is_correct": true, "explanation": "個人は集団の中の一人ひとりの人を表す。集団の中で声が埋もれる人について言う文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様を表す語で、声を持つ人の代わりにはならないので、「天気の声」は文として成り立たない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖」は甘味料の名で、声を出す持ち主にはならないので合わない。"}, {"text": "台所", "is_correct": false, "explanation": "「台所」は料理をする場所で、声の持ち主を表す語としては合わない。"}], "explanations": {"個人": "個人は集団の中の一人ひとりの人を表す。集団の中で声が埋もれる人について言う文脈に合う。", "天気": "「天気」は空模様を表す語で、声を持つ人の代わりにはならないので、「天気の声」は文として成り立たない。", "砂糖": "「砂糖」は甘味料の名で、声を出す持ち主にはならないので合わない。", "台所": "「台所」は料理をする場所で、声の持ち主を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "個人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は個人がはっきりしていて、どこにいても目立つ。", "explanation": "ここは〈個性〉の意味。個人は一人の人を指すので、性格の際立った特徴には個性を使う。"}, {"text": "この会社の個人は三百人だ。", "explanation": "ここは〈社員〉の意味。個人は一人ひとりの人を指し、会社に属する人全体の数には社員を使う。"}, {"text": "その学校には、生徒が五百個人いる。", "explanation": "ここは〈人〉の数え方。個人は数え方の単位には使わず、人数を数えるときは人を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36331, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部活は、個人を集まってできた組織だ。", "corrected_sentence": "この部活は、個人が集まってできた組織だ。", "error_description": "誤りは「個人を」。「集まる」の主体は「が」で示すので、対象の「を」は誤り。正しくは「個人が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36331, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校は、生徒という個人が、集団の中で育てる場所だ。", "corrected_sentence": "学校は、生徒という個人を、集団の中で育てる場所だ。", "error_description": "誤りは「個人が」。「育てる」は育てる対象を「を」で示す必要がある。主格の「が」は誤り。正しくは「個人を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36332, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「枝が絡み合い」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「絡み合う」は目的語を取らないので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「枝に絡み合い」は相手を示す形として不自然で、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「絡み合う」と結びつかず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「枝が絡み合い」の主語を示す。", "を": "「絡み合う」は目的語を取らないので、「を」は合わない。", "に": "「枝に絡み合い」は相手を示す形として不自然で、成り立たない。", "へ": "方向の「へ」は「絡み合う」と結びつかず、文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "に": "相手の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36332, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「古い木の根が絡み合い」の主語を示す。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、「根より絡み合い」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「絡み合う」は目的語を取らないので、「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」で、「根で絡み合い」とは主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「古い木の根が絡み合い」の主語を示す。", "より": "比較の「より」で、「根より絡み合い」は意味が通らない。", "を": "「絡み合う」は目的語を取らないので、「を」は合わない。", "で": "手段の「で」で、「根で絡み合い」とは主語を示せない。"}, "error_tags": {"より": "比較の誤り", "を": "目的語の誤り", "で": "手段の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36332, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いくつかのものが、まるで糸のように、おたがいにからまって、ほどけなくなること。", "primary_collocate": null, "pronunciation": "からみあう", "ipa": "kaɾamiaɯ", "syllable_count": 5, "sentences": [{"text": "釣り糸が絡み合って、ほどくのに三十分もかかった。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "釣[つ]り糸[いと]が絡[から]み合[あ]って、ほどくのに三十分[さんじゅっぷん]もかかった。", "sentence_source": "generated"}, {"text": "庭の木の枝が絡み合い、空がほとんど見えなくなっている。", "target_word": "絡み合い", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]の枝[えだ]が絡[から]み合[あ]い、空[そら]がほとんど見[み]えなくなっている。", "sentence_source": "generated"}, {"text": "イヤホンのコードがかばんの中で絡み合っていて、使えるまでに時間がかかった。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "イヤホンのコードがかばんの中[なか]で絡[から]み合[あ]っていて、使[つか]えるまでに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "二本のつるが絡み合いながら、フェンスの上まで伸びていた。", "target_word": "絡み合いながら", "complexity_tier": "T3", "furigana": "二本[にほん]のつるが絡[から]み合[あ]いながら、フェンスの上[うえ]まで伸[の]びていた。", "sentence_source": "generated"}, {"text": "毛糸の玉が絡み合ってしまい、編み物が始められない。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "毛糸[けいと]の玉[たま]が絡[から]み合[あ]ってしまい、編[あ]み物[もの]が始[はじ]められない。", "sentence_source": "generated"}, {"text": "海の中では、昆布の長い葉が絡み合って、まるで森のようだった。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "海[うみ]の中[なか]では、昆布[こんぶ]の長[なが]い葉[は]が絡[から]み合[あ]って、まるで森[もり]のようだった。", "sentence_source": "generated"}, {"text": "髪が風で絡み合ってしまい、くしが通らない。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "髪[かみ]が風[かぜ]で絡[から]み合[あ]ってしまい、くしが通[とお]らない。", "sentence_source": "generated"}, {"text": "古い木の根が絡み合い、地面の下でしっかり岩をつかんでいる。", "target_word": "絡み合い", "complexity_tier": "T3", "furigana": "古[ふる]い木[き]の根[ね]が絡[から]み合[あ]い、地面[じめん]の下[した]でしっかり岩[いわ]をつかんでいる。", "sentence_source": "generated"}, {"text": "子猫がじゃれたので、二つの毛糸玉が絡み合ってしまった。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "子猫[こねこ]がじゃれたので、二[ふた]つの毛糸玉[けいとだま]が絡[から]み合[あ]ってしまった。", "sentence_source": "generated"}, {"text": "ケーブルが絡み合ったまま引っ張ると、結び目がかえって固くなる。", "target_word": "絡み合った", "complexity_tier": "T3", "furigana": "ケーブルが絡[から]み合[あ]ったまま引[ひ]っ張[ぱ]ると、結[むす]び目[め]がかえって固[かた]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絡み合う", "label": "終止形"}, {"form": "絡み合い", "label": "連用形"}, {"form": "絡み合って", "label": "て形"}, {"form": "絡み合った", "label": "た形"}, {"form": "絡み合わない", "label": "ない形"}], "register": "書き言葉", "sense_fingerprint": "糸やひもなどの物が互いにからまってほどけない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36332, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絡み合って", "is_correct": true, "explanation": "正解。「釣り糸が〜、ほどくのに」と続く中止形。"}, {"text": "絡み合え", "is_correct": false, "explanation": "命令形で、文の途中では続かない。"}, {"text": "絡み目", "is_correct": false, "explanation": "名詞で、「釣り糸が」の述語にならない。"}, {"text": "絡み合う", "is_correct": false, "explanation": "終止形で、「、ほどくのに」と続く文にならない。"}], "explanations": {"絡み合って": "正解。「釣り糸が〜、ほどくのに」と続く中止形。", "絡み合え": "命令形で、文の途中では続かない。", "絡み目": "名詞で、「釣り糸が」の述語にならない。", "絡み合う": "終止形で、「、ほどくのに」と続く文にならない。"}, "sentence_index": 0, "correct_answer": "絡み合って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "磁石同士が絡み合って、ぴたりとくっついた。", "explanation": "ここは〈引き合う〉の意味。磁石が互いに引っ張り合う場面は「引き合う」で表し、糸のようにからまってほどけなくなる「絡み合う」は合わない。"}, {"text": "ヘビが腕に絡み合い、動けなくなった。", "explanation": "ここは〈からみつく〉の意味。ヘビが一方的に腕へ巻きつく場面は「からみつく」で表し、互いにからまる「絡み合う」は合わない。"}, {"text": "満員電車で乗客同士が絡み合い、身動きが取れない。", "explanation": "ここは〈押し合う〉の意味。人がぶつかって押し合う場面は「押し合う」で表し、糸のようにからまる意味の「絡み合う」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36332, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絡み合って", "is_correct": true, "explanation": "正解。「髪が風で絡み合ってしまい」の形。"}, {"text": "絡ませ", "is_correct": false, "explanation": "他動詞の語幹で、「しまい」へ続く形にならない。"}, {"text": "絡み合わせ", "is_correct": false, "explanation": "使役の名詞形で、ここでは文が成り立たない。"}, {"text": "絡み合った", "is_correct": false, "explanation": "た形で、「しまい」と続く形にはならない。"}], "explanations": {"絡み合って": "正解。「髪が風で絡み合ってしまい」の形。", "絡ませ": "他動詞の語幹で、「しまい」へ続く形にならない。", "絡み合わせ": "使役の名詞形で、ここでは文が成り立たない。", "絡み合った": "た形で、「しまい」と続く形にはならない。"}, "sentence_index": 6, "correct_answer": "絡み合って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの原子が絡み合って、分子を作る。", "explanation": "ここは〈化学的に結びつく〉の意味。原子同士の結合は「結合する」で表し、「絡み合う」は糸などが互いにからまる意味なので合わない。"}, {"text": "雨水が土に絡み合って、すぐ地中へ消えた。", "explanation": "ここは〈染み込む〉の意味。水が土の中へ入り込む場面は「染み込む」で表し、「絡み合う」は合わない。"}, {"text": "酔った客が店員に絡み合い、仕事が止まった。", "explanation": "ここは〈絡む〉の意味（からんで相手を困らせる）。一方的に相手へからむ場面は「絡む」で表し、互いに関わり合う「絡み合う」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36332, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電話線がほかの配線を絡み合ってしまい、修理に時間がかかった。", "corrected_sentence": "電話線がほかの配線と絡み合ってしまい、修理に時間がかかった。", "error_description": "「絡み合う」は相手を「と」で示す。「を」は目的語の助詞で、「絡み合う」には合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "絡み合い", "is_correct": true, "explanation": "正解。「庭の木の枝が絡み合い、」と続く連用形。"}, {"text": "絡み合う", "is_correct": false, "explanation": "終止形で文を言い切るので、「、空が」と続けられない。"}, {"text": "絡み合った", "is_correct": false, "explanation": "た形で過去・完了を表し、「、空が」と続く形ではない。"}, {"text": "絡み合わない", "is_correct": false, "explanation": "ない形で否定の意味になり、枝がからむという文の内容と逆になる。"}], "correct_form": "絡み合い", "base_form": "絡み合う", "form_label": "連用形", "sentence_index": 1, "explanations": {"絡み合い": "正解。「庭の木の枝が絡み合い、」と続く連用形。", "絡み合う": "終止形で文を言い切るので、「、空が」と続けられない。", "絡み合った": "た形で過去・完了を表し、「、空が」と続く形ではない。", "絡み合わない": "ない形で否定の意味になり、枝がからむという文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36332, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の草が絡み合いた結果、道がふさがった。", "corrected_sentence": "庭の草が絡み合った結果、道がふさがった。", "error_description": "「絡み合う」のた形は「絡み合った」。「絡み合いた」はこの動詞の活用として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "絡み合い", "is_correct": true, "explanation": "正解。「古い木の根が絡み合い、」と続く連用形。"}, {"text": "絡ませ", "is_correct": false, "explanation": "他動詞の連用形で、「根が」の述語にならず、文が成り立たない。"}, {"text": "絡み合おう", "is_correct": false, "explanation": "意志形で、文の途中では続かない。"}, {"text": "絡み合え", "is_correct": false, "explanation": "命令形で、文の途中では続かない。"}], "correct_form": "絡み合い", "base_form": "絡み合う", "form_label": "連用形", "sentence_index": 7, "explanations": {"絡み合い": "正解。「古い木の根が絡み合い、」と続く連用形。", "絡ませ": "他動詞の連用形で、「根が」の述語にならず、文が成り立たない。", "絡み合おう": "意志形で、文の途中では続かない。", "絡み合え": "命令形で、文の途中では続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36333, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「要因が絡み合う」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「絡み合う」は目的語を取らないので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「絡む」は「に」を取るが、「絡み合う」は互いに関わるので「に」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「絡み合う」と結びつかず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「要因が絡み合う」の主語を示す。", "を": "「絡み合う」は目的語を取らないので、「を」は合わない。", "に": "「絡む」は「に」を取るが、「絡み合う」は互いに関わるので「に」では成り立たない。", "へ": "方向の「へ」は「絡み合う」と結びつかず、文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "に": "相手の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36333, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36333, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "複数の事柄や要素が互いに影響し合い、複雑に関係し合っている状態。", "primary_collocate": null, "pronunciation": "からみあう", "ipa": "kaɾamiaɯ", "syllable_count": 5, "sentences": [{"text": "さらに、アミノ酸や有機酸が複雑に絡み合い、主食に奥深い風味と旨味の層を付与する。", "target_word": "絡み合い", "complexity_tier": "T3", "furigana": "さらに、アミノ酸[さん]や有機酸[ゆうきさん]が複雑[ふくざつ]に絡[から]み合[あ]い、主食[しゅしょく]に奥深[おくぶか]い風味[ふうみ]と旨味[うまみ]の層[そう]を付与[ふよ]する。", "sentence_source": "mined"}, {"text": "この問題は、経済や政治など多くの要因が絡み合っているので、簡単には解決できない。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、経済[けいざい]や政治[せいじ]など多[おお]くの要因[よういん]が絡[から]み合[あ]っているので、簡単[かんたん]には解決[かいけつ]できない。", "sentence_source": "generated"}, {"text": "二人の過去と現在の事情が絡み合い、物語は少しずつ複雑になっていった。", "target_word": "絡み合い", "complexity_tier": "T3", "furigana": "二人[ふたり]の過去[かこ]と現在[げんざい]の事情[じじょう]が絡[から]み合[あ]い、物語[ものがたり]は少[すこ]しずつ複雑[ふくざつ]になっていった。", "sentence_source": "generated"}, {"text": "複数の利害が絡み合う交渉では、一方だけを満足させることは難しい。", "target_word": "絡み合う", "complexity_tier": "T3", "furigana": "複数[ふくすう]の利害[りがい]が絡[から]み合[あ]う交渉[こうしょう]では、一方[いっぽう]だけを満足[まんぞく]させることは難[むずか]しい。", "sentence_source": "generated"}, {"text": "気候の変化には、海と大気の動きが絡み合って影響している。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "気候[きこう]の変化[へんか]には、海[うみ]と大気[たいき]の動[うご]きが絡[から]み合[あ]って影響[えいきょう]している。", "sentence_source": "generated"}, {"text": "人間関係と仕事の悩みが絡み合って、彼女は何から手をつけていいか分からなかった。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "人間関係[にんげんかんけい]と仕事[しごと]の悩[なや]みが絡[から]み合[あ]って、彼女[かのじょ]は何[なに]から手[て]をつけていいか分[わ]からなかった。", "sentence_source": "generated"}, {"text": "この小説では、三つの家族の運命が絡み合いながら進んでいく。", "target_word": "絡み合いながら", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]では、三[みっ]つの家族[かぞく]の運命[うんめい]が絡[から]み合[あ]いながら進[すす]んでいく。", "sentence_source": "generated"}, {"text": "原因が一つではなく、いくつもの出来事が絡み合った結果、事故が起きた。", "target_word": "絡み合った", "complexity_tier": "T3", "furigana": "原因[げんいん]が一[ひと]つではなく、いくつもの出来事[できごと]が絡[から]み合[あ]った結果[けっか]、事故[じこ]が起[お]きた。", "sentence_source": "generated"}, {"text": "国同士の思惑が絡み合っているため、会議はなかなかまとまらない。", "target_word": "絡み合って", "complexity_tier": "T3", "furigana": "国同士[くにどうし]の思惑[おもわく]が絡[から]み合[あ]っているため、会議[かいぎ]はなかなかまとまらない。", "sentence_source": "generated"}, {"text": "このお茶の味の決め手は、香りと酸味が絡み合うところにある。", "target_word": "絡み合う", "complexity_tier": "T3", "furigana": "このお茶[ちゃ]の味[あじ]の決[き]め手[て]は、香[かお]りと酸味[さんみ]が絡[から]み合[あ]うところにある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絡み合う", "label": "終止形"}, {"form": "絡み合い", "label": "連用形"}, {"form": "絡み合って", "label": "て形"}, {"form": "絡み合った", "label": "た形"}, {"form": "絡み合わない", "label": "ない形"}], "register": "書き言葉", "sense_fingerprint": "要因や事情が互いに影響して複雑にからむ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36333, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絡み合い", "is_correct": true, "explanation": "正解。「複雑に」を受けて、後ろに文が続く中止形。"}, {"text": "絡み目", "is_correct": false, "explanation": "名詞なので、「複雑に」の後には続かず、文が成り立たない。"}, {"text": "絡み合え", "is_correct": false, "explanation": "命令形で、文の途中に置くと意味が成り立たない。"}, {"text": "絡み合わ", "is_correct": false, "explanation": "未然形で、「ない」「ず」などが続かないと文にならない。"}], "explanations": {"絡み合い": "正解。「複雑に」を受けて、後ろに文が続く中止形。", "絡み目": "名詞なので、「複雑に」の後には続かず、文が成り立たない。", "絡み合え": "命令形で、文の途中に置くと意味が成り立たない。", "絡み合わ": "未然形で、「ない」「ず」などが続かないと文にならない。"}, "sentence_index": 0, "correct_answer": "絡み合い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上司が部下の仕事に絡み合い、現場が混乱した。", "explanation": "ここは〈干渉する〉の意味。一方的に口を出す場面は「干渉する」で表し、互いに影響し合う「絡み合う」は合わない。"}, {"text": "歯車が絡み合って、機械が止まった。", "explanation": "ここは〈かみ合う〉の意味。歯車の噛み合わせは「かみ合う」で表し、「絡み合う」は合わない。"}, {"text": "インクが水に絡み合い、紙が薄く色づいた。", "explanation": "ここは〈溶け込む〉の意味。液体が別の液体に広がって混ざる場面は「溶け込む」で表し、互いに影響し合う「絡み合う」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36333, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絡み合いながら", "is_correct": true, "explanation": "正解。「進んでいく」と続く同時進行の形。"}, {"text": "絡み合っている", "is_correct": false, "explanation": "状態の形で、「運命が〜進んでいく」の流れに入らない。"}, {"text": "絡ませ", "is_correct": false, "explanation": "他動詞の語幹で、文が続かない。"}, {"text": "絡み合った", "is_correct": false, "explanation": "完了の形で、「進んでいく」とは続かない。"}], "explanations": {"絡み合いながら": "正解。「進んでいく」と続く同時進行の形。", "絡み合っている": "状態の形で、「運命が〜進んでいく」の流れに入らない。", "絡ませ": "他動詞の語幹で、文が続かない。", "絡み合った": "完了の形で、「進んでいく」とは続かない。"}, "sentence_index": 6, "correct_answer": "絡み合いながら"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水素と酸素が絡み合って、水分子になる。", "explanation": "ここは〈化学的に結びつく〉の意味。原子や分子の結合は「結合する」で表し、「絡み合う」は要因や事情が互いに影響する意味なので合わない。"}, {"text": "スポンジに水が絡み合った。", "explanation": "ここは〈染み込む〉の意味。水が内部に入り込む場面は「染み込む」で表し、「絡み合う」は合わない。"}, {"text": "子犬が飼い主の足に絡み合った。", "explanation": "ここは〈まとわりつく〉の意味。一方が相手の周りにくっつく場面は「まとわりつく」で表し、互いに影響し合う「絡み合う」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36333, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この事故は、天候と人為的なミスを絡み合って起きた。", "corrected_sentence": "この事故は、天候と人為的なミスが絡み合って起きた。", "error_description": "「絡み合う」は主語（ミス）を「が」で示す自動詞。「を」は目的語の助詞で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36333, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの計画が絡み合いて、進行が遅れている。", "corrected_sentence": "二つの計画が絡み合って、進行が遅れている。", "error_description": "「絡み合う」のて形は「絡み合って」。「絡み合いて」はこの動詞の活用として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36334, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「産物が豊かな」で、産物が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「豊かだ」は目的語を取らず、「産物を豊かな」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「産物へ豊かな土地」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すので、「産物から豊かな土地」は「豊かな」とつながらない。"}], "correct_answer": "が", "explanations": {"が": "「産物が豊かな」で、産物が主語になる。", "を": "「豊かだ」は目的語を取らず、「産物を豊かな」は合わない。", "へ": "方向を表すので、「産物へ豊かな土地」は成り立たない。", "から": "起点を表すので、「産物から豊かな土地」は「豊かな」とつながらない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36334, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「産物を配った」で、配る対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「産物がみんなに配った」では、産物が配る主体になって合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「産物へ配った」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「産物のみんなに配った」は述語につながらず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「産物を配った」で、配る対象を表す。", "が": "「産物がみんなに配った」では、産物が配る主体になって合わない。", "へ": "方向を表すので、「産物へ配った」は成り立たない。", "の": "「産物のみんなに配った」は述語につながらず文が成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36334, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が作ったり、生まれたりしたもの。", "primary_collocate": null, "pronunciation": "さんぶつ", "ipa": "sambɯtsɯ", "syllable_count": 4, "sentences": [{"text": "この島の産物は、魚と塩です。", "target_word": "産物", "complexity_tier": "T2", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "北海道は、農業の産物が豊かな土地だ。", "target_word": "産物", "complexity_tier": "T3", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "旅行先で、土地の産物を買って帰った。", "target_word": "産物", "complexity_tier": "T3", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "山の産物を、市場で売っている。", "target_word": "産物", "complexity_tier": "T2", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "この地方の主な産物は、お茶です。", "target_word": "産物", "complexity_tier": "T2", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "海の産物が、毎朝港に届く。", "target_word": "産物", "complexity_tier": "T2", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "産物を船で運んで、町に売りに行った。", "target_word": "産物", "complexity_tier": "T3", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "彼は、自分の畑の産物をみんなに配った。", "target_word": "産物", "complexity_tier": "T3", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "その国は、豊かな産物のおかげで栄えた。", "target_word": "産物", "complexity_tier": "T3", "furigana": "さんぶつ", "sentence_source": "generated"}, {"text": "この町の産物は、全国の店に並んでいる。", "target_word": "産物", "complexity_tier": "T3", "furigana": "さんぶつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "副産物", "label": "派生"}, {"form": "農産物", "label": "派生"}, {"form": "海産物", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 土地で作られる品物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true