INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36334, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "産物", "is_correct": true, "explanation": "「さんぶつ」で、聞こえた語と一致する。"}, {"text": "乾物", "is_correct": false, "explanation": "「かんぶつ」で、最初の音だけが違う。"}, {"text": "万物", "is_correct": false, "explanation": "「ばんぶつ」で、最初の音だけが違う。"}, {"text": "散文", "is_correct": false, "explanation": "「さんぶん」で、最後の音だけが違う。"}, {"text": "文物", "is_correct": false, "explanation": "「ぶんぶつ」で、最初の音だけが違う。"}], "explanations": {"産物": "「さんぶつ」で、聞こえた語と一致する。", "乾物": "「かんぶつ」で、最初の音だけが違う。", "万物": "「ばんぶつ」で、最初の音だけが違う。", "散文": "「さんぶん」で、最後の音だけが違う。", "文物": "「ぶんぶつ」で、最初の音だけが違う。"}, "sentence_index": null, "correct_answer": "産物"}, "level_3": {"options": [{"text": "産物", "is_correct": true, "explanation": "島で作られる品物が魚と塩だという意味に合う。"}, {"text": "名前", "is_correct": false, "explanation": "形は合うが、「島の名前は魚と塩」では意味が合わない。"}, {"text": "気候", "is_correct": false, "explanation": "形は合うが、「気候は魚と塩」では意味が合わない。"}, {"text": "言葉", "is_correct": false, "explanation": "形は合うが、「言葉は魚と塩」では意味が合わない。"}], "explanations": {"産物": "島で作られる品物が魚と塩だという意味に合う。", "名前": "形は合うが、「島の名前は魚と塩」では意味が合わない。", "気候": "形は合うが、「気候は魚と塩」では意味が合わない。", "言葉": "形は合うが、「言葉は魚と塩」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "産物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山の産物を、市場で笑っている。", "explanation": "「産物」は物で、笑う対象ではないので「笑う」とは使えない。"}, {"text": "山の産物は、とても眠い人だ。", "explanation": "「産物」は品物で、人を表す語ではない。"}, {"text": "山の産物が、市場で歌っている。", "explanation": "「産物」は歌う主体にならず、述語と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validat