INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36335, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町並みは、長い歴史を産物だ。", "corrected_sentence": "この町並みは、長い歴史の産物だ。", "error_description": "「長い歴史の産物」と言うべきところが「を」になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
