INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36336, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "資源を修飾する連体の「の」が入り、「資源の少ない国」になる。"}, {"text": "へ", "is_correct": false, "explanation": "「資源へ少ない国」は方向を表す形で、修飾の文脈に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「資源に少ない国」は名詞を修飾できず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「資源から少ない国」は起点の形で、修飾の文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "資源を修飾する連体の「の」が入り、「資源の少ない国」になる。", "へ": "「資源へ少ない国」は方向を表す形で、修飾の文脈に合わない。", "に": "「資源に少ない国」は名詞を修飾できず、文が成り立たない。", "から": "「資源から少ない国」は起点の形で、修飾の文脈に合わない。"}, "error_tags": {"へ": "方向", "に": "位置", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36336, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "資源は、人が使うことができる大切なものです。", "primary_collocate": null, "pronunciation": "しげん", "ipa": "ɕiɡeɴ", "syllable_count": 3, "sentences": [{"text": "日本は石油などの資源が少ない国だ。", "target_word": "資源", "complexity_tier": "T3", "furigana": "日本[にほん]は石油[せきゆ]などの資源[しげん]が少[すく]ない国[くに]だ。", "sentence_source": "generated"}, {"text": "水は大切な資源なので、むだに使わないようにしよう。", "target_word": "資源", "complexity_tier": "T3", "furigana": "水[みず]は大切[たいせつ]な資源[しげん]なので、むだに使[つか]わないようにしよう。", "sentence_source": "generated"}, {"text": "この山には木や水など、豊かな資源がある。", "target_word": "資源", "complexity_tier": "T3", "furigana": "この山[やま]には木[き]や水[みず]など、豊[ゆた]かな資源[しげん]がある。", "sentence_source": "generated"}, {"text": "資源を守るために、紙やびんを集めてリサイクルする。", "target_word": "資源", "complexity_tier": "T3", "furigana": "資源[しげん]を守[まも]るために、紙[かみ]やびんを集[あつ]めてリサイクルする。", "sentence_source": "generated"}, {"text": "地球の資源には限りがあるから、大切に使おう。", "target_word": "資源", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の資源[しげん]には限[かぎ]りがあるから、大切[たいせつ]に使[つか]おう。", "sentence_source": "generated"}, {"text": "この島は海の資源が多く、漁業がさかんだ。", "target_word": "資源", "complexity_tier": "T3", "furigana": "この島[しま]は海[うみ]の資源[しげん]が多[おお]く、漁業[ぎょぎょう]がさかんだ。", "sentence_source": "generated"}, {"text": "石炭は昔、国の大事な資源だった。", "target_word": "資源", "complexity_tier": "T3", "furigana": "石炭[せきたん]は昔[むかし]、国[くに]の大事[だいじ]な資源[しげん]だった。", "sentence_source": "generated"}, {"text": "資源の少ない国は、外国から買わなければならない。", "target_word": "資源", "complexity_tier": "T3", "furigana": "資源[しげん]の少[すく]ない国[くに]は、外国[がいこく]から買[か]わなければならない。", "sentence_source": "generated"}, {"text": "ごみを減らすことは、資源を守ることにもなる。", "target_word": "資源", "complexity_tier": "T3", "furigana": "ごみを減[へ]らすことは、資源[しげん]を守[まも]ることにもなる。", "sentence_source": "generated"}, {"text": "町の森は大切な資源で、みんなで守っている。", "target_word": "資源", "complexity_tier": "T3", "furigana": "町[まち]の森[もり]は大切[たいせつ]な資源[しげん]で、みんなで守[まも]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "資源", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "石油・水・木材など、人が利用できる自然の大切な物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36336, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "資源", "is_correct": true, "explanation": "石油など自然から得る大切な物を指し、「資源が少ない」に合う。"}, {"text": "理由", "is_correct": false, "explanation": "「石油などの理由が少ない」は意味をなさず、文に合わない。"}, {"text": "漫画", "is_correct": false, "explanation": "「石油などの漫画が少ない」は文意が通らない。"}, {"text": "砂時計", "is_correct": false, "explanation": "「石油などの砂時計が少ない」は不自然で、文に合わない。"}], "explanations": {"資源": "石油など自然から得る大切な物を指し、「資源が少ない」に合う。", "理由": "「石油などの理由が少ない」は意味をなさず、文に合わない。", "漫画": "「石油などの漫画が少ない」は文意が通らない。", "砂時計": "「石油などの砂時計が少ない」は不自然で、文に合わない。"}, "sentence_index": 0, "correct_answer": "資源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家を建て直すため、資源を業者に注文した。", "explanation": "ここは〈資材〉の意味。資源は自然から得る大きな物を指すので、建築に使う材料には使わない。"}, {"text": "このケーキの資源は、小麦粉と卵と砂糖だ。", "explanation": "ここは〈材料〉の意味。自然から得る大きな物を指す資源とは言わない。"}, {"text": "事件の資源は、社長の一言にあった。", "explanation": "ここは〈根源〉の意味。資源は利用する自然の物を指すので、事件の原因を表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36336, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "資源", "is_correct": true, "explanation": "国にとって大事な自然の物という意味で、「大事な資源だった」に合う。"}, {"text": "合唱", "is_correct": false, "explanation": "「大事な合唱だった」は文意が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "「国の大事な時計だった」は石炭の文脈に合わない。"}, {"text": "風邪", "is_correct": false, "explanation": "「国の大事な風邪だった」は意味をなさない。"}], "explanations": {"資源": "国にとって大事な自然の物という意味で、「大事な資源だった」に合う。", "合唱": "「大事な合唱だった」は文意が通らない。", "時計": "「国の大事な時計だった」は石炭の文脈に合わない。", "風邪": "「国の大事な風邪だった」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "資源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は締め切りまでに、小説の資源を書き終えた。", "explanation": "ここは〈原稿〉の意味。資源は自然から得る物を指すので、文章を指す文には合わない。"}, {"text": "授業で先生が、英語の資源を配って説明した。", "explanation": "ここは〈教材〉の意味。資源は自然界の物を指し、授業で配る教材には使わない。"}, {"text": "画家は次の展覧会のために、新しい資源を描き始めた。", "explanation": "ここは〈作品〉の意味。資源は自然から得る物で、描く対象の作品には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36336, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ごみを減らせば、資源を守られる。", "corrected_sentence": "ごみを減らせば、資源が守られる。", "error_description": "誤: を / 正: が。受身文の主語は「が」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
