INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36338, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「一秒の十分の一」で、秒に続けて数量の範囲を作る「の」。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「一秒」を主語にすると「はかれる」の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示す。「一秒に十分の一まで」では計測の対象や単位を表せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここには移動や向きの意味がない。"}], "correct_answer": "の", "explanations": {"の": "「一秒の十分の一」で、秒に続けて数量の範囲を作る「の」。", "が": "「が」は主語を示すが、「一秒」を主語にすると「はかれる」の文として成り立たない。", "に": "「に」は到達点や相手を示す。「一秒に十分の一まで」では計測の対象や単位を表せず、不自然。", "へ": "「へ」は方向を示すが、ここには移動や向きの意味がない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36338, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間の長さをはかるための、とても短い単位です。", "primary_collocate": null, "pronunciation": "びょう", "ipa": "bʲoː", "syllable_count": 2, "sentences": [{"text": "百メートルを十五秒で走れるように、毎日練習している。", "target_word": "秒", "complexity_tier": "T3", "furigana": "百[ひゃく]メートルを十五秒[じゅうごびょう]で走[はし]れるように、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "信号が青に変わるまで、あと三十秒ほどかかる。", "target_word": "秒", "complexity_tier": "T3", "furigana": "信号[しんごう]が青[あお]に変[か]わるまで、あと三十秒[さんじゅうびょう]ほどかかる。", "sentence_source": "generated"}, {"text": "時計の針が一秒ごとに小さな音を立てる。", "target_word": "秒", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]が一秒[いちびょう]ごとに小[ちい]さな音[おと]を立[た]てる。", "sentence_source": "generated"}, {"text": "カップ麺にお湯を入れて、三分、つまり百八十秒待つ。", "target_word": "秒", "complexity_tier": "T3", "furigana": "カップ麺[めん]にお湯[ゆ]を入[い]れて、三分[さんぷん]、つまり百八十秒[ひゃくはちじゅうびょう]待[ま]つ。", "sentence_source": "generated"}, {"text": "一秒でも遅れると、電車のドアは閉まってしまう。", "target_word": "秒", "complexity_tier": "T3", "furigana": "一秒[いちびょう]でも遅[おく]れると、電車[でんしゃ]のドアは閉[し]まってしまう。", "sentence_source": "generated"}, {"text": "彼は問題を見て、五秒で答えを出した。", "target_word": "秒", "complexity_tier": "T3", "furigana": "彼[かれ]は問題[もんだい]を見[み]て、五秒[ごびょう]で答[こた]えを出[だ]した。", "sentence_source": "generated"}, {"text": "試合は終了の十秒前に、同点になった。", "target_word": "秒", "complexity_tier": "T3", "furigana": "試合[しあい]は終了[しゅうりょう]の十秒前[じゅうびょうまえ]に、同点[どうてん]になった。", "sentence_source": "generated"}, {"text": "このストップウォッチは、一秒の十分の一まで正確にはかれる。", "target_word": "秒", "complexity_tier": "T3", "furigana": "このストップウォッチは、一秒[いちびょう]の十分[じゅうぶん]の一[いち]まで正確[せいかく]にはかれる。", "sentence_source": "generated"}, {"text": "一分は六十秒だと、小学校で習った。", "target_word": "秒", "complexity_tier": "T3", "furigana": "一分[いっぷん]は六十秒[ろくじゅうびょう]だと、小学校[しょうがっこう]で習[なら]った。", "sentence_source": "generated"}, {"text": "電子レンジで三十秒温めると、ちょうどいい熱さになる。", "target_word": "秒", "complexity_tier": "T3", "furigana": "電子[でんし]レンジで三十秒[さんじゅうびょう]温[あたた]めると、ちょうどいい熱[あつ]さになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "秒", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "一分の六十分の一にあたる時間の単位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: ストップウォッチ (Zipf 2.43), はかれる (Zipf 1.45)']::text[], 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36338, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秒", "is_correct": true, "explanation": "時間の単位で、「十五秒で走る」の形に入る語。"}, {"text": "円", "is_correct": false, "explanation": "円は金額の単位で、走る時間を言う文には合わない。"}, {"text": "点", "is_correct": false, "explanation": "点は得点や評価の数で、走る時間の表し方として意味が通らない。"}, {"text": "回", "is_correct": false, "explanation": "回は回数の数え方で、速さの時間を表せない。"}], "explanations": {"秒": "時間の単位で、「十五秒で走る」の形に入る語。", "円": "円は金額の単位で、走る時間を言う文には合わない。", "点": "点は得点や評価の数で、走る時間の表し方として意味が通らない。", "回": "回は回数の数え方で、速さの時間を表せない。"}, "sentence_index": 0, "correct_answer": "秒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "りんごを三秒買った。", "explanation": "ここは〈個〉の意味。秒は時間の単位で、物を数える助数詞にはならない。"}, {"text": "問い合わせが三秒来た。", "explanation": "ここは〈件〉の意味。秒は時間の長さなので、問い合わせの数は表せない。"}, {"text": "車を三秒買った。", "explanation": "ここは〈台〉の意味。秒は時間の単位で、車の台数を数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36338, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秒", "is_correct": true, "explanation": "時間の単位で、「終了の十秒前」と言う形に入る語。"}, {"text": "階", "is_correct": false, "explanation": "階は建物の層を数える語で、試合の終了までの時間には使えない。"}, {"text": "本", "is_correct": false, "explanation": "本は細長い物を数える語で、時間の前後を表す文には合わない。"}, {"text": "枚", "is_correct": false, "explanation": "枚は薄い物を数える語で、試合の残り時間には当てはまらない。"}], "explanations": {"秒": "時間の単位で、「終了の十秒前」と言う形に入る語。", "階": "階は建物の層を数える語で、試合の終了までの時間には使えない。", "本": "本は細長い物を数える語で、時間の前後を表す文には合わない。", "枚": "枚は薄い物を数える語で、試合の残り時間には当てはまらない。"}, "sentence_index": 6, "correct_answer": "秒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "午後三秒に集合します。", "explanation": "ここは〈時刻〉の意味。秒は時間の長さで、時刻の一点を表す「午後三時」の代わりにはならない。"}, {"text": "室温は二十五秒に保つ。", "explanation": "ここは〈度〉の意味。秒は時間の単位で、温度の数値には使えない。"}, {"text": "その店は創業三十秒だ。", "explanation": "ここは〈年〉の意味。秒は時間の長さで、創業からの年数は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36338, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試合は残り五秒を終わった。", "corrected_sentence": "試合は残り五秒で終わった。", "error_description": "「終わる」は目的語の「を」を取らない。時間の範囲や手段を示すには「で」を使うので、「残り五秒で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36338, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "信号が変わるまで、あと三十秒待きました。", "corrected_sentence": "信号が変わるまで、あと三十秒待ちました。", "error_description": "「待つ」の連用形は「待ち」。「待き」という活用形はないので誤り。正しくは「待ちました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36340, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「仕事の効率が上がった」で、効率を主語として示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「上がる」は目的語を取らない自動詞なので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点を示すが、ここでは効率そのものが主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「上がる」の主語を導く働きはない。"}], "correct_answer": "が", "explanations": {"が": "「仕事の効率が上がった」で、効率を主語として示す「が」。", "を": "「上がる」は目的語を取らない自動詞なので、「を」は合わない。", "に": "「に」は到達点を示すが、ここでは効率そのものが主語になる。", "へ": "「へ」は方向を示すが、「上がる」の主語を導く働きはない。"}, "error_tags": {"を": "目的語", "に": "到達点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36340, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36340, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "やりたいことを少ない力で成し遂げられる度合い。", "primary_collocate": null, "pronunciation": "こうりつ", "ipa": "koːɾitsɯ", "syllable_count": 4, "sentences": [{"text": "この方法なら、短い時間で効率よく覚えられる。", "target_word": "効率", "complexity_tier": "T3", "furigana": "この方法[ほうほう]なら、短[みじか]い時間[じかん]で効率[こうりつ]よく覚[おぼ]えられる。", "sentence_source": "generated"}, {"text": "机の上を片づけたら、仕事の効率が上がった。", "target_word": "効率", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]を片[かた]づけたら、仕事[しごと]の効率[こうりつ]が上[あ]がった。", "sentence_source": "generated"}, {"text": "忙しいときほど、効率を考えて動くことが大切です。", "target_word": "効率", "complexity_tier": "T3", "furigana": "忙[いそが]しいときほど、効率[こうりつ]を考[かんが]えて動[うご]くことが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "一つずつ手で洗うのは効率が悪いので、機械を使いました。", "target_word": "効率", "complexity_tier": "T3", "furigana": "一[ひと]つずつ手[て]で洗[あら]うのは効率[こうりつ]が悪[わる]いので、機械[きかい]を使[つか]いました。", "sentence_source": "generated"}, {"text": "買い物リストを作ると、効率よく店を回れます。", "target_word": "効率", "complexity_tier": "T3", "furigana": "買[か]い物[もの]リストを作[つく]ると、効率[こうりつ]よく店[みせ]を回[まわ]れます。", "sentence_source": "generated"}, {"text": "効率を上げたいなら、まず睡眠をしっかりとるべきだ。", "target_word": "効率", "complexity_tier": "T3", "furigana": "効率[こうりつ]を上[あ]げたいなら、まず睡眠[すいみん]をしっかりとるべきだ。", "sentence_source": "generated"}, {"text": "彼は効率ばかり気にして、仲間の気持ちを考えない。", "target_word": "効率", "complexity_tier": "T3", "furigana": "彼[かれ]は効率[こうりつ]ばかり気[き]にして、仲間[なかま]の気持[きも]ちを考[かんが]えない。", "sentence_source": "generated"}, {"text": "道が混んでいたので、移動の効率が下がってしまった。", "target_word": "効率", "complexity_tier": "T3", "furigana": "道[みち]が混[こ]んでいたので、移動[いどう]の効率[こうりつ]が下[さ]がってしまった。", "sentence_source": "generated"}, {"text": "新しいソフトのおかげで、事務の効率が二倍になった。", "target_word": "効率", "complexity_tier": "T3", "furigana": "新[あたら]しいソフトのおかげで、事務[じむ]の効率[こうりつ]が二倍[にばい]になった。", "sentence_source": "generated"}, {"text": "効率を優先しすぎると、大事なことを見落とすことがある。", "target_word": "効率", "complexity_tier": "T3", "furigana": "効率[こうりつ]を優先[ゆうせん]しすぎると、大事[だいじ]なことを見落[みお]とすことがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "効率", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "少ない労力や時間で目的を果たせる度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 見落とす (Zipf 2.36)']::text[], 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36340, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "効率", "is_correct": true, "explanation": "少ない労力で目的を果たす度合いを指し、「短い時間で〜よく覚えられる」に入る語。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、覚え方の良し悪しを表す文には合わない。"}, {"text": "服装", "is_correct": false, "explanation": "服装は身なりのことで、覚え方の仕方とは結びつかない。"}, {"text": "高度", "is_correct": false, "explanation": "高度は高さや程度を表す語で、覚える仕方の説明には合わない。"}], "explanations": {"効率": "少ない労力で目的を果たす度合いを指し、「短い時間で〜よく覚えられる」に入る語。", "天気": "天気は空模様のことで、覚え方の良し悪しを表す文には合わない。", "服装": "服装は身なりのことで、覚え方の仕方とは結びつかない。", "高度": "高度は高さや程度を表す語で、覚える仕方の説明には合わない。"}, "sentence_index": 0, "correct_answer": "効率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は効率がすぐ出た。", "explanation": "ここは〈効果〉の意味。効率は作業の進み具合を表すので、薬の作用には使えない。"}, {"text": "この方法は効率がかからず、楽だ。", "explanation": "ここは〈手間〉の意味。手間は作業にかかる労力のことで、効率は「かかる」ものではないので合わない。"}, {"text": "説明の効率が深まった。", "explanation": "ここは〈理解〉の意味。理解は内容をつかむことで、効率は深まるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36340, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "効率", "is_correct": true, "explanation": "仕事や作業の進み具合を指し、「彼は〜ばかり気にして」に入る語。"}, {"text": "河口", "is_correct": false, "explanation": "河口は川の出口の場所で、仲間の気持ちとの対比で気にする対象にはならない。"}, {"text": "植木", "is_correct": false, "explanation": "植木は庭の草木のことで、この文の「気にして」の対象として意味が通らない。"}, {"text": "砂利", "is_correct": false, "explanation": "砂利は細かい石のことで、ここでは気にかける対象として不自然。"}], "explanations": {"効率": "仕事や作業の進み具合を指し、「彼は〜ばかり気にして」に入る語。", "河口": "河口は川の出口の場所で、仲間の気持ちとの対比で気にする対象にはならない。", "植木": "植木は庭の草木のことで、この文の「気にして」の対象として意味が通らない。", "砂利": "砂利は細かい石のことで、ここでは気にかける対象として不自然。"}, "sentence_index": 6, "correct_answer": "効率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは効率が濃くて、少し飲みにくい。", "explanation": "ここは〈味〉の意味。効率は仕事の進み具合で、味の濃さは表せない。"}, {"text": "彼女は効率を重ねても、いつも明るい。", "explanation": "ここは〈年齢〉の意味。効率は年齢のように積み重なるものではないので、「重ねる」とは合わない。"}, {"text": "窓から見える効率が美しい。", "explanation": "ここは〈景色〉の意味。効率は目に見えるものではないので、窓から見える対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36340, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業の効率が上げるために、道具を整えた。", "corrected_sentence": "作業の効率を上げるために、道具を整えた。", "error_description": "「上げる」は目的語の「を」を取る。「効率が上げる」の「が」は誤りで、「効率を上げる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36340, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "段取りを変えて、効率を上がった。", "corrected_sentence": "段取りを変えて、効率を上げた。", "error_description": "「上げる」は他動詞で「効率を上げた」と使う。「上がる」は自動詞なので、「効率を上がった」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36342, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「管理が甘い」の「が」。「管理」が「甘い」の主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "「管理へ甘い」は成り立たず、「甘い」は方向の「へ」を取らない。"}, {"text": "と", "is_correct": false, "explanation": "「管理と甘い」は並列の「と」だが、続く述語がなく文にならない。"}, {"text": "から", "is_correct": false, "explanation": "「管理から甘い」は起点の「から」で、「甘い」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「管理が甘い」の「が」。「管理」が「甘い」の主語になる。", "へ": "「管理へ甘い」は成り立たず、「甘い」は方向の「へ」を取らない。", "と": "「管理と甘い」は並列の「と」だが、続く述語がなく文にならない。", "から": "「管理から甘い」は起点の「から」で、「甘い」の主語にはならない。"}, "error_tags": {"へ": "方向", "と": "並列", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36342, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「火の管理には注意が必要」の「に」。管理に対して注意の対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「注意が必要」とは続かない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐだけで、「特に注意が必要」が続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「火の管理へは」は方向を示す「へ」で、「注意が必要」の対象を表せない。"}], "correct_answer": "に", "explanations": {"に": "「火の管理には注意が必要」の「に」。管理に対して注意の対象を示す。", "を": "「を」は目的語を示すが、「注意が必要」とは続かない。", "の": "「の」は名詞をつなぐだけで、「特に注意が必要」が続かない。", "へ": "「火の管理へは」は方向を示す「へ」で、「注意が必要」の対象を表せない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36342, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものをうまく使えるように、ちゃんとすること。", "primary_collocate": null, "pronunciation": "かんり", "ipa": "kaɴɾi", "syllable_count": 3, "sentences": [{"text": "店長は毎日、倉庫の在庫を管理しています。", "target_word": "管理", "complexity_tier": "T3", "furigana": "店長[てんちょう]は毎日[まいにち]、倉庫[そうこ]の在庫[ざいこ]を管理[かんり]しています。", "sentence_source": "generated"}, {"text": "パスワードの管理が甘いと、他の人に使われてしまう。", "target_word": "管理", "complexity_tier": "T3", "furigana": "パスワードの管理[かんり]が甘[あま]いと、他[ほか]の人[ひと]に使[つか]われてしまう。", "sentence_source": "generated"}, {"text": "この部屋は温度の管理が行き届いていて、いつも快適です。", "target_word": "管理", "complexity_tier": "T3", "furigana": "この部屋[へや]は温度[おんど]の管理[かんり]が行[い]き届[とど]いていて、いつも快適[かいてき]です。", "sentence_source": "generated"}, {"text": "大切な書類は、鍵のかかる棚で管理することになっている。", "target_word": "管理", "complexity_tier": "T3", "furigana": "大切[たいせつ]な書類[しょるい]は、鍵[かぎ]のかかる棚[たな]で管理[かんり]することになっている。", "sentence_source": "generated"}, {"text": "お金の管理が苦手なので、家計簿アプリを使っています。", "target_word": "管理", "complexity_tier": "T3", "furigana": "お金[かね]の管理[かんり]が苦手[にがて]なので、家計簿[かけいぼ]アプリを使[つか]っています。", "sentence_source": "generated"}, {"text": "図書館では、本の貸し出しをコンピューターで管理している。", "target_word": "管理", "complexity_tier": "T3", "furigana": "図書館[としょかん]では、本[ほん]の貸[か]し出[だ]しをコンピューターで管理[かんり]している。", "sentence_source": "generated"}, {"text": "時間の管理ができる人は、仕事も早く終わらせる。", "target_word": "管理", "complexity_tier": "T3", "furigana": "時間[じかん]の管理[かんり]ができる人[ひと]は、仕事[しごと]も早[はや]く終[お]わらせる。", "sentence_source": "generated"}, {"text": "古い建物なので、火の管理には特に注意が必要だ。", "target_word": "管理", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]なので、火[ひ]の管理[かんり]には特[とく]に注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "子どもの写真は、日付ごとにフォルダーに分けて管理している。", "target_word": "管理", "complexity_tier": "T3", "furigana": "子[こ]どもの写真[しゃしん]は、日付[ひづけ]ごとにフォルダーに分[わ]けて管理[かんり]している。", "sentence_source": "generated"}, {"text": "畑の水の管理を任されて、毎朝見回りに行きます。", "target_word": "管理", "complexity_tier": "T3", "furigana": "畑[はたけ]の水[みず]の管理[かんり]を任[まか]されて、毎朝[まいあさ]見回[みまわ]りに行[い]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "管理", "label": "基本形"}, {"form": "管理する", "label": "サ変動詞形"}], "register": "一般", "sense_fingerprint": "物や数量、状態をきちんと把握して扱うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 任さ (Zipf 3.66), 毎朝 (Zipf 3.91), 見回り (Zipf 2.9)']::text[], 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36342, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理", "is_correct": true, "explanation": "「在庫を管理する」の形。数や状態を把握して整える意味で、倉庫の文脈に合う。"}, {"text": "修理", "is_correct": false, "explanation": "「在庫を修理する」は意味が通らない。修理は壊れた物を直すことに使う。"}, {"text": "運転", "is_correct": false, "explanation": "「在庫を運転する」は成り立たない。運転は車や機械を動かすことに使う。"}, {"text": "出版", "is_correct": false, "explanation": "「在庫を出版する」は意味が通らない。出版は本や雑誌を世に出すことに使う。"}], "explanations": {"管理": "「在庫を管理する」の形。数や状態を把握して整える意味で、倉庫の文脈に合う。", "修理": "「在庫を修理する」は意味が通らない。修理は壊れた物を直すことに使う。", "運転": "「在庫を運転する」は成り立たない。運転は車や機械を動かすことに使う。", "出版": "「在庫を出版する」は意味が通らない。出版は本や雑誌を世に出すことに使う。"}, "sentence_index": 0, "correct_answer": "管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はその日の出来事を、心の中で管理している。", "explanation": "ここは〈覚えておく〉の意味。管理は物や数量を整えて扱う語で、思い出を胸にしまう場面には使わない。"}, {"text": "彼は母からの頼みを管理して、その場で笑顔を見せた。", "explanation": "ここは〈引き受ける〉の意味。管理は物事を整えて保つ語で、頼みを受ける場面には使えない。"}, {"text": "彼は誘いをきっぱり管理して、その場を去った。", "explanation": "ここは〈断る〉の意味。管理は対象を整えて保つことで、誘いを断る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36342, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理", "is_correct": true, "explanation": "「時間の管理ができる」の形。時間をうまく整える意味で、文脈に合う。"}, {"text": "製造", "is_correct": false, "explanation": "「時間の製造ができる」は意味が通らない。製造は物を作ることに使う。"}, {"text": "輸出", "is_correct": false, "explanation": "「時間の輸出」は成り立たない。輸出は商品を国外へ送ることに使う。"}, {"text": "建築", "is_correct": false, "explanation": "「時間の建築」は成り立たない。建築は建物を作ることに使う。"}], "explanations": {"管理": "「時間の管理ができる」の形。時間をうまく整える意味で、文脈に合う。", "製造": "「時間の製造ができる」は意味が通らない。製造は物を作ることに使う。", "輸出": "「時間の輸出」は成り立たない。輸出は商品を国外へ送ることに使う。", "建築": "「時間の建築」は成り立たない。建築は建物を作ることに使う。"}, "sentence_index": 6, "correct_answer": "管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方、窓から景色を管理して過ごした。", "explanation": "ここは〈眺める〉の意味。景色を見て楽しむ場面に、管理は使わない。"}, {"text": "友達の誕生日を管理して、みんなで祝った。", "explanation": "ここは〈お祝いの席を設ける〉の意味。管理は物事を整えて保つ語なので、催しを開く場面には使えない。"}, {"text": "彼の言葉を管理して、すぐに信じた。", "explanation": "ここは〈真に受ける〉の意味。管理は物事を整えて保つ語なので、人の言葉を真に受ける場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36342, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は会社の情報の管理を力を入れている。", "corrected_sentence": "彼は会社の情報の管理に力を入れている。", "error_description": "「力を入れる」は「に」で受ける（管理に力を入れる）。ここの「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36342, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はお金の管理を得意だ。", "corrected_sentence": "彼はお金の管理が得意だ。", "error_description": "「得意」は「が」で受ける（管理が得意）。ここの「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36344, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時間を厳守する」の「を」。厳守の対象である時間を示している。"}, {"text": "に", "is_correct": false, "explanation": "「に」は厳守の対象を示さない。「時間に厳守しなければならない」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「時間で厳守」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「時間が厳守しなければならない」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「時間を厳守する」の「を」。厳守の対象である時間を示している。", "に": "「に」は厳守の対象を示さない。「時間に厳守しなければならない」は成り立たない。", "で": "「で」は場所や手段を表す。「時間で厳守」は意味が通らない。", "が": "「が」は主語を示す。「時間が厳守しなければならない」は文として成り立たない。"}, "error_tags": {"に": "着点", "で": "手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36344, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時間を厳守する」の「を」。厳守の対象である時間を示している。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同の相手を示す。「時間と厳守する」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「時間へ厳守する」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「時間から厳守する」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「時間を厳守する」の「を」。厳守の対象である時間を示している。", "と": "「と」は共同の相手を示す。「時間と厳守する」は意味が通らない。", "へ": "「へ」は方向を示す。「時間へ厳守する」は成り立たない。", "から": "「から」は起点を示す。「時間から厳守する」は文が成り立たない。"}, "error_tags": {"と": "共同", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36344, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "時間をしっかりまもること。", "primary_collocate": null, "pronunciation": "げんしゅ", "ipa": "ɡeɲɕɯ", "syllable_count": 3, "sentences": [{"text": "会議は九時からなので、開始時間の厳守が必要だ。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "会議[かいぎ]は九時[くじ]からなので、開始[かいし]時間[じかん]の厳守[げんしゅ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この学校では、授業の始まる時間を厳守しなければならない。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "この学校[がっこう]では、授業[じゅぎょう]の始[はじ]まる時間[じかん]を厳守[げんしゅ]しなければならない。", "sentence_source": "generated"}, {"text": "電車は時間の厳守が基本で、一分の遅れも許されない。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "電車[でんしゃ]は時間[じかん]の厳守[げんしゅ]が基本[きほん]で、一分[いっぷん]の遅[おく]れも許[ゆる]されない。", "sentence_source": "generated"}, {"text": "提出の時間を厳守しないと、レポートは受け取ってもらえない。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "提出[ていしゅつ]の時間[じかん]を厳守[げんしゅ]しないと、レポートは受[う]け取[と]ってもらえない。", "sentence_source": "generated"}, {"text": "彼は時間の厳守にうるさく、遅刻した人を叱る。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "彼[かれ]は時間[じかん]の厳守[げんしゅ]にうるさく、遅刻[ちこく]した人[ひと]を叱[しか]る。", "sentence_source": "generated"}, {"text": "工事は時間を厳守して進められたので、予定どおり終わった。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "工事[こうじ]は時間[じかん]を厳守[げんしゅ]して進[すす]められたので、予定[よてい]どおり終[お]わった。", "sentence_source": "generated"}, {"text": "発表は一人五分なので、時間を厳守すること。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "発表[はっぴょう]は一人[ひとり]五分[ごふん]なので、時間[じかん]を厳守[げんしゅ]すること。", "sentence_source": "generated"}, {"text": "バスは出発の時間を厳守するので、集合に遅れてはいけない。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "バスは出発[しゅっぱつ]の時間[じかん]を厳守[げんしゅ]するので、集合[しゅうごう]に遅[おく]れてはいけない。", "sentence_source": "generated"}, {"text": "試験の終了時間を厳守するため、先生はタイマーを使った。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "試験[しけん]の終了[しゅうりょう]時間[じかん]を厳守[げんしゅ]するため、先生[せんせい]はタイマーを使[つか]った。", "sentence_source": "generated"}, {"text": "面接では、開始の時間を厳守することが大切だ。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、開始[かいし]の時間[じかん]を厳守[げんしゅ]することが大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳守", "label": "基本形"}, {"form": "厳守する", "label": "終止形（サ変）"}, {"form": "厳守しない", "label": "未然形"}, {"form": "厳守して", "label": "連用形（て）"}, {"form": "厳守した", "label": "連用形（た）"}], "register": "やや硬い標準（普通体）", "sense_fingerprint": "授業・会議・提出などの決まった時間を、きびしく守ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '612eb789-5ace-4898-ab3a-9c8bb3bd2e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36344, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厳守", "is_correct": true, "explanation": "ここは決まった時間をきびしく守る〈厳守〉。開始時間を守ることが必要だという文になる。"}, {"text": "脱線", "is_correct": false, "explanation": "脱線は本筋から外れること。「開始時間の脱線が必要だ」は意味が通らない。"}, {"text": "反撃", "is_correct": false, "explanation": "反撃は攻められた側が攻め返すこと。「開始時間の反撃」は不自然。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案などに点数をつけること。「開始時間の採点が必要だ」は意味が通らない。"}], "explanations": {"厳守": "ここは決まった時間をきびしく守る〈厳守〉。開始時間を守ることが必要だという文になる。", "脱線": "脱線は本筋から外れること。「開始時間の脱線が必要だ」は意味が通らない。", "反撃": "反撃は攻められた側が攻め返すこと。「開始時間の反撃」は不自然。", "採点": "採点は答案などに点数をつけること。「開始時間の採点が必要だ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "厳守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の花を厳守して、毎朝水をやった。", "explanation": "ここは〈世話〉の意味。厳守は決まりや時間を守ることで、植物を育てる行為には使わない。"}, {"text": "健康を厳守するために、毎朝走っている。", "explanation": "ここは〈維持〉の意味。厳守は約束や決まりを守ることで、健康の状態を保つ文では使わない。"}, {"text": "不審者を厳守するため、警備員が見回っている。", "explanation": "ここは〈監視〉の意味。厳守は決まりや時間を守ることで、人の動きを見張る文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36344, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厳守", "is_correct": true, "explanation": "ここは時間を守る〈厳守〉。発表の時間を守ることを求める文になる。"}, {"text": "熟読", "is_correct": false, "explanation": "熟読は文章をよく読むこと。「時間を熟読すること」は意味が通らない。"}, {"text": "反映", "is_correct": false, "explanation": "反映は他に影響を与えて表れること。「時間を反映すること」は成り立たない。"}, {"text": "接種", "is_correct": false, "explanation": "接種は予防のために体に入れること。「時間を接種すること」は不自然。"}], "explanations": {"厳守": "ここは時間を守る〈厳守〉。発表の時間を守ることを求める文になる。", "熟読": "熟読は文章をよく読むこと。「時間を熟読すること」は意味が通らない。", "反映": "反映は他に影響を与えて表れること。「時間を反映すること」は成り立たない。", "接種": "接種は予防のために体に入れること。「時間を接種すること」は不自然。"}, "sentence_index": 6, "correct_answer": "厳守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相手の意見を厳守して、話を聞いた。", "explanation": "ここは〈尊重〉の意味。厳守は決まりや時間を守ることで、意見を大切にする意味には合わない。"}, {"text": "機械の厳守を毎日行う。", "explanation": "ここは〈点検〉の意味。厳守は決まりや時間を守ることで、機械を調べて確かめる行為には使わない。"}, {"text": "作品の厳守に時間をかけた。", "explanation": "ここは〈仕上げ〉の意味。厳守は時間などを守る行為で、作品を完成させる工程には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36344, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "締め切りの厳守で求められている。", "corrected_sentence": "締め切りの厳守が求められている。", "error_description": "「求められる」の主語は「厳守」なので「が」を付ける。「で」は誤りで、正しくは「厳守が求められている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36344, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遅刻を防ぐため、開始時間の厳守を却下する。", "corrected_sentence": "遅刻を防ぐため、開始時間の厳守を徹底する。", "error_description": "「厳守」は「徹底する」のように守ることを強める動詞と組む。「却下する」は退ける意味で、守る対象の厳守とは組まない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36345, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時間を厳守するのが当たり前」の「を」。厳守の対象である時間を示している。"}, {"text": "に", "is_correct": false, "explanation": "「に」は厳守の対象を示さない。「時間に厳守するのが」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「時間で厳守する」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「時間が厳守する」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「時間を厳守するのが当たり前」の「を」。厳守の対象である時間を示している。", "に": "「に」は厳守の対象を示さない。「時間に厳守するのが」は成り立たない。", "で": "「で」は手段や場所を表す。「時間で厳守する」は意味が通らない。", "が": "「が」は主語を示す。「時間が厳守する」は成り立たない。"}, "error_tags": {"に": "着点", "で": "手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36345, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時間を厳守できず」の「を」。厳守の対象である時間を示している。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同の相手を示す。「時間と厳守できず」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「時間へ厳守できず」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点や対象を示すが、「時間に厳守できず」は不自然で文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「時間を厳守できず」の「を」。厳守の対象である時間を示している。", "と": "「と」は共同の相手を示す。「時間と厳守できず」は意味が通らない。", "へ": "「へ」は方向を示す。「時間へ厳守できず」は成り立たない。", "に": "「に」は着点や対象を示すが、「時間に厳守できず」は不自然で文が成り立たない。"}, "error_tags": {"と": "共同", "へ": "方向", "に": "着点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36345, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "約束した時間を正確に守ること。遅れずに行動すること。", "primary_collocate": null, "pronunciation": "げんしゅ", "ipa": "ɡeɲɕɯ", "syllable_count": 3, "sentences": [{"text": "友達との待ち合わせは、約束の時間を厳守するようにしている。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "友達[ともだち]との待[ま]ち合[あ]わせは、約束[やくそく]の時間[じかん]を厳守[げんしゅ]するようにしている。", "sentence_source": "generated"}, {"text": "取引先との約束では、時間を厳守するのが当たり前だ。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "取引先[とりひきさき]との約束[やくそく]では、時間[じかん]を厳守[げんしゅ]するのが当[あ]たり前[まえ]だ。", "sentence_source": "generated"}, {"text": "彼女は集合の時間を厳守する人で、いつも五分前に来ている。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は集合[しゅうごう]の時間[じかん]を厳守[げんしゅ]する人[ひと]で、いつも五分前[ごふんまえ]に来[き]ている。", "sentence_source": "generated"}, {"text": "約束の時間を厳守するため、運転手は早く出発した。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]を厳守[げんしゅ]するため、運転手[うんてんしゅ]は早[はや]く出発[しゅっぱつ]した。", "sentence_source": "generated"}, {"text": "遅れずに行動するために、集合の時間を厳守しよう。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "遅[おく]れずに行動[こうどう]するために、集合[しゅうごう]の時間[じかん]を厳守[げんしゅ]しよう。", "sentence_source": "generated"}, {"text": "子どもにも、約束した帰宅の時間の厳守を教えている。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "子[こ]どもにも、約束[やくそく]した帰宅[きたく]の時間[じかん]の厳守[げんしゅ]を教[おし]えている。", "sentence_source": "generated"}, {"text": "約束した時間の厳守は、社会人としての基本だ。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "約束[やくそく]した時間[じかん]の厳守[げんしゅ]は、社会人[しゃかいじん]としての基本[きほん]だ。", "sentence_source": "generated"}, {"text": "彼は約束した時間を厳守できず、また客を待たせてしまった。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "彼[かれ]は約束[やくそく]した時間[じかん]を厳守[げんしゅ]できず、また客[きゃく]を待[ま]たせてしまった。", "sentence_source": "generated"}, {"text": "医者との約束の時間を厳守したので、診察はすぐ始まった。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "医者[いしゃ]との約束[やくそく]の時間[じかん]を厳守[げんしゅ]したので、診察[しんさつ]はすぐ始[はじ]まった。", "sentence_source": "generated"}, {"text": "旅行では集合の時間の厳守が求められ、遅れた人は置いていかれる。", "target_word": "厳守", "complexity_tier": "T3", "furigana": "旅行[りょこう]では集合[しゅうごう]の時間[じかん]の厳守[げんしゅ]が求[もと]められ、遅[おく]れた人[ひと]は置[お]いていかれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳守", "label": "基本形"}, {"form": "厳守する", "label": "終止形（サ変）"}, {"form": "厳守しない", "label": "未然形"}, {"form": "厳守して", "label": "連用形（て）"}, {"form": "厳守した", "label": "連用形（た）"}], "register": "やや硬い標準（普通体）", "sense_fingerprint": "待ち合わせや集合など、約束した時刻に遅れず行動すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '612eb789-5ace-4898-ab3a-9c8bb3bd2e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36345, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厳守", "is_correct": true, "explanation": "ここは約束の時間を正確に守る〈厳守〉。待ち合わせの時間を守る、という文になる。"}, {"text": "点灯", "is_correct": false, "explanation": "点灯は明かりをつけること。約束の時間には使わないので「時間を点灯する」は合わない。"}, {"text": "消去", "is_correct": false, "explanation": "消去はデータなどを消すこと。「約束の時間を消去する」は意味が通らない。"}, {"text": "装着", "is_correct": false, "explanation": "装着は身につけること。時間は身につける対象にならず、文として成り立たない。"}], "explanations": {"厳守": "ここは約束の時間を正確に守る〈厳守〉。待ち合わせの時間を守る、という文になる。", "点灯": "点灯は明かりをつけること。約束の時間には使わないので「時間を点灯する」は合わない。", "消去": "消去はデータなどを消すこと。「約束の時間を消去する」は意味が通らない。", "装着": "装着は身につけること。時間は身につける対象にならず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "厳守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "逃げた犯人を厳守するため、警官は早く出発した。", "explanation": "ここは〈追跡〉の意味。厳守は決まりや時間を守ることで、人の後を追う意味にはならない。"}, {"text": "美術館で絵画を厳守したあと、カフェで休んだ。", "explanation": "ここは〈鑑賞〉の意味。厳守は約束や時間を守ることで、絵を味わう行為には使わない。"}, {"text": "お気に入りの帽子を厳守して、毎日かぶっている。", "explanation": "ここは〈大切にする〉の意味。厳守は決まりや時間を守ることで、物を大事にする意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36345, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厳守", "is_correct": true, "explanation": "ここは約束した時間を守る〈厳守〉。社会人として基本になる行為を述べている。"}, {"text": "放浪", "is_correct": false, "explanation": "放浪は目的もなくさまようこと。時間の基本として成り立たない。"}, {"text": "運搬", "is_correct": false, "explanation": "運搬は荷物を運ぶこと。約束の時間を基本とする文には合わない。"}, {"text": "録画", "is_correct": false, "explanation": "録画は映像を記録すること。約束の時間には合わない。"}], "explanations": {"厳守": "ここは約束した時間を守る〈厳守〉。社会人として基本になる行為を述べている。", "放浪": "放浪は目的もなくさまようこと。時間の基本として成り立たない。", "運搬": "運搬は荷物を運ぶこと。約束の時間を基本とする文には合わない。", "録画": "録画は映像を記録すること。約束の時間には合わない。"}, "sentence_index": 6, "correct_answer": "厳守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ストーブを厳守して、部屋を暖めた。", "explanation": "ここは〈点火〉の意味。厳守は約束や決まりを守ることで、火をつける行為には使わない。"}, {"text": "鉱山で石炭を厳守して、町に運んだ。", "explanation": "ここは〈採掘〉の意味。厳守は守る行為で、地中から資源を掘り出す意味にはならない。"}, {"text": "ピアノの曲を厳守して、会場を沸かせた。", "explanation": "ここは〈演奏〉の意味。厳守は時間や決まりを守ることで、曲を弾いて聞かせる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36345, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "約束の時間の厳守を、毎日努めている。", "corrected_sentence": "約束の時間の厳守に、毎日努めている。", "error_description": "「努める」は目標を「に」で示す。「を」は誤りで、正しくは「厳守に努める」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36345, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族との約束では、時間の厳守を断っている。", "corrected_sentence": "家族との約束では、時間の厳守を心がけている。", "error_description": "「厳守」は「心がける」のように守る姿勢を表す動詞と組む。「断る」は退ける意味で、守る対象の厳守とは組まない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36346, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「周りの目を意識しすぎて」の「を」。「意識する」は目的語に「を」を取る。"}, {"text": "に", "is_correct": false, "explanation": "「目に意識しすぎて」は成り立たず、「意識」の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「目と意識しすぎて」は並列にならず、不自然で文として続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「目へ意識しすぎて」は方向を表す「へ」で、「意識」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「周りの目を意識しすぎて」の「を」。「意識する」は目的語に「を」を取る。", "に": "「目に意識しすぎて」は成り立たず、「意識」の目的語にならない。", "と": "「目と意識しすぎて」は並列にならず、不自然で文として続かない。", "へ": "「目へ意識しすぎて」は方向を表す「へ」で、「意識」の対象にはならない。"}, "error_tags": {"に": "帰着点", "と": "並列", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無意識", "is_correct": true, "explanation": "「意識」の対義語で、気づいていない心の状態を表す。"}, {"text": "感情", "is_correct": false, "explanation": "「感情」は「意識」の対義語ではない。"}, {"text": "理性", "is_correct": false, "explanation": "「理性」は「意識」の対義語ではない。"}, {"text": "感覚", "is_correct": false, "explanation": "「感覚」は「意識」の対義語ではない。"}], "correct_answer": "無意識", "explanations": {"無意識": "「意識」の対義語で、気づいていない心の状態を表す。", "感情": "「感情」は「意識」の対義語ではない。", "理性": "「理性」は「意識」の対義語ではない。", "感覚": "「感覚」は「意識」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36346, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「意識を持つ」の「を」。「持つ」の目的語を示す。"}, {"text": "の", "is_correct": false, "explanation": "「意識の、家族みんなで持つ」と続かず、名詞を修飾する形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「意識で持つ」は手段の「で」となるが、「持つ」の対象にならず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「意識から持つ」は起点を表し、「持つ」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「意識を持つ」の「を」。「持つ」の目的語を示す。", "の": "「意識の、家族みんなで持つ」と続かず、名詞を修飾する形にならない。", "で": "「意識で持つ」は手段の「で」となるが、「持つ」の対象にならず不自然。", "から": "「意識から持つ」は起点を表し、「持つ」の目的語にはならない。"}, "error_tags": {"の": "連体修飾", "で": "手段", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無意識", "is_correct": true, "explanation": "「意識」の対義語で、気づいていない心の状態を表す。"}, {"text": "想像", "is_correct": false, "explanation": "「想像」は「意識」の対義語ではない。"}, {"text": "記憶", "is_correct": false, "explanation": "「記憶」は「意識」の対義語ではない。"}, {"text": "推測", "is_correct": false, "explanation": "「推測」は「意識」の対義語ではない。"}], "correct_answer": "無意識", "explanations": {"無意識": "「意識」の対義語で、気づいていない心の状態を表す。", "想像": "「想像」は「意識」の対義語ではない。", "記憶": "「記憶」は「意識」の対義語ではない。", "推測": "「推測」は「意識」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36346, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の考えや気持ちに気づいていること。", "primary_collocate": null, "pronunciation": "いしき", "ipa": "iɕiki", "syllable_count": 3, "sentences": [{"text": "毎日、姿勢を意識して歩くようにしている。", "target_word": "意識", "complexity_tier": "T3", "furigana": "毎日[まいにち]、姿勢[しせい]を意識[いしき]して歩[ある]くようにしている。", "sentence_source": "generated"}, {"text": "彼女は周りの目を意識しすぎて、うまく話せなかった。", "target_word": "意識", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は周[まわ]りの目[め]を意識[いしき]しすぎて、うまく話[はな]せなかった。", "sentence_source": "generated"}, {"text": "健康への意識が変わって、野菜を食べるようになった。", "target_word": "意識", "complexity_tier": "T3", "furigana": "健康[けんこう]への意識[いしき]が変[か]わって、野菜[やさい]を食[た]べるようになった。", "sentence_source": "generated"}, {"text": "自分が怒っていることを意識すると、少し落ち着けた。", "target_word": "意識", "complexity_tier": "T3", "furigana": "自分[じぶん]が怒[おこ]っていることを意識[いしき]すると、少[すこ]し落[お]ち着[つ]けた。", "sentence_source": "generated"}, {"text": "相手に意識を向けて聞けば、話の内容がよく分かる。", "target_word": "意識", "complexity_tier": "T3", "furigana": "相手[あいて]に意識[いしき]を向[む]けて聞[き]けば、話[はなし]の内容[ないよう]がよく分[わ]かる。", "sentence_source": "generated"}, {"text": "彼は先生の前では、言葉づかいを意識している。", "target_word": "意識", "complexity_tier": "T3", "furigana": "彼[かれ]は先生[せんせい]の前[まえ]では、言葉[ことば]づかいを意識[いしき]している。", "sentence_source": "generated"}, {"text": "安全への意識が低いと、事故が起こりやすい。", "target_word": "意識", "complexity_tier": "T3", "furigana": "安全[あんぜん]への意識[いしき]が低[ひく]いと、事故[じこ]が起[お]こりやすい。", "sentence_source": "generated"}, {"text": "ゴミを減らす意識を、家族みんなで持つようにした。", "target_word": "意識", "complexity_tier": "T3", "furigana": "ゴミを減[へ]らす意識[いしき]を、家族[かぞく]みんなで持[も]つようにした。", "sentence_source": "generated"}, {"text": "ライバルを意識するあまり、自分のペースを失った。", "target_word": "意識", "complexity_tier": "T3", "furigana": "ライバルを意識[いしき]するあまり、自分[じぶん]のペースを失[うしな]った。", "sentence_source": "generated"}, {"text": "話すときは、声の大きさを意識するといいですよ。", "target_word": "意識", "complexity_tier": "T3", "furigana": "話[はな]すときは、声[こえ]の大[おお]きさを意識[いしき]するといいですよ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意識", "label": "基本形"}, {"form": "意識する", "label": "サ変動詞形"}], "register": "一般", "sense_fingerprint": "あることに注意を向けて気づいている心の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: 言葉づかい (Zipf 2.33)']::text[], 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36346, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意識", "is_correct": true, "explanation": "「姿勢を意識する」の形。注意を向けて気をつける意味で、文脈に合う。"}, {"text": "購入", "is_correct": false, "explanation": "「姿勢を購入する」は意味が通らない。購入は物を買うことに使う。"}, {"text": "申請", "is_correct": false, "explanation": "「姿勢を申請する」は意味が通らない。申請は手続きを求めることに使う。"}, {"text": "製造", "is_correct": false, "explanation": "「姿勢を製造する」は意味が通らない。製造は物を作ることに使う。"}], "explanations": {"意識": "「姿勢を意識する」の形。注意を向けて気をつける意味で、文脈に合う。", "購入": "「姿勢を購入する」は意味が通らない。購入は物を買うことに使う。", "申請": "「姿勢を申請する」は意味が通らない。申請は手続きを求めることに使う。", "製造": "「姿勢を製造する」は意味が通らない。製造は物を作ることに使う。"}, "sentence_index": 0, "correct_answer": "意識"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は負けたくなくて、最後まで意識を張り通した。", "explanation": "ここは〈意地〉の意味。意地を張るとは言うが、意識を張るとは言わない。"}, {"text": "寒さで指の意識がなくなった。", "explanation": "ここは〈感覚〉の意味。冷えて感じなくなる話は感覚と言い、意識は注意が向いている心の状態を指すので合わない。"}, {"text": "その映画は、観る人に強い意識を残した。", "explanation": "ここは〈印象〉の意味。作品が人に残すものは印象と言い、意識は注意が向いている心の状態を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36346, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意識", "is_correct": true, "explanation": "「安全への意識」の形。安全に注意を向けている心の状態を表し、文脈に合う。"}, {"text": "湿度", "is_correct": false, "explanation": "「安全への湿度が低い」は意味が通らない。湿度は空気中の水分を表す。"}, {"text": "発音", "is_correct": false, "explanation": "「安全への発音が低い」は意味が通らない。発音は言葉の音を表す。"}, {"text": "眠気", "is_correct": false, "explanation": "「安全への眠気が低い」は意味が通らない。眠気は眠くなる感覚を表す。"}], "explanations": {"意識": "「安全への意識」の形。安全に注意を向けている心の状態を表し、文脈に合う。", "湿度": "「安全への湿度が低い」は意味が通らない。湿度は空気中の水分を表す。", "発音": "「安全への発音が低い」は意味が通らない。発音は言葉の音を表す。", "眠気": "「安全への眠気が低い」は意味が通らない。眠気は眠くなる感覚を表す。"}, "sentence_index": 6, "correct_answer": "意識"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故の後、彼は意識を取り戻すまで三日かかった。", "explanation": "ここは〈意識不明〉の意味。意識を失う・取り戻す場面は別義で、気づいている心の状態とは違う。"}, {"text": "その話に深く意識を受けた。", "explanation": "ここは〈感銘〉の意味。感銘を受けるとは言うが、意識を受けるとは言わない。"}, {"text": "彼は意識が早く、すぐに結論を出す。", "explanation": "ここは〈決断〉の意味。決めるのが速い人は決断が早いと言い、意識が早いとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36346, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は、いつも周りの目で意識して話している。", "corrected_sentence": "彼女は、いつも周りの目を意識して話している。", "error_description": "「意識する」は「を」で受ける（目を意識する）。ここの「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36346, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は毎朝、呼吸に意識してストレッチをする。", "corrected_sentence": "彼は毎朝、呼吸を意識してストレッチをする。", "error_description": "「意識する」は「を」で受ける（呼吸を意識する）。ここの「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
