INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36348, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「砂浜に根付く」の「に」。根付く場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「根付く」は目的語を取らないので、「を」は合わない。"}, {"text": "の", "is_correct": false, "explanation": "「砂浜の根付き」は名詞を修飾する形にならず、文が続かない。"}, {"text": "と", "is_correct": false, "explanation": "「砂浜と根付き」は並列にならず、「花を咲かせた」に続かない。"}], "correct_answer": "に", "explanations": {"に": "「砂浜に根付く」の「に」。根付く場所を示す。", "を": "「根付く」は目的語を取らないので、「を」は合わない。", "の": "「砂浜の根付き」は名詞を修飾する形にならず、文が続かない。", "と": "「砂浜と根付き」は並列にならず、「花を咲かせた」に続かない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36348, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ねっこがはえたように、しっかりとあるところに定着すること。", "primary_collocate": null, "pronunciation": "ねづく", "ipa": "nedzɯkɯ", "syllable_count": 3, "sentences": [{"text": "植え替えた苗が無事に根付いて、新しい葉が出てきた。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "植[う]え替[か]えた苗[なえ]が無事[ぶじ]に根付[ねづ]いて、新[あたら]しい葉[は]が出[で]てきた。", "sentence_source": "generated"}, {"text": "庭に植えた桜の木が、やっと根付いたようだ。", "target_word": "根付いた", "complexity_tier": "T3", "furigana": "庭[にわ]に植[う]えた桜[さくら]の木[き]が、やっと根付[ねづ]いたようだ。", "sentence_source": "generated"}, {"text": "この川には、外国から来た魚が根付いている。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "この川[かわ]には、外国[がいこく]から来[き]た魚[さかな]が根付[ねづ]いている。", "sentence_source": "generated"}, {"text": "移植した草花が根付くまで、毎日水をやります。", "target_word": "根付く", "complexity_tier": "T3", "furigana": "移植[いしょく]した草花[くさばな]が根付[ねづ]くまで、毎日[まいにち]水[みず]をやります。", "sentence_source": "generated"}, {"text": "引っ越してきた家族は、少しずつこの町に根付いていった。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してきた家族[かぞく]は、少[すこ]しずつこの町[まち]に根付[ねづ]いていった。", "sentence_source": "generated"}, {"text": "都会から来た若者が、村に根付いて農業を続けている。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "都会[とかい]から来[き]た若者[わかもの]が、村[むら]に根付[ねづ]いて農業[のうぎょう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "風が強い場所では、小さな木はなかなか根付かない。", "target_word": "根付かない", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い場所[ばしょ]では、小[ちい]さな木[き]はなかなか根付[ねづ]かない。", "sentence_source": "generated"}, {"text": "海から運ばれた種が砂浜に根付き、花を咲かせた。", "target_word": "根付き", "complexity_tier": "T3", "furigana": "海[うみ]から運[はこ]ばれた種[たね]が砂浜[すなはま]に根付[ねづ]き、花[はな]を咲[さ]かせた。", "sentence_source": "generated"}, {"text": "雨が少ない年は、新しい草がうまく根付かないことがある。", "target_word": "根付かない", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない年[とし]は、新[あたら]しい草[くさ]がうまく根付[ねづ]かないことがある。", "sentence_source": "generated"}, {"text": "山に植えた杉の苗が、数年後にはしっかりと根付いていた。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "山[やま]に植[う]えた杉[すぎ]の苗[なえ]が、数年後[すうねんご]にはしっかりと根付[ねづ]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根付く", "label": "辞書形"}, {"form": "根付かない", "label": "否定形"}, {"form": "根付き", "label": "連用形"}, {"form": "根付いて", "label": "て形"}, {"form": "根付いた", "label": "過去形"}, {"form": "根付けば", "label": "仮定形"}, {"form": "根付こう", "label": "意志形"}], "register": "一般", "sense_fingerprint": "植物や人、生き物がある場所に根を下ろして定着する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36348, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根付いて", "is_correct": true, "explanation": "「苗が無事に根付いて」の形。しっかり定着した状態を表し、文脈に合う。"}, {"text": "枯れて", "is_correct": false, "explanation": "「苗が無事に枯れて」は文脈と矛盾する。枯れるは植物がだめになることを表す。"}, {"text": "折れて", "is_correct": false, "explanation": "「苗が無事に折れて」は意味が通らない。折れるは物が曲がって切れることを表す。"}, {"text": "倒れて", "is_correct": false, "explanation": "「苗が無事に倒れて」は文脈と合わない。倒れるは立っていたものが横になることを表す。"}], "explanations": {"根付いて": "「苗が無事に根付いて」の形。しっかり定着した状態を表し、文脈に合う。", "枯れて": "「苗が無事に枯れて」は文脈と矛盾する。枯れるは植物がだめになることを表す。", "折れて": "「苗が無事に折れて」は意味が通らない。折れるは物が曲がって切れることを表す。", "倒れて": "「苗が無事に倒れて」は文脈と合わない。倒れるは立っていたものが横になることを表す。"}, "sentence_index": 0, "correct_answer": "根付いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強い風で、桜の花びらが根付いて道に散らばった。", "explanation": "ここは〈舞い落ちる〉の意味。花びらが舞い落ちる場面に根付くは使えない。"}, {"text": "坂道で、ボールが根付いてそのまま転がった。", "explanation": "ここは〈移動する〉の意味。ボールが動く場面に根付くは使わず、根を下ろす意味とずれる。"}, {"text": "その鳥は春に根付いて、南へ旅立った。", "explanation": "ここは〈渡りをする〉の意味。鳥が季節ごとに移動する場面に根付くは使えず、定着の意味と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36348, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根付かない", "is_correct": true, "explanation": "「なかなか根付かない」の否定形。定着しにくい状態を表し、文脈に合う。"}, {"text": "散って", "is_correct": false, "explanation": "「なかなか散って」は意味が通らない。散るは花や葉が離れることを表す。"}, {"text": "眠って", "is_correct": false, "explanation": "「なかなか眠って」は文脈と合わない。眠るは人や動物が寝ることを表す。"}, {"text": "運んで", "is_correct": false, "explanation": "「なかなか運んで」は文脈と合わない。運ぶは物を移すことを表す。"}], "explanations": {"根付かない": "「なかなか根付かない」の否定形。定着しにくい状態を表し、文脈に合う。", "散って": "「なかなか散って」は意味が通らない。散るは花や葉が離れることを表す。", "眠って": "「なかなか眠って」は文脈と合わない。眠るは人や動物が寝ることを表す。", "運んで": "「なかなか運んで」は文脈と合わない。運ぶは物を移すことを表す。"}, "sentence_index": 6, "correct_answer": "根付かない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "赤ちゃんは布団に、ぐっすり根付いた。", "explanation": "ここは〈寝付く〉の意味。寝付くとは言うが、根付くは眠りに入る意味では使わない。"}, {"text": "強い風で、落ち葉が根付いて、地面に積もった。", "explanation": "ここは〈舞い降りる〉の意味。落ち葉が舞い降りる場面に根付くは使えない。"}, {"text": "鳥は空に根付いて、ずっと飛び続けた。", "explanation": "ここは〈空を翔ける〉の意味。空を翔ける様子に根付くは使えず、定着の意味と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36348, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "苗が根付ないと、水を吸えない。", "corrected_sentence": "苗が根付かないと、水を吸えない。", "error_description": "「根付く」の否定形は「根付かない」。「根付ない」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "根付いた", "is_correct": true, "explanation": "「やっと根付いたようだ」の過去形。定着した結果の様子を表す。"}, {"text": "根付いて", "is_correct": false, "explanation": "て形では「ようだ」と続かず、文が成り立たない。"}, {"text": "根付けば", "is_correct": false, "explanation": "仮定形では「ようだ」の断定と合わない。"}, {"text": "根付こう", "is_correct": false, "explanation": "意志形では、すでに起きた様子を述べる文に合わない。"}], "correct_form": "根付いた", "base_form": "根付く", "form_label": "過去形", "sentence_index": 1, "explanations": {"根付いた": "「やっと根付いたようだ」の過去形。定着した結果の様子を表す。", "根付いて": "て形では「ようだ」と続かず、文が成り立たない。", "根付けば": "仮定形では「ようだ」の断定と合わない。", "根付こう": "意志形では、すでに起きた様子を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36348, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "苗は、水はけのよい土を根付いた。", "corrected_sentence": "苗は、水はけのよい土に根付いた。", "error_description": "「根付く」は場所を「に」で表す（土に根付く）。ここの「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "根付き", "is_correct": true, "explanation": "「根付き、花を咲かせた」の連用形。文を中止して次の動作につなぐ形。"}, {"text": "根付け", "is_correct": false, "explanation": "命令形では、種が根付いて花を咲かせたという出来事を述べる文に合わない。"}, {"text": "根付かない", "is_correct": false, "explanation": "否定形では、種が定着して花を咲かせたという事実に合わない。"}, {"text": "根付こう", "is_correct": false, "explanation": "意志形では、実際に起きた結果を述べる文に合わない。"}], "correct_form": "根付き", "base_form": "根付く", "form_label": "連用形", "sentence_index": 7, "explanations": {"根付き": "「根付き、花を咲かせた」の連用形。文を中止して次の動作につなぐ形。", "根付け": "命令形では、種が根付いて花を咲かせたという出来事を述べる文に合わない。", "根付かない": "否定形では、種が定着して花を咲かせたという事実に合わない。", "根付こう": "意志形では、実際に起きた結果を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36349, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「根付くには」の「に」。〜するためには、の意味で条件を示す。"}, {"text": "が", "is_correct": false, "explanation": "「根付くが」は主語にならず、「時間がかかる」と続かない。"}, {"text": "を", "is_correct": false, "explanation": "「根付く」は目的語を取らないので、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「根付くへ」は方向にならず、「は」で続く形にもならない。"}], "correct_answer": "に", "explanations": {"に": "「根付くには」の「に」。〜するためには、の意味で条件を示す。", "が": "「根付くが」は主語にならず、「時間がかかる」と続かない。", "を": "「根付く」は目的語を取らないので、「を」は合わない。", "へ": "「根付くへ」は方向にならず、「は」で続く形にもならない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36349, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「心に根付いてきた」の「に」。根付く場所（人々の心）を示す。"}, {"text": "で", "is_correct": false, "explanation": "「心で根付いてきた」は手段の「で」になり、場所を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「心と根付いてきた」は並列にならず、文が続かない。"}, {"text": "の", "is_correct": false, "explanation": "「心の根付いてきた」は名詞を修飾する形にならず、文が続かない。"}], "correct_answer": "に", "explanations": {"に": "「心に根付いてきた」の「に」。根付く場所（人々の心）を示す。", "で": "「心で根付いてきた」は手段の「で」になり、場所を示せない。", "と": "「心と根付いてきた」は並列にならず、文が続かない。", "の": "「心の根付いてきた」は名詞を修飾する形にならず、文が続かない。"}, "error_tags": {"で": "手段", "と": "並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36349, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある考え方や習慣などが、人々の間に深く浸透して、簡単には変わらなくなること。", "primary_collocate": null, "pronunciation": "ねづく", "ipa": "nedzɯkɯ", "syllable_count": 3, "sentences": [{"text": "日本では、朝にあいさつをする習慣が深く根付いている。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "日本[にほん]では、朝[あさ]にあいさつをする習慣[しゅうかん]が深[ふか]く根付[ねづ]いている。", "sentence_source": "generated"}, {"text": "新しい働き方が会社に根付くには、時間がかかる。", "target_word": "根付く", "complexity_tier": "T3", "furigana": "新[あたら]しい働[はたら]き方[かた]が会社[かいしゃ]に根付[ねづ]くには、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "この地域では、お互いに助け合う文化が根付いています。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、お互[たが]いに助[たす]け合[あ]う文化[ぶんか]が根付[ねづ]いています。", "sentence_source": "generated"}, {"text": "分別してゴミを出すという考え方は、すっかり家庭に根付いた。", "target_word": "根付いた", "complexity_tier": "T3", "furigana": "分別[ぶんべつ]してゴミを出[だ]すという考[かんが]え方[かた]は、すっかり家庭[かてい]に根付[ねづ]いた。", "sentence_source": "generated"}, {"text": "早起きの習慣が根付くまで、毎朝同じ時間に起きてみた。", "target_word": "根付く", "complexity_tier": "T3", "furigana": "早起[はやお]きの習慣[しゅうかん]が根付[ねづ]くまで、毎朝[まいあさ]同[おな]じ時間[じかん]に起[お]きてみた。", "sentence_source": "generated"}, {"text": "一度根付いた古い考えは、簡単には変わらない。", "target_word": "根付いた", "complexity_tier": "T3", "furigana": "一度[いちど]根付[ねづ]いた古[ふる]い考[かんが]えは、簡単[かんたん]には変[か]わらない。", "sentence_source": "generated"}, {"text": "キャッシュレス決済は、若い人たちの間に根付きつつある。", "target_word": "根付き", "complexity_tier": "T3", "furigana": "キャッシュレス決済[けっさい]は、若[わか]い人[ひと]たちの間[あいだ]に根付[ねづ]きつつある。", "sentence_source": "generated"}, {"text": "祭りは長い年月をかけて、この町の人々の心に根付いてきた。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "祭[まつ]りは長[なが]い年月[としつき]をかけて、この町[まち]の人々[ひとびと]の心[こころ]に根付[ねづ]いてきた。", "sentence_source": "generated"}, {"text": "環境を守る意識が学校に根付くよう、毎月授業を行っている。", "target_word": "根付く", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]る意識[いしき]が学校[がっこう]に根付[ねづ]くよう、毎月[まいつき]授業[じゅぎょう]を行[おこな]っている。", "sentence_source": "generated"}, {"text": "お正月に家族で集まる風習は、今も多くの家に根付いている。", "target_word": "根付いて", "complexity_tier": "T3", "furigana": "お正月[しょうがつ]に家族[かぞく]で集[あつ]まる風習[ふうしゅう]は、今[いま]も多[おお]くの家[いえ]に根付[ねづ]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根付く", "label": "辞書形"}, {"form": "根付かない", "label": "否定形"}, {"form": "根付き", "label": "連用形"}, {"form": "根付いて", "label": "て形"}, {"form": "根付いた", "label": "過去形"}, {"form": "根付けば", "label": "仮定形"}, {"form": "根付こう", "label": "意志形"}], "register": "一般", "sense_fingerprint": "考え方・習慣・文化が人々の間に深く定着する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36349, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根付いて", "is_correct": true, "explanation": "「深く根付いている」の形。習慣が人々の間に浸透している状態を表す。"}, {"text": "刻んで", "is_correct": false, "explanation": "「習慣が深く刻んでいる」は成り立たない。刻むは物に跡をつける意味。"}, {"text": "枯れて", "is_correct": false, "explanation": "「習慣が深く枯れている」は成り立たない。枯れるは植物が生命を失うことを表す。"}, {"text": "凍って", "is_correct": false, "explanation": "「習慣が深く凍っている」は文脈と合わない。凍るは水などが固まる意味。"}], "explanations": {"根付いて": "「深く根付いている」の形。習慣が人々の間に浸透している状態を表す。", "刻んで": "「習慣が深く刻んでいる」は成り立たない。刻むは物に跡をつける意味。", "枯れて": "「習慣が深く枯れている」は成り立たない。枯れるは植物が生命を失うことを表す。", "凍って": "「習慣が深く凍っている」は文脈と合わない。凍るは水などが固まる意味。"}, "sentence_index": 0, "correct_answer": "根付いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その店のセールは一晩だけ根付いて、翌朝には消えていた。", "explanation": "ここは〈一時的に流行する〉の意味。一晩で消える流行は、長く残る習慣や考え方に使う語とは合わない。"}, {"text": "その電車は駅のホームに根付いたまま、動かなかった。", "explanation": "ここは〈停車したまま動かない〉の意味。乗り物の停止に根付くは使わず、人々の間に浸透する意味とは合わない。"}, {"text": "その工事は三年前に根付いて、今も続いている。", "explanation": "ここは〈始まる〉の意味。工事の始まりは根付くとは言わず、長く定着する習慣とは別物なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36349, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根付き", "is_correct": true, "explanation": "「根付きつつある」の連用形。浸透が進んでいる状態を表す。"}, {"text": "散り", "is_correct": false, "explanation": "「人々の間に散りつつある」は意味が通らない。散るは散らばる意味。"}, {"text": "倒れ", "is_correct": false, "explanation": "「人々の間に倒れつつある」は意味が通らない。倒れるは横になる意味。"}, {"text": "折れ", "is_correct": false, "explanation": "「人々の間に折れつつある」は意味が通らない。折れるは曲がって切れる意味。"}], "explanations": {"根付き": "「根付きつつある」の連用形。浸透が進んでいる状態を表す。", "散り": "「人々の間に散りつつある」は意味が通らない。散るは散らばる意味。", "倒れ": "「人々の間に倒れつつある」は意味が通らない。倒れるは横になる意味。", "折れ": "「人々の間に折れつつある」は意味が通らない。折れるは曲がって切れる意味。"}, "sentence_index": 6, "correct_answer": "根付き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は部屋のすみに根付いて、一日中動かなかった。", "explanation": "ここは〈その場に居続ける〉の意味。居続けることは、根付くが人々の間に浸透する意味とは合わない。"}, {"text": "昨日の試合で、彼の得点がすっかり根付いた。", "explanation": "ここは〈一過性の出来事として残る〉の意味。一度きりの得点は、人々の間に深く浸透して変わらなくなる習慣や考え方ではないので、根付くとは言わない。"}, {"text": "その機械は、工場の床に根付いたまま壊れた。", "explanation": "ここは〈床に固定される〉の意味。機械を床に固定する場面には根付くを使わず、習慣や考え方の浸透とも違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36349, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この習慣は、地域の人々の間を根付いている。", "corrected_sentence": "この習慣は、地域の人々の間に根付いている。", "error_description": "「根付く」は場所を「に」で表す（間に根付く）。ここの「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "根付く", "is_correct": true, "explanation": "辞書形で、「〜には時間がかかる」の主語になる形。"}, {"text": "根付き", "is_correct": false, "explanation": "連用形では「〜には時間がかかる」の主題にならず、文が成り立たない。"}, {"text": "根付こう", "is_correct": false, "explanation": "意志形では「〜には」の形に合わず、文が成り立たない。"}, {"text": "根付かない", "is_correct": false, "explanation": "否定形の「根付かないには」は不自然で、意味も文脈に合わない。"}], "correct_form": "根付く", "base_form": "根付く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"根付く": "辞書形で、「〜には時間がかかる」の主語になる形。", "根付き": "連用形では「〜には時間がかかる」の主題にならず、文が成り立たない。", "根付こう": "意志形では「〜には」の形に合わず、文が成り立たない。", "根付かない": "否定形の「根付かないには」は不自然で、意味も文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36349, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "分別収集は、今ではすっかり家庭に根付くている。", "corrected_sentence": "分別収集は、今ではすっかり家庭に根付いている。", "error_description": "「根付く」のて形は「根付いて」。「根付くている」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "根付いて", "is_correct": true, "explanation": "て形で、「根付いてきた」と続けて経過を表す。"}, {"text": "根付いた", "is_correct": false, "explanation": "過去形では「根付いたてきた」と続かず、文が成り立たない。"}, {"text": "根付けば", "is_correct": false, "explanation": "仮定形では「てきた」に続かず、文が成り立たない。"}, {"text": "根付く", "is_correct": false, "explanation": "辞書形では「てきた」に続かず、文が成り立たない。"}], "correct_form": "根付いて", "base_form": "根付く", "form_label": "て形", "sentence_index": 7, "explanations": {"根付いて": "て形で、「根付いてきた」と続けて経過を表す。", "根付いた": "過去形では「根付いたてきた」と続かず、文が成り立たない。", "根付けば": "仮定形では「てきた」に続かず、文が成り立たない。", "根付く": "辞書形では「てきた」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36351, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「本物の儀式に擬える」で、比べる先を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「儀式が擬えて」では儀式が主語になり、比べる先を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「儀式で擬えて」は手段の意味になり、比べる先を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「儀式の擬えて」と連体修飾にすると、後ろに述語が続かない。"}], "correct_answer": "に", "explanations": {"に": "「本物の儀式に擬える」で、比べる先を示す格助詞。", "が": "「儀式が擬えて」では儀式が主語になり、比べる先を示せない。", "で": "「儀式で擬えて」は手段の意味になり、比べる先を表せない。", "の": "「儀式の擬えて」と連体修飾にすると、後ろに述語が続かない。"}, "error_tags": {"が": "主語", "で": "手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36351, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「山里の庵に擬える」で、比べる先を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「庵を擬えて」では庵が目的語になり、比べる先を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「庵へ擬えて」は方向の意味になり、比較の文にならない。"}, {"text": "から", "is_correct": false, "explanation": "「庵から擬えて」は起点の意味になり、比べる先を示せない。"}], "correct_answer": "に", "explanations": {"に": "「山里の庵に擬える」で、比べる先を示す格助詞。", "を": "「庵を擬えて」では庵が目的語になり、比べる先を示せない。", "へ": "「庵へ擬えて」は方向の意味になり、比較の文にならない。", "から": "「庵から擬えて」は起点の意味になり、比べる先を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36351, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "他のものや人の状態・動作・性質などを、まねて同じようにすること。", "primary_collocate": null, "pronunciation": "なぞらえる", "ipa": "nazoɾaeɾɯ", "syllable_count": 5, "sentences": [{"text": "彼は有名な作家の文体に擬えて小説を書いた。", "target_word": "擬えて", "complexity_tier": "T3", "furigana": "彼[かれ]は有名[ゆうめい]な作家[さっか]の文体[ぶんたい]に擬[なぞら]えて小説[しょうせつ]を書[か]いた。", "sentence_source": "generated"}, {"text": "祭りの行列を本物の儀式に擬えて、学校で再現した。", "target_word": "擬えて", "complexity_tier": "T3", "furigana": "祭[まつ]りの行列[ぎょうれつ]を本物[ほんもの]の儀式[ぎしき]に擬[なぞら]えて、学校[がっこう]で再現[さいげん]した。", "sentence_source": "generated"}, {"text": "この人形は実在の武将に擬えて作られた。", "target_word": "擬えて", "complexity_tier": "T3", "furigana": "この人形[にんぎょう]は実在[じつざい]の武将[ぶしょう]に擬[なぞら]えて作[つく]られた。", "sentence_source": "generated"}, {"text": "子どもは大人の話し方に擬えて、ままごとをしている。", "target_word": "擬えて", "complexity_tier": "T3", "furigana": "子[こ]どもは大人[おとな]の話[はな]し方[かた]に擬[なぞら]えて、ままごとをしている。", "sentence_source": "generated"}, {"text": "劇団は昔の裁判に擬えた舞台を発表した。", "target_word": "擬えた", "complexity_tier": "T3", "furigana": "劇団[げきだん]は昔[むかし]の裁判[さいばん]に擬[なぞら]えた舞台[ぶたい]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "彼は師匠の動きに擬えて、剣の型を覚えた。", "target_word": "擬えて", "complexity_tier": "T3", "furigana": "彼[かれ]は師匠[ししょう]の動[うご]きに擬[なぞら]えて、剣[けん]の型[かた]を覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "実際の試合に擬えた練習で、チームは本番に備えた。", "target_word": "擬えた", "complexity_tier": "T3", "furigana": "実際[じっさい]の試合[しあい]に擬[なぞら]えた練習[れんしゅう]で、チームは本番[ほんばん]に備[そな]えた。", "sentence_source": "generated"}, {"text": "茶室は山里の庵に擬えて建てられた。", "target_word": "擬えて", "complexity_tier": "T3", "furigana": "茶室[ちゃしつ]は山里[やまざと]の庵[いおり]に擬[なぞら]えて建[た]てられた。", "sentence_source": "generated"}, {"text": "古い物語に擬えて、今の出来事を風刺する本が出た。", "target_word": "擬えて", "complexity_tier": "T3", "furigana": "古[ふる]い物語[ものがたり]に擬[なぞら]えて、今[いま]の出来事[できごと]を風刺[ふうし]する本[ほん]が出[で]た。", "sentence_source": "generated"}, {"text": "京都の町は、中国の都に擬えて造られた。", "target_word": "擬えて", "complexity_tier": "T3", "furigana": "京都[きょうと]の町[まち]は、中国[ちゅうごく]の都[みやこ]に擬[なぞら]えて造[つく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "擬える", "label": "終止形"}, {"form": "擬えた", "label": "過去形"}, {"form": "擬えて", "label": "て形"}, {"form": "擬えない", "label": "否定形"}, {"form": "擬えれば", "label": "仮定形"}], "register": "標準的な書き言葉", "sense_fingerprint": "手本となるものの状態や動作をまねて、同じようにつくる・行う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36351, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擬えて", "is_correct": true, "explanation": "「文体にまねて」の連用形で、後ろの「小説を書いた」につながる。"}, {"text": "壊して", "is_correct": false, "explanation": "「文体に壊して」では文体にならう意味にならない。"}, {"text": "眺めて", "is_correct": false, "explanation": "「文体に眺めて」では対象の取り方が合わず、文が成り立たない。"}, {"text": "飲んで", "is_correct": false, "explanation": "「文体に飲んで」は意味が通らず、文として不自然。"}], "explanations": {"擬えて": "「文体にまねて」の連用形で、後ろの「小説を書いた」につながる。", "壊して": "「文体に壊して」では文体にならう意味にならない。", "眺めて": "「文体に眺めて」では対象の取り方が合わず、文が成り立たない。", "飲んで": "「文体に飲んで」は意味が通らず、文として不自然。"}, "sentence_index": 0, "correct_answer": "擬えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は報告書の数字を、前年の数字に擬えて、大まかに見積もった。", "explanation": "ここは〈見積もる〉（大まかに推し量る）の意味。大まかに推し量る場面は、手本どおりにまねる擬えるでは言えない。"}, {"text": "彼は部下の努力を、自分の功績に擬えて、褒美を受け取った。", "explanation": "ここは〈横取りする〉（人のものを取る）の意味。人の努力を自分のものにする場面は、まねて同じにする擬えるでは言えない。"}, {"text": "彼女は約束を、ただの冗談に擬えて、気にしなかった。", "explanation": "ここは〈見くびる〉（大したことはないと軽く見る）の意味。約束を軽く見る場面は、まねて同じにする擬えるでは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36351, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擬えた", "is_correct": true, "explanation": "過去形の連体修飾で、後ろの「練習」を詳しく説明する形。"}, {"text": "忘れた", "is_correct": false, "explanation": "「試合に忘れた練習」では試合との関係が成り立たず、文が通らない。"}, {"text": "叫んだ", "is_correct": false, "explanation": "「試合に叫んだ練習」は意味が通らない。"}, {"text": "叱った", "is_correct": false, "explanation": "「試合に叱った練習」は文として成り立たない。"}], "explanations": {"擬えた": "過去形の連体修飾で、後ろの「練習」を詳しく説明する形。", "忘れた": "「試合に忘れた練習」では試合との関係が成り立たず、文が通らない。", "叫んだ": "「試合に叫んだ練習」は意味が通らない。", "叱った": "「試合に叱った練習」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "擬えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は隣の人の言葉を、悪口に擬えて、腹を立てた。", "explanation": "ここは〈曲解する〉（わざと悪く受け取る）の意味。言葉を悪く解釈する場面は、まねて同じにする擬えるでは言えない。"}, {"text": "彼は友人の励ましを、非難に擬えて、ふさぎこんだ。", "explanation": "ここは〈勘違いする〉（別の意味に取る）の意味。励ましを非難と取り違える場面は、まねて同じにする擬えるでは言えない。"}, {"text": "彼は息子の失敗を、成功に擬えて、大いに喜んだ。", "explanation": "ここは〈過大評価する〉（実際より高く見る）の意味。失敗を成功と見なす場面は、まねて同じにする擬えるでは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36351, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒の作文を、名作の構成で擬えて褒めた。", "corrected_sentence": "先生は生徒の作文を、名作の構成に擬えて褒めた。", "error_description": "「で」が誤り。「AをBに擬える」の比べる先には「に」を使う。「で」では手段の意味になり、比べる先が取れない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "擬えて", "is_correct": true, "explanation": "て形。後ろの「再現した」へつなぐ形で、文に合う。"}, {"text": "擬える", "is_correct": false, "explanation": "終止形。文中で言い切ると、後ろの語句と続かない。"}, {"text": "擬えた", "is_correct": false, "explanation": "過去形。文中では後ろの語句と続かず、文が成り立たない。"}, {"text": "擬えない", "is_correct": false, "explanation": "否定形。否定の意味になり、再現するという文の内容と合わない。"}], "correct_form": "擬えて", "base_form": "擬える", "form_label": "て形", "sentence_index": 1, "explanations": {"擬えて": "て形。後ろの「再現した」へつなぐ形で、文に合う。", "擬える": "終止形。文中で言い切ると、後ろの語句と続かない。", "擬えた": "過去形。文中では後ろの語句と続かず、文が成り立たない。", "擬えない": "否定形。否定の意味になり、再現するという文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36351, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は転んだことを、人生の転機に擬えた話した。", "corrected_sentence": "彼女は転んだことを、人生の転機に擬えて話した。", "error_description": "「擬えた」が誤り。後ろの「話した」につなぐには、て形の「擬えて」が必要。過去形の「擬えた」では続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "擬えて", "is_correct": true, "explanation": "て形。後ろの「建てられた」へつなぐ形で、文に合う。"}, {"text": "擬えれば", "is_correct": false, "explanation": "仮定形。「〜ば」の条件になり、「建てられた」と続かない。"}, {"text": "擬えます", "is_correct": false, "explanation": "丁寧形。普通体の文に丁寧語が混ざり、文のスタイルが合わない。"}, {"text": "擬えられる", "is_correct": false, "explanation": "可能・受身の形。「建てられた」と重なり、文の意味が合わない。"}], "correct_form": "擬えて", "base_form": "擬える", "form_label": "て形", "sentence_index": 7, "explanations": {"擬えて": "て形。後ろの「建てられた」へつなぐ形で、文に合う。", "擬えれば": "仮定形。「〜ば」の条件になり、「建てられた」と続かない。", "擬えます": "丁寧形。普通体の文に丁寧語が混ざり、文のスタイルが合わない。", "擬えられる": "可能・受身の形。「建てられた」と重なり、文の意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36352, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「流動する物は」で、話題を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「物へ、形を変える」は主語がなく成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「流動する物を、形を変える」は「を」が二つ重なり、文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「物から、形を変える」は意味が合わず不自然。"}], "correct_answer": "は", "explanations": {"は": "「流動する物は」で、話題を示す。", "へ": "「物へ、形を変える」は主語がなく成り立たない。", "を": "「流動する物を、形を変える」は「を」が二つ重なり、文として成り立たない。", "から": "「物から、形を変える」は意味が合わず不自然。"}, "error_tags": {"へ": "direction", "を": "object", "から": "source"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "固定", "is_correct": true, "explanation": "一か所に留まって動かないことで、流動の反対である。"}, {"text": "移動", "is_correct": false, "explanation": "場所を動くことで、反対の意味ではない。"}, {"text": "蒸発", "is_correct": false, "explanation": "気体になることで、流動の反対ではない。"}, {"text": "変形", "is_correct": false, "explanation": "形が変わることで、流動に近く反対ではない。"}], "correct_answer": "固定", "explanations": {"固定": "一か所に留まって動かないことで、流動の反対である。", "移動": "場所を動くことで、反対の意味ではない。", "蒸発": "気体になることで、流動の反対ではない。", "変形": "形が変わることで、流動に近く反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36352, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「流動を利用する」で利用する対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「流動に利用して」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「流動から利用して」は、続く「塗る」と意味がつながらず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「流動が利用して」は、流動が利用する側になり意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「流動を利用する」で利用する対象を示す。", "に": "「流動に利用して」は文として成り立たない。", "から": "「流動から利用して」は、続く「塗る」と意味がつながらず不自然。", "が": "「流動が利用して」は、流動が利用する側になり意味が合わない。"}, "error_tags": {"に": "target", "から": "source", "が": "subject"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静止", "is_correct": true, "explanation": "動かずじっとしていることで、流動の反対である。"}, {"text": "沸騰", "is_correct": false, "explanation": "液体が煮え立つことで、反対の意味ではない。"}, {"text": "溶解", "is_correct": false, "explanation": "溶けて液体になることで、反対の意味ではない。"}, {"text": "変形", "is_correct": false, "explanation": "形が変わることで、流動に近く反対ではない。"}], "correct_answer": "静止", "explanations": {"静止": "動かずじっとしていることで、流動の反対である。", "沸騰": "液体が煮え立つことで、反対の意味ではない。", "溶解": "溶けて液体になることで、反対の意味ではない。", "変形": "形が変わることで、流動に近く反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36352, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものが、かたちをかえながら、ゆっくりうごくこと。", "primary_collocate": null, "pronunciation": "りゅうどう", "ipa": "ɾʲɯːdoː", "syllable_count": 4, "sentences": [{"text": "水あめはゆっくり流動する。", "target_word": "流動", "complexity_tier": "T2", "furigana": "みずあめはゆっくりりゅうどうする。", "sentence_source": "generated"}, {"text": "流動する物は、形を変える。", "target_word": "流動", "complexity_tier": "T2", "furigana": "りゅうどうするものは、かたちをかえる。", "sentence_source": "generated"}, {"text": "溶岩の流動が止まりました。", "target_word": "流動", "complexity_tier": "T2", "furigana": "ようがんのりゅうどうがとまりました。", "sentence_source": "generated"}, {"text": "氷河は、とてもゆっくり流動しています。", "target_word": "流動", "complexity_tier": "T3", "furigana": "ひょうがは、とてもゆっくりりゅうどうしています。", "sentence_source": "generated"}, {"text": "泥の流動を、カメラで記録した。", "target_word": "流動", "complexity_tier": "T3", "furigana": "どろのりゅうどうを、カメラできろくした。", "sentence_source": "generated"}, {"text": "粘り気が強いと、流動が遅くなる。", "target_word": "流動", "complexity_tier": "T3", "furigana": "ねばりけがつよいと、りゅうどうがおそくなる。", "sentence_source": "generated"}, {"text": "地下の岩は、長い時間をかけて流動している。", "target_word": "流動", "complexity_tier": "T3", "furigana": "ちかのいわは、ながいじかんをかけてりゅうどうしている。", "sentence_source": "generated"}, {"text": "ペンキの流動を利用して、壁をきれいに塗る。", "target_word": "流動", "complexity_tier": "T3", "furigana": "ペンキのりゅうどうをりようして、かべをきれいにぬる。", "sentence_source": "generated"}, {"text": "流動する砂の中に、足が沈んでしまった。", "target_word": "流動", "complexity_tier": "T3", "furigana": "りゅうどうするすなのなかに、あしがしずんでしまった。", "sentence_source": "generated"}, {"text": "液体の流動を調べる実験で、小さな粒の動きを観察した。", "target_word": "流動", "complexity_tier": "T4", "furigana": "えきたいのりゅうどうをしらべるじっけんで、ちいさなつぶのうごきをかんさつした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流動する", "label": "活用"}, {"form": "流動性", "label": "派生"}, {"form": "流動体", "label": "派生"}, {"form": "流動的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物がゆっくり形を変えて動くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36352, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流動", "is_correct": true, "explanation": "見出し語そのものである。"}, {"text": "流行", "is_correct": false, "explanation": "りゅうこう。「ど」が「こ」に変わるだけの別語。"}, {"text": "流通", "is_correct": false, "explanation": "りゅうつう。「ど」が「つ」に変わるだけの別語。"}, {"text": "流用", "is_correct": false, "explanation": "りゅうよう。「ど」が「よ」に変わるだけの別語。"}], "explanations": {"流動": "見出し語そのものである。", "流行": "りゅうこう。「ど」が「こ」に変わるだけの別語。", "流通": "りゅうつう。「ど」が「つ」に変わるだけの別語。", "流用": "りゅうよう。「ど」が「よ」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "流動"}, "level_3": {"options": [{"text": "流動", "is_correct": true, "explanation": "水あめがゆっくり形を変えて動く意味で合う。"}, {"text": "勉強", "is_correct": false, "explanation": "形は合うが意味が合わない。水あめは勉強しない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが意味が合わない。水あめは結婚しない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。水あめは散歩しない。"}], "explanations": {"流動": "水あめがゆっくり形を変えて動く意味で合う。", "勉強": "形は合うが意味が合わない。水あめは勉強しない。", "結婚": "形は合うが意味が合わない。水あめは結婚しない。", "散歩": "形は合うが意味が合わない。水あめは散歩しない。"}, "sentence_index": 0, "correct_answer": "流動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い机を二階へ流動するのは大変だ。", "explanation": "流動は物が自分で形を変えて動くことで、人が運ぶ意味ではない。"}, {"text": "毎日、公園まで流動して健康を保っている。", "explanation": "流動は人が歩くことではないので誤り。"}, {"text": "このスープは流動がとても熱いので、少し冷ましてから飲む。", "explanation": "流動は温度を表す語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36352, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "流動", "is_correct": true, "explanation": "見出し語そのものである。"}, {"text": "流氷", "is_correct": false, "explanation": "りゅうひょう。「ど」が「ひょ」に変わるだけの別語。"}, {"text": "流暢", "is_correct": false, "explanation": "りゅうちょう。「ど」が「ちょ」に変わるだけの別語。"}, {"text": "竜王", "is_correct": false, "explanation": "りゅうおう。「ど」が「お」に変わるだけの別語。"}], "explanations": {"流動": "見出し語そのものである。", "流氷": "りゅうひょう。「ど」が「ひょ」に変わるだけの別語。", "流暢": "りゅうちょう。「ど」が「ちょ」に変わるだけの別語。", "竜王": "りゅうおう。「ど」が「お」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "流動"}, "level_3": {"options": [{"text": "流動", "is_correct": true, "explanation": "地下の岩が長い時間かけてゆっくり動く意味で合う。"}, {"text": "睡眠", "is_correct": false, "explanation": "形は合うが意味が合わない。岩は睡眠しない。"}, {"text": "営業", "is_correct": false, "explanation": "形は合うが意味が合わない。岩は営業しない。"}, {"text": "計算", "is_correct": false, "explanation": "形は合うが意味が合わない。岩は計算しない。"}], "explanations": {"流動": "地下の岩が長い時間かけてゆっくり動く意味で合う。", "睡眠": "形は合うが意味が合わない。岩は睡眠しない。", "営業": "形は合うが意味が合わない。岩は営業しない。", "計算": "形は合うが意味が合わない。岩は計算しない。"}, "sentence_index": 6, "correct_answer": "流動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "引っ越しで荷物の流動を手伝い、トラックに積んだ。", "explanation": "流動は荷物を運ぶ作業ではないので誤り。"}, {"text": "彼は夜遅くまで流動して、試験に合格した。", "explanation": "流動は勉強することではないので誤り。"}, {"text": "窓ガラスが流動して、床に落ちて粉々になった。", "explanation": "流動は物が壊れることではなく、ゆっくり形を変えて動くことなので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
