INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36353, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停滞", "is_correct": true, "explanation": "物事が進まず滞ることで、流動の反対である。"}, {"text": "変動", "is_correct": false, "explanation": "状態が変わることで、流動に近く反対ではない。"}, {"text": "変化", "is_correct": false, "explanation": "状態が変わることで、流動に近く反対ではない。"}, {"text": "発展", "is_correct": false, "explanation": "進んで大きくなることで、反対の意味ではない。"}], "correct_answer": "停滞", "explanations": {"停滞": "物事が進まず滞ることで、流動の反対である。", "変動": "状態が変わることで、流動に近く反対ではない。", "変化": "状態が変わることで、流動に近く反対ではない。", "発展": "進んで大きくなることで、反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36353, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事が停滞せず、次々に状態を変えて進んでいくこと。流れるように変化し続ける性質。", "primary_collocate": null, "pronunciation": "りゅうどう", "ipa": "ɾʲɯːdoː", "syllable_count": 4, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "流動", "complexity_tier": "T6", "furigana": "ちゅうおうぎんこうによるだいきぼなしさんかいいれオペレーション、すなわちりょうてきかんわせいさくは、たんなるりゅうどうせいのきょうきゅうにとどまらず、こくさいしじょうにおけるかかくはっけんきのうをわいきょくせしめるそくめんをはらんでいる。", "sentence_source": "mined"}, {"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "流動", "complexity_tier": "T6", "furigana": "さらに、こうしたひでんとうてきなきんゆうせいさくがインフレきたいのアンカーとしてきのうしえるいっぽうで、かじょうなりゅうどうせいがじったいけいざいにおけるぶっかじょうしょうあつりょくとそうじょうこうかをうみ、よきせぬスタグフレーションやざいせいしゅどうのシナリオへときけつするリスクをつねにないほうしていることを、われわれはれいてつににんしきするせきむをおっている。", "sentence_source": "mined"}, {"text": "社会は常に流動している。", "target_word": "流動", "complexity_tier": "T3", "furigana": "しゃかいはつねにりゅうどうしている。", "sentence_source": "generated"}, {"text": "流動的な状況が続いています。", "target_word": "流動的", "complexity_tier": "T2", "furigana": "りゅうどうてきなじょうきょうがつづいています。", "sentence_source": "generated"}, {"text": "雇用の流動が進んでいる。", "target_word": "流動", "complexity_tier": "T3", "furigana": "こようのりゅうどうがすすんでいる。", "sentence_source": "generated"}, {"text": "人材の流動が激しい業界で働いている。", "target_word": "流動", "complexity_tier": "T3", "furigana": "じんざいのりゅうどうがはげしいぎょうかいではたらいている。", "sentence_source": "generated"}, {"text": "国際情勢は流動していて、先が読めない。", "target_word": "流動", "complexity_tier": "T3", "furigana": "こくさいじょうせいはりゅうどうしていて、さきがよめない。", "sentence_source": "generated"}, {"text": "流動する世論に合わせて、政党は方針を変えた。", "target_word": "流動", "complexity_tier": "T4", "furigana": "りゅうどうするよろんにあわせて、せいとうはほうしんをかえた。", "sentence_source": "generated"}, {"text": "人口の流動が増えれば、地方の町も変わるだろう。", "target_word": "流動", "complexity_tier": "T4", "furigana": "じんこうのりゅうどうがふえれば、ちほうのまちもかわるだろう。", "sentence_source": "generated"}, {"text": "彼は社会が流動する時代に、柔軟に対応する力を身につけた。", "target_word": "流動", "complexity_tier": "T5", "furigana": "かれはしゃかいがりゅうどうするじだいに、じゅうなんにたいおうするちからをみにつけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流動的", "label": "派生"}, {"form": "流動性", "label": "派生"}, {"form": "流動化", "label": "派生"}, {"form": "流動する", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 状態を次々に変えて進む性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36353, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流動", "is_correct": true, "explanation": "見出し語そのものである。"}, {"text": "流行", "is_correct": false, "explanation": "りゅうこう。「ど」が「こ」に変わるだけの別語。"}, {"text": "流通", "is_correct": false, "explanation": "りゅうつう。「ど」が「つ」に変わるだけの別語。"}, {"text": "流用", "is_correct": false, "explanation": "りゅうよう。「ど」が「よ」に変わるだけの別語。"}], "explanations": {"流動": "見出し語そのものである。", "流行": "りゅうこう。「ど」が「こ」に変わるだけの別語。", "流通": "りゅうつう。「ど」が「つ」に変わるだけの別語。", "流用": "りゅうよう。「ど」が「よ」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "流動"}, "level_3": {"options": [{"text": "流動", "is_correct": true, "explanation": "「流動性」で、資金が滞らず動く性質を表す。"}, {"text": "安全", "is_correct": false, "explanation": "形は合うが意味が合わない。「安全性の供給」は量的緩和の説明にならない。"}, {"text": "可能", "is_correct": false, "explanation": "形は合うが意味が合わない。「可能性の供給」は量的緩和の説明にならない。"}, {"text": "必要", "is_correct": false, "explanation": "形は合うが意味が合わない。「必要性の供給」は量的緩和の説明にならない。"}], "explanations": {"流動": "「流動性」で、資金が滞らず動く性質を表す。", "安全": "形は合うが意味が合わない。「安全性の供給」は量的緩和の説明にならない。", "可能": "形は合うが意味が合わない。「可能性の供給」は量的緩和の説明にならない。", "必要": "形は合うが意味が合わない。「必要性の供給」は量的緩和の説明にならない。"}, "sentence_index": 0, "correct_answer": "流動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "流動的な石は、百年前から全く変わらず動かない。", "explanation": "流動的は変化し続けることなので、変わらない物には使えない。"}, {"text": "彼の身長は流動的で、ちょうど百八十センチある。", "explanation": "流動的は次々に変わり続ける様子なので、決まった数値を述べる文には合わない。"}, {"text": "流動的な箸でご飯を食べた。", "explanation": "流動的は箸の性質を表す語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36353, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "流動", "is_correct": true, "explanation": "見出し語そのものである。"}, {"text": "流氷", "is_correct": false, "explanation": "りゅうひょう。「ど」が「ひょ」に変わるだけの別語。"}, {"text": "流暢", "is_correct": false, "explanation": "りゅうちょう。「ど」が「ちょ」に変わるだけの別語。"}, {"text": "竜王", "is_correct": false, "explanation": "りゅうおう。「ど」が「お」に変わるだけの別語。"}], "explanations": {"流動": "見出し語そのものである。", "流氷": "りゅうひょう。「ど」が「ひょ」に変わるだけの別語。", "流暢": "りゅうちょう。「ど」が「ちょ」に変わるだけの別語。", "竜王": "りゅうおう。「ど」が「お」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "流動"}, "level_3": {"options": [{"text": "流動", "is_correct": true, "explanation": "情勢が次々に変わって先が読めない意味で合う。"}, {"text": "安定", "is_correct": false, "explanation": "形は合うが意味が合わない。安定なら先は読めるはずで、後半と矛盾する。"}, {"text": "休憩", "is_correct": false, "explanation": "形は合うが意味が合わない。国際情勢が休憩するとは言えない。"}, {"text": "成功", "is_correct": false, "explanation": "形は合うが意味が合わない。国際情勢が成功するとは言えない。"}], "explanations": {"流動": "情勢が次々に変わって先が読めない意味で合う。", "安定": "形は合うが意味が合わない。安定なら先は読めるはずで、後半と矛盾する。", "休憩": "形は合うが意味が合わない。国際情勢が休憩するとは言えない。", "成功": "形は合うが意味が合わない。国際情勢が成功するとは言えない。"}, "sentence_index": 6, "correct_answer": "流動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝、公園を流動して体を鍛えている。", "explanation": "流動は人が走ることではないので、運動の意味に使うのは誤り。"}, {"text": "ケーキを流動して、お皿に載せた。", "explanation": "流動は物を運ぶ動作ではないので誤り。"}, {"text": "空が流動して、とてもきれいな青色だった。", "explanation": "流動は色の状態を表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
