INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36353, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この業界は人材の流動に激しい。", "corrected_sentence": "この業界は人材の流動が激しい。", "error_description": "「激しい」の主語は「が」で表す。「流動に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36354, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「差異がある」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「差異を〜ある」では目的語になり、存在を述べる「ある」に続かない。"}, {"text": "と", "is_correct": false, "explanation": "「差異とある」は並列の形になり、存在の文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「差異からある」は起点の意味になり、存在を述べる文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「差異がある」の主語を示す格助詞。", "を": "「差異を〜ある」では目的語になり、存在を述べる「ある」に続かない。", "と": "「差異とある」は並列の形になり、存在の文として成り立たない。", "から": "「差異からある」は起点の意味になり、存在を述べる文に合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
