INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36354, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ふたつのものが、おなじではないこと。", "primary_collocate": null, "pronunciation": "さい", "ipa": "sai", "syllable_count": 2, "sentences": [{"text": "二つの写真には、小さな差異がいくつかある。", "target_word": "差異", "complexity_tier": "T3", "furigana": "二[ふた]つの写真[しゃしん]には、小[ちい]さな差異[さい]がいくつかある。", "sentence_source": "generated"}, {"text": "兄と弟の考え方には大きな差異がある。", "target_word": "差異", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]の考[かんが]え方[かた]には大[おお]きな差異[さい]がある。", "sentence_source": "generated"}, {"text": "実験の結果に差異が出た理由を調べた。", "target_word": "差異", "complexity_tier": "T3", "furigana": "実験[じっけん]の結果[けっか]に差異[さい]が出[で]た理由[りゆう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "二つの辞書の説明の差異を表にまとめた。", "target_word": "差異", "complexity_tier": "T3", "furigana": "二[ふた]つの辞書[じしょ]の説明[せつめい]の差異[さい]を表[ひょう]にまとめた。", "sentence_source": "generated"}, {"text": "年齢による体力の差異は、はっきり見られる。", "target_word": "差異", "complexity_tier": "T3", "furigana": "年齢[ねんれい]による体力[たいりょく]の差異[さい]は、はっきり見[み]られる。", "sentence_source": "generated"}, {"text": "双子でも性格の差異はあるものだ。", "target_word": "差異", "complexity_tier": "T3", "furigana": "双子[ふたご]でも性格[せいかく]の差異[さい]はあるものだ。", "sentence_source": "generated"}, {"text": "計画と実際の差異を、報告書に書く必要がある。", "target_word": "差異", "complexity_tier": "T3", "furigana": "計画[けいかく]と実際[じっさい]の差異[さい]を、報告書[ほうこくしょ]に書[か]く必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "国によって習慣に差異があるのは当然だ。", "target_word": "差異", "complexity_tier": "T3", "furigana": "国[くに]によって習慣[しゅうかん]に差異[さい]があるのは当然[とうぜん]だ。", "sentence_source": "generated"}, {"text": "値段の差異はわずかで、品質はほとんど同じだった。", "target_word": "差異", "complexity_tier": "T3", "furigana": "値段[ねだん]の差異[さい]はわずかで、品質[ひんしつ]はほとんど同[おな]じだった。", "sentence_source": "generated"}, {"text": "二人の意見に差異はなく、すぐに話がまとまった。", "target_word": "差異", "complexity_tier": "T3", "furigana": "二人[ふたり]の意見[いけん]に差異[さい]はなく、すぐに話[はなし]がまとまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "差異", "label": "基本形"}], "register": "標準的な書き言葉", "sense_fingerprint": "二つのものが同じでないこと、その食い違い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36354, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差異", "is_correct": true, "explanation": "「小さな違い」を表す名詞で、写真の違いを述べる文に合う。"}, {"text": "寝具", "is_correct": false, "explanation": "「二つの写真には小さな寝具がある」では写真の話題と合わず、意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「二つの写真に冷蔵庫がある」は内容が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "「二つの写真に天気がある」は意味が通らない。"}], "explanations": {"差異": "「小さな違い」を表す名詞で、写真の違いを述べる文に合う。", "寝具": "「二つの写真には小さな寝具がある」では写真の話題と合わず、意味が通らない。", "冷蔵庫": "「二つの写真に冷蔵庫がある」は内容が成り立たない。", "天気": "「二つの写真に天気がある」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "差異"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は両親の意見の差異に遠慮して、何も言わずに黙った。", "explanation": "ここは〈気兼ね〉（相手を気にする）の意味。相手を気にして黙る場面は、違いを表す差異では言えない。"}, {"text": "彼は計器の差異を、天気の話に擬えて、説明した。", "explanation": "ここは〈世間話〉（雑談）の意味。雑談に当てはめる場面は、違いを表す差異では言えない。"}, {"text": "会議は差異で可決された。", "explanation": "ここは〈満場一致〉の意味。全員が同じ意見になった場面は、違いを表す差異では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36354, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差異", "is_correct": true, "explanation": "計画と実際の違いを表し、報告書に書く対象として合う。"}, {"text": "祭り", "is_correct": false, "explanation": "「計画と実際の祭りを報告書に書く」では内容として成り立たない。"}, {"text": "階段", "is_correct": false, "explanation": "「計画と実際の階段を報告書に書く」は意味が通らない。"}, {"text": "湿気", "is_correct": false, "explanation": "「計画と実際の湿気」は報告書の内容と合わない。"}], "explanations": {"差異": "計画と実際の違いを表し、報告書に書く対象として合う。", "祭り": "「計画と実際の祭りを報告書に書く」では内容として成り立たない。", "階段": "「計画と実際の階段を報告書に書く」は意味が通らない。", "湿気": "「計画と実際の湿気」は報告書の内容と合わない。"}, "sentence_index": 6, "correct_answer": "差異"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は外見を理由に差異を受けた。", "explanation": "ここは〈差別〉（不当な扱い）の意味。不当に扱われる場面は、違いを中立に表す差異では言えない。"}, {"text": "彼は道具の差異を、手際の良さに擬えて、評価した。", "explanation": "ここは〈技量〉（腕前）の意味。腕前を比べる場面は、違いを表す差異では言えず、擬えるでは合わない。"}, {"text": "彼女は夏の差異を、冬の寒さに擬えて、薄着で出かけた。", "explanation": "ここは〈寒暖の差〉（気温の開き）の意味。季節の寒さを当てはめる場面は、違いを表す差異では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36354, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの計画の差異が、表にして比べた。", "corrected_sentence": "二つの計画の差異を、表にして比べた。", "error_description": "「が」が誤り。「比べた」の目的語になるので「を」が必要。「が」では差異が主語になり、比べる対象が欠けて文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36354, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの装置の差異が見つけた。", "corrected_sentence": "二つの装置の差異が見つかった。", "error_description": "「見つけた」が誤り。「差異」は主語になる名詞で、人が主語の「見つける」とは合わない。自然に「差異が見つかった」と受け身の自動詞「見つかる」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
