INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36355, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「差異がある」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「差異を〜ある」では目的語になり、存在を述べる「ある」に続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「差異へある」は方向の意味になり、存在の文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「差異とあるため」は並列の形になり、存在を示す文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「差異がある」の主語を示す格助詞。", "を": "「差異を〜ある」では目的語になり、存在を述べる「ある」に続かない。", "へ": "「差異へある」は方向の意味になり、存在の文として成り立たない。", "と": "「差異とあるため」は並列の形になり、存在を示す文に合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36355, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つ以上のものの間に見られる、異なる点。違い。", "primary_collocate": null, "pronunciation": "さい", "ipa": "sai", "syllable_count": 2, "sentences": [{"text": "東京と大阪の言葉の差異を調べている。", "target_word": "差異", "complexity_tier": "T3", "furigana": "東京[とうきょう]と大阪[おおさか]の言葉[ことば]の差異[さい]を調[しら]べている。", "sentence_source": "generated"}, {"text": "新旧の機種に目立った差異は見当たらない。", "target_word": "差異", "complexity_tier": "T3", "furigana": "新旧[しんきゅう]の機種[きしゅ]に目立[めだ]った差異[さい]は見当[みあ]たらない。", "sentence_source": "generated"}, {"text": "男女の賃金の差異が、問題になっている。", "target_word": "差異", "complexity_tier": "T3", "furigana": "男女[だんじょ]の賃金[ちんぎん]の差異[さい]が、問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "説明書と実物の差異に、客は不満を述べた。", "target_word": "差異", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]と実物[じつぶつ]の差異[さい]に、客[きゃく]は不満[ふまん]を述[の]べた。", "sentence_source": "generated"}, {"text": "二つの案の差異を、会議で整理した。", "target_word": "差異", "complexity_tier": "T3", "furigana": "二[ふた]つの案[あん]の差異[さい]を、会議[かいぎ]で整理[せいり]した。", "sentence_source": "generated"}, {"text": "地域ごとの気温の差異は、地図で見るとよくわかる。", "target_word": "差異", "complexity_tier": "T3", "furigana": "地域[ちいき]ごとの気温[きおん]の差異[さい]は、地図[ちず]で見[み]るとよくわかる。", "sentence_source": "generated"}, {"text": "翻訳によって文の印象に差異が生じる。", "target_word": "差異", "complexity_tier": "T3", "furigana": "翻訳[ほんやく]によって文[ぶん]の印象[いんしょう]に差異[さい]が生[しょう]じる。", "sentence_source": "generated"}, {"text": "作り方に差異があるため、味も少し違う。", "target_word": "差異", "complexity_tier": "T3", "furigana": "作[つく]り方[かた]に差異[さい]があるため、味[あじ]も少[すこ]し違[ちが]う。", "sentence_source": "generated"}, {"text": "前回の調査との差異は、ほとんど見られなかった。", "target_word": "差異", "complexity_tier": "T3", "furigana": "前回[ぜんかい]の調査[ちょうさ]との差異[さい]は、ほとんど見[み]られなかった。", "sentence_source": "generated"}, {"text": "両者の主張の差異が明らかになり、議論が深まった。", "target_word": "差異", "complexity_tier": "T3", "furigana": "両者[りょうしゃ]の主張[しゅちょう]の差異[さい]が明[あき]らかになり、議論[ぎろん]が深[ふか]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "差異", "label": "基本形"}], "register": "標準的な書き言葉", "sense_fingerprint": "比べたときに見つかる異なる点、違い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36355, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差異", "is_correct": true, "explanation": "言葉の違いを指し、調べる対象として合う。"}, {"text": "階段", "is_correct": false, "explanation": "「言葉の階段を調べている」は調べる対象として成り立たない。"}, {"text": "湿気", "is_correct": false, "explanation": "「言葉の湿気を調べている」は意味が通らない。"}, {"text": "天井", "is_correct": false, "explanation": "「言葉の天井を調べている」は調べる対象として意味が通らない。"}], "explanations": {"差異": "言葉の違いを指し、調べる対象として合う。", "階段": "「言葉の階段を調べている」は調べる対象として成り立たない。", "湿気": "「言葉の湿気を調べている」は意味が通らない。", "天井": "「言葉の天井を調べている」は調べる対象として意味が通らない。"}, "sentence_index": 0, "correct_answer": "差異"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は二つの案を、差異に擬えて、一つに決めた。", "explanation": "ここは〈一本化〉（一つにまとめる）の意味。案をまとめる場面は、違いを表す差異では言えず、擬えるでは合わない。"}, {"text": "選挙は差異で決まった。", "explanation": "ここは〈僅差〉（わずかな差）の意味。わずかな得票差で勝敗が決まる場面は、差異では言えない。"}, {"text": "彼女は作品の差異を、名画の模写に擬えて、発表した。", "explanation": "ここは〈盗作〉（他人の作品を写す）の意味。他人の作品を写して出す場面は、形をそっくり同じにする擬えるでは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36355, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差異", "is_correct": true, "explanation": "文の印象に生じる違いを表す名詞で、「生じる」の主語として合う。"}, {"text": "天気", "is_correct": false, "explanation": "「文の印象に天気が生じる」は意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「文の印象に冷蔵庫が生じる」は意味が成り立たない。"}, {"text": "寝具", "is_correct": false, "explanation": "「文の印象に寝具が生じる」は文として意味が通らない。"}], "explanations": {"差異": "文の印象に生じる違いを表す名詞で、「生じる」の主語として合う。", "天気": "「文の印象に天気が生じる」は意味が通らない。", "冷蔵庫": "「文の印象に冷蔵庫が生じる」は意味が成り立たない。", "寝具": "「文の印象に寝具が生じる」は文として意味が通らない。"}, "sentence_index": 6, "correct_answer": "差異"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は人込みの差異を、祭りの騒ぎに擬えて、大声で叫んだ。", "explanation": "ここは〈苦情〉（不満を訴える）の意味。不満を訴える場面は、形をそっくり同じにする擬えるでは言えない。"}, {"text": "彼は会議の差異を、雨の量に擬えて報告した。", "explanation": "ここは〈降水量〉（雨の多さを量ること）の意味。雨を量る場面は、違いを表す差異では言えず、擬えるでは合わない。"}, {"text": "議案は差異を、全員の賛成に擬えて可決した。", "explanation": "ここは〈可決〉（議案を認めること）の意味。全員の賛成で議案を通す場面は、違いを表す差異では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36355, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの方法の差異を、図で飲んだ。", "corrected_sentence": "二つの方法の差異を、図で示した。", "error_description": "「飲んだ」が誤り。「差異」は「示す」「整理する」などと組む名詞で、「飲む」とは結びつかない。正しくは「示した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36355, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの学説の差異が、研究者が注目している。", "corrected_sentence": "二つの学説の差異に、研究者が注目している。", "error_description": "「が」が誤り。「注目する」は対象に「に」を取るので「差異に」が正しい。「が」では差異が主語になり、「注目している」の対象が欠ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36356, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "遅刻する先の時間や場面を示す「に」が入り、「デートに遅刻」になる。"}, {"text": "を", "is_correct": false, "explanation": "「デートを遅刻」は目的語の形になり、遅刻の文脈に合わない。"}, {"text": "が", "is_correct": false, "explanation": "「デートが遅刻」は主語の形になり、人が遅れる文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、遅れる場面を示す形として合わない。"}], "correct_answer": "に", "explanations": {"に": "遅刻する先の時間や場面を示す「に」が入り、「デートに遅刻」になる。", "を": "「デートを遅刻」は目的語の形になり、遅刻の文脈に合わない。", "が": "「デートが遅刻」は主語の形になり、人が遅れる文として不自然。", "へ": "方向を表す「へ」は、遅れる場面を示す形として合わない。"}, "error_tags": {"を": "目的語", "が": "主格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36356, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "食事という予定に遅れることを示す「に」が入り、「食事に遅刻」になる。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は、遅れる予定を示す形として合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表す「と」は、遅刻する先を示す形として合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は、遅刻の文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "食事という予定に遅れることを示す「に」が入り、「食事に遅刻」になる。", "から": "起点を表す「から」は、遅れる予定を示す形として合わない。", "と": "並列を表す「と」は、遅刻する先を示す形として合わない。", "より": "比較を表す「より」は、遅刻の文脈に合わない。"}, "error_tags": {"から": "起点", "と": "相手・並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36356, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "約束の時間に遅れること", "primary_collocate": null, "pronunciation": "ちこく", "ipa": "tɕikokɯ", "syllable_count": 3, "sentences": [{"text": "友だちとの約束に遅刻して、あやまった。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "友[とも]だちとの約束[やくそく]に遅刻[ちこく]して、あやまった。", "sentence_source": "generated"}, {"text": "電車が止まったので、デートに遅刻してしまった。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まったので、デートに遅刻[ちこく]してしまった。", "sentence_source": "generated"}, {"text": "大切な面接に遅刻しないように、早めに家を出た。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "大切[たいせつ]な面接[めんせつ]に遅刻[ちこく]しないように、早[はや]めに家[いえ]を出[で]た。", "sentence_source": "generated"}, {"text": "彼は待ち合わせにいつも遅刻するので、みんな怒っている。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "彼[かれ]は待[ま]ち合[あ]わせにいつも遅刻[ちこく]するので、みんな怒[おこ]っている。", "sentence_source": "generated"}, {"text": "十分の遅刻でも、相手には失礼になる。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "十分[じゅっぷん]の遅刻[ちこく]でも、相手[あいて]には失礼[しつれい]になる。", "sentence_source": "generated"}, {"text": "約束の場所に着くと、遅刻した私を彼女は笑って許してくれた。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "約束[やくそく]の場所[ばしょ]に着[つ]くと、遅刻[ちこく]した私[わたし]を彼女[かのじょ]は笑[わら]って許[ゆる]してくれた。", "sentence_source": "generated"}, {"text": "打ち合わせに遅刻するときは、前もって連絡したほうがいい。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "打[う]ち合[あ]わせに遅刻[ちこく]するときは、前[まえ]もって連絡[れんらく]したほうがいい。", "sentence_source": "generated"}, {"text": "道が混んでいて、友人との食事に遅刻した。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "道[みち]が混[こ]んでいて、友人[ゆうじん]との食事[しょくじ]に遅刻[ちこく]した。", "sentence_source": "generated"}, {"text": "彼女は遅刻をきらうので、約束の十分前に来る。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は遅刻[ちこく]をきらうので、約束[やくそく]の十分前[じゅっぷんまえ]に来[く]る。", "sentence_source": "generated"}, {"text": "地図を見まちがえて、客との約束に遅刻してしまった。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]まちがえて、客[きゃく]との約束[やくそく]に遅刻[ちこく]してしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遅刻", "label": "基本形"}, {"form": "遅刻する", "label": "動詞形"}, {"form": "遅刻した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "待ち合わせや面接など、相手との約束の時間に遅れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: きらう (Zipf 1.4)']::text[], 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36356, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遅刻", "is_correct": true, "explanation": "約束の時間に遅れることを表し、「約束に遅刻して」に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "「約束に掃除して」は成り立たず、文意が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "「約束に散歩して」は意味が合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "「約束に宿題して」は文脈に合わない。"}], "explanations": {"遅刻": "約束の時間に遅れることを表し、「約束に遅刻して」に合う。", "掃除": "「約束に掃除して」は成り立たず、文意が通らない。", "散歩": "「約束に散歩して」は意味が合わない。", "宿題": "「約束に宿題して」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "遅刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "体調が悪くなり、会議の途中で遅刻して帰った。", "explanation": "ここは〈早退〉の意味。遅刻は時刻に遅れることで、途中で帰る行為は表さないので合わない。"}, {"text": "熱が出て、今日の授業に遅刻して休んだ。", "explanation": "ここは〈欠席〉の意味。遅刻は遅れて来ることで、休むことは表さないので合わない。"}, {"text": "雨が続いたので、遠足を一週間遅刻することにした。", "explanation": "ここは〈延期〉の意味。遅刻は人が約束の時刻に遅れることで、行事の日を後ろにずらす意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36356, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遅刻", "is_correct": true, "explanation": "時間に間に合わないことを表し、「打ち合わせに遅刻する」に合う。"}, {"text": "昼寝", "is_correct": false, "explanation": "「打ち合わせに昼寝するとき」は意味が合わない。"}, {"text": "読書", "is_correct": false, "explanation": "「打ち合わせに読書するとき」は文脈に合わない。"}, {"text": "落雷", "is_correct": false, "explanation": "「打ち合わせに落雷するとき」は成り立たない。"}], "explanations": {"遅刻": "時間に間に合わないことを表し、「打ち合わせに遅刻する」に合う。", "昼寝": "「打ち合わせに昼寝するとき」は意味が合わない。", "読書": "「打ち合わせに読書するとき」は文脈に合わない。", "落雷": "「打ち合わせに落雷するとき」は成り立たない。"}, "sentence_index": 6, "correct_answer": "遅刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな荷物を遅刻して運んだ。", "explanation": "ここは〈運ぶ〉の意味。遅刻は時間に遅れることで、物を運ぶ動作は表さないので合わない。"}, {"text": "ノートを遅刻して書いた。", "explanation": "ここは〈書く〉の意味。遅刻は時間の概念で、文字を書く動作には使わない。"}, {"text": "ケーキを遅刻して焼いた。", "explanation": "ここは〈焼く〉の意味。遅刻は時間に遅れることで、料理の工程には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36356, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝坊して、友人との約束に遅刻てた。", "corrected_sentence": "寝坊して、友人との約束に遅刻した。", "error_description": "誤: 遅刻てた / 正: 遅刻した。「遅刻」は「し」で活用するので「て」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36356, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝坊して、約束の時間を遅刻した。", "corrected_sentence": "寝坊して、約束の時間に遅刻した。", "error_description": "誤: を / 正: に。「遅刻する」は時間に遅れることなので、時間の後に「に」を付ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36357, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "遅刻の直後に続く「と」で、条件を示す「遅刻すると」が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「遅刻を、先生に理由を聞かれる」は文の形が崩れ、条件の文脈に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、遅刻の直後に続く条件の形に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は、遅刻の直後に続く条件の形に合わない。"}], "correct_answer": "と", "explanations": {"と": "遅刻の直後に続く「と」で、条件を示す「遅刻すると」が成り立つ。", "を": "「遅刻を、先生に理由を聞かれる」は文の形が崩れ、条件の文脈に合わない。", "へ": "方向を表す「へ」は、遅刻の直後に続く条件の形に合わない。", "より": "比較を表す「より」は、遅刻の直後に続く条件の形に合わない。"}, "error_tags": {"を": "目的語", "へ": "方向・相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
