INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36357, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "決められた時刻に間に合わないこと", "primary_collocate": null, "pronunciation": "ちこく", "ipa": "tɕikokɯ", "syllable_count": 3, "sentences": [{"text": "寝坊したので、今朝は学校に遅刻した。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "寝坊[ねぼう]したので、今朝[けさ]は学校[がっこう]に遅刻[ちこく]した。", "sentence_source": "generated"}, {"text": "遅刻すると、先生に理由を聞かれる。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "遅刻[ちこく]すると、先生[せんせい]に理由[りゆう]を聞[き]かれる。", "sentence_source": "generated"}, {"text": "毎朝早く起きるから、会社に遅刻したことはない。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]早[はや]く起[お]きるから、会社[かいしゃ]に遅刻[ちこく]したことはない。", "sentence_source": "generated"}, {"text": "バスが遅れて、授業に遅刻してしまった。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "バスが遅[おく]れて、授業[じゅぎょう]に遅刻[ちこく]してしまった。", "sentence_source": "generated"}, {"text": "遅刻が三回続くと、親に連絡が行く。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "遅刻[ちこく]が三回[さんかい]続[つづ]くと、親[おや]に連絡[れんらく]が行[い]く。", "sentence_source": "generated"}, {"text": "始業のベルが鳴ったあとに入ると、遅刻になる。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "始業[しぎょう]のベルが鳴[な]ったあとに入[はい]ると、遅刻[ちこく]になる。", "sentence_source": "generated"}, {"text": "雨で電車が止まり、多くの社員が遅刻した。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "雨[あめ]で電車[でんしゃ]が止[と]まり、多[おお]くの社員[しゃいん]が遅刻[ちこく]した。", "sentence_source": "generated"}, {"text": "朝ごはんを急いで食べたが、結局遅刻した。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんを急[いそ]いで食[た]べたが、結局[けっきょく]遅刻[ちこく]した。", "sentence_source": "generated"}, {"text": "弟は遅刻しそうになって、駅から走って学校へ行った。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "弟[おとうと]は遅刻[ちこく]しそうになって、駅[えき]から走[はし]って学校[がっこう]へ行[い]った。", "sentence_source": "generated"}, {"text": "遅刻は一度でも、仕事の信用に関わる。", "target_word": "遅刻", "complexity_tier": "T3", "furigana": "遅刻[ちこく]は一度[いちど]でも、仕事[しごと]の信用[しんよう]に関[かか]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遅刻", "label": "基本形"}, {"form": "遅刻する", "label": "動詞形"}, {"form": "遅刻した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "学校や会社など、決められた始業時刻に間に合わないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f58e5a06-dc41-4937-81ba-37dc3d155f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36357, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遅刻", "is_correct": true, "explanation": "始業時刻に間に合わないことを表し、「学校に遅刻した」に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「学校に散歩した」は意味が通らない。"}, {"text": "宿題", "is_correct": false, "explanation": "「学校に宿題した」は文脈に合わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "「学校に昼寝した」は不自然で、文意に合わない。"}], "explanations": {"遅刻": "始業時刻に間に合わないことを表し、「学校に遅刻した」に合う。", "散歩": "「学校に散歩した」は意味が通らない。", "宿題": "「学校に宿題した」は文脈に合わない。", "昼寝": "「学校に昼寝した」は不自然で、文意に合わない。"}, "sentence_index": 0, "correct_answer": "遅刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪をひいて、授業に遅刻を休んだ。", "explanation": "ここは〈欠席〉の意味。遅刻は時刻に遅れることで、授業を休む意味は表さないので合わない。"}, {"text": "電車が十分遅刻して、会社が始まった。", "explanation": "ここは〈遅延〉の意味。遅刻は人が時刻に間に合わないことで、乗り物の遅れには使わない。"}, {"text": "熱が出て、授業の途中で遅刻して帰った。", "explanation": "ここは〈早退〉の意味。遅刻は遅れて来ることで、途中で帰る行為は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36357, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遅刻", "is_correct": true, "explanation": "時刻に間に合わなかった意味で、「社員が遅刻した」に合う。"}, {"text": "停電", "is_correct": false, "explanation": "「社員が停電した」は意味をなさない。"}, {"text": "落雷", "is_correct": false, "explanation": "「社員が落雷した」は成り立たない。"}, {"text": "雪崩", "is_correct": false, "explanation": "「社員が雪崩した」は文意に合わない。"}], "explanations": {"遅刻": "時刻に間に合わなかった意味で、「社員が遅刻した」に合う。", "停電": "「社員が停電した」は意味をなさない。", "落雷": "「社員が落雷した」は成り立たない。", "雪崩": "「社員が雪崩した」は文意に合わない。"}, "sentence_index": 6, "correct_answer": "遅刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨で試合が遅刻になった。", "explanation": "ここは〈延期〉の意味。遅刻は人が時刻に間に合わないことで、試合の日程変更には使わないので合わない。"}, {"text": "荷物を遅刻で送った。", "explanation": "ここは〈送る〉の意味。遅刻は時刻に遅れることで、荷物を送る方法を表す語ではない。"}, {"text": "先生の質問に、遅刻で答えた。", "explanation": "ここは〈答える〉の意味。遅刻は時刻の概念で、答えの内容や方法を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36357, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝坊して、今朝は学校に遅刻てた。", "corrected_sentence": "寝坊して、今朝は学校に遅刻した。", "error_description": "誤: 遅刻てた / 正: 遅刻した。「遅刻」は「し」で活用するので「て」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36357, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨で電車が止まり、社員を遅刻した。", "corrected_sentence": "大雨で電車が止まり、社員が遅刻した。", "error_description": "誤: を / 正: が。遅刻する人は主語になるので「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fe1edb9-1a37-42aa-affb-5f6edb30cfd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36358, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「親切な行為に」は感謝の対象・理由を示す「に」。行為の直後に付く格助詞として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「行為が」にすると、後ろの「みんなが」と主語が二つ重なり不自然。"}, {"text": "と", "is_correct": false, "explanation": "「行為と」は並列の意味になり、感謝の理由を述べる文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、感謝の対象を示す文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「親切な行為に」は感謝の対象・理由を示す「に」。行為の直後に付く格助詞として正しい。", "が": "「行為が」にすると、後ろの「みんなが」と主語が二つ重なり不自然。", "と": "「行為と」は並列の意味になり、感謝の理由を述べる文に合わない。", "へ": "「へ」は方向を示すので、感謝の対象を示す文には合わない。"}, "error_tags": {"が": "主語の重複", "と": "並列・引用の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
