INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36358, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が何かをする、そのすること。", "primary_collocate": null, "pronunciation": "こうい", "ipa": "koːi", "syllable_count": 3, "sentences": [{"text": "人の物を勝手に使う行為は、許されません。", "target_word": "行為", "complexity_tier": "T3", "furigana": "人(ひと)の物(もの)を勝手(かって)に使(つか)う行為(こうい)は、許(ゆる)されません。", "sentence_source": "generated"}, {"text": "彼の親切な行為に、みんなが感謝した。", "target_word": "行為", "complexity_tier": "T3", "furigana": "彼(かれ)の親切(しんせつ)な行為(こうい)に、みんなが感謝(かんしゃ)した。", "sentence_source": "generated"}, {"text": "危険な行為をやめないと、事故が起きる。", "target_word": "行為", "complexity_tier": "T3", "furigana": "危険(きけん)な行為(こうい)をやめないと、事故(じこ)が起(お)きる。", "sentence_source": "generated"}, {"text": "電車内で大声を出す行為は、他の客の迷惑になる。", "target_word": "行為", "complexity_tier": "T3", "furigana": "電車内(でんしゃない)で大声(おおごえ)を出(だ)す行為(こうい)は、他(ほか)の客(きゃく)の迷惑(めいわく)になる。", "sentence_source": "generated"}, {"text": "川にごみを捨てる行為は法律で禁じられている。", "target_word": "行為", "complexity_tier": "T3", "furigana": "川(かわ)にごみを捨(す)てる行為(こうい)は法律(ほうりつ)で禁(きん)じられている。", "sentence_source": "generated"}, {"text": "勇気ある行為が認められ、彼は表彰された。", "target_word": "行為", "complexity_tier": "T3", "furigana": "勇気(ゆうき)ある行為(こうい)が認(みと)められ、彼(かれ)は表彰(ひょうしょう)された。", "sentence_source": "generated"}, {"text": "子どもは大人の行為を見て、まねをする。", "target_word": "行為", "complexity_tier": "T3", "furigana": "子(こ)どもは大人(おとな)の行為(こうい)を見(み)て、まねをする。", "sentence_source": "generated"}, {"text": "約束を破る行為は、信頼を失う原因になる。", "target_word": "行為", "complexity_tier": "T3", "furigana": "約束(やくそく)を破(やぶ)る行為(こうい)は、信頼(しんらい)を失(うしな)う原因(げんいん)になる。", "sentence_source": "generated"}, {"text": "試験中にスマホを見る行為は、不正とされる。", "target_word": "行為", "complexity_tier": "T3", "furigana": "試験中(しけんちゅう)にスマホを見(み)る行為(こうい)は、不正(ふせい)とされる。", "sentence_source": "generated"}, {"text": "彼女の行為には悪意がなく、ただ心配していただけだった。", "target_word": "行為", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の行為(こうい)には悪意(あくい)がなく、ただ心配(しんぱい)していただけだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行為", "label": "基本形"}, {"form": "行為を", "label": "目的語"}, {"form": "行為は", "label": "主題"}], "register": "書き言葉", "sense_fingerprint": "人が意図して行う動作や振る舞い。善悪の評価の対象になる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36358, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行為", "is_correct": true, "explanation": "「勝手に物を使う行為」として、人の意図的な振る舞いを指す。文の主語に入り、「許されません」と合う。"}, {"text": "行事", "is_correct": false, "explanation": "「行事」は決まった催しを指す。物を勝手に使うことを行事とは言えず、文が成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節」は一年の区分を指し、人の振る舞いには使わない。主語として文が成り立たない。"}, {"text": "義務", "is_correct": false, "explanation": "「義務」は果たすべき務め。勝手に物を使うことを義務とは言えず、「許されません」ともつながらない。"}], "explanations": {"行為": "「勝手に物を使う行為」として、人の意図的な振る舞いを指す。文の主語に入り、「許されません」と合う。", "行事": "「行事」は決まった催しを指す。物を勝手に使うことを行事とは言えず、文が成り立たない。", "季節": "「季節」は一年の区分を指し、人の振る舞いには使わない。主語として文が成り立たない。", "義務": "「義務」は果たすべき務め。勝手に物を使うことを義務とは言えず、「許されません」ともつながらない。"}, "sentence_index": 0, "correct_answer": "行為"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ペットは夜になると行為が活発になる。", "explanation": "ここは〈行動〉の意味。行為は人が意図して行う振る舞いを指すので、動物の活動量の増減には使わない。"}, {"text": "祭りの行為が、ゆっくりと町を進んでいく。", "explanation": "ここは〈行列〉の意味。行為は個人の意図的な振る舞いを指し、人が連なって進む列には使わない。"}, {"text": "来月の行為には、全校生徒が参加する。", "explanation": "ここは〈行事〉の意味。行為は人が何かをする振る舞いを指し、学校の催し物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36358, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行為", "is_correct": true, "explanation": "「大人の行為を見て」で、まねの対象になる振る舞いを指す。文脈に合う。"}, {"text": "天候", "is_correct": false, "explanation": "「大人の天候を見て」は意味をなさず、まねの対象にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "「大人の寿命を見て」は見えないものを見ることになり、まねをする文に合わない。"}, {"text": "責任", "is_correct": false, "explanation": "「大人の責任を見て、まねをする」は不自然で、まねの対象として成り立たない。"}], "explanations": {"行為": "「大人の行為を見て」で、まねの対象になる振る舞いを指す。文脈に合う。", "天候": "「大人の天候を見て」は意味をなさず、まねの対象にならない。", "寿命": "「大人の寿命を見て」は見えないものを見ることになり、まねをする文に合わない。", "責任": "「大人の責任を見て、まねをする」は不自然で、まねの対象として成り立たない。"}, "sentence_index": 6, "correct_answer": "行為"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の行為は、週五日の事務だ。", "explanation": "ここは〈仕事〉の意味。行為は人が何かをする行い自体を指し、職業や勤務内容の意味にはならない。"}, {"text": "数学の行為が、前回より十点上がった。", "explanation": "ここは〈成績〉の意味。行為は人の振る舞いを指し、テストの点数の上昇には使わない。"}, {"text": "大雨で起きた行為が、町中で話題になった。", "explanation": "ここは〈出来事〉の意味。行為は人が意図して行うことを指すので、大雨のような自然の出来事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36358, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人の家に無断で入る行為を、犯罪になることがある。", "corrected_sentence": "人の家に無断で入る行為は、犯罪になることがある。", "error_description": "文の主題を示す「行為は」の「は」を、目的語を示す「行為を」の「を」にした誤り。主題が消え、文の骨組みが崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36358, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は自分の行為を反省しる。", "corrected_sentence": "彼は自分の行為を反省している。", "error_description": "「反省する」の活用を誤り「反省しる」とした。「反省している」が正しく、動詞として成立しない形になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36360, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「秩序を保つ」の目的語を示す「を」。文の形に合い、保っていたという意味が通る。"}, {"text": "が", "is_correct": false, "explanation": "「秩序が保っていた」では、保つは他動詞なので主語の「が」と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「秩序に保っていた」は、保つの目的語を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「秩序へ保っていた」は方向を示す「へ」が合わず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「秩序を保つ」の目的語を示す「を」。文の形に合い、保っていたという意味が通る。", "が": "「秩序が保っていた」では、保つは他動詞なので主語の「が」と合わない。", "に": "「秩序に保っていた」は、保つの目的語を示せず不自然。", "へ": "「秩序へ保っていた」は方向を示す「へ」が合わず、文が成り立たない。"}, "error_tags": {"が": "他動詞と主語の不一致", "に": "目的語の格の誤り", "へ": "方向の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "混乱", "is_correct": true, "explanation": "「秩序」が乱れた状態を指し、辞書で対義語として並ぶ語。文脈の「社会の秩序」の反対になる。"}, {"text": "安全", "is_correct": false, "explanation": "「安全」は危険がない状態で、秩序の反対語ではない。"}, {"text": "信頼", "is_correct": false, "explanation": "「信頼」は相手を頼る気持ちで、秩序の反対語ではない。"}, {"text": "対話", "is_correct": false, "explanation": "「対話」は話し合いを指し、秩序と対になる語ではない。"}], "correct_answer": "混乱", "explanations": {"混乱": "「秩序」が乱れた状態を指し、辞書で対義語として並ぶ語。文脈の「社会の秩序」の反対になる。", "安全": "「安全」は危険がない状態で、秩序の反対語ではない。", "信頼": "「信頼」は相手を頼る気持ちで、秩序の反対語ではない。", "対話": "「対話」は話し合いを指し、秩序と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36360, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36360, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がきちんと整っていること。", "primary_collocate": null, "pronunciation": "ちつじょ", "ipa": "tɕitsɯdʑo", "syllable_count": 3, "sentences": [{"text": "警察は町の秩序を守るために、毎晩見回りをしている。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "警察(けいさつ)は町(まち)の秩序(ちつじょ)を守(まも)るために、毎晩(まいばん)見回(みまわ)りをしている。", "sentence_source": "generated"}, {"text": "災害のあとも、人々は列に並び、秩序を保っていた。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "災害(さいがい)のあとも、人々(ひとびと)は列(れつ)に並(なら)び、秩序(ちつじょ)を保(たも)っていた。", "sentence_source": "generated"}, {"text": "試合のあと観客が暴れ出し、会場の秩序が失われた。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "試合(しあい)のあと観客(かんきゃく)が暴(あば)れ出(だ)し、会場(かいじょう)の秩序(ちつじょ)が失(うしな)われた。", "sentence_source": "generated"}, {"text": "社会の秩序は、みんながルールを守ることで成り立つ。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "社会(しゃかい)の秩序(ちつじょ)は、みんながルールを守(まも)ることで成(な)り立(た)つ。", "sentence_source": "generated"}, {"text": "先生が入ってくると、騒がしかった教室に秩序が戻った。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "先生(せんせい)が入(はい)ってくると、騒(さわ)がしかった教室(きょうしつ)に秩序(ちつじょ)が戻(もど)った。", "sentence_source": "generated"}, {"text": "新しい法律は、市場の秩序を乱す業者を取り締まるためのものだ。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "新(あたら)しい法律(ほうりつ)は、市場(しじょう)の秩序(ちつじょ)を乱(みだ)す業者(ぎょうしゃ)を取(と)り締(し)まるためのものだ。", "sentence_source": "generated"}, {"text": "古い秩序が崩れ、新しい時代が始まった。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "古(ふる)い秩序(ちつじょ)が崩(くず)れ、新(あたら)しい時代(じだい)が始(はじ)まった。", "sentence_source": "generated"}, {"text": "避難所では、ボランティアが秩序ある行動を呼びかけた。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "避難所(ひなんじょ)では、ボランティアが秩序(ちつじょ)ある行動(こうどう)を呼(よ)びかけた。", "sentence_source": "generated"}, {"text": "秩序を重んじる祖父は、毎日同じ時間に起きる。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "秩序(ちつじょ)を重(おも)んじる祖父(そふ)は、毎日(まいにち)同(おな)じ時間(じかん)に起(お)きる。", "sentence_source": "generated"}, {"text": "国際社会の秩序を保つには、各国の協力が欠かせない。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "国際社会(こくさいしゃかい)の秩序(ちつじょ)を保(たも)つには、各国(かっこく)の協力(きょうりょく)が欠(か)かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "秩序", "label": "基本形"}, {"form": "秩序を", "label": "目的語"}, {"form": "秩序が", "label": "主語"}], "register": "書き言葉", "sense_fingerprint": "社会や集団などが、決まりに従って乱れずに整っている状態。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36360, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「町の秩序を守る」は、町の決まりや安全な状態を保つ意味。見回りの目的として自然に合う。"}, {"text": "寿命", "is_correct": false, "explanation": "「寿命を守る」は意味をなさず、見回りの目的とも結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を守る」は意味をなさず、見回りとも結びつかない。"}, {"text": "騒音", "is_correct": false, "explanation": "「騒音を守る」は意味をなさず、見回りの目的にならない。"}], "explanations": {"秩序": "「町の秩序を守る」は、町の決まりや安全な状態を保つ意味。見回りの目的として自然に合う。", "寿命": "「寿命を守る」は意味をなさず、見回りの目的とも結びつかない。", "天気": "「天気を守る」は意味をなさず、見回りとも結びつかない。", "騒音": "「騒音を守る」は意味をなさず、見回りの目的にならない。"}, "sentence_index": 0, "correct_answer": "秩序"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ようやく私の秩序が来た。", "explanation": "ここは〈順番〉の意味。秩序は整った状態を指し、自分の番が回ってくるという意味には使わない。"}, {"text": "研修の秩序は、一か月と決まっている。", "explanation": "ここは〈期間〉の意味。秩序は整った状態を指し、時間の長さには使わない。"}, {"text": "列車の秩序は、毎朝更新される。", "explanation": "ここは〈時刻表〉の意味。秩序は状態を表す語で、運行予定を書いた表の更新には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36360, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「古い秩序が崩れ」は、社会の決まりが失われる意味で、新しい時代の始まりと文脈が合う。"}, {"text": "寿命", "is_correct": false, "explanation": "「古い寿命が崩れ」は、寿命が崩れるという言い方が成り立たない。"}, {"text": "人口", "is_correct": false, "explanation": "「古い人口が崩れ」は意味が通らず、時代の変化とも結びつかない。"}, {"text": "学費", "is_correct": false, "explanation": "「古い学費が崩れ」は金額が崩れるという意味になり、不自然。"}], "explanations": {"秩序": "「古い秩序が崩れ」は、社会の決まりが失われる意味で、新しい時代の始まりと文脈が合う。", "寿命": "「古い寿命が崩れ」は、寿命が崩れるという言い方が成り立たない。", "人口": "「古い人口が崩れ」は意味が通らず、時代の変化とも結びつかない。", "学費": "「古い学費が崩れ」は金額が崩れるという意味になり、不自然。"}, "sentence_index": 6, "correct_answer": "秩序"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方になると、通りの秩序が自動で点く。", "explanation": "ここは〈照明〉の意味。秩序は決まりに従った状態で、光を発する設備が点くことには使わない。"}, {"text": "今月の秩序は、前月より二万円増えた。", "explanation": "ここは〈報酬〉の意味。秩序は状態を表す語で、金額が増えるという意味は持たない。"}, {"text": "祖父の秩序は、この半年で三キロ減った。", "explanation": "ここは〈体重〉の意味。秩序は社会や集団の状態を指し、人の体の重さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36360, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の秩序を保たれ、住民は安心して暮らしている。", "corrected_sentence": "町の秩序が保たれ、住民は安心して暮らしている。", "error_description": "「保たれ」の主語を示す「秩序が」の「が」を「秩序を」の「を」にした誤り。受身の主語には「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36360, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園では、秩序が保っている。", "corrected_sentence": "公園では、秩序が保たれている。", "error_description": "「秩序が」を主語にするなら動詞は受身の「保たれている」が必要。他動詞「保っている」は主語と結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36362, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「準備を優先して」で、先にする対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「準備に優先して」は不自然。優先は対象を「を」で受ける。"}, {"text": "で", "is_correct": false, "explanation": "「準備で優先して」は手段を表す格で、優先の対象にならない。"}, {"text": "が", "is_correct": false, "explanation": "「準備が優先して」は主語の形で、対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「準備を優先して」で、先にする対象を示す。", "に": "「準備に優先して」は不自然。優先は対象を「を」で受ける。", "で": "「準備で優先して」は手段を表す格で、優先の対象にならない。", "が": "「準備が優先して」は主語の形で、対象を表せない。"}, "error_tags": {"に": "対象の格の誤り", "で": "手段の格の誤り", "が": "主語の格の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "後回し", "is_correct": true, "explanation": "優先の対義語。重要なものを先にせず、あとに回す意味。"}, {"text": "集約", "is_correct": false, "explanation": "まとめる意味。先後の対立ではない。"}, {"text": "転嫁", "is_correct": false, "explanation": "負担を他人に移す意味。先に扱うこととは対立しない。"}, {"text": "容認", "is_correct": false, "explanation": "認めて受け入れる意味。扱いの順序の対義語ではない。"}], "correct_answer": "後回し", "explanations": {"後回し": "優先の対義語。重要なものを先にせず、あとに回す意味。", "集約": "まとめる意味。先後の対立ではない。", "転嫁": "負担を他人に移す意味。先に扱うこととは対立しない。", "容認": "認めて受け入れる意味。扱いの順序の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36362, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「避難を優先して行動」で、先にする対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「避難へ優先して」は方向を表す格で、対象を受けない。"}, {"text": "と", "is_correct": false, "explanation": "「避難と優先して」は並列や相手を表す格で、対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「避難で優先して」は手段を表す格で、優先の対象を受けない。"}], "correct_answer": "を", "explanations": {"を": "「避難を優先して行動」で、先にする対象を示す。", "へ": "「避難へ優先して」は方向を表す格で、対象を受けない。", "と": "「避難と優先して」は並列や相手を表す格で、対象にならない。", "で": "「避難で優先して」は手段を表す格で、優先の対象を受けない。"}, "error_tags": {"へ": "方向の格の誤り", "と": "並列・相手の格の誤り", "で": "手段の格の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "後回し", "is_correct": true, "explanation": "優先の対義語。家族の用事より友人との約束を先にせず、あとに回す意味。"}, {"text": "専念", "is_correct": false, "explanation": "一つのことに集中する意味。先後の対立ではない。"}, {"text": "期待", "is_correct": false, "explanation": "よい結果を待ち望む意味。扱いの順序とは関係ない。"}, {"text": "分類", "is_correct": false, "explanation": "種類ごとに分ける意味。先に扱うこととは対立しない。"}], "correct_answer": "後回し", "explanations": {"後回し": "優先の対義語。家族の用事より友人との約束を先にせず、あとに回す意味。", "専念": "一つのことに集中する意味。先後の対立ではない。", "期待": "よい結果を待ち望む意味。扱いの順序とは関係ない。", "分類": "種類ごとに分ける意味。先に扱うこととは対立しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36362, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "大事なことを一番先にすること", "primary_collocate": null, "pronunciation": "ゆうせん", "ipa": "jɯːseɴ", "syllable_count": 4, "sentences": [{"text": "子どもの命を優先して、母親は迷わず水の中に入った。", "target_word": "優先", "complexity_tier": "T3", "furigana": "子[こ]どもの命[いのち]を優先[ゆうせん]して、母親[ははおや]は迷[まよ]わず水[みず]の中[なか]に入[はい]った。", "sentence_source": "generated"}, {"text": "大事な試験の準備を優先して、ほかの予定は後回しにした。", "target_word": "優先", "complexity_tier": "T3", "furigana": "大事[だいじ]な試験[しけん]の準備[じゅんび]を優先[ゆうせん]して、ほかの予定[よてい]は後回[あとまわ]しにした。", "sentence_source": "generated"}, {"text": "今日は仕事より体の回復を優先して、早めに寝ることにした。", "target_word": "優先", "complexity_tier": "T3", "furigana": "今日[きょう]は仕事[しごと]より体[からだ]の回復[かいふく]を優先[ゆうせん]して、早[はや]めに寝[ね]ることにした。", "sentence_source": "generated"}, {"text": "病院では、症状が重い人の治療が優先される。", "target_word": "優先", "complexity_tier": "T3", "furigana": "病院[びょういん]では、症状[しょうじょう]が重[おも]い人[ひと]の治療[ちりょう]が優先[ゆうせん]される。", "sentence_source": "generated"}, {"text": "限られたお金は、家賃や食費の支払いを優先して使っている。", "target_word": "優先", "complexity_tier": "T3", "furigana": "限[かぎ]られたお金[かね]は、家賃[やちん]や食費[しょくひ]の支払[しはら]いを優先[ゆうせん]して使[つか]っている。", "sentence_source": "generated"}, {"text": "緊急の電話が入ったので、会議を中断してそちらを優先した。", "target_word": "優先", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の電話[でんわ]が入[はい]ったので、会議[かいぎ]を中断[ちゅうだん]してそちらを優先[ゆうせん]した。", "sentence_source": "generated"}, {"text": "商品を買うとき、私は値段より品質を優先して選ぶ。", "target_word": "優先", "complexity_tier": "T3", "furigana": "商品[しょうひん]を買[か]うとき、私[わたし]は値段[ねだん]より品質[ひんしつ]を優先[ゆうせん]して選[えら]ぶ。", "sentence_source": "generated"}, {"text": "災害が起きたときは、まず避難を優先して行動してください。", "target_word": "優先", "complexity_tier": "T3", "furigana": "災害[さいがい]が起[お]きたときは、まず避難[ひなん]を優先[ゆうせん]して行動[こうどう]してください。", "sentence_source": "generated"}, {"text": "自分の希望より、相手の都合を優先して日程を決めた。", "target_word": "優先", "complexity_tier": "T3", "furigana": "自分[じぶん]の希望[きぼう]より、相手[あいて]の都合[つごう]を優先[ゆうせん]して日程[にってい]を決[き]めた。", "sentence_source": "generated"}, {"text": "一人で悩んでいた彼は、友人との約束より家族の用事を優先した。", "target_word": "優先", "complexity_tier": "T3", "furigana": "一人[ひとり]で悩[なや]んでいた彼[かれ]は、友人[ゆうじん]との約束[やくそく]より家族[かぞく]の用事[ようじ]を優先[ゆうせん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "優先", "label": "基本形"}, {"form": "優先する", "label": "終止形"}, {"form": "優先して", "label": "て形"}, {"form": "優先した", "label": "た形"}], "register": "中立", "sense_fingerprint": "大事なことや急ぐことを、ほかより先にしたり重く扱ったりすること。「Aを優先する」の形が基本。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36362, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "優先", "is_correct": true, "explanation": "「子どもの命を優先して」で、命を何より先に扱う意味に合う。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像に収める意味。命を撮影するという文にはならない。"}, {"text": "解読", "is_correct": false, "explanation": "暗号などを読み解く意味。命を解読するとは言わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味。命を点火するという文にはならない。"}], "explanations": {"優先": "「子どもの命を優先して」で、命を何より先に扱う意味に合う。", "撮影": "写真や映像に収める意味。命を撮影するという文にはならない。", "解読": "暗号などを読み解く意味。命を解読するとは言わない。", "点火": "火をつける意味。命を点火するという文にはならない。"}, "sentence_index": 0, "correct_answer": "優先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "決勝でライバルを破り、ついに優先を果たした。", "explanation": "ここは〈優勝〉の意味。優先は何を先にするかを表すので、大会で一位になることは表せない。"}, {"text": "説明は、理解しやすい優先で並べてある。", "explanation": "ここは〈順序〉の意味。優先は扱いの先後を指すので、説明を並べる順序には使わない。"}, {"text": "この製品は、価格で他社より優先に立っている。", "explanation": "ここは〈優位〉の意味。優先は扱いの先後を表すので、他社より有利な立場を表す「優位に立つ」の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36362, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "優先", "is_correct": true, "explanation": "「品質を優先して選ぶ」で、品質を重く扱う意味に合う。"}, {"text": "点呼", "is_correct": false, "explanation": "人を一人ずつ呼び確かめる意味。商品を点呼して選ぶとは言わない。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える意味。商品を換気するという文にはならない。"}, {"text": "施錠", "is_correct": false, "explanation": "錠をかける意味。品質を施錠して選ぶという文にはならない。"}], "explanations": {"優先": "「品質を優先して選ぶ」で、品質を重く扱う意味に合う。", "点呼": "人を一人ずつ呼び確かめる意味。商品を点呼して選ぶとは言わない。", "換気": "空気を入れ替える意味。商品を換気するという文にはならない。", "施錠": "錠をかける意味。品質を施錠して選ぶという文にはならない。"}, "sentence_index": 6, "correct_answer": "優先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会場の仕上がりは、どの作品も優先の美しさだった。", "explanation": "ここは〈優美〉の意味。優先は扱いの先後を表す語で、美しさの品位は表さない。"}, {"text": "その学生は試験で、クラスの誰より優先の点を取った。", "explanation": "ここは〈優秀〉の意味。優先は何を先にするかを指し、成績の良さには使わない。"}, {"text": "この布は、肌ざわりが優先の逸品だと店の人が勧めた。", "explanation": "ここは〈上等な〉の意味。優先は扱いの先後を表すので、布の品質の良さを表す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36362, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもを先に避難させるため、まず安全を優先で行動した。", "corrected_sentence": "子どもを先に避難させるため、まず安全を優先して行動した。", "error_description": "「優先」を動詞として使うには「優先して」の形が必要。「優先で」は文法的に成り立たず、「て」の形が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
