INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36363, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "「ほかの荷物より優先して」で、比べる相手を示す。"}, {"text": "と", "is_correct": false, "explanation": "「ほかの荷物と優先して」の「と」は並ぶ相手を示し、比べて先にする意味にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「ほかの荷物で優先して」は手段の格で、比べる相手を表さない。"}, {"text": "の", "is_correct": false, "explanation": "「ほかの荷物の優先して」は動詞に続かず、文として成り立たない。"}], "correct_answer": "より", "explanations": {"より": "「ほかの荷物より優先して」で、比べる相手を示す。", "と": "「ほかの荷物と優先して」の「と」は並ぶ相手を示し、比べて先にする意味にはならない。", "で": "「ほかの荷物で優先して」は手段の格で、比べる相手を表さない。", "の": "「ほかの荷物の優先して」は動詞に続かず、文として成り立たない。"}, "error_tags": {"と": "並列・相手の格の誤り", "で": "手段の格の誤り", "の": "連体の助詞の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "後回し", "is_correct": true, "explanation": "優先の対義語。先にせず、あとに回す意味。"}, {"text": "辞退", "is_correct": false, "explanation": "申し出を断って退く意味。先後の対立ではない。"}, {"text": "分担", "is_correct": false, "explanation": "仕事を分け持つ意味。先に扱うこととは対立しない。"}, {"text": "要望", "is_correct": false, "explanation": "ほしいと求める意味。扱いの順序の対義語ではない。"}], "correct_answer": "後回し", "explanations": {"後回し": "優先の対義語。先にせず、あとに回す意味。", "辞退": "申し出を断って退く意味。先後の対立ではない。", "分担": "仕事を分け持つ意味。先に扱うこととは対立しない。", "要望": "ほしいと求める意味。扱いの順序の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36363, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他のものより先に扱うこと。また、その扱い。", "primary_collocate": null, "pronunciation": "ゆうせん", "ipa": "jɯːseɴ", "syllable_count": 4, "sentences": [{"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "優先", "complexity_tier": "T4", "furigana": "現代[げんだい]の商業的[しょうぎょうてき]なベーキングにおいては往々[おうおう]にして画一的[かくいつてき]な効率性[こうりつせい]が優先[ゆうせん]されがちであるが、彼[かれ]が真[しん]に渇望[かつぼう]するのは、サワードウ特有[とくゆう]の繊細[せんさい]かつ複雑[ふくざつ]な酸味[さんみ]と、穀物[こくもつ]本来[ほんらい]が秘[ひ]める深[ふか]い旨[うま]みの極致[きょくち]である。", "sentence_source": "mined"}, {"text": "救急車が来たら、ほかの車は道をあけて通行を優先させる。", "target_word": "優先", "complexity_tier": "T3", "furigana": "救急車[きゅうきゅうしゃ]が来[き]たら、ほかの車[くるま]は道[みち]をあけて通行[つうこう]を優先[ゆうせん]させる。", "sentence_source": "generated"}, {"text": "時間が限られているので、まず重要な仕事から優先して進めよう。", "target_word": "優先", "complexity_tier": "T3", "furigana": "時間[じかん]が限[かぎ]られているので、まず重要[じゅうよう]な仕事[しごと]から優先[ゆうせん]して進[すす]めよう。", "sentence_source": "generated"}, {"text": "この列は予約をしたお客さんが優先なので、あとの人は少し待ってください。", "target_word": "優先", "complexity_tier": "T3", "furigana": "この列[れつ]は予約[よやく]をしたお客[きゃく]さんが優先[ゆうせん]なので、あとの人[ひと]は少[すこ]し待[ま]ってください。", "sentence_source": "generated"}, {"text": "彼は家族の健康を何より優先して、遅くまでの仕事をやめた。", "target_word": "優先", "complexity_tier": "T3", "furigana": "彼[かれ]は家族[かぞく]の健康[けんこう]を何[なに]より優先[ゆうせん]して、遅[おそ]くまでの仕事[しごと]をやめた。", "sentence_source": "generated"}, {"text": "試験前は遊びより勉強を優先しなければならない。", "target_word": "優先", "complexity_tier": "T3", "furigana": "試験前[しけんまえ]は遊[あそ]びより勉強[べんきょう]を優先[ゆうせん]しなければならない。", "sentence_source": "generated"}, {"text": "工事では、費用よりも安全を優先する方針が決まった。", "target_word": "優先", "complexity_tier": "T3", "furigana": "工事[こうじ]では、費用[ひよう]よりも安全[あんぜん]を優先[ゆうせん]する方針[ほうしん]が決[き]まった。", "sentence_source": "generated"}, {"text": "急ぎの荷物は、ほかの荷物より優先して送ります。", "target_word": "優先", "complexity_tier": "T3", "furigana": "急[いそ]ぎの荷物[にもつ]は、ほかの荷物[にもつ]より優先[ゆうせん]して送[おく]ります。", "sentence_source": "generated"}, {"text": "歩行者が渡っているときは、歩行者を優先するのが交通のルールだ。", "target_word": "優先", "complexity_tier": "T3", "furigana": "歩行者[ほこうしゃ]が渡[わた]っているときは、歩行者[ほこうしゃ]を優先[ゆうせん]するのが交通[こうつう]のルールだ。", "sentence_source": "generated"}, {"text": "彼女は自分の意見よりも、チーム全体の利益を優先して判断した。", "target_word": "優先", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の意見[いけん]よりも、チーム全体[ぜんたい]の利益[りえき]を優先[ゆうせん]して判断[はんだん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "優先", "label": "基本形"}, {"form": "優先する", "label": "終止形"}, {"form": "優先して", "label": "て形"}, {"form": "優先される", "label": "受身形"}], "register": "中立", "sense_fingerprint": "複数のものの中で、あるものをほかより先に、または重く扱うこと。「Aを優先する」「Aが優先される」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: ベーキング (Zipf 1.24), 極致 (Zipf 2.48)']::text[], 'f9cf4dc1-c7e1-4580-8173-01af158491fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36363, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "優先", "is_correct": true, "explanation": "「効率性が優先されがち」で、効率を重く扱う意味に合う。"}, {"text": "解散", "is_correct": false, "explanation": "集団を解いて散らす意味。効率性を解散するとは言わない。"}, {"text": "整列", "is_correct": false, "explanation": "並べて揃える意味。効率性が整列されるという文にはならない。"}, {"text": "通過", "is_correct": false, "explanation": "通り過ぎる意味。効率性が通過されがちとは言えない。"}], "explanations": {"優先": "「効率性が優先されがち」で、効率を重く扱う意味に合う。", "解散": "集団を解いて散らす意味。効率性を解散するとは言わない。", "整列": "並べて揃える意味。効率性が整列されるという文にはならない。", "通過": "通り過ぎる意味。効率性が通過されがちとは言えない。"}, "sentence_index": 0, "correct_answer": "優先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その試合は後半に入ると、彼のチームが優先を握った。", "explanation": "ここは〈優勢〉の意味。優先は扱いの先後を指すので、試合の有利さを表す語としては使わない。"}, {"text": "この店は、優先な品だけを選んで仕入れている。", "explanation": "ここは〈優良〉の意味。優先は扱いの先後を表すので、品質の良さは表さない。"}, {"text": "この店のケーキは、私の優先にぴったり合う。", "explanation": "ここは〈好み〉の意味。優先は扱いの先後を表し、味の好みには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36363, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "優先", "is_correct": true, "explanation": "「安全を優先する方針」で、安全を先に扱う意味に合う。"}, {"text": "採決", "is_correct": false, "explanation": "議案の可否を決める意味。安全を採決するとは言わない。"}, {"text": "閉鎖", "is_correct": false, "explanation": "出入りを止める意味。安全を閉鎖する方針という文にはならない。"}, {"text": "撤回", "is_correct": false, "explanation": "取り消す意味。安全を撤回するとは言わない。"}], "explanations": {"優先": "「安全を優先する方針」で、安全を先に扱う意味に合う。", "採決": "議案の可否を決める意味。安全を採決するとは言わない。", "閉鎖": "出入りを止める意味。安全を閉鎖する方針という文にはならない。", "撤回": "取り消す意味。安全を撤回するとは言わない。"}, "sentence_index": 6, "correct_answer": "優先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その演奏は、会場の誰もが認めるほど優先だった。", "explanation": "ここは〈優秀〉の意味。優先は何を先にするかの扱いを指し、演奏の出来ばえには使わない。"}, {"text": "彼女の立ち居振る舞いは、どこか優先で品があった。", "explanation": "ここは〈優雅〉の意味。優先は順序や扱いを表すので、立ち居振る舞いの上品さには使わない。"}, {"text": "彼は仕事の腕前が優先だと評判だ。", "explanation": "ここは〈優れた〉の意味。優先は扱いの先後で、腕前の良さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36363, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏休みは宿題より旅行に優先して計画した。", "corrected_sentence": "夏休みは宿題より旅行を優先して計画した。", "error_description": "「優先する」は先にする対象を「を」で受ける。「旅行に優先して」の「に」が誤りで、「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36363, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "予算会議では、費用よりも安全を優先ない方針になった。", "corrected_sentence": "予算会議では、費用よりも安全を優先する方針になった。", "error_description": "「優先する」の活用の誤り。「優先ない」は文として成り立たず、「優先する」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a964984-339e-4ce2-85e5-3db48fc6bed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36364, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「色を選択する」で、えらぶ対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「色に選択してください」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「色と選択してください」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「色へ選択してください」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「色を選択する」で、えらぶ対象を示す。", "に": "「色に選択してください」は文法的に成り立たない。", "と": "「色と選択してください」は文法的に成り立たない。", "へ": "「色へ選択してください」は文法的に成り立たない。"}, "error_tags": {"に": "target_or_location", "と": "quotation_or_companion", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "強制", "is_correct": true, "explanation": "えらぶ自由がなく押しつけられることで、「選択」の反対の関係にある。"}, {"text": "注文", "is_correct": false, "explanation": "メニューから頼むことで、反対語ではない。"}, {"text": "決定", "is_correct": false, "explanation": "物事を決めることで、反対語ではない。"}, {"text": "判断", "is_correct": false, "explanation": "見極めて決めることで、反対語ではない。"}], "correct_answer": "強制", "explanations": {"強制": "えらぶ自由がなく押しつけられることで、「選択」の反対の関係にある。", "注文": "メニューから頼むことで、反対語ではない。", "決定": "物事を決めることで、反対語ではない。", "判断": "見極めて決めることで、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36364, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「選択する前に」で、時を示す。"}, {"text": "と", "is_correct": false, "explanation": "「選択する前と、よく考えてね」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「選択する前の、よく考えてね」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「選択する前へ、よく考えてね」は文法的に成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「選択する前に」で、時を示す。", "と": "「選択する前と、よく考えてね」は文法的に成り立たない。", "の": "「選択する前の、よく考えてね」は文として成り立たない。", "へ": "「選択する前へ、よく考えてね」は文法的に成り立たない。"}, "error_tags": {"と": "quotation_or_companion", "の": "possessive", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "強制", "is_correct": true, "explanation": "えらぶ自由がなく、むりにさせられることで、「選択」の反対の関係にある。"}, {"text": "選別", "is_correct": false, "explanation": "選び分けることで、むしろ近い意味。"}, {"text": "比較", "is_correct": false, "explanation": "見比べることで、反対語ではない。"}, {"text": "判断", "is_correct": false, "explanation": "見極めて決めることで、反対語ではない。"}], "correct_answer": "強制", "explanations": {"強制": "えらぶ自由がなく、むりにさせられることで、「選択」の反対の関係にある。", "選別": "選び分けることで、むしろ近い意味。", "比較": "見比べることで、反対語ではない。", "判断": "見極めて決めることで、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36364, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんある中から、一つをえらぶこと。", "primary_collocate": null, "pronunciation": "せんたく", "ipa": "sentakɯ", "syllable_count": 4, "sentences": [{"text": "選択は難しい。", "target_word": "選択", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好きな色を選択してください。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "どちらにするか、選択に迷った。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "メニューが多くて、選択が大変だった。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "私は海外で働く選択をした。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画面で言語を選択します。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "いい選択だと思います。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "選択する前に、よく考えてね。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼の選択を、みんなが応援した。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "たくさんの本の中から選択するのは楽しい。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "選択する", "label": "活用"}, {"form": "選択した", "label": "活用"}, {"form": "選択肢", "label": "派生"}, {"form": "選択的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | たくさんの中から一つえらぶこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36364, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "選択", "is_correct": true, "explanation": "見出し語の「せんたく」で、一つをえらぶことを表す。"}, {"text": "先端", "is_correct": false, "explanation": "「せんたん」で、最後のモーラだけが違う別の語。"}, {"text": "船体", "is_correct": false, "explanation": "「せんたい」で、最後のモーラだけが違う別の語。"}, {"text": "先達", "is_correct": false, "explanation": "「せんたつ」で、最後のモーラだけが違う別の語。"}], "explanations": {"選択": "見出し語の「せんたく」で、一つをえらぶことを表す。", "先端": "「せんたん」で、最後のモーラだけが違う別の語。", "船体": "「せんたい」で、最後のモーラだけが違う別の語。", "先達": "「せんたつ」で、最後のモーラだけが違う別の語。"}, "sentence_index": null, "correct_answer": "選択"}, "level_3": {"options": [{"text": "選択", "is_correct": true, "explanation": "えらぶことが難しいという意味になり、文に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机が難しいというのは意味が合わない。"}, {"text": "皿", "is_correct": false, "explanation": "形は合うが、皿が難しいというのは意味が合わない。"}, {"text": "傘", "is_correct": false, "explanation": "形は合うが、傘が難しいというのは意味が合わない。"}], "explanations": {"選択": "えらぶことが難しいという意味になり、文に合う。", "机": "形は合うが、机が難しいというのは意味が合わない。", "皿": "形は合うが、皿が難しいというのは意味が合わない。", "傘": "形は合うが、傘が難しいというのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "選択"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨で服がぬれたから、家で選択を始めた。", "explanation": "「選択」は服を洗うことではなく、洗濯と混同した誤用。"}, {"text": "風邪をひいて、選択が三十九度もあった。", "explanation": "「選択」は体温を表す語ではないので、温度とは結びつかない。"}, {"text": "山の選択に登って、きれいな景色を見た。", "explanation": "「選択」は山の頂上などを表す語ではないので、登る場所にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36364, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "選択", "is_correct": true, "explanation": "見出し語の「せんたく」で、たくさんの中から一つをえらぶこと。"}, {"text": "詮索", "is_correct": false, "explanation": "「せんさく」で、「た」が「さ」に変わった別の語。"}, {"text": "先客", "is_correct": false, "explanation": "「せんきゃく」で、「た」が「きゃ」に変わった別の語。"}, {"text": "先覚", "is_correct": false, "explanation": "「せんかく」で、「た」が「か」に変わった別の語。"}], "explanations": {"選択": "見出し語の「せんたく」で、たくさんの中から一つをえらぶこと。", "詮索": "「せんさく」で、「た」が「さ」に変わった別の語。", "先客": "「せんきゃく」で、「た」が「きゃ」に変わった別の語。", "先覚": "「せんかく」で、「た」が「か」に変わった別の語。"}, "sentence_index": null, "correct_answer": "選択"}, "level_3": {"options": [{"text": "選択", "is_correct": true, "explanation": "「いい選択だ」は、えらんだことをほめる自然な表現。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが、「いい昨日だと思います」は意味が合わない。"}, {"text": "全部", "is_correct": false, "explanation": "形は合うが、「いい全部だと思います」は意味が合わない。"}, {"text": "以外", "is_correct": false, "explanation": "形は合うが、「いい以外だと思います」は意味が合わない。"}], "explanations": {"選択": "「いい選択だ」は、えらんだことをほめる自然な表現。", "昨日": "形は合うが、「いい昨日だと思います」は意味が合わない。", "全部": "形は合うが、「いい全部だと思います」は意味が合わない。", "以外": "形は合うが、「いい以外だと思います」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "選択"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の夜は、選択が降って、道がぬれた。", "explanation": "「選択」は雨のような天気を表す語ではないので、「降る」とは結びつかない。"}, {"text": "このスープは、選択がとてもおいしい。", "explanation": "「選択」は味を表す語ではなく、おいしいと言う対象にならない。"}, {"text": "毎日、選択を二回食べている。", "explanation": "「選択」は食べ物ではないので、「食べる」の目的語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX