INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36365, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「進路の選択」で、進路が何についての選択かを示す。"}, {"text": "を", "is_correct": false, "explanation": "「進路を選択は」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「進路に選択は」は文法的に成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「進路で選択は」は文法的に成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「進路の選択」で、進路が何についての選択かを示す。", "を": "「進路を選択は」は文法的に成り立たない。", "に": "「進路に選択は」は文法的に成り立たない。", "で": "「進路で選択は」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker", "に": "target_or_location", "で": "means_or_place"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "強制", "is_correct": true, "explanation": "選ぶ自由がなく押しつけられることで、「選択」の反対の関係にある。"}, {"text": "判断", "is_correct": false, "explanation": "物事を見極めて決めることで、反対語ではない。"}, {"text": "採用", "is_correct": false, "explanation": "選んで用いることで、むしろ近い意味。"}, {"text": "決定", "is_correct": false, "explanation": "物事を決めることで、反対語ではない。"}], "correct_answer": "強制", "explanations": {"強制": "選ぶ自由がなく押しつけられることで、「選択」の反対の関係にある。", "判断": "物事を見極めて決めることで、反対語ではない。", "採用": "選んで用いることで、むしろ近い意味。", "決定": "物事を決めることで、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36365, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「商品を選択する」で、選ぶ対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「商品に選択する」は文法的に成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「商品で選択する」は目的語の位置では成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「商品と選択する」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「商品を選択する」で、選ぶ対象を示す。", "に": "「商品に選択する」は文法的に成り立たない。", "で": "「商品で選択する」は目的語の位置では成り立たない。", "と": "「商品と選択する」は文法的に成り立たない。"}, "error_tags": {"に": "target_or_location", "で": "means_or_place", "と": "quotation_or_companion"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "強制", "is_correct": true, "explanation": "選ぶ自由がなく押しつけられることで、自分の意志で選ぶ「選択」の反対の関係にある。"}, {"text": "検討", "is_correct": false, "explanation": "よく考えることで、反対語ではない。"}, {"text": "比較", "is_correct": false, "explanation": "見比べることで、反対語ではない。"}, {"text": "判断", "is_correct": false, "explanation": "見極めて決めることで、反対語ではない。"}], "correct_answer": "強制", "explanations": {"強制": "選ぶ自由がなく押しつけられることで、自分の意志で選ぶ「選択」の反対の関係にある。", "検討": "よく考えることで、反対語ではない。", "比較": "見比べることで、反対語ではない。", "判断": "見極めて決めることで、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36365, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数のものの中から、自分の意志で特定のものを選ぶこと。", "primary_collocate": null, "pronunciation": "せんたく", "ipa": "sentakɯ", "syllable_count": 4, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "選択", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "進路の選択は、自分で決めるべきだ。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼女は迷わず安全な道を選択した。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "選択の自由が奪われてはならない。", "target_word": "選択", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "複数の案から最適なものを選択する。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "間違った選択をしても、そこから学べる。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "選択に迫られた彼は、しばらく黙り込んだ。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消費者は商品を選択する際、価格を比較する。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "選択を誤ると、後で後悔することになる。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "私たちには、別の選択もあったはずだ。", "target_word": "選択", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "選択する", "label": "活用"}, {"form": "選択した", "label": "活用"}, {"form": "選択肢", "label": "派生"}, {"form": "選択的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 自分の意志で選び取ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: エグジット (Zipf 1.27)']::text[], '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36365, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "選択", "is_correct": true, "explanation": "見出し語の「せんたく」で、複数の中から選ぶことを表す。"}, {"text": "先端", "is_correct": false, "explanation": "「せんたん」で、最後のモーラだけが違う別の語。"}, {"text": "船体", "is_correct": false, "explanation": "「せんたい」で、最後のモーラだけが違う別の語。"}, {"text": "先達", "is_correct": false, "explanation": "「せんたつ」で、最後のモーラだけが違う別の語。"}], "explanations": {"選択": "見出し語の「せんたく」で、複数の中から選ぶことを表す。", "先端": "「せんたん」で、最後のモーラだけが違う別の語。", "船体": "「せんたい」で、最後のモーラだけが違う別の語。", "先達": "「せんたつ」で、最後のモーラだけが違う別の語。"}, "sentence_index": null, "correct_answer": "選択"}, "level_3": {"options": [{"text": "選択", "is_correct": true, "explanation": "出口戦略を選ぶという意味になり、文脈に合う。"}, {"text": "修理", "is_correct": false, "explanation": "形は合うが、出口戦略を修理するのは意味が合わない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、出口戦略を運転するのは意味が合わない。"}, {"text": "収穫", "is_correct": false, "explanation": "形は合うが、出口戦略を収穫するのは意味が合わない。"}], "explanations": {"選択": "出口戦略を選ぶという意味になり、文脈に合う。", "修理": "形は合うが、出口戦略を修理するのは意味が合わない。", "運転": "形は合うが、出口戦略を運転するのは意味が合わない。", "収穫": "形は合うが、出口戦略を収穫するのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "選択"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夕食は、選択の味がとても良かった。", "explanation": "「選択」は選ぶことで、料理の味を表す語として使うことはできない。"}, {"text": "彼は雨の中を、駅まで選択して歩いた。", "explanation": "「選択」は「歩く」様子を表さないため、移動の仕方の説明に使うのは誤り。"}, {"text": "この塔の選択は、五メートルほどある。", "explanation": "「選択」は物の高さを表す語ではないので、大きさの説明に使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36365, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "選択", "is_correct": true, "explanation": "見出し語の「せんたく」で、自分の意志で選ぶことを表す。"}, {"text": "詮索", "is_correct": false, "explanation": "「せんさく」で、「た」が「さ」に変わった別の語。"}, {"text": "先客", "is_correct": false, "explanation": "「せんきゃく」で、「た」が「きゃ」に変わった別の語。"}, {"text": "先覚", "is_correct": false, "explanation": "「せんかく」で、「た」が「か」に変わった別の語。"}], "explanations": {"選択": "見出し語の「せんたく」で、自分の意志で選ぶことを表す。", "詮索": "「せんさく」で、「た」が「さ」に変わった別の語。", "先客": "「せんきゃく」で、「た」が「きゃ」に変わった別の語。", "先覚": "「せんかく」で、「た」が「か」に変わった別の語。"}, "sentence_index": null, "correct_answer": "選択"}, "level_3": {"options": [{"text": "選択", "is_correct": true, "explanation": "「選択に迫られる」は、選ぶことを求められるという自然な表現。"}, {"text": "天井", "is_correct": false, "explanation": "形は合うが、天井に迫られるのは意味が合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、砂糖に迫られるのは意味が合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、散歩に迫られて黙り込むのは意味が合わない。"}], "explanations": {"選択": "「選択に迫られる」は、選ぶことを求められるという自然な表現。", "天井": "形は合うが、天井に迫られるのは意味が合わない。", "砂糖": "形は合うが、砂糖に迫られるのは意味が合わない。", "散歩": "形は合うが、散歩に迫られて黙り込むのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "選択"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は毎朝、ベランダで選択を干している。", "explanation": "「選択」は衣類を洗うことではなく、物を干す対象として使うのは誤り。"}, {"text": "彼は熱があって、選択が高いので学校を休んだ。", "explanation": "「選択」は体温を表す語ではないので、「高い」とは結びつかない。"}, {"text": "犬が公園で楽しそうに選択している。", "explanation": "「選択」は選ぶ行為で、犬が遊ぶ様子の描写には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
