INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36366, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を表す格助詞。「五十年前に遡って」で、戻る先の時点を示す。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す。「五十年前で遡って」では時点を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を表す。「五十年前と遡って」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す。「五十年前が遡って」では時点が主語になり、動詞と合わない。"}], "correct_answer": "に", "explanations": {"に": "時点を表す格助詞。「五十年前に遡って」で、戻る先の時点を示す。", "で": "場所や手段を表す。「五十年前で遡って」では時点を示せず不自然。", "と": "相手や引用を表す。「五十年前と遡って」は意味が通らない。", "が": "主語を表す。「五十年前が遡って」では時点が主語になり、動詞と合わない。"}, "error_tags": {"で": "場所・手段", "と": "相手・引用", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
