INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36366, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ずっと昔のことを思い出して、今のこととつなげること。", "primary_collocate": null, "pronunciation": "さかのぼる", "ipa": "sakanoboɾɯ", "syllable_count": 5, "sentences": [{"text": "子どものころまで遡ると、この町の祭りを思い出す。", "target_word": "遡る", "complexity_tier": "T3", "furigana": "子[こ]どものころまで遡[さかのぼ]ると、この町[まち]の祭[まつ]りを思[おも]い出[だ]す。", "sentence_source": "generated"}, {"text": "祖母の話は、いつも五十年前に遡って今の暮らしにつながる。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "祖母[そぼ]の話[はなし]は、いつも五十年前[ごじゅうねんまえ]に遡[さかのぼ]って今[いま]の暮[く]らしにつながる。", "sentence_source": "generated"}, {"text": "昔に遡って思い出すと、あの出会いの日の空の色が今も鮮やかに残っている。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "昔[むかし]に遡[さかのぼ]って思[おも]い出[だ]すと、あの出会[であ]いの日[ひ]の空[そら]の色[いろ]が今[いま]も鮮[あざ]やかに残[のこ]っている。", "sentence_source": "generated"}, {"text": "彼は学生時代まで遡って、友人との思い出を話し始めた。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "彼[かれ]は学生時代[がくせいじだい]まで遡[さかのぼ]って、友人[ゆうじん]との思[おも]い出[で]を話[はな]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "話が昔に遡ると、父は急に楽しそうになる。", "target_word": "遡る", "complexity_tier": "T3", "furigana": "話[はなし]が昔[むかし]に遡[さかのぼ]ると、父[ちち]は急[きゅう]に楽[たの]しそうになる。", "sentence_source": "generated"}, {"text": "高校の頃に遡って思い返すと、あの放課後の教室の空気がよみがえってくる。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "高校[こうこう]の頃[ころ]に遡[さかのぼ]って思[おも]い返[かえ]すと、あの放課後[ほうかご]の教室[きょうしつ]の空気[くうき]がよみがえってくる。", "sentence_source": "generated"}, {"text": "祖父は若いころの記憶まで遡って、それが今の自分の生き方につながると話した。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "祖父[そふ]は若[わか]いころの記憶[きおく]まで遡[さかのぼ]って、それが今[いま]の自分[じぶん]の生[い]き方[かた]につながると話[はな]した。", "sentence_source": "generated"}, {"text": "話題が戦争の時代に遡ったとき、祖父は黙ってしまった。", "target_word": "遡った", "complexity_tier": "T3", "furigana": "話題[わだい]が戦争[せんそう]の時代[じだい]に遡[さかのぼ]ったとき、祖父[そふ]は黙[だま]ってしまった。", "sentence_source": "generated"}, {"text": "思い出を遡ると、いつも海辺の家が出てくる。", "target_word": "遡る", "complexity_tier": "T3", "furigana": "思[おも]い出[で]を遡[さかのぼ]ると、いつも海辺[うみべ]の家[いえ]が出[で]てくる。", "sentence_source": "generated"}, {"text": "幼いころに遡って、あの日の夕焼けを思い出した。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "幼[おさな]いころに遡[さかのぼ]って、あの日[ひ]の夕焼[ゆうや]けを思[おも]い出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遡る", "label": "終止形"}, {"form": "遡らない", "label": "未然形"}, {"form": "遡ります", "label": "連用形（丁寧）"}, {"form": "遡って", "label": "連用形（て）"}, {"form": "遡った", "label": "連用形（た）"}, {"form": "遡れば", "label": "仮定形"}, {"form": "遡ろう", "label": "意志形"}], "register": "標準（普通体）", "sense_fingerprint": "記憶や話の中で昔に戻り、思い出を今につなげる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '612eb789-5ace-4898-ab3a-9c8bb3bd2e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36366, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遡る", "is_correct": true, "explanation": "「子どものころまで」に続き、過去へさかのぼって今につなげる意味の動詞。文の意味に合う。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を大きく出す動作。「子どものころまで叫ぶと」では時間の方向と結びつかず、意味が通らない。"}, {"text": "誘う", "is_correct": false, "explanation": "人を誘う意味。過去の時点まで誘うとは言えず、文が成り立たない。"}, {"text": "凍える", "is_correct": false, "explanation": "寒さで体が冷える意味。「子どものころまで凍える」は時間の流れを表せず不自然。"}], "explanations": {"遡る": "「子どものころまで」に続き、過去へさかのぼって今につなげる意味の動詞。文の意味に合う。", "叫ぶ": "声を大きく出す動作。「子どものころまで叫ぶと」では時間の方向と結びつかず、意味が通らない。", "誘う": "人を誘う意味。過去の時点まで誘うとは言えず、文が成り立たない。", "凍える": "寒さで体が冷える意味。「子どものころまで凍える」は時間の流れを表せず不自然。"}, "sentence_index": 0, "correct_answer": "遡る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ずっと歩いたあと、彼はようやく遡って町に着いた。", "explanation": "ここは〈たどり着く〉の意味。遡るは昔のことを今へつなげる時に使い、目的地へ着く意味では使わない。"}, {"text": "明日の天気を遡って予想した。", "explanation": "ここは〈予想する〉の意味。遡るは過去から今へたどる時に使い、未来を見通す意味では使わない。"}, {"text": "仕事が終わったので、遡って家に帰った。", "explanation": "ここは〈戻る〉の意味。遡るは時間や川の流れをさかのぼる時に使い、場所へ帰る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36366, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遡って", "is_correct": true, "explanation": "過去へさかのぼって今につなげる動詞の連用形。「若いころの記憶まで」に続き、文が成り立つ。"}, {"text": "踊って", "is_correct": false, "explanation": "体を動かして舞う意味。「記憶まで踊って」では過去へ戻る意味にならない。"}, {"text": "縫って", "is_correct": false, "explanation": "布などを針で縫う意味。記憶に対しては使えず、文が成り立たない。"}, {"text": "焦がして", "is_correct": false, "explanation": "表面を焦がす意味。記憶を焦がすとは言わず、過去へ戻る意味にならない。"}], "explanations": {"遡って": "過去へさかのぼって今につなげる動詞の連用形。「若いころの記憶まで」に続き、文が成り立つ。", "踊って": "体を動かして舞う意味。「記憶まで踊って」では過去へ戻る意味にならない。", "縫って": "布などを針で縫う意味。記憶に対しては使えず、文が成り立たない。", "焦がして": "表面を焦がす意味。記憶を焦がすとは言わず、過去へ戻る意味にならない。"}, "sentence_index": 6, "correct_answer": "遡って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の上を遡って片付けた。", "explanation": "ここは〈片付ける〉の意味。遡るは過去を思い出して今へつなげる時に使い、物を整理する動作には使わない。"}, {"text": "幼いころの夕焼けを遡って、すぐにカメラで撮影した。", "explanation": "ここは〈撮影する〉の意味。遡るは過去を思い出して今へつなげる時に使い、写真を撮る動作には使わない。"}, {"text": "誰かに名前を呼ばれて、後ろを遡った。", "explanation": "ここは〈振り返る〉の意味。遡るは時間や原因をさかのぼる時に使い、体の向きを変えて後ろを見る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36366, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さいころで遡って、毎年見ていた花火を思い出した。", "corrected_sentence": "小さいころに遡って、毎年見ていた花火を思い出した。", "error_description": "時点を表す「に」が正しく、「で」は場所や手段を表すため「小さいころで遡って」は不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遡って", "is_correct": true, "explanation": "連用形（て）。後ろの「今の暮らしにつながる」と続けて、文を成立させる。"}, {"text": "遡ろう", "is_correct": false, "explanation": "意志形になり、事実を述べる文に合わない。「遡ろう今の暮らし」と続けると文が崩れる。"}, {"text": "遡ろう", "is_correct": false, "explanation": "意志形になり、「五十年前に遡ろう今の暮らし」と続けると文が崩れる。"}, {"text": "遡らない", "is_correct": false, "explanation": "否定形のため、「遡らない今の暮らし」となり、後ろの「つながる」と意味がつながらない。"}], "correct_form": "遡って", "base_form": "遡る", "form_label": "連用形（て）", "sentence_index": 1, "explanations": {"遡って": "連用形（て）。後ろの「今の暮らしにつながる」と続けて、文を成立させる。", "遡ろう": "意志形になり、「五十年前に遡ろう今の暮らし」と続けると文が崩れる。", "遡らない": "否定形のため、「遡らない今の暮らし」となり、後ろの「つながる」と意味がつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36366, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼い日に遡った、二人で作った船を思い出した。", "corrected_sentence": "幼い日に遡って、二人で作った船を思い出した。", "error_description": "動作を続けるには連用形「て」が必要。「遡った」では文が途切れて不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遡った", "is_correct": true, "explanation": "連用形（た）。「遡ったとき」と時点を表し、後ろの「祖父は黙ってしまった」に続く。"}, {"text": "遡って", "is_correct": false, "explanation": "て形のため、後ろに「とき」が続かず「遡ってとき」となり文が成り立たない。"}, {"text": "遡れば", "is_correct": false, "explanation": "仮定形のため、「遡ればとき」となり、時点を表す「とき」と続かない。"}, {"text": "遡れ", "is_correct": false, "explanation": "命令形のため、「遡れとき」となり、「とき」の前に置けず文が成り立たない。"}], "correct_form": "遡った", "base_form": "遡る", "form_label": "連用形（た）", "sentence_index": 7, "explanations": {"遡った": "連用形（た）。「遡ったとき」と時点を表し、後ろの「祖父は黙ってしまった」に続く。", "遡って": "て形のため、後ろに「とき」が続かず「遡ってとき」となり文が成り立たない。", "遡れば": "仮定形のため、「遡ればとき」となり、時点を表す「とき」と続かない。", "遡れ": "命令形のため、「遡れとき」となり、「とき」の前に置けず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
