INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36367, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "動作の対象を表す格助詞。「根を遡って」で、さかのぼる対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す。「根で遡って」では対象を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を表す。「根と遡って」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体を表す。「根の遡って」では後ろの動詞に続かず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "動作の対象を表す格助詞。「根を遡って」で、さかのぼる対象を示す。", "で": "場所や手段を表す。「根で遡って」では対象を示せず不自然。", "と": "相手や引用を表す。「根と遡って」は意味が通らない。", "の": "連体を表す。「根の遡って」では後ろの動詞に続かず、文が成り立たない。"}, "error_tags": {"で": "場所・手段", "と": "相手・引用", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36367, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の原因や根拠を、遠い過去や根本までたどって考えること。", "primary_collocate": null, "pronunciation": "さかのぼる", "ipa": "sakanoboɾɯ", "syllable_count": 5, "sentences": [{"text": "事故の原因を遡って調べると、点検の不足が分かった。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]を遡[さかのぼ]って調[しら]べると、点検[てんけん]の不足[ぶそく]が分[わ]かった。", "sentence_source": "generated"}, {"text": "問題の根本まで遡って考えないと、同じ失敗を繰り返す。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "問題[もんだい]の根本[こんぽん]まで遡[さかのぼ]って考[かんが]えないと、同[おな]じ失敗[しっぱい]を繰[く]り返[かえ]す。", "sentence_source": "generated"}, {"text": "病気の原因を遡ると、毎日の食事に行き着いた。", "target_word": "遡る", "complexity_tier": "T3", "furigana": "病気[びょうき]の原因[げんいん]を遡[さかのぼ]ると、毎日[まいにち]の食事[しょくじ]に行[い]き着[つ]いた。", "sentence_source": "generated"}, {"text": "責任の所在を遡って確かめたところ、担当者の連絡ミスだった。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "責任[せきにん]の所在[しょざい]を遡[さかのぼ]って確[たし]かめたところ、担当者[たんとうしゃ]の連絡[れんらく]ミスだった。", "sentence_source": "generated"}, {"text": "言葉の意味を遡って調べると、もとは別の言葉だった。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "言葉[ことば]の意味[いみ]を遡[さかのぼ]って調[しら]べると、もとは別[べつ]の言葉[ことば]だった。", "sentence_source": "generated"}, {"text": "争いの原因を遡ってみると、小さな誤解から始まっていた。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "争[あらそ]いの原因[げんいん]を遡[さかのぼ]ってみると、小[ちい]さな誤解[ごかい]から始[はじ]まっていた。", "sentence_source": "generated"}, {"text": "データの誤りを遡って確認し、入力の段階の間違いを見つけた。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "データの誤[あやま]りを遡[さかのぼ]って確認[かくにん]し、入力[にゅうりょく]の段階[だんかい]の間違[まちが]いを見[み]つけた。", "sentence_source": "generated"}, {"text": "彼の考え方の根を遡って理解するために、育った環境を調べた。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "彼[かれ]の考[かんが]え方[かた]の根[ね]を遡[さかのぼ]って理解[りかい]するために、育[そだ]った環境[かんきょう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "失敗の理由を遡って考えれば、準備の遅れに気づくはずだ。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の理由[りゆう]を遡[さかのぼ]って考[かんが]えれば、準備[じゅんび]の遅[おく]れに気[き]づくはずだ。", "sentence_source": "generated"}, {"text": "停電の原因を遡って探した結果、古い配線が見つかった。", "target_word": "遡って", "complexity_tier": "T3", "furigana": "停電[ていでん]の原因[げんいん]を遡[さかのぼ]って探[さが]した結果[けっか]、古[ふる]い配線[はいせん]が見[み]つかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遡る", "label": "終止形"}, {"form": "遡らない", "label": "未然形"}, {"form": "遡ります", "label": "連用形（丁寧）"}, {"form": "遡って", "label": "連用形（て）"}, {"form": "遡った", "label": "連用形（た）"}, {"form": "遡れば", "label": "仮定形"}, {"form": "遡ろう", "label": "意志形"}], "register": "標準（普通体）", "sense_fingerprint": "原因・根拠・責任を、もとの出来事や根本までたどって調べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '612eb789-5ace-4898-ab3a-9c8bb3bd2e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36367, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遡って", "is_correct": true, "explanation": "原因や根拠を根本までたどる意味の動詞の連用形。「事故の原因を」に続き、「調べると」へ自然につながる。"}, {"text": "叫んで", "is_correct": false, "explanation": "大声を出す意味。原因を大声で調べるという流れは不自然で、文の意味が通らない。"}, {"text": "誘って", "is_correct": false, "explanation": "人を誘う意味。「原因を誘って調べる」は成り立たない。"}, {"text": "凍えて", "is_correct": false, "explanation": "寒さで体が冷える意味。原因を凍えながら調べるという意味になり、文脈に合わない。"}], "explanations": {"遡って": "原因や根拠を根本までたどる意味の動詞の連用形。「事故の原因を」に続き、「調べると」へ自然につながる。", "叫んで": "大声を出す意味。原因を大声で調べるという流れは不自然で、文の意味が通らない。", "誘って": "人を誘う意味。「原因を誘って調べる」は成り立たない。", "凍えて": "寒さで体が冷える意味。原因を凍えながら調べるという意味になり、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "遡って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が強くなったので、遡って引き返した。", "explanation": "ここは〈引き返す〉の意味。遡るは原因や根拠をたどる時に使い、来た道を戻る意味では使わない。"}, {"text": "建物の壁を遡って塗った。", "explanation": "ここは〈塗る〉の意味。遡るは原因や根拠を過去からたどる時に使い、ペンキを塗る動作には使わない。"}, {"text": "会議のあとで、費用を遡って、予算を決めた。", "explanation": "ここは〈決める〉の意味。遡るは原因や根拠をたどる時に使い、予算を決める意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36367, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遡って", "is_correct": true, "explanation": "原因や根拠を根本までたどる意味の動詞の連用形。「データの誤りを」に続き、「確認し」へつながる。"}, {"text": "踊って", "is_correct": false, "explanation": "体を動かして舞う意味。「データの誤りを踊って確認し」は意味が通らない。"}, {"text": "縫って", "is_correct": false, "explanation": "布などを針で縫う意味。誤りを縫って確認するという文は成り立たない。"}, {"text": "焦がして", "is_correct": false, "explanation": "表面を焦がす意味。誤りを焦がして確認するとは言わず、文脈に合わない。"}], "explanations": {"遡って": "原因や根拠を根本までたどる意味の動詞の連用形。「データの誤りを」に続き、「確認し」へつながる。", "踊って": "体を動かして舞う意味。「データの誤りを踊って確認し」は意味が通らない。", "縫って": "布などを針で縫う意味。誤りを縫って確認するという文は成り立たない。", "焦がして": "表面を焦がす意味。誤りを焦がして確認するとは言わず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "遡って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "荷物を遡って届けた。", "explanation": "ここは〈届ける〉の意味。遡るは原因や根拠をたどる時に使い、物を送り届ける動作には使わない。"}, {"text": "列車が出たあと、駅を遡った。", "explanation": "ここは〈振り返る〉の意味。遡るは時間や原因をさかのぼる時に使い、後ろを見る動作には使わない。"}, {"text": "合格までの残りの日数を遡った。", "explanation": "ここは〈数える〉の意味。遡るは過去へさかのぼる意味で、日数を数える動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36367, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不具合の原因で遡って、設計のどこが問題かを確かめた。", "corrected_sentence": "不具合の原因を遡って、設計のどこが問題かを確かめた。", "error_description": "「原因を遡る」と目的語に「を」が必要。「で」は手段や場所を表すため、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遡って", "is_correct": true, "explanation": "連用形（て）。後ろの「考えないと」へ続けて、文を成立させる。"}, {"text": "遡ろう", "is_correct": false, "explanation": "意志形のため、「根本まで遡ろう考えないと」と続けると文が崩れる。"}, {"text": "遡ります", "is_correct": false, "explanation": "丁寧な終止形のため、後ろの「考えないと」と続けられない。"}, {"text": "遡らない", "is_correct": false, "explanation": "否定形のため、「根本まで遡らない考えないと」となり、接続が成り立たない。"}], "correct_form": "遡って", "base_form": "遡る", "form_label": "連用形（て）", "sentence_index": 1, "explanations": {"遡って": "連用形（て）。後ろの「考えないと」へ続けて、文を成立させる。", "遡ろう": "意志形のため、「根本まで遡ろう考えないと」と続けると文が崩れる。", "遡ります": "丁寧な終止形のため、後ろの「考えないと」と続けられない。", "遡らない": "否定形のため、「根本まで遡らない考えないと」となり、接続が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36367, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "配線の不良まで遡る、原因を突き止めた。", "corrected_sentence": "配線の不良まで遡って、原因を突き止めた。", "error_description": "「遡って」と動作をつなぐ必要があるのに終止形の「遡る」で切れてしまい、文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遡って", "is_correct": true, "explanation": "連用形（て）。「根を遡って理解するために」と続き、目的を表す文が成り立つ。"}, {"text": "遡ろう", "is_correct": false, "explanation": "意志形になり、「根を遡ろう理解するために」と続けると文が崩れる。"}, {"text": "遡れば", "is_correct": false, "explanation": "仮定形のため、後ろの「理解するために」と文として続かない。"}, {"text": "遡れ", "is_correct": false, "explanation": "命令形のため、「根を遡れ理解するために」となり、接続が成り立たない。"}], "correct_form": "遡って", "base_form": "遡る", "form_label": "連用形（て）", "sentence_index": 7, "explanations": {"遡って": "連用形（て）。「根を遡って理解するために」と続き、目的を表す文が成り立つ。", "遡ろう": "意志形になり、「根を遡ろう理解するために」と続けると文が崩れる。", "遡れば": "仮定形のため、後ろの「理解するために」と文として続かない。", "遡れ": "命令形のため、「根を遡れ理解するために」となり、接続が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36368, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「彼にとって」の「に」。「〜にとって」の形で判断の立場を示し、文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「彼が」は主語を表すが、「とって」と続かないので「彼がとって」は不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「彼を」は対象を表すが、「とって」の前には置けず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「彼へ」は方向を表すが、「彼へとって」という形は存在せず不自然になる。"}], "correct_answer": "に", "explanations": {"に": "「彼にとって」の「に」。「〜にとって」の形で判断の立場を示し、文が成り立つ。", "が": "「彼が」は主語を表すが、「とって」と続かないので「彼がとって」は不自然になる。", "を": "「彼を」は対象を表すが、「とって」の前には置けず、文が成り立たない。", "へ": "「彼へ」は方向を表すが、「彼へとって」という形は存在せず不自然になる。"}, "error_tags": {"が": "主語", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36368, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36368, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "神聖は、とても大事で、だれも壊してはいけないことです。", "primary_collocate": null, "pronunciation": "しんせい", "ipa": "ɕinseː", "syllable_count": 4, "sentences": [{"text": "村の人にとって、この掟は神聖なものだ。", "target_word": "神聖な", "complexity_tier": "T3", "furigana": "村[むら]の人[ひと]にとって、この掟[おきて]は神聖[しんせい]なものだ。", "sentence_source": "generated"}, {"text": "約束を守ることは、彼にとって神聖な義務だった。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]ることは、彼[かれ]にとって神聖[しんせい]な義務[ぎむ]だった。", "sentence_source": "generated"}, {"text": "祖母は、家族が集まる食事の時間を神聖だと考えている。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、家族[かぞく]が集[あつ]まる食事[しょくじ]の時間[じかん]を神聖[しんせい]だと考[かんが]えている。", "sentence_source": "generated"}, {"text": "彼女は図書館の規則を神聖なものと考え、いつも静かに歩く。", "target_word": "神聖な", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は図書館[としょかん]の規則[きそく]を神聖[しんせい]なものと考え、いつも静[しず]かに歩[ある]く。", "sentence_source": "generated"}, {"text": "勝手に記録を書き換えると、神聖な約束を破ることになる。", "target_word": "神聖な", "complexity_tier": "T3", "furigana": "勝手[かって]に記録[きろく]を書[か]き換[か]えると、神聖[しんせい]な約束[やくそく]を破[やぶ]ることになる。", "sentence_source": "generated"}, {"text": "国境は神聖で、侵してはならないと彼は言った。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "国境[こっきょう]は神聖[しんせい]で、侵[おか]してはならないと彼[かれ]は言[い]った。", "sentence_source": "generated"}, {"text": "彼にとって、仕事の前の朝の散歩は神聖な時間だ。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "彼[かれ]にとって、仕事[しごと]の前[まえ]の朝[あさ]の散歩[さんぽ]は神聖[しんせい]な時間[じかん]だ。", "sentence_source": "generated"}, {"text": "選手たちは試合のルールを神聖なものとして守っている。", "target_word": "神聖な", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは試合[しあい]のルールを神聖[しんせい]なものとして守[まも]っている。", "sentence_source": "generated"}, {"text": "母は、子どもの眠りを神聖なものとして守っている。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "母[はは]は、子[こ]どもの眠[ねむ]りを神聖[しんせい]なものとして守[まも]っている。", "sentence_source": "generated"}, {"text": "学問の自由は神聖であり、だれにも奪えない。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "学問[がくもん]の自由[じゆう]は神聖[しんせい]であり、だれにも奪[うば]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "神聖", "label": "基本形"}, {"form": "神聖な", "label": "連体形"}, {"form": "神聖で", "label": "連用形"}, {"form": "神聖だ", "label": "終止形"}], "register": "標準的な書き言葉", "sense_fingerprint": "とても大切で、だれも傷つけたり壊したりしてはならないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36368, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神聖な", "is_correct": true, "explanation": "連体形「神聖な」が「もの」を修飾し、「この掟は神聖なものだ」として成り立つ。"}, {"text": "神聖で", "is_correct": false, "explanation": "中止形の「神聖で」は「もの」に直接つながらず、「神聖でものだ」となって文が成り立たない。"}, {"text": "神聖だ", "is_correct": false, "explanation": "終止形の「神聖だ」は名詞「もの」を修飾できず、「神聖だものだ」は不自然になる。"}, {"text": "神聖に", "is_correct": false, "explanation": "連用形の「神聖に」は名詞を修飾できず、「神聖にものだ」は文法的に成り立たない。"}], "explanations": {"神聖な": "連体形「神聖な」が「もの」を修飾し、「この掟は神聖なものだ」として成り立つ。", "神聖で": "中止形の「神聖で」は「もの」に直接つながらず、「神聖でものだ」となって文が成り立たない。", "神聖だ": "終止形の「神聖だ」は名詞「もの」を修飾できず、「神聖だものだ」は不自然になる。", "神聖に": "連用形の「神聖に」は名詞を修飾できず、「神聖にものだ」は文法的に成り立たない。"}, "sentence_index": 0, "correct_answer": "神聖な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この切手は神聖で、雨に濡れると色が落ちやすく、すぐに傷む。", "explanation": "ここは〈脆い〉（壊れやすい）の意味。壊れやすい様子は「脆い」で表し、「神聖」は侵しがたい尊さを表すので合わない。"}, {"text": "この部品は神聖で、なくては機械が動かない。", "explanation": "ここは〈不可欠〉の意味。神聖は尊く侵せないことを指し、部品が必要不可欠だという意味では使えない。"}, {"text": "彼は時間に神聖で、一度も遅刻したことがない。", "explanation": "ここは〈厳格〉の意味。時間に厳しい人は「厳格」と言い、「神聖」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36368, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神聖", "is_correct": true, "explanation": "「神聖な時間」の語幹「神聖」。ここでは後ろの「な時間」につながる形として空所に入る。"}, {"text": "神聖さ", "is_correct": false, "explanation": "「神聖さな時間」となり、名詞「神聖さ」は「な時間」の形で続かない。"}, {"text": "神聖化", "is_correct": false, "explanation": "「神聖化な時間」となり、「神聖化」は「な時間」の形容として成り立たない。"}, {"text": "神聖視", "is_correct": false, "explanation": "「神聖視な時間」となり、「神聖視」は神聖だとみなす行為を表し、「な時間」には続かない。"}], "explanations": {"神聖": "「神聖な時間」の語幹「神聖」。ここでは後ろの「な時間」につながる形として空所に入る。", "神聖さ": "「神聖さな時間」となり、名詞「神聖さ」は「な時間」の形で続かない。", "神聖化": "「神聖化な時間」となり、「神聖化」は「な時間」の形容として成り立たない。", "神聖視": "「神聖視な時間」となり、「神聖視」は神聖だとみなす行為を表し、「な時間」には続かない。"}, "sentence_index": 6, "correct_answer": "神聖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この肉は神聖で、口の中でとろけるほどやわらかい。", "explanation": "ここは〈やわらかい〉の意味。肉のやわらかさは「やわらかい」で表し、「神聖」は尊さや侵しがたさを表すので合わない。"}, {"text": "この布団は神聖で、とても寝心地がいい。", "explanation": "ここは〈快適〉の意味。寝心地の良さは「快適」で表し、「神聖」は尊さや侵しがたさを言う語なので合わない。"}, {"text": "彼は神聖で、一度決めたら絶対に意見を変えない。", "explanation": "ここは〈頑固〉の意味。意見を変えない人は「頑固」と言い、「神聖」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36368, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この約束は神聖な、だれも破ってはならない。", "corrected_sentence": "この約束は神聖で、だれも破ってはならない。", "error_description": "「神聖な」は誤り。連体形「な」は名詞に続けるもので、読点の前で文を終えることはできない。述語にするなら「神聖で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36368, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その規則は神聖なを、だれも破ってはならない。", "corrected_sentence": "その規則は神聖で、だれも破ってはならない。", "error_description": "「神聖なを」は誤り。連体形「な」の後に格助詞「を」は続かず、文として成り立たない。述語は「神聖で」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36369, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "俗", "is_correct": true, "explanation": "「神聖」の対義語。神聖な尊さと対になる、世俗的で清らかさのないものを指す。"}, {"text": "尊い", "is_correct": false, "explanation": "「神聖」の類義語で、対義語ではない。"}, {"text": "清浄", "is_correct": false, "explanation": "清らかさを表す語で、「神聖」の類義語にあたり対義語ではない。"}, {"text": "荘厳", "is_correct": false, "explanation": "厳かで重々しい様子を表す語で、「神聖」に近い意味を持ち対義語ではない。"}], "correct_answer": "俗", "explanations": {"俗": "「神聖」の対義語。神聖な尊さと対になる、世俗的で清らかさのないものを指す。", "尊い": "「神聖」の類義語で、対義語ではない。", "清浄": "清らかさを表す語で、「神聖」の類義語にあたり対義語ではない。", "荘厳": "厳かで重々しい様子を表す語で、「神聖」に近い意味を持ち対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36369, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "俗", "is_correct": true, "explanation": "「神聖」の対義語。神聖な尊さと対になる、世俗的なものを指す。"}, {"text": "崇高", "is_correct": false, "explanation": "気高く尊い様子を表す語で、「神聖」の類義語にあたり対義語ではない。"}, {"text": "敬虔", "is_correct": false, "explanation": "神仏を敬い慎む様子を表す語で、「神聖」に近い意味を持ち対義語ではない。"}, {"text": "厳か", "is_correct": false, "explanation": "厳粛で重々しい様子を表す語で、「神聖」の類義語にあたり対義語ではない。"}], "correct_answer": "俗", "explanations": {"俗": "「神聖」の対義語。神聖な尊さと対になる、世俗的なものを指す。", "崇高": "気高く尊い様子を表す語で、「神聖」の類義語にあたり対義語ではない。", "敬虔": "神仏を敬い慎む様子を表す語で、「神聖」に近い意味を持ち対義語ではない。", "厳か": "厳粛で重々しい様子を表す語で、「神聖」の類義語にあたり対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36369, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "神聖とは、神のように尊く、清らかで、侵してはならないこと。また、そのさま。", "primary_collocate": null, "pronunciation": "しんせい", "ipa": "ɕinseː", "syllable_count": 4, "sentences": [{"text": "山頂の神社は、神聖な空気に包まれていた。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "山頂[さんちょう]の神社[じんじゃ]は、神聖[しんせい]な空気[くうき]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "巫女は神聖な衣を身につけて舞った。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "巫女[みこ]は神聖[しんせい]な衣[ころも]を身[み]につけて舞[ま]った。", "sentence_source": "generated"}, {"text": "神聖な泉の水で、参拝者は手を清める。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "神聖[しんせい]な泉[いずみ]の水[みず]で、参拝者[さんぱいしゃ]は手[て]を清[きよ]める。", "sentence_source": "generated"}, {"text": "古代の人々は、大きな岩を神聖なものとしてあがめた。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "古代[こだい]の人々[ひとびと]は、大[おお]きな岩[いわ]を神聖[しんせい]なものとしてあがめた。", "sentence_source": "generated"}, {"text": "神聖な儀式の間は、だれも話してはならない。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "神聖[しんせい]な儀式[ぎしき]の間[あいだ]は、だれも話[はな]してはならない。", "sentence_source": "generated"}, {"text": "雪をかぶった山は、神聖な美しさを見せていた。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "雪[ゆき]をかぶった山[やま]は、神聖[しんせい]な美[うつく]しさを見[み]せていた。", "sentence_source": "generated"}, {"text": "この島は昔から神聖とされ、一般の人は入れない。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "この島[しま]は昔[むかし]から神聖[しんせい]とされ、一般[いっぱん]の人[ひと]は入[はい]れない。", "sentence_source": "generated"}, {"text": "王は神聖な存在とされ、人々は顔を見ることもできなかった。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "王[おう]は神聖[しんせい]な存在[そんざい]とされ、人々[ひとびと]は顔[かお]を見[み]ることもできなかった。", "sentence_source": "generated"}, {"text": "祭りの夜、境内は神聖な静けさに満ちていた。", "target_word": "神聖", "complexity_tier": "T3", "furigana": "祭[まつ]りの夜[よる]、境内[けいだい]は神聖[しんせい]な静[しず]けさに満[み]ちていた。", "sentence_source": "generated"}, {"text": "教会の鐘の音は神聖な響きを帯び、人々は祈りを始めた。", "target_word": "神聖な", "complexity_tier": "T3", "furigana": "教会[きょうかい]の鐘[かね]の音[ね]は神聖[しんせい]な響[ひび]きを帯[お]び、人々[ひとびと]は祈[いの]りを始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "神聖", "label": "基本形"}, {"form": "神聖な", "label": "連体形"}, {"form": "神聖に", "label": "連用形"}, {"form": "神聖とされ", "label": "連用形"}], "register": "標準的な書き言葉", "sense_fingerprint": "神のように尊く清らかで、人が汚してはならないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36369, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神聖", "is_correct": true, "explanation": "「神聖な空気」の語幹「神聖」。「な空気」につながる形で空所に入り、文が成り立つ。"}, {"text": "神聖さ", "is_correct": false, "explanation": "名詞「神聖さ」は「神聖さな空気」と続かず、「空気」を修飾する形にならない。"}, {"text": "神聖化", "is_correct": false, "explanation": "「神聖化」は神聖にすることを表す名詞で、「神聖化な空気」とは続かない。"}, {"text": "神聖視", "is_correct": false, "explanation": "「神聖視」は神聖だとみなす意味で、「神聖視な空気」とは続かず文が成り立たない。"}], "explanations": {"神聖": "「神聖な空気」の語幹「神聖」。「な空気」につながる形で空所に入り、文が成り立つ。", "神聖さ": "名詞「神聖さ」は「神聖さな空気」と続かず、「空気」を修飾する形にならない。", "神聖化": "「神聖化」は神聖にすることを表す名詞で、「神聖化な空気」とは続かない。", "神聖視": "「神聖視」は神聖だとみなす意味で、「神聖視な空気」とは続かず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "神聖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は神聖で、週末には行列ができるほど有名だ。", "explanation": "ここは〈有名〉の意味。広く知られていることは「有名」で表し、「神聖」は尊く清らかな様子を表すので合わない。"}, {"text": "この宝石は神聖で、千円で買える。", "explanation": "ここは〈安価〉の意味。値段の安さは「安い」で表し、「神聖」は尊さを表す語なので合わない。"}, {"text": "彼はいつも神聖なものばかり食べて、ぜいたくに暮らしている。", "explanation": "ここは〈贅沢〉の意味。ぜいたくな暮らしは「贅沢」で表し、「神聖」は尊さを表す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36369, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神聖", "is_correct": true, "explanation": "「神聖とされ」の語幹「神聖」。「とされ」につながって文が成り立つ。"}, {"text": "神聖で", "is_correct": false, "explanation": "「神聖で」は「とされ」と続かず、「神聖でとされ」は文として成り立たない。"}, {"text": "神聖に", "is_correct": false, "explanation": "「神聖に」は「とされ」に続けると「神聖にとされ」となり、不自然で成り立たない。"}, {"text": "神聖な", "is_correct": false, "explanation": "連体形「神聖な」は「とされ」に続かず、「神聖なとされ」は文法的に成り立たない。"}], "explanations": {"神聖": "「神聖とされ」の語幹「神聖」。「とされ」につながって文が成り立つ。", "神聖で": "「神聖で」は「とされ」と続かず、「神聖でとされ」は文として成り立たない。", "神聖に": "「神聖に」は「とされ」に続けると「神聖にとされ」となり、不自然で成り立たない。", "神聖な": "連体形「神聖な」は「とされ」に続かず、「神聖なとされ」は文法的に成り立たない。"}, "sentence_index": 6, "correct_answer": "神聖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は神聖で、時刻を正確に知らせてくれる。", "explanation": "ここは〈正確〉の意味。時刻の確かさは「正確」で表し、「神聖」は尊さや侵しがたさを表すので合わない。"}, {"text": "この野菜は神聖で、朝採れのように新鮮だ。", "explanation": "ここは〈新鮮〉の意味。採れたての状態は「新鮮」で言い、「神聖」は尊さを表すので合わない。"}, {"text": "彼女は神聖で、いつも周りの人を困らせる。", "explanation": "ここは〈わがまま〉の意味。自分の思い通りにしたがる性格は「わがまま」で表し、「神聖」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36369, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りの夜、社殿は神聖なの静けさに満ちていた。", "corrected_sentence": "祭りの夜、社殿は神聖な静けさに満ちていた。", "error_description": "「神聖なの」は誤り。連体形「な」の後に「の」は続かない。名詞「静けさ」を修飾するには「神聖な」だけでよい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36369, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この森は神聖なで、人々に大切に守られてきた。", "corrected_sentence": "この森は神聖で、人々に大切に守られてきた。", "error_description": "「神聖なで」は誤り。「な」は名詞を修飾する連体形で、述語には「神聖で」を使うのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36370, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「工事の開始が遅れた」の主語を示す「が」。遅れるのは開始なので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「開始を遅れた」は、遅れるという自動詞の目的語にできず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「開始へ遅れた」は方向を示す「へ」が合わず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「開始と遅れた」は並列の意味になり、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「工事の開始が遅れた」の主語を示す「が」。遅れるのは開始なので正しい。", "を": "「開始を遅れた」は、遅れるという自動詞の目的語にできず不自然。", "へ": "「開始へ遅れた」は方向を示す「へ」が合わず、文が成り立たない。", "と": "「開始と遅れた」は並列の意味になり、文が成り立たない。"}, "error_tags": {"を": "自動詞との不一致", "へ": "方向の誤り", "と": "並列の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終了", "is_correct": true, "explanation": "「開始」の対義語として辞書に並ぶ語。会議の始まりの反対で、終わることを表す。"}, {"text": "準備", "is_correct": false, "explanation": "「準備」は始まりに向けた下準備で、開始の反対語ではない。"}, {"text": "完成", "is_correct": false, "explanation": "「完成」は仕上がることで、始まりの反対語ではない。"}, {"text": "延期", "is_correct": false, "explanation": "「延期」は予定を後にずらすことで、開始の対義語ではない。"}], "correct_answer": "終了", "explanations": {"終了": "「開始」の対義語として辞書に並ぶ語。会議の始まりの反対で、終わることを表す。", "準備": "「準備」は始まりに向けた下準備で、開始の反対語ではない。", "完成": "「完成」は仕上がることで、始まりの反対語ではない。", "延期": "「延期」は予定を後にずらすことで、開始の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36370, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「開始の」は、始まりの時刻を示す「の」。ベルが開始を知らせる関係として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「開始がベルが鳴る」は主格が二つ重なり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「開始よりベルが鳴る」は比較の意味になり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「開始でベルが鳴る」は手段や場所を示す「で」が合わず、ベルの鳴る理由にならない。"}], "correct_answer": "の", "explanations": {"の": "「開始の」は、始まりの時刻を示す「の」。ベルが開始を知らせる関係として正しい。", "が": "「開始がベルが鳴る」は主格が二つ重なり、文が成り立たない。", "より": "「開始よりベルが鳴る」は比較の意味になり、文が成り立たない。", "で": "「開始でベルが鳴る」は手段や場所を示す「で」が合わず、ベルの鳴る理由にならない。"}, "error_tags": {"が": "主格の重複", "より": "比較の誤り", "で": "手段・場所の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終了", "is_correct": true, "explanation": "「開始」の対義語として辞書に並ぶ語。放送の始まりの反対で、終わることを表す。"}, {"text": "出発", "is_correct": false, "explanation": "「出発」は出かけることで、開始の対義語ではない。"}, {"text": "延長", "is_correct": false, "explanation": "「延長」は長く続けることで、始まりの反対語ではない。"}, {"text": "解決", "is_correct": false, "explanation": "「解決」は問題が片付くことで、開始の反対語ではない。"}], "correct_answer": "終了", "explanations": {"終了": "「開始」の対義語として辞書に並ぶ語。放送の始まりの反対で、終わることを表す。", "出発": "「出発」は出かけることで、開始の対義語ではない。", "延長": "「延長」は長く続けることで、始まりの反対語ではない。", "解決": "「解決」は問題が片付くことで、開始の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36370, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが始まること。", "primary_collocate": null, "pronunciation": "かいし", "ipa": "kaiɕi", "syllable_count": 3, "sentences": [{"text": "試合は午後一時に開始される予定です。", "target_word": "開始", "complexity_tier": "T3", "furigana": "試合(しあい)は午後(ごご)一時(いちじ)に開始(かいし)される予定(よてい)です。", "sentence_source": "generated"}, {"text": "工事の開始が遅れたので、完成も来月になる。", "target_word": "開始", "complexity_tier": "T3", "furigana": "工事(こうじ)の開始(かいし)が遅(おく)れたので、完成(かんせい)も来月(らいげつ)になる。", "sentence_source": "generated"}, {"text": "先生の合図とともに、試験が開始された。", "target_word": "開始", "complexity_tier": "T3", "furigana": "先生(せんせい)の合図(あいず)とともに、試験(しけん)が開始(かいし)された。", "sentence_source": "generated"}, {"text": "会議の開始時刻に間に合うよう、早めに家を出た。", "target_word": "開始", "complexity_tier": "T3", "furigana": "会議(かいぎ)の開始(かいし)時刻(じこく)に間(ま)に合(あ)うよう、早(はや)めに家(いえ)を出(で)た。", "sentence_source": "generated"}, {"text": "新しいサービスの開始を、多くの客が待っていた。", "target_word": "開始", "complexity_tier": "T3", "furigana": "新(あたら)しいサービスの開始(かいし)を、多(おお)くの客(きゃく)が待(ま)っていた。", "sentence_source": "generated"}, {"text": "雨のため、イベントの開始が三十分延びた。", "target_word": "開始", "complexity_tier": "T3", "furigana": "雨(あめ)のため、イベントの開始(かいし)が三十分(さんじゅっぷん)延(の)びた。", "sentence_source": "generated"}, {"text": "授業が始まる前に、先生は準備を開始した。", "target_word": "開始", "complexity_tier": "T3", "furigana": "授業(じゅぎょう)が始(はじ)まる前(まえ)に、先生(せんせい)は準備(じゅんび)を開始(かいし)した。", "sentence_source": "generated"}, {"text": "開始のベルが鳴ると、選手たちは一斉に走り出した。", "target_word": "開始", "complexity_tier": "T3", "furigana": "開始(かいし)のベルが鳴(な)ると、選手(せんしゅ)たちは一斉(いっせい)に走(はし)り出(だ)した。", "sentence_source": "generated"}, {"text": "交渉を開始するには、両国の同意が必要だ。", "target_word": "開始", "complexity_tier": "T3", "furigana": "交渉(こうしょう)を開始(かいし)するには、両国(りょうこく)の同意(どうい)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "放送の開始まで、あと五分しかない。", "target_word": "開始", "complexity_tier": "T3", "furigana": "放送(ほうそう)の開始(かいし)まで、あと五分(ごふん)しかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "開始", "label": "基本形"}, {"form": "開始する", "label": "サ変動詞"}, {"form": "開始した", "label": "過去形"}, {"form": "開始される", "label": "受身形"}], "register": "書き言葉", "sense_fingerprint": "試合・会議・工事・サービスなどが始まること、または始めること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 鳴る (Zipf 3.73), 一斉 (Zipf 3.98), 走り出し (Zipf 3.0)']::text[], '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36370, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "開始", "is_correct": true, "explanation": "「午後一時に開始される予定」は、試合が始まる時刻を表し、文脈に合う。"}, {"text": "到着", "is_correct": false, "explanation": "「到着される予定」は人や物が着く意味で、試合には合わない。"}, {"text": "解散", "is_correct": false, "explanation": "「解散される予定」は集まりが別れる意味で、試合の始まりを表さない。"}, {"text": "配布", "is_correct": false, "explanation": "「配布される予定」は物を配る意味で、試合の時刻の話には合わない。"}], "explanations": {"開始": "「午後一時に開始される予定」は、試合が始まる時刻を表し、文脈に合う。", "到着": "「到着される予定」は人や物が着く意味で、試合には合わない。", "解散": "「解散される予定」は集まりが別れる意味で、試合の始まりを表さない。", "配布": "「配布される予定」は物を配る意味で、試合の時刻の話には合わない。"}, "sentence_index": 0, "correct_answer": "開始"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生から、明日の集合場所の開始が届いた。", "explanation": "ここは〈伝言〉の意味。開始は物事が始まることを指し、連絡の言葉を表す語ではない。"}, {"text": "犬の開始は、十五年ほどと言われる。", "explanation": "ここは〈寿命〉の意味。開始は始まりを指し、生き物がどれだけ生きるかの長さには使わない。"}, {"text": "彼女は北海道の開始だ。", "explanation": "ここは〈出身〉の意味。開始は物事の始まりを指し、人の生まれ育った土地には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36370, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "開始", "is_correct": true, "explanation": "「準備を開始した」で、準備に取りかかる意味を表し、授業前の文脈に合う。"}, {"text": "試食", "is_correct": false, "explanation": "「準備を試食した」は意味が通らず、準備の動作と結びつかない。"}, {"text": "点呼", "is_correct": false, "explanation": "「準備を点呼した」は人を呼んで確認する意味で、準備とは合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「準備を採点した」は評価する意味になり、準備の動作にならない。"}], "explanations": {"開始": "「準備を開始した」で、準備に取りかかる意味を表し、授業前の文脈に合う。", "試食": "「準備を試食した」は意味が通らず、準備の動作と結びつかない。", "点呼": "「準備を点呼した」は人を呼んで確認する意味で、準備とは合わない。", "採点": "「準備を採点した」は評価する意味になり、準備の動作にならない。"}, "sentence_index": 6, "correct_answer": "開始"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小説の開始は、若い作家だ。", "explanation": "ここは〈著者〉の意味。開始は物事の始まりを指し、書いた人を表す語ではない。"}, {"text": "祖父の開始が減った。", "explanation": "ここは〈体重〉の意味。開始は始まりを指し、体の重さの増減には使わない。"}, {"text": "今朝の開始は三度だった。", "explanation": "ここは〈気温〉の意味。開始は物事の始まりを指し、空気の温度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36370, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新製品の発売開始を、来月に決まった。", "corrected_sentence": "新製品の発売開始は、来月に決まった。", "error_description": "主題を示す「開始は」の「は」を、目的語の「開始を」の「を」にした誤り。「決まった」は自動詞なので目的語の「を」は取れず、主語を示す「は」や「が」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36370, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業の開始が早まらったので、予定通り終わった。", "corrected_sentence": "作業の開始が早まったので、予定通り終わった。", "error_description": "「早まる」の過去形を「早まらった」と誤った。正しくは「早まった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36372, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を表す格助詞。「開始の時刻に」で、全員が席につく時点を示す。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す。「時刻で」では時点を示せず、文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体を表す。「時刻の、全員が席についた」では文が続かない。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す。「時刻が、全員が席についた」では時刻が主語として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "時点を表す格助詞。「開始の時刻に」で、全員が席につく時点を示す。", "で": "場所や手段を表す。「時刻で」では時点を示せず、文の意味が通らない。", "の": "連体を表す。「時刻の、全員が席についた」では文が続かない。", "が": "主語を表す。「時刻が、全員が席についた」では時刻が主語として成り立たない。"}, "error_tags": {"で": "場所・手段", "の": "連体", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36372, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "動作の対象を表す格助詞。「時刻を、チャイムで知らせる」で、知らせる内容を示す。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表す。「時刻と、チャイムで知らせる」では対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す。「時刻へ知らせる」は不自然で、対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を表す。「時刻より、チャイムで知らせる」では文の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "動作の対象を表す格助詞。「時刻を、チャイムで知らせる」で、知らせる内容を示す。", "と": "相手や並列を表す。「時刻と、チャイムで知らせる」では対象として成り立たない。", "へ": "方向を表す。「時刻へ知らせる」は不自然で、対象を示せない。", "より": "比較や起点を表す。「時刻より、チャイムで知らせる」では文の目的語にならない。"}, "error_tags": {"と": "相手・並列", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36372, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするための、決まったときのこと。", "primary_collocate": null, "pronunciation": "じこく", "ipa": "dʑikokɯ", "syllable_count": 3, "sentences": [{"text": "出発の時刻は朝七時と決まっている。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "出発[しゅっぱつ]の時刻[じこく]は朝[あさ]七時[しちじ]と決[き]まっている。", "sentence_source": "generated"}, {"text": "会議の開始の時刻に、全員が席についた。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "会議[かいぎ]の開始[かいし]の時刻[じこく]に、全員[ぜんいん]が席[せき]についた。", "sentence_source": "generated"}, {"text": "試験の終了の時刻まで、教室を出てはいけない。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "試験[しけん]の終了[しゅうりょう]の時刻[じこく]まで、教室[きょうしつ]を出[で]てはいけない。", "sentence_source": "generated"}, {"text": "約束の時刻になっても、彼は来なかった。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "約束[やくそく]の時刻[じこく]になっても、彼[かれ]は来[こ]なかった。", "sentence_source": "generated"}, {"text": "バスの発車の時刻を、駅の掲示板で確認した。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "バスの発車[はっしゃ]の時刻[じこく]を、駅[えき]の掲示板[けいじばん]で確認[かくにん]した。", "sentence_source": "generated"}, {"text": "閉店の時刻が近づくと、店内に音楽が流れる。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "閉店[へいてん]の時刻[じこく]が近[ちか]づくと、店内[てんない]に音楽[おんがく]が流[なが]れる。", "sentence_source": "generated"}, {"text": "集合の時刻に遅れた人は、先に出発したバスに乗れなかった。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "集合[しゅうごう]の時刻[じこく]に遅[おく]れた人[ひと]は、先[さき]に出発[しゅっぱつ]したバスに乗[の]れなかった。", "sentence_source": "generated"}, {"text": "授業の開始の時刻を、チャイムで知らせる。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の開始[かいし]の時刻[じこく]を、チャイムで知[し]らせる。", "sentence_source": "generated"}, {"text": "面会の時刻は、前の日に電話で決める。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "面会[めんかい]の時刻[じこく]は、前[まえ]の日[ひ]に電話[でんわ]で決[き]める。", "sentence_source": "generated"}, {"text": "締め切りの時刻を過ぎたので、書類は受け付けてもらえなかった。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "締[し]め切[き]りの時刻[じこく]を過[す]ぎたので、書類[しょるい]は受[う]け付[つ]けてもらえなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時刻", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "出発・開始・締め切りなど、予定として決められた時刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '612eb789-5ace-4898-ab3a-9c8bb3bd2e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36372, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時刻", "is_correct": true, "explanation": "決まった時点を表す名詞。「出発の」に続き、「朝七時と決まっている」と意味が通る。"}, {"text": "行き先", "is_correct": false, "explanation": "移動する目的地を表す。「出発の行き先は朝七時と決まっている」は意味が通らない。"}, {"text": "運賃", "is_correct": false, "explanation": "乗り物の料金を表す。時間の決まりを述べる文には入らない。"}, {"text": "座席", "is_correct": false, "explanation": "座る場所を表す。「出発の座席は朝七時と決まっている」は成り立たない。"}], "explanations": {"時刻": "決まった時点を表す名詞。「出発の」に続き、「朝七時と決まっている」と意味が通る。", "行き先": "移動する目的地を表す。「出発の行き先は朝七時と決まっている」は意味が通らない。", "運賃": "乗り物の料金を表す。時間の決まりを述べる文には入らない。", "座席": "座る場所を表す。「出発の座席は朝七時と決まっている」は成り立たない。"}, "sentence_index": 0, "correct_answer": "時刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "授業の時刻は五十分と決まっている。", "explanation": "ここは〈時間〉の意味。時刻は決まった一点の時を指すので、五十分という長さには使わない。"}, {"text": "入学の時刻は四月だ。", "explanation": "ここは〈時期〉の意味。時刻は一日の中の時点を指し、季節や時期には使わない。"}, {"text": "旅行の時刻は三日間だ。", "explanation": "ここは〈日程〉の意味。時刻は時点で、三日間という日程の範囲には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36372, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時刻", "is_correct": true, "explanation": "決まった時点を表す名詞。「集合の」に続き、遅れた時点を示して文が成り立つ。"}, {"text": "人数", "is_correct": false, "explanation": "人の数を表す。「集合の人数に遅れた人」は意味が通らない。"}, {"text": "定員", "is_correct": false, "explanation": "乗れる上限の人数を表す。時点を示す文脈には入らない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券を表す。「集合の切符に遅れた」とは言えず、文が成り立たない。"}], "explanations": {"時刻": "決まった時点を表す名詞。「集合の」に続き、遅れた時点を示して文が成り立つ。", "人数": "人の数を表す。「集合の人数に遅れた人」は意味が通らない。", "定員": "乗れる上限の人数を表す。時点を示す文脈には入らない。", "切符": "乗車券を表す。「集合の切符に遅れた」とは言えず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "時刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "滞在の時刻は一週間だ。", "explanation": "ここは〈期間〉の意味。時刻は一点の時を指すので、一週間という期間には使わない。"}, {"text": "彼は江戸の時刻に生まれた。", "explanation": "ここは〈時代〉の意味。時刻は一日の中の時点を指し、歴史の時代には使わない。"}, {"text": "彼の時刻は三十歳だ。", "explanation": "ここは〈年齢〉の意味。時刻は年齢を表せず、人の年の数には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36372, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "到着の時刻を、夕方六時と決まっている。", "corrected_sentence": "到着の時刻は、夕方六時と決まっている。", "error_description": "「時刻」に続く助詞は「は」が正しい。「を」は対象を表すため、「決まっている」の主題としては合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36372, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "締め切りの時刻で受付が閉まる。", "corrected_sentence": "締め切りの時刻に受付が閉まる。", "error_description": "時点を示すには「に」が必要。「で」は場所や手段を表すため、ここでは不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36373, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "動作の対象を表す格助詞。「時刻を、ニュースが伝えていた」で、伝えられる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す。「時刻が、ニュースが伝えていた」では時刻が伝える主体にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体を表す。「時刻の、ニュースが伝えていた」では文が続かない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表す。「時刻と、ニュースが伝えていた」では目的語として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "動作の対象を表す格助詞。「時刻を、ニュースが伝えていた」で、伝えられる対象を示す。", "が": "主語を表す。「時刻が、ニュースが伝えていた」では時刻が伝える主体にならず不自然。", "の": "連体を表す。「時刻の、ニュースが伝えていた」では文が続かない。", "と": "相手や並列を表す。「時刻と、ニュースが伝えていた」では目的語として成り立たない。"}, "error_tags": {"が": "主語", "の": "連体", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36373, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を表す格助詞。「撮影した時刻が小さく表示されている」で、表示される主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を表す。「表示されている」は受け身のため、対象の「を」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す。「撮影した時刻で小さく表示」では主語を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す。「撮影した時刻へ小さく表示されている」では表示の主体にならない。"}], "correct_answer": "が", "explanations": {"が": "主語を表す格助詞。「撮影した時刻が小さく表示されている」で、表示される主体を示す。", "を": "動作の対象を表す。「表示されている」は受け身のため、対象の「を」では文が成り立たない。", "で": "場所や手段を表す。「撮影した時刻で小さく表示」では主語を示せず不自然。", "へ": "方向を表す。「撮影した時刻へ小さく表示されている」では表示の主体にならない。"}, "error_tags": {"を": "対象", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36373, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある特定の時点。時間の一点。", "primary_collocate": null, "pronunciation": "じこく", "ipa": "dʑikokɯ", "syllable_count": 3, "sentences": [{"text": "事故が起きた時刻は、午後三時十分ごろだった。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "事故[じこ]が起[お]きた時刻[じこく]は、午後[ごご]三時[さんじ]十分[じゅっぷん]ごろだった。", "sentence_source": "generated"}, {"text": "地震が発生した時刻を、ニュースが正確に伝えていた。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "地震[じしん]が発生[はっせい]した時刻[じこく]を、ニュースが正確[せいかく]に伝[つた]えていた。", "sentence_source": "generated"}, {"text": "防犯カメラには、男が店に入った時刻が記録されている。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "防犯[ぼうはん]カメラには、男[おとこ]が店[みせ]に入[はい]った時刻[じこく]が記録[きろく]されている。", "sentence_source": "generated"}, {"text": "メールが届いた時刻を確認すると、夜中の二時だった。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "メールが届[とど]いた時刻[じこく]を確認[かくにん]すると、夜中[よなか]の二時[にじ]だった。", "sentence_source": "generated"}, {"text": "時計が止まっていて、正しい時刻が分からない。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "時計[とけい]が止[と]まっていて、正[ただ]しい時刻[じこく]が分[わ]からない。", "sentence_source": "generated"}, {"text": "日の出の時刻は、季節によって変わる。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "日[ひ]の出[で]の時刻[じこく]は、季節[きせつ]によって変[か]わる。", "sentence_source": "generated"}, {"text": "電話をかけた時刻を、ノートに書いておいた。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "電話[でんわ]をかけた時刻[じこく]を、ノートに書[か]いておいた。", "sentence_source": "generated"}, {"text": "この写真には、撮影した時刻が小さく表示されている。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "この写真[しゃしん]には、撮影[さつえい]した時刻[じこく]が小[ちい]さく表示[ひょうじ]されている。", "sentence_source": "generated"}, {"text": "現在の時刻を知りたくて、スマホの画面を見た。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "現在[げんざい]の時刻[じこく]を知[し]りたくて、スマホの画面[がめん]を見[み]た。", "sentence_source": "generated"}, {"text": "荷物を受け取った時刻は、記録に残っていない。", "target_word": "時刻", "complexity_tier": "T3", "furigana": "荷物[にもつ]を受[う]け取[と]った時刻[じこく]は、記録[きろく]に残[のこ]っていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時刻", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "出来事が起きた・時計が示す、時間の流れの中の一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '612eb789-5ace-4898-ab3a-9c8bb3bd2e3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36373, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時刻", "is_correct": true, "explanation": "時間の流れの中の一点を表す名詞。「事故が起きた」に続き、「午後三時十分ごろだった」と合う。"}, {"text": "場所", "is_correct": false, "explanation": "ものが置かれたり出来事が起きたりする所を表す。「事故が起きた場所は午後三時十分ごろだった」は意味が通らない。"}, {"text": "天候", "is_correct": false, "explanation": "その時の空模様を表す。時間を示す文に入らず、意味が成り立たない。"}, {"text": "目撃者", "is_correct": false, "explanation": "出来事を見た人を表す。時点を述べる文には入らない。"}], "explanations": {"時刻": "時間の流れの中の一点を表す名詞。「事故が起きた」に続き、「午後三時十分ごろだった」と合う。", "場所": "ものが置かれたり出来事が起きたりする所を表す。「事故が起きた場所は午後三時十分ごろだった」は意味が通らない。", "天候": "その時の空模様を表す。時間を示す文に入らず、意味が成り立たない。", "目撃者": "出来事を見た人を表す。時点を述べる文には入らない。"}, "sentence_index": 0, "correct_answer": "時刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作業の時刻は二時間ほどかかる。", "explanation": "ここは〈時間〉の意味。時刻は一点の時を指すので、二時間という長さには使わない。"}, {"text": "桜の時刻は四月だ。", "explanation": "ここは〈時期〉の意味。時刻は一日の中の時点を指し、季節や時期には使わない。"}, {"text": "父の時刻は五十代だ。", "explanation": "ここは〈年齢〉の意味。時刻は人の年齢を表せず、五十代という年の範囲には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36373, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時刻", "is_correct": true, "explanation": "時間の流れの中の一点を表す名詞。「電話をかけた」に続き、ノートに書く対象として合う。"}, {"text": "座席", "is_correct": false, "explanation": "座る場所を表す。電話をかけた場所を示す語として、ノートに書いておく内容にはならない。"}, {"text": "身長", "is_correct": false, "explanation": "体の高さを表す。「電話をかけた身長」は意味が通らない。"}, {"text": "重さ", "is_correct": false, "explanation": "ものの重さを表す。「電話をかけた重さ」は意味が通らない。"}], "explanations": {"時刻": "時間の流れの中の一点を表す名詞。「電話をかけた」に続き、ノートに書く対象として合う。", "座席": "座る場所を表す。電話をかけた場所を示す語として、ノートに書いておく内容にはならない。", "身長": "体の高さを表す。「電話をかけた身長」は意味が通らない。", "重さ": "ものの重さを表す。「電話をかけた重さ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "時刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "合宿の時刻は一週間だ。", "explanation": "ここは〈期間〉の意味。時刻は一点の時を指すので、一週間という期間には使わない。"}, {"text": "修理の時刻は三日だ。", "explanation": "ここは〈日数〉の意味。時刻は時点を表し、かかる日数の数には使わない。"}, {"text": "駅までの時刻は五キロだ。", "explanation": "ここは〈距離〉の意味。時刻は時間の一点を指し、五キロという距離の長さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36373, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電話が切れた時刻が、係員が記録した。", "corrected_sentence": "電話が切れた時刻を、係員が記録した。", "error_description": "「時刻」は記録される対象なので助詞は「を」が正しい。「が」は主語を表し、「記録した」の目的語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36373, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面接の時刻へ、受付で名前を書いた。", "corrected_sentence": "面接の時刻に、受付で名前を書いた。", "error_description": "時点を示すには「に」が必要。「へ」は方向を表すため、時刻には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866c64ad-7119-4ef6-865a-815457e7fb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36374, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不信", "is_correct": true, "explanation": "信じることの対義語。相手を疑い、信じないこと。"}, {"text": "友情", "is_correct": false, "explanation": "友人同士の親しい気持ちで、対義語の関係ではない。"}, {"text": "結婚", "is_correct": false, "explanation": "夫婦になる制度や行為で、信頼の対義語ではない。"}, {"text": "旅行", "is_correct": false, "explanation": "移動して楽しむことで、対義語の関係ではない。"}], "correct_answer": "不信", "explanations": {"不信": "信じることの対義語。相手を疑い、信じないこと。", "友情": "友人同士の親しい気持ちで、対義語の関係ではない。", "結婚": "夫婦になる制度や行為で、信頼の対義語ではない。", "旅行": "移動して楽しむことで、対義語の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36374, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不信", "is_correct": true, "explanation": "信じていた人への信頼の対義語。信じられなくなること。"}, {"text": "食事", "is_correct": false, "explanation": "食べることで、対義語の関係ではない。"}, {"text": "病気", "is_correct": false, "explanation": "体の不調で、信頼の対義語ではない。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態で、対義語の関係ではない。"}], "correct_answer": "不信", "explanations": {"不信": "信じていた人への信頼の対義語。信じられなくなること。", "食事": "食べることで、対義語の関係ではない。", "病気": "体の不調で、信頼の対義語ではない。", "天気": "空の状態で、対義語の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36374, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "誰かを信じること。", "primary_collocate": null, "pronunciation": "しんらい", "ipa": "ɕiɴɾai", "syllable_count": 4, "sentences": [{"text": "私は長年の友人を信頼している。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "私(わたし)は長年(ながねん)の友人(ゆうじん)を信頼(しんらい)している。", "sentence_source": "generated"}, {"text": "子どもは親を信頼して、安心して眠る。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "子(こ)どもは親(おや)を信頼(しんらい)して、安心(あんしん)して眠(ねむ)る。", "sentence_source": "generated"}, {"text": "チームの仲間を信頼して、最後までプレーした。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "チームの仲間(なかま)を信頼(しんらい)して、最後(さいご)までプレーした。", "sentence_source": "generated"}, {"text": "彼は信頼できる人だから、お金を預けても大丈夫だ。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "彼(かれ)は信頼(しんらい)できる人(ひと)だから、お金(かね)を預(あず)けても大丈夫(だいじょうぶ)だ。", "sentence_source": "generated"}, {"text": "信頼がなければ、大事な仕事は任せられない。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "信頼(しんらい)がなければ、大事(だいじ)な仕事(しごと)は任(まか)せられない。", "sentence_source": "generated"}, {"text": "先生を信頼しているので、進路の相談をした。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "先生(せんせい)を信頼(しんらい)しているので、進路(しんろ)の相談(そうだん)をした。", "sentence_source": "generated"}, {"text": "お互いに信頼して、約束を守り合った。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "お互(たが)いに信頼(しんらい)して、約束(やくそく)を守(まも)り合(あ)った。", "sentence_source": "generated"}, {"text": "その医者は、患者から信頼されている。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "その医者(いしゃ)は、患者(かんじゃ)から信頼(しんらい)されている。", "sentence_source": "generated"}, {"text": "部下を信頼するのは、簡単ではないが大切だ。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "部下(ぶか)を信頼(しんらい)するのは、簡単(かんたん)ではないが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "信頼していた人にだまされて、とても悲しかった。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "信頼(しんらい)していた人(ひと)にだまされて、とても悲(かな)しかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "信頼", "label": "基本形"}, {"form": "信頼する", "label": "サ変動詞"}, {"form": "信頼される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "誰かを信じて頼りにするという心の動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36374, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信頼", "is_correct": true, "explanation": "友人を頼りにして信じているという意味で、ここにだけ入る。"}, {"text": "翻訳", "is_correct": false, "explanation": "「友人を翻訳している」は意味が通らない。"}, {"text": "梱包", "is_correct": false, "explanation": "「友人を梱包している」は不自然。"}, {"text": "解説", "is_correct": false, "explanation": "「友人を解説している」は文脈に合わない。"}], "explanations": {"信頼": "友人を頼りにして信じているという意味で、ここにだけ入る。", "翻訳": "「友人を翻訳している」は意味が通らない。", "梱包": "「友人を梱包している」は不自然。", "解説": "「友人を解説している」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "信頼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "給料日前で現金がないので、信頼で本を買った。", "explanation": "ここは〈信用〉（掛け売り・後払い）の意味。信頼は人を信じる気持ちで、支払いの方法ではないので合わない。"}, {"text": "毎晩、父は神棚の前で信頼を捧げて、家族の健康を祈る。", "explanation": "ここは〈信仰〉の意味。信頼は人への気持ちで、神仏に捧げる語ではないので合わない。"}, {"text": "父は周囲に反対されても、自分の信頼を曲げずに店を続けた。", "explanation": "ここは〈信念〉の意味。信頼は人を信じる気持ちで、自分の考えや主義を貫く意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36374, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信頼", "is_correct": true, "explanation": "お互いに信じ合う意味で、ここに入る語。"}, {"text": "製造", "is_correct": false, "explanation": "「お互いに製造して、約束を守り合った」は意味が通らない。"}, {"text": "配達", "is_correct": false, "explanation": "「お互いに配達して」は文脈に合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "「お互いに清掃して」は約束の文脈に合わない。"}], "explanations": {"信頼": "お互いに信じ合う意味で、ここに入る語。", "製造": "「お互いに製造して、約束を守り合った」は意味が通らない。", "配達": "「お互いに配達して」は文脈に合わない。", "清掃": "「お互いに清掃して」は約束の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "信頼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の交差点で信頼が故障して、車が止まった。", "explanation": "信頼は信号機の意味を持たない。人への気持ちを表す語なので、機械の故障には使えず合わない。"}, {"text": "この音楽は私の信頼によく合う。", "explanation": "ここは〈好み〉の意味。信頼は人を頼る気持ちで、音楽の好みには使わないので合わない。"}, {"text": "この電池は信頼が長く、一年は持つ。", "explanation": "ここは〈寿命〉の意味。信頼は人への気持ちで、物の持ちには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36374, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は弟を信頼に、留守番を任せた。", "corrected_sentence": "母は弟を信頼して、留守番を任せた。", "error_description": "「信頼する」は動詞として「信頼して」と活用する。「信頼に」は活用の誤りで、この文では不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36374, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客は店員の説明を信頼で、商品を買った。", "corrected_sentence": "客は店員の説明を信頼して、商品を買った。", "error_description": "「信頼して」が正しい連用形。「信頼で」は手段の助詞で、ここでは不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36375, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「深い信頼がある」の「ある」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「深い信頼とある」は文として成り立たず、「と」は並列や共同を表すので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「信頼へある」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「深い信頼がある」の「ある」の主語を示す「が」。", "を": "「ある」は目的語を取らないので「を」は合わない。", "と": "「深い信頼とある」は文として成り立たず、「と」は並列や共同を表すので不自然。", "へ": "方向を表す「へ」で、「信頼へある」は不自然。"}, "error_tags": {"を": "目的格", "と": "並列・共同", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不信", "is_correct": true, "explanation": "信頼の対義語。相手を疑い、頼りにできないと思う気持ち。"}, {"text": "希望", "is_correct": false, "explanation": "将来への望みで、信頼の対義語ではない。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせることで、信頼と対になる語ではない。"}, {"text": "努力", "is_correct": false, "explanation": "目標に向けて力を尽くすことで、信頼の反対の意味にはならない。"}], "correct_answer": "不信", "explanations": {"不信": "信頼の対義語。相手を疑い、頼りにできないと思う気持ち。", "希望": "将来への望みで、信頼の対義語ではない。", "協力": "力を合わせることで、信頼と対になる語ではない。", "努力": "目標に向けて力を尽くすことで、信頼の反対の意味にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36375, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「友達の信頼に応える」の「応える」が相手を表すときの「に」。"}, {"text": "が", "is_correct": false, "explanation": "「信頼が応えた」は主語の誤りで、「応える」の相手にはならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「信頼の応えた」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同を表す「と」で、「信頼と応えた」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「友達の信頼に応える」の「応える」が相手を表すときの「に」。", "が": "「信頼が応えた」は主語の誤りで、「応える」の相手にはならない。", "の": "連体修飾の「の」で、「信頼の応えた」は文が成り立たない。", "と": "共同を表す「と」で、「信頼と応えた」は不自然。"}, "error_tags": {"が": "主格", "の": "連体", "と": "共同"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不信", "is_correct": true, "explanation": "信頼の対義語。相手を信じられず、疑う気持ち。"}, {"text": "愛情", "is_correct": false, "explanation": "深く大切に思う気持ちで、信頼の対義語ではない。"}, {"text": "感謝", "is_correct": false, "explanation": "恩に対して感じる気持ちで、対義語の関係ではない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読む行為で、信頼の対義語ではない。"}], "correct_answer": "不信", "explanations": {"不信": "信頼の対義語。相手を信じられず、疑う気持ち。", "愛情": "深く大切に思う気持ちで、信頼の対義語ではない。", "感謝": "恩に対して感じる気持ちで、対義語の関係ではない。", "読書": "本を読む行為で、信頼の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36375, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "相手を疑わず、頼りにできると思う気持ち。", "primary_collocate": null, "pronunciation": "しんらい", "ipa": "ɕiɴɾai", "syllable_count": 4, "sentences": [{"text": "例えば、赤は情熱や緊急を、青は信頼を連想させる。", "target_word": "信頼", "complexity_tier": "T4", "furigana": "例(たと)えば、赤(あか)は情熱(じょうねつ)や緊急(きんきゅう)を、青(あお)は信頼(しんらい)を連想(れんそう)させる。", "sentence_source": "mined"}, {"text": "長い間の付き合いで、二人の間には深い信頼がある。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "長(なが)い間(あいだ)の付(つ)き合(あ)いで、二人(ふたり)の間(あいだ)には深(ふか)い信頼(しんらい)がある。", "sentence_source": "generated"}, {"text": "彼の正直な態度が、客の信頼を得た。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "彼(かれ)の正直(しょうじき)な態度(たいど)が、客(きゃく)の信頼(しんらい)を得(え)た。", "sentence_source": "generated"}, {"text": "一度うそをつくと、信頼を失ってしまう。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "一度(いちど)うそをつくと、信頼(しんらい)を失(うしな)ってしまう。", "sentence_source": "generated"}, {"text": "上司は部下に仕事を任せて、信頼を示した。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "上司(じょうし)は部下(ぶか)に仕事(しごと)を任(まか)せて、信頼(しんらい)を示(しめ)した。", "sentence_source": "generated"}, {"text": "この店は品質がよく、客からの信頼が厚い。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "この店(みせ)は品質(ひんしつ)がよく、客(きゃく)からの信頼(しんらい)が厚(あつ)い。", "sentence_source": "generated"}, {"text": "医者と患者の信頼がなければ、治療はうまくいかない。", "target_word": "信頼", "complexity_tier": "T4", "furigana": "医者(いしゃ)と患者(かんじゃ)の信頼(しんらい)がなければ、治療(ちりょう)はうまくいかない。", "sentence_source": "generated"}, {"text": "約束を守ることで、友達の信頼に応えた。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "約束(やくそく)を守(まも)ることで、友達(ともだち)の信頼(しんらい)に応(こた)えた。", "sentence_source": "generated"}, {"text": "銀行にとって、客の信頼は何より大切だ。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "銀行(ぎんこう)にとって、客(きゃく)の信頼(しんらい)は何(なに)より大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "彼女に対する信頼は、少しも変わらない。", "target_word": "信頼", "complexity_tier": "T3", "furigana": "彼女(かのじょ)に対(たい)する信頼(しんらい)は、少(すこ)しも変(か)わらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "信頼", "label": "基本形"}, {"form": "信頼する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "相手を疑わず、頼りにできると思う気持ちそのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36375, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信頼", "is_correct": true, "explanation": "青が連想させる、人を疑わず頼れると感じる安心感を表す語。ここにだけ入る。"}, {"text": "騒音", "is_correct": false, "explanation": "「青は騒音を連想させる」は色の連想として不自然。"}, {"text": "割引", "is_correct": false, "explanation": "「青は割引を連想させる」は意味が通らない。"}, {"text": "空腹", "is_correct": false, "explanation": "「青は空腹を連想させる」は色の連想として不自然。"}], "explanations": {"信頼": "青が連想させる、人を疑わず頼れると感じる安心感を表す語。ここにだけ入る。", "騒音": "「青は騒音を連想させる」は色の連想として不自然。", "割引": "「青は割引を連想させる」は意味が通らない。", "空腹": "「青は空腹を連想させる」は色の連想として不自然。"}, "sentence_index": 0, "correct_answer": "信頼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は貯金がなかったので、信頼でテレビを買った。", "explanation": "ここは〈信用〉（後払い）の意味。信頼は人を疑わない気持ちで、支払いの方法を表さないので合わない。"}, {"text": "毎朝、彼女は神社で信頼を捧げて、家族の無事を祈る。", "explanation": "ここは〈信仰〉の意味。信頼は人への気持ちで、神仏に捧げる語ではないので合わない。"}, {"text": "彼は周囲の反対にも自分の信頼を曲げず、計画を進めた。", "explanation": "ここは〈信念〉の意味。信頼は相手を信じる気持ちで、自分の考えや主義を貫く意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36375, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信頼", "is_correct": true, "explanation": "医者と患者の間にあるべき、疑わない頼りやすさを表す語。ここにだけ入る。"}, {"text": "名刺", "is_correct": false, "explanation": "「医者と患者の名刺がなければ」は文脈に合わない。"}, {"text": "時差", "is_correct": false, "explanation": "「医者と患者の時差がなければ」は意味が通らない。"}, {"text": "指輪", "is_correct": false, "explanation": "「医者と患者の指輪がなければ治療は」は関係のない物で不自然。"}], "explanations": {"信頼": "医者と患者の間にあるべき、疑わない頼りやすさを表す語。ここにだけ入る。", "名刺": "「医者と患者の名刺がなければ」は文脈に合わない。", "時差": "「医者と患者の時差がなければ」は意味が通らない。", "指輪": "「医者と患者の指輪がなければ治療は」は関係のない物で不自然。"}, "sentence_index": 6, "correct_answer": "信頼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝の交差点で信頼が故障して、車が一時止まった。", "explanation": "信頼は信号機の意味を持たない。人への気持ちを表す語なので、機械の故障には使えず合わない。"}, {"text": "このお菓子は私の信頼によく合う。", "explanation": "ここは〈好み〉の意味。信頼は人を頼れると思う気持ちで、味の好みには使わないので合わない。"}, {"text": "この電池は信頼が長く、一年は持つ。", "explanation": "ここは〈寿命〉（ものの持ちの良さ）の意味。信頼は人への気持ちで、物の耐久性には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36375, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は約束を守り続けて、同僚の信頼で集めた。", "corrected_sentence": "彼は約束を守り続けて、同僚の信頼を集めた。", "error_description": "「集める」の目的語には「信頼を」の「を」が必要。「信頼で」は手段の助詞で、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36375, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長年の誠実な対応で、取引先からの信頼に得た。", "corrected_sentence": "長年の誠実な対応で、取引先からの信頼を得た。", "error_description": "「得る」は目的語を「を」で取る。「信頼に」の「に」は誤りで、この文では不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
