INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36376, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かがこわれて、元の形や状態でなくなること。", "primary_collocate": null, "pronunciation": "ほうかい", "ipa": "hoːkai", "syllable_count": 4, "sentences": [{"text": "地震で古い橋が崩壊し、車が通れなくなった。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "地震(じしん)で古(ふる)い橋(はし)が崩壊(ほうかい)し、車(くるま)が通(とお)れなくなった。", "sentence_source": "generated"}, {"text": "雪の重みで、小屋の屋根が崩壊した。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "雪(ゆき)の重(おも)みで、小屋(こや)の屋根(やね)が崩壊(ほうかい)した。", "sentence_source": "generated"}, {"text": "ビルの崩壊を防ぐため、柱を補強している。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "ビルの崩壊(ほうかい)を防(ふせ)ぐため、柱(はしら)を補強(ほきょう)している。", "sentence_source": "generated"}, {"text": "長い雨で山の斜面が崩壊する恐れがある。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "長(なが)い雨(あめ)で山(やま)の斜面(しゃめん)が崩壊(ほうかい)する恐(おそ)れがある。", "sentence_source": "generated"}, {"text": "工事のミスが、建物の崩壊につながった。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "工事(こうじ)のミスが、建物(たてもの)の崩壊(ほうかい)につながった。", "sentence_source": "generated"}, {"text": "崩壊したトンネルの前で、作業員が調査を始めた。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "崩壊(ほうかい)したトンネルの前(まえ)で、作業員(さぎょういん)が調査(ちょうさ)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "氷河の崩壊は、温暖化の影響だと言われている。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "氷河(ひょうが)の崩壊(ほうかい)は、温暖化(おんだんか)の影響(えいきょう)だと言(い)われている。", "sentence_source": "generated"}, {"text": "壁が崩壊する直前に、住民は全員避難していた。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "壁(かべ)が崩壊(ほうかい)する直前(ちょくぜん)に、住民(じゅうみん)は全員(ぜんいん)避難(ひなん)していた。", "sentence_source": "generated"}, {"text": "堤防の崩壊によって、川の水が町に流れ込んだ。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "堤防(ていぼう)の崩壊(ほうかい)によって、川(かわ)の水(みず)が町(まち)に流(なが)れ込(こ)んだ。", "sentence_source": "generated"}, {"text": "崩壊の原因を調べるため、専門家が現場に入った。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "崩壊(ほうかい)の原因(げんいん)を調(しら)べるため、専門家(せんもんか)が現場(げんば)に入(はい)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "崩壊", "label": "基本形"}, {"form": "崩壊する", "label": "サ変動詞"}, {"form": "崩壊した", "label": "過去形"}, {"form": "崩壊し", "label": "連用形"}], "register": "書き言葉", "sense_fingerprint": "建物・橋・斜面などの物が崩れて、元の形を保てなくなること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36376, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崩壊", "is_correct": true, "explanation": "「橋が崩壊し」は、物が壊れて形を失う意味。車が通れなくなった結果と合う。"}, {"text": "完成", "is_correct": false, "explanation": "「橋が完成し」は仕上がる意味で、車が通れなくなる理由にならない。"}, {"text": "配布", "is_correct": false, "explanation": "「橋が配布し」は意味が通らず、橋の状態を表さない。"}, {"text": "乗車", "is_correct": false, "explanation": "「橋が乗車し」は人が乗る意味で、橋には使わない。"}], "explanations": {"崩壊": "「橋が崩壊し」は、物が壊れて形を失う意味。車が通れなくなった結果と合う。", "完成": "「橋が完成し」は仕上がる意味で、車が通れなくなる理由にならない。", "配布": "「橋が配布し」は意味が通らず、橋の状態を表さない。", "乗車": "「橋が乗車し」は人が乗る意味で、橋には使わない。"}, "sentence_index": 0, "correct_answer": "崩壊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新人は四月から工場に崩壊する。", "explanation": "ここは〈配属〉の意味。崩壊は物が壊れることで、人を職場に割り当てる意味は持たない。"}, {"text": "新しい店は来週崩壊する予定だ。", "explanation": "ここは〈開店〉の意味。崩壊は壊れる事態を指し、店の開業には使わない。"}, {"text": "昨日の更新から、ノートパソコンが崩壊している。", "explanation": "ここは〈故障〉の意味。崩壊は建物や組織のように大きな構造が崩れることを指し、機械の不具合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36376, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崩壊", "is_correct": true, "explanation": "「氷河の崩壊」は氷の塊が崩れ落ちる意味で、温暖化の影響として文脈に合う。"}, {"text": "点火", "is_correct": false, "explanation": "「氷河の点火」は火をつける意味で、氷河の話には使わない。"}, {"text": "採点", "is_correct": false, "explanation": "「氷河の採点」は評価する意味で、自然現象の話に合わない。"}, {"text": "受験", "is_correct": false, "explanation": "「氷河の受験」は試験を受ける意味で、意味が通らない。"}], "explanations": {"崩壊": "「氷河の崩壊」は氷の塊が崩れ落ちる意味で、温暖化の影響として文脈に合う。", "点火": "「氷河の点火」は火をつける意味で、氷河の話には使わない。", "採点": "「氷河の採点」は評価する意味で、自然現象の話に合わない。", "受験": "「氷河の受験」は試験を受ける意味で、意味が通らない。"}, "sentence_index": 6, "correct_answer": "崩壊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その村で赤ちゃんが崩壊した。", "explanation": "ここは〈誕生〉の意味。崩壊は壊れることで、命が生まれる意味には使わない。"}, {"text": "来年の観光客は崩壊すると予想されている。", "explanation": "ここは〈増加〉の意味。崩壊は壊れる事態で、人数が増えるという意味は持たない。"}, {"text": "次の春、息子は中学校に崩壊する。", "explanation": "ここは〈入学〉の意味。崩壊は物が壊れることで、学校に入る意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36376, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨が、堤防の崩壊に招いた。", "corrected_sentence": "大雨が、堤防の崩壊を招いた。", "error_description": "「招く」の目的語を示す「崩壊を」の「を」を「崩壊に」の「に」にした誤り。「招く」は目的語に「を」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36376, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "橋の崩壊を防げため、柱を補強した。", "corrected_sentence": "橋の崩壊を防ぐため、柱を補強した。", "error_description": "「防ぐため」の「防ぐ」を「防げため」と活用させた誤り。「ため」は動詞の終止形に続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
