INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36377, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物や組織、関係などが完全に壊れて、元の形や機能を失うこと。", "primary_collocate": null, "pronunciation": "ほうかい", "ipa": "hoːkai", "syllable_count": 4, "sentences": [{"text": "会社の崩壊を防ぐため、社長は新しい計画を立てた。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "会社(かいしゃ)の崩壊(ほうかい)を防(ふせ)ぐため、社長(しゃちょう)は新(あたら)しい計画(けいかく)を立(た)てた。", "sentence_source": "generated"}, {"text": "長い争いのすえ、二人の信頼関係は崩壊した。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "長(なが)い争(あらそ)いのすえ、二人(ふたり)の信頼(しんらい)関係(かんけい)は崩壊(ほうかい)した。", "sentence_source": "generated"}, {"text": "戦争で国の経済が崩壊し、人々の生活は苦しくなった。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "戦争(せんそう)で国(くに)の経済(けいざい)が崩壊(ほうかい)し、人々(ひとびと)の生活(せいかつ)は苦(くる)しくなった。", "sentence_source": "generated"}, {"text": "家族の崩壊は、小さなうそから始まることもある。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "家族(かぞく)の崩壊(ほうかい)は、小(ちい)さなうそから始(はじ)まることもある。", "sentence_source": "generated"}, {"text": "組織が崩壊すると、仲間はばらばらになってしまう。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "組織(そしき)が崩壊(ほうかい)すると、仲間(なかま)はばらばらになってしまう。", "sentence_source": "generated"}, {"text": "政府の崩壊後、その国は長い混乱に入った。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "政府(せいふ)の崩壊後(ほうかいご)、その国(くに)は長(なが)い混乱(こんらん)に入(はい)った。", "sentence_source": "generated"}, {"text": "チームの崩壊は、エースの退団がきっかけだった。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "チームの崩壊(ほうかい)は、エースの退団(たいだん)がきっかけだった。", "sentence_source": "generated"}, {"text": "信じていた価値観が崩壊して、彼は何も手につかなかった。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "信(しん)じていた価値観(かちかん)が崩壊(ほうかい)して、彼(かれ)は何(なに)も手(て)につかなかった。", "sentence_source": "generated"}, {"text": "伝統的な村の共同体は、人口の減少で崩壊しかけている。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "伝統的(でんとうてき)な村(むら)の共同体(きょうどうたい)は、人口(じんこう)の減少(げんしょう)で崩壊(ほうかい)しかけている。", "sentence_source": "generated"}, {"text": "友情の崩壊を心配して、彼女は本音を言えなかった。", "target_word": "崩壊", "complexity_tier": "T3", "furigana": "友情(ゆうじょう)の崩壊(ほうかい)を心配(しんぱい)して、彼女(かのじょ)は本音(ほんね)を言(い)えなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "崩壊", "label": "基本形"}, {"form": "崩壊する", "label": "サ変動詞"}, {"form": "崩壊した", "label": "過去形"}, {"form": "崩壊し", "label": "連用形"}], "register": "書き言葉", "sense_fingerprint": "会社・国・家族・信頼関係・価値観などの組織や関係が成り立たなくなること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36377, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崩壊", "is_correct": true, "explanation": "「会社の崩壊」は組織が成り立たなくなること。それを防ぐという文脈に合う。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は人が抱く気持ちで、会社という組織の状態を防ぐ対象にはならない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点をつける行為で、「会社の採点を防ぐ」は意味が通らない。"}, {"text": "読書", "is_correct": false, "explanation": "読書は本を読むことで、会社の状態を表せないので文が成り立たない。"}], "explanations": {"崩壊": "「会社の崩壊」は組織が成り立たなくなること。それを防ぐという文脈に合う。", "感謝": "感謝は人が抱く気持ちで、会社という組織の状態を防ぐ対象にはならない。", "採点": "採点は答案に点をつける行為で、「会社の採点を防ぐ」は意味が通らない。", "読書": "読書は本を読むことで、会社の状態を表せないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "崩壊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強風で自転車が崩壊して、道の真ん中に倒れた。", "explanation": "ここは〈転倒〉の意味。崩壊は組織や物が機能を失って元の形を保てなくなることで、自転車が倒れる場面では転倒を使う。"}, {"text": "使わなくなった家電を、部品ごとに崩壊して整理した。", "explanation": "ここは〈分解〉の意味。崩壊は意図せず壊れて機能を失うことで、計画的に部品を外す場面では使わない。"}, {"text": "週末は天気が崩壊する見込みだ。", "explanation": "ここは〈天気が崩れる〉の意味。崩壊は組織や物が機能を失うことで、天気の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36377, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崩壊", "is_correct": true, "explanation": "「チームの崩壊」はチームが機能しなくなること。エースの退団が原因として合う。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩いて出かける行為で、チームの状態を表せないので文が成り立たない。"}, {"text": "結婚", "is_correct": false, "explanation": "結婚は人同士が家族になることで、チームという集団の状態には使わない。"}, {"text": "手術", "is_correct": false, "explanation": "手術は体の治療行為で、チームの状態を述べる文では意味が通らない。"}], "explanations": {"崩壊": "「チームの崩壊」はチームが機能しなくなること。エースの退団が原因として合う。", "散歩": "散歩は歩いて出かける行為で、チームの状態を表せないので文が成り立たない。", "結婚": "結婚は人同士が家族になることで、チームという集団の状態には使わない。", "手術": "手術は体の治療行為で、チームの状態を述べる文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "崩壊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷蔵庫に入れ忘れた牛乳が、一晩で崩壊してしまった。", "explanation": "ここは〈腐敗〉の意味。崩壊は組織や物が機能を失うことで、食品が傷んで変質する場合には使わない。"}, {"text": "誤解を招いた発言は、翌日すぐに崩壊した。", "explanation": "ここは〈撤回〉の意味。崩壊は組織や関係が成り立たなくなることで、自分の発言を取り消す場面では撤回を使う。"}, {"text": "レジで千円札が崩壊して、小銭になった。", "explanation": "ここは〈崩す〉（お札を小銭にする）の意味。崩壊は物が壊れて機能を失うことで、お札を小銭に替える場面では崩すを使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36377, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨で堤防の崩壊を始まった。", "corrected_sentence": "雨で堤防の崩壊が始まった。", "error_description": "「始まる」は主語に「が」を取る自動詞。「崩壊が始まった」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36377, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国の崩壊に防ぐには、人々の協力が必要だ。", "corrected_sentence": "国の崩壊を防ぐには、人々の協力が必要だ。", "error_description": "「防ぐ」は目的語に「を」を取る。「崩壊を防ぐ」が正しく、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36378, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「続く」は「直線が続く」のように、続くものを主語として「が」で示す。文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「続く」は目的語を取らないので、「直線を続いている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「直線と続いている」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すが、ここは比べる文ではないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「続く」は「直線が続く」のように、続くものを主語として「が」で示す。文に合う。", "を": "「を」は目的語を示すが、「続く」は目的語を取らないので、「直線を続いている」は成り立たない。", "と": "「と」は相手や並列を示すが、「直線と続いている」では文が成り立たない。", "より": "「より」は比較の基準を示すが、ここは比べる文ではないので合わない。"}, "error_tags": {"を": "目的語", "と": "相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
