INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36378, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まっすぐな線", "primary_collocate": null, "pronunciation": "ちょくせん", "ipa": "tɕokɯseɴ", "syllable_count": 4, "sentences": [{"text": "定規を使って、紙に直線を引いた。", "target_word": "直線", "complexity_tier": "T3", "furigana": "定規(じょうぎ)を使(つか)って、紙(かみ)に直線(ちょくせん)を引(ひ)いた。", "sentence_source": "generated"}, {"text": "この道路は五キロも直線が続いている。", "target_word": "直線", "complexity_tier": "T3", "furigana": "この道路(どうろ)は五(ご)キロも直線(ちょくせん)が続(つづ)いている。", "sentence_source": "generated"}, {"text": "二つの点を直線で結んでください。", "target_word": "直線", "complexity_tier": "T3", "furigana": "二(ふた)つの点(てん)を直線(ちょくせん)で結(むす)んでください。", "sentence_source": "generated"}, {"text": "矢は直線を描いて飛び、的の中心に突き刺さった。", "target_word": "直線", "complexity_tier": "T3", "furigana": "矢(や)は直線(ちょくせん)を描(えが)いて飛(と)び、的(まと)の中心(ちゅうしん)に突(つ)き刺(さ)さった。", "sentence_source": "generated"}, {"text": "直線では速い車も、カーブでは速度を落とす。", "target_word": "直線", "complexity_tier": "T3", "furigana": "直線(ちょくせん)では速(はや)い車(くるま)も、カーブでは速度(そくど)を落(お)とす。", "sentence_source": "generated"}, {"text": "地図の上で、東京から大阪まで直線を引いてみた。", "target_word": "直線", "complexity_tier": "T3", "furigana": "地図(ちず)の上(うえ)で、東京(とうきょう)から大阪(おおさか)まで直線(ちょくせん)を引(ひ)いてみた。", "sentence_source": "generated"}, {"text": "グラフが直線になったので、二つの量は比例している。", "target_word": "直線", "complexity_tier": "T3", "furigana": "グラフが直線(ちょくせん)になったので、二(ふた)つの量(りょう)は比例(ひれい)している。", "sentence_source": "generated"}, {"text": "その画家は直線だけを使って、建物の輪郭を描いた。", "target_word": "直線", "complexity_tier": "T3", "furigana": "その画家(がか)は直線(ちょくせん)だけを使(つか)って、建物(たてもの)の輪郭(りんかく)を描(えが)いた。", "sentence_source": "generated"}, {"text": "フリーハンドで直線を描くのは意外にむずかしい。", "target_word": "直線", "complexity_tier": "T3", "furigana": "フリーハンドで直線(ちょくせん)を描(えが)くのは意外(いがい)にむずかしい。", "sentence_source": "generated"}, {"text": "森の中の道は曲がりくねっていて、直線の道はほとんどない。", "target_word": "直線", "complexity_tier": "T3", "furigana": "森(もり)の中(なか)の道(みち)は曲(ま)がりくねっていて、直線(ちょくせん)の道(みち)はほとんどない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直線", "label": "基本形"}, {"form": "直線を", "label": "目的語"}, {"form": "直線に", "label": "副詞的用法"}], "register": "中立", "sense_fingerprint": "曲がらない、まっすぐな線や道筋。図形・道路・グラフなどで使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36378, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直線", "is_correct": true, "explanation": "「紙に直線を引く」は、まっすぐな線を描くこと。文に合う。"}, {"text": "感想", "is_correct": false, "explanation": "感想は述べたり書いたりするもので、紙に引くものではない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸の音で、紙に引くことはできない。"}, {"text": "借金", "is_correct": false, "explanation": "借金は返す義務のあるお金で、紙に引くものではない。"}], "explanations": {"直線": "「紙に直線を引く」は、まっすぐな線を描くこと。文に合う。", "感想": "感想は述べたり書いたりするもので、紙に引くものではない。", "寝息": "寝息は眠っている人の呼吸の音で、紙に引くことはできない。", "借金": "借金は返す義務のあるお金で、紙に引くものではない。"}, "sentence_index": 0, "correct_answer": "直線"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋の角は直線になっていて、床と壁がきれいに交わっている。", "explanation": "ここは〈直角〉の意味。直線は曲がりのない一本の線で、二つの面が角で交わる様子には使わない。"}, {"text": "バッターは直線を待ちかまえて、力いっぱい打った。", "explanation": "ここは〈直球〉の意味。直線は図形の線で、野球の投球を指すときには使わない。"}, {"text": "コンパスで描いた円の直線を、定規で測った。", "explanation": "ここは〈直径〉の意味。円の中心を通る長さを測る場面なので、直線（一般の線）とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36378, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直線", "is_correct": true, "explanation": "「グラフが直線になった」は、グラフが一本のまっすぐな線になったこと。比例の説明に合う。"}, {"text": "満足", "is_correct": false, "explanation": "満足は人の気持ちを表す語で、グラフの形には使わない。"}, {"text": "失望", "is_correct": false, "explanation": "失望は期待が裏切られた時の人の気持ちで、グラフの形には当てはまらない。"}, {"text": "反省", "is_correct": false, "explanation": "反省は自分の行いを振り返ることで、グラフの形を表せない。"}], "explanations": {"直線": "「グラフが直線になった」は、グラフが一本のまっすぐな線になったこと。比例の説明に合う。", "満足": "満足は人の気持ちを表す語で、グラフの形には使わない。", "失望": "失望は期待が裏切られた時の人の気持ちで、グラフの形には当てはまらない。", "反省": "反省は自分の行いを振り返ることで、グラフの形を表せない。"}, "sentence_index": 6, "correct_answer": "直線"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は直線の形をしていて、積み重ねやすい。", "explanation": "ここは〈直方体〉の意味。箱は立体なので、線を表す直線とは言わない。"}, {"text": "この床は直線になっているか、水平器で確かめた。", "explanation": "ここは〈水平〉の意味。床の平らさを確かめる場面なので、線の直線とは言わない。"}, {"text": "彼女は直線で答えを選んだ。", "explanation": "ここは〈直感〉の意味。図形の線を指す直線は、判断の仕方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36378, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この先の道は、しばらく直線を続いている。", "corrected_sentence": "この先の道は、しばらく直線が続いている。", "error_description": "「続く」は主語に「が」を取る。「直線が続いている」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36378, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二点を結ぶと直線をできる。", "corrected_sentence": "二点を結ぶと直線ができる。", "error_description": "「できる」は主語に「が」を取る。「直線ができる」が正しく、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36379, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「続く」は「直線が続く」のように、続くものを主語として「が」で示す。文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「続く」は目的語を取らないので、「直線を続いている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「直線と続いている」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すが、ここは比べる文ではないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「続く」は「直線が続く」のように、続くものを主語として「が」で示す。文に合う。", "を": "「を」は目的語を示すが、「続く」は目的語を取らないので、「直線を続いている」は成り立たない。", "と": "「と」は相手や並列を示すが、「直線と続いている」では文が成り立たない。", "より": "「より」は比較の基準を示すが、ここは比べる文ではないので合わない。"}, "error_tags": {"を": "目的語", "と": "相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36379, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「紙に直線を並べる」の直線は並べる対象なので、目的語として「を」で示す。文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、並べる主体は「子ども」なので、「直線が並べる」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「直線と並べる」では並べる対象を表せず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すが、ここは比べる文ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「紙に直線を並べる」の直線は並べる対象なので、目的語として「を」で示す。文に合う。", "が": "「が」は主語を示すが、並べる主体は「子ども」なので、「直線が並べる」は合わない。", "と": "「と」は相手や並列を示すが、「直線と並べる」では並べる対象を表せず、意味が通らない。", "より": "「より」は比較の基準を示すが、ここは比べる文ではないので合わない。"}, "error_tags": {"が": "主語", "と": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36379, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まっすぐに伸びた線。曲がっていない線。", "primary_collocate": null, "pronunciation": "ちょくせん", "ipa": "tɕokɯseɴ", "syllable_count": 4, "sentences": [{"text": "地図の上に定規で直線を引いた。", "target_word": "直線", "complexity_tier": "T3", "furigana": "地図[ちず]の上[うえ]に定規[じょうぎ]で直線[ちょくせん]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "この道路は十キロも直線が続いている。", "target_word": "直線", "complexity_tier": "T3", "furigana": "この道路[どうろ]は十[じゅっ]キロも直線[ちょくせん]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "紙の上に点を打ち、その間を直線で結んだ。", "target_word": "直線", "complexity_tier": "T3", "furigana": "紙[かみ]の上[うえ]に点[てん]を打[う]ち、その間[あいだ]を直線[ちょくせん]で結[むす]んだ。", "sentence_source": "generated"}, {"text": "飛行機は海の上を直線に近いコースで飛んだ。", "target_word": "直線", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は海[うみ]の上[うえ]を直線[ちょくせん]に近[ちか]いコースで飛[と]んだ。", "sentence_source": "generated"}, {"text": "線が曲がってしまったので、もう一度直線を引き直した。", "target_word": "直線", "complexity_tier": "T3", "furigana": "線[せん]が曲[ま]がってしまったので、もう一度[いちど]直線[ちょくせん]を引[ひ]き直[なお]した。", "sentence_source": "generated"}, {"text": "曲線ではなく直線で描くと、図が見やすくなる。", "target_word": "直線", "complexity_tier": "T3", "furigana": "曲線[きょくせん]ではなく直線[ちょくせん]で描[えが]くと、図[ず]が見[み]やすくなる。", "sentence_source": "generated"}, {"text": "この線は曲がっていないので、直線だと言える。", "target_word": "直線", "complexity_tier": "T3", "furigana": "この線[せん]は曲[ま]がっていないので、直線[ちょくせん]だと言[い]える。", "sentence_source": "generated"}, {"text": "子どもは紙に直線を何本も並べて遊んでいた。", "target_word": "直線", "complexity_tier": "T3", "furigana": "子[こ]どもは紙[かみ]に直線[ちょくせん]を何本[なんぼん]も並[なら]べて遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "グラフが直線になったので、二つの量は比例している。", "target_word": "直線", "complexity_tier": "T3", "furigana": "グラフが直線[ちょくせん]になったので、二[ふた]つの量[りょう]は比例[ひれい]している。", "sentence_source": "generated"}, {"text": "この図形は、すべて直線で囲まれている。", "target_word": "直線", "complexity_tier": "T3", "furigana": "この図形は、すべて直線[ちょくせん]で囲まれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直線", "label": "基本形"}, {"form": "直線的", "label": "派生形（形状詞）"}], "register": "neutral", "sense_fingerprint": "曲がらずまっすぐに伸びた線。曲線の対。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36379, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直線", "is_correct": true, "explanation": "「定規で直線を引く」は、まっすぐな線を描くこと。文に合う。"}, {"text": "指紋", "is_correct": false, "explanation": "指紋は指先の模様で、定規で引くものではない。"}, {"text": "借金", "is_correct": false, "explanation": "借金は返す義務のあるお金で、定規で引くことはできない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸の音で、定規で引くものではない。"}], "explanations": {"直線": "「定規で直線を引く」は、まっすぐな線を描くこと。文に合う。", "指紋": "指紋は指先の模様で、定規で引くものではない。", "借金": "借金は返す義務のあるお金で、定規で引くことはできない。", "寝息": "寝息は眠っている人の呼吸の音で、定規で引くものではない。"}, "sentence_index": 0, "correct_answer": "直線"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この道は直線で、何度も角を曲がって学校へ行く。", "explanation": "直線はまっすぐで曲がらない線なので、何度も角を曲がる道とは言わない。"}, {"text": "この部屋の角は直線になっていて、床と壁がきれいに交わっている。", "explanation": "ここは〈直角〉の意味。直線は曲がりのない一本の線で、二つの面が角で交わる様子には使わない。"}, {"text": "ピザは丸いのに、直線の形をしている。", "explanation": "ピザは丸い形なので、直線の形とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36379, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直線", "is_correct": true, "explanation": "「曲がっていないので直線だと言える」は、一本のまっすぐな線であるという意味で文に合う。"}, {"text": "曲線", "is_correct": false, "explanation": "曲線は曲がった線のことで、曲がっていない線には当てはまらない。"}, {"text": "平面", "is_correct": false, "explanation": "平面は平らな面のことで、線を指す語ではない。"}, {"text": "立体", "is_correct": false, "explanation": "立体は立体的な図形のことで、線を指す語ではない。"}], "explanations": {"直線": "「曲がっていないので直線だと言える」は、一本のまっすぐな線であるという意味で文に合う。", "曲線": "曲線は曲がった線のことで、曲がっていない線には当てはまらない。", "平面": "平面は平らな面のことで、線を指す語ではない。", "立体": "立体は立体的な図形のことで、線を指す語ではない。"}, "sentence_index": 6, "correct_answer": "直線"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この滑らかな波は、すべて直線で描かれている。", "explanation": "ここは〈曲線〉の意味。滑らかに曲がった線は直線とは言わない。"}, {"text": "このボールは、表面がすべて直線でできている。", "explanation": "ここは〈曲面〉の意味。球の表面は曲がった面で、直線ではない。"}, {"text": "彼は直線で結論を出した。", "explanation": "直線は図形の線を指す語で、結論の出し方には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36379, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の横に、直線を影が伸びている。", "corrected_sentence": "窓の横に、直線の影が伸びている。", "error_description": "「直線」が「影」を修飾するには「の」が必要。「を」は目的語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36379, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この線が直線をなるまで、何度も引き直した。", "corrected_sentence": "この線が直線になるまで、何度も引き直した。", "error_description": "「なる」は変化先を「に」で示す。「直線になる」が正しく、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
