INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36380, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "元に戻せること", "primary_collocate": null, "pronunciation": "かぎゃく", "ipa": "kaɡʲaku", "syllable_count": 3, "sentences": [{"text": "この操作は可逆なので、間違えてもすぐに元に戻せる。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "この操作[そうさ]は可逆[かぎゃく]なので、間違[まちが]えてもすぐに元[もと]に戻[もど]せる。", "sentence_source": "generated"}, {"text": "氷が水になる変化は可逆だが、卵を焼く変化は可逆ではない。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "氷[こおり]が水[みず]になる変化[へんか]は可逆[かぎゃく]だが、卵[たまご]を焼[や]く変化[へんか]は可逆[かぎゃく]ではない。", "sentence_source": "generated"}, {"text": "可逆な変化と元に戻らない変化の違いを、実験で確かめた。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "可逆[かぎゃく]な変化[へんか]と元[もと]に戻[もど]らない変化[へんか]の違[ちが]いを、実験[じっけん]で確[たし]かめた。", "sentence_source": "generated"}, {"text": "この化学反応は可逆で、条件を変えれば元の物質に戻る。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "この化学[かがく]反応[はんのう]は可逆[かぎゃく]で、条件[じょうけん]を変[か]えれば元[もと]の物質[ぶっしつ]に戻[もど]る。", "sentence_source": "generated"}, {"text": "ファイルの圧縮方式には、可逆のものと元に戻らないものがある。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "ファイルの圧縮[あっしゅく]方式[ほうしき]には、可逆[かぎゃく]のものと元[もと]に戻[もど]らないものがある。", "sentence_source": "generated"}, {"text": "設定の変更は可逆だから、気軽に試してみるといい。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "設定[せってい]の変更[へんこう]は可逆[かぎゃく]だから、気軽[きがる]に試[ため]してみるといい。", "sentence_source": "generated"}, {"text": "手術は可逆ではないので、医者は患者に十分に説明した。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]は可逆[かぎゃく]ではないので、医者[いしゃ]は患者[かんじゃ]に十分[じゅうぶん]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "可逆かどうかを調べてから、実験の手順を決めた。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "可逆[かぎゃく]かどうかを調[しら]べてから、実験[じっけん]の手順[てじゅん]を決[き]めた。", "sentence_source": "generated"}, {"text": "紙を折る行為は可逆に見えるが、折り目は完全には消えない。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "紙[かみ]を折[お]る行為[こうい]は可逆[かぎゃく]に見[み]えるが、折[お]り目[め]は完全[かんぜん]には消[き]えない。", "sentence_source": "generated"}, {"text": "この変化が可逆であれば、材料を無駄にせずに済む。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "この変化[へんか]が可逆[かぎゃく]であれば、材料[ざいりょう]を無駄[むだ]にせずに済[す]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "可逆", "label": "基本形"}, {"form": "可逆な", "label": "連体形(な)"}, {"form": "可逆の", "label": "連体形(の)"}, {"form": "可逆で", "label": "連用形(で)"}, {"form": "可逆ではない", "label": "否定形"}], "register": "書き言葉(文章語・常体)", "sense_fingerprint": "変化や操作が元の状態に戻せる性質。科学・技術・操作の文脈で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '264dd313-b4bf-4db0-a29c-2a90cdc233fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36380, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可逆", "is_correct": true, "explanation": "「可逆なので」は、元に戻せるという後半の内容と理由でつながる。"}, {"text": "不可逆", "is_correct": false, "explanation": "元に戻せないという意味になり、後半の「すぐに元に戻せる」と矛盾する。"}, {"text": "複雑", "is_correct": false, "explanation": "操作が複雑であることは、元に戻せることの理由にならない。"}, {"text": "大量", "is_correct": false, "explanation": "操作の量を表す語で、元に戻せることの理由として意味が通らない。"}], "explanations": {"可逆": "「可逆なので」は、元に戻せるという後半の内容と理由でつながる。", "不可逆": "元に戻せないという意味になり、後半の「すぐに元に戻せる」と矛盾する。", "複雑": "操作が複雑であることは、元に戻せることの理由にならない。", "大量": "操作の量を表す語で、元に戻せることの理由として意味が通らない。"}, "sentence_index": 0, "correct_answer": "可逆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この計画は可逆で、予算さえあれば今年中に始められる。", "explanation": "ここは〈実現可能〉の意味。可逆は元に戻せる性質を表し、計画が実行できるかどうかは表さないので合わない。"}, {"text": "この部品は長さが可逆で、使う場所に合わせて調節できる。", "explanation": "ここは〈可変〉の意味。可逆は元の状態に戻せることで、長さを自由に変えられることは指さないので合わない。"}, {"text": "議案の可逆は、本会議の決定によるものだ。", "explanation": "「可決」との取り違え。可逆は元に戻せる性質で、議案を正式に承認することは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36380, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可逆", "is_correct": true, "explanation": "「可逆ではないので」は、元に戻せないから医者が丁寧に説明した、という理由になる。"}, {"text": "有名", "is_correct": false, "explanation": "「有名ではないので」では、医者が説明する理由として意味が通らない。"}, {"text": "静か", "is_correct": false, "explanation": "手術の静かさは、説明する理由にならない。"}, {"text": "大量", "is_correct": false, "explanation": "手術の量を表す語で、説明する理由として合わない。"}], "explanations": {"可逆": "「可逆ではないので」は、元に戻せないから医者が丁寧に説明した、という理由になる。", "有名": "「有名ではないので」では、医者が説明する理由として意味が通らない。", "静か": "手術の静かさは、説明する理由にならない。", "大量": "手術の量を表す語で、説明する理由として合わない。"}, "sentence_index": 6, "correct_answer": "可逆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この紙は可逆なので、材料を無駄にしない。", "explanation": "ここは〈再生紙〉の意味。可逆は元に戻せる性質で、使い終わった紙を再び材料にすることは指さないので合わない。"}, {"text": "この腕は可逆で、床に置いたまま動かせない。", "explanation": "ここは〈可動〉（動かせること）の意味。可逆は元に戻せることで、腕を動かせるかどうかは表さないので、動かせないという後半とも合わない。"}, {"text": "川の流れは可逆で、いつも海へ向かっている。", "explanation": "ここは〈逆行〉（逆向きに進むこと）の意味。可逆は元に戻せることで、流れの向きが逆になることは指さないので、いつも海へ向かうという文と矛盾して合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36380, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この作業は可逆ので、失敗しても途中からやり直せる。", "corrected_sentence": "この作業は可逆なので、失敗しても途中からやり直せる。", "error_description": "「可逆」は形容動詞なので、後ろに「な」を付けて「可逆なので」とする必要がある。「可逆ので」は「な」が抜けた誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36380, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬の作用は可逆に言われている。", "corrected_sentence": "この薬の作用は可逆だと言われている。", "error_description": "「可逆」を述語にして「だと言われている」で続ける必要がある。「可逆に」は連用形の副詞的な形で、言われている内容を示せないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36382, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "得る", "is_correct": true, "explanation": "失うの対義語。方向感覚を失う⇔得るで対応する。"}, {"text": "読む", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}, {"text": "走る", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}, {"text": "眠る", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}], "correct_answer": "得る", "explanations": {"得る": "失うの対義語。方向感覚を失う⇔得るで対応する。", "読む": "失うと対義の関係にない動詞。", "走る": "失うと対義の関係にない動詞。", "眠る": "失うと対義の関係にない動詞。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36382, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36382, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "なくすこと。もうもっていないこと。", "primary_collocate": null, "pronunciation": "うしなう", "ipa": "ɯɕinaɯ", "syllable_count": 4, "sentences": [{"text": "彼は事故で意識を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "彼[かれ]は事故[じこ]で意識[いしき]を失[うしな]った。", "sentence_source": "generated"}, {"text": "自信を失わないで、最後まで頑張ってください。", "target_word": "失わ", "complexity_tier": "T3", "furigana": "自信[じしん]を失[うしな]わないで、最後[さいご]まで頑張[がんば]ってください。", "sentence_source": "generated"}, {"text": "長い間使わないと、せっかくの技術を失ってしまう。", "target_word": "失って", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]使[つか]わないと、せっかくの技術[ぎじゅつ]を失[うしな]ってしまう。", "sentence_source": "generated"}, {"text": "大雨で道が見えなくなり、方向感覚を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で道[みち]が見[み]えなくなり、方向感覚[ほうこうかんかく]を失[うしな]った。", "sentence_source": "generated"}, {"text": "失敗が続いて、彼はやる気を失っている。", "target_word": "失って", "complexity_tier": "T3", "furigana": "失敗[しっぱい]が続[つづ]いて、彼[かれ]はやる気[き]を失[うしな]っている。", "sentence_source": "generated"}, {"text": "うそをつくと、友だちの信用を失う。", "target_word": "失う", "complexity_tier": "T3", "furigana": "うそをつくと、友[とも]だちの信用[しんよう]を失[うしな]う。", "sentence_source": "generated"}, {"text": "夜になって、町はすっかり活気を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "夜[よる]になって、町[まち]はすっかり活気[かっき]を失[うしな]った。", "sentence_source": "generated"}, {"text": "暑さで食欲を失い、昼ご飯も食べられなかった。", "target_word": "失い", "complexity_tier": "T3", "furigana": "暑[あつ]さで食欲[しょくよく]を失[うしな]い、昼[ひる]ご飯[はん]も食[た]べられなかった。", "sentence_source": "generated"}, {"text": "声を失った歌手は、舞台に立てなくなった。", "target_word": "失った", "complexity_tier": "T3", "furigana": "声[こえ]を失[うしな]った歌手[かしゅ]は、舞台[ぶたい]に立[た]てなくなった。", "sentence_source": "generated"}, {"text": "試合の途中で集中力を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "試合[しあい]の途中[とちゅう]で集中力[しゅうちゅうりょく]を失[うしな]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "失う", "label": "終止形"}, {"form": "失い", "label": "連用形"}, {"form": "失わない", "label": "否定形"}, {"form": "失って", "label": "テ形"}, {"form": "失った", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "意識・自信・信用・感覚など、形のないものがなくなって、もう持っていない状態になる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36382, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失った", "is_correct": true, "explanation": "「意識を失った」は、意識がなくなる意味で文に合う。"}, {"text": "書いた", "is_correct": false, "explanation": "「意識を書いた」は意味が成り立たず、ここには入らない。"}, {"text": "食べた", "is_correct": false, "explanation": "「意識を食べた」は動詞と目的語が合わず、不自然。"}, {"text": "歌った", "is_correct": false, "explanation": "「意識を歌った」は不自然で、事故で倒れる文脈にも合わない。"}], "explanations": {"失った": "「意識を失った」は、意識がなくなる意味で文に合う。", "書いた": "「意識を書いた」は意味が成り立たず、ここには入らない。", "食べた": "「意識を食べた」は動詞と目的語が合わず、不自然。", "歌った": "「意識を歌った」は不自然で、事故で倒れる文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "失った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の約束を失った。", "explanation": "ここは〈忘れる〉の意味。失うは、もっていたものが手元からなくなる意味で、約束や記憶には使わない。"}, {"text": "英単語を失うために、毎日練習している。", "explanation": "ここは〈覚える〉の意味。失うは何かがなくなる意味で、覚えるための練習とは合わない。"}, {"text": "やっと試験の答えを失った。", "explanation": "ここは〈思い出す〉の意味。失うは答えが消えることで、思い出して取り戻す場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36382, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失った", "is_correct": true, "explanation": "「活気を失った」は、活気がなくなる意味で文に合う。"}, {"text": "買った", "is_correct": false, "explanation": "「活気を買った」は成り立たず、ここには入らない。"}, {"text": "運んだ", "is_correct": false, "explanation": "「活気を運んだ」は目的語と動詞が合わず、不自然。"}, {"text": "焼いた", "is_correct": false, "explanation": "「活気を焼いた」は意味が成り立たない。"}], "explanations": {"失った": "「活気を失った」は、活気がなくなる意味で文に合う。", "買った": "「活気を買った」は成り立たず、ここには入らない。", "運んだ": "「活気を運んだ」は目的語と動詞が合わず、不自然。", "焼いた": "「活気を焼いた」は意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "失った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "難しい本の内容を失った。", "explanation": "ここは〈理解する〉の意味。失うは手元のものがなくなる意味で、内容を理解したことには使わない。"}, {"text": "寝坊して、乗るはずだった電車を失った。", "explanation": "ここは〈逃す〉の意味。失うは手元のものがなくなる意味で、乗り遅れて電車に間に合わなかった場面には使わない。"}, {"text": "夜の静けさを味わい、余韻を失った。", "explanation": "ここは〈消える〉の意味。失うは持っていたものを手放してなくす意味で、余韻が自然に消えていく様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36382, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故のショックで彼は意識に失った。", "corrected_sentence": "事故のショックで彼は意識を失った。", "error_description": "失うの目的語「意識」には「を」を付ける。「に」は誤りで、正しくは「意識を失った」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "失わ", "is_correct": true, "explanation": "未然形。「ない」に続く形なので「失わないで」に合う。"}, {"text": "失い", "is_correct": false, "explanation": "連用形。「ない」には続かないので「失いないで」となり誤り。"}, {"text": "失って", "is_correct": false, "explanation": "テ形。「ないで」の前には置けないので誤り。"}, {"text": "失おう", "is_correct": false, "explanation": "意志形。「失おうないで」は成り立たない。"}], "correct_form": "失わ", "base_form": "失う", "form_label": "未然形", "sentence_index": 1, "explanations": {"失わ": "未然形。「ない」に続く形なので「失わないで」に合う。", "失い": "連用形。「ない」には続かないので「失いないで」となり誤り。", "失って": "テ形。「ないで」の前には置けないので誤り。", "失おう": "意志形。「失おうないで」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36382, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨で方向感覚を失いて、道に迷った。", "corrected_sentence": "大雨で方向感覚を失って、道に迷った。", "error_description": "テ形は「失って」。「失いて」は誤った活用で、正しくは「失って」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "失い", "is_correct": true, "explanation": "連用形。「、」で文を中止する形で、「食欲を失い、」と続く。"}, {"text": "失わ", "is_correct": false, "explanation": "未然形。「、」で続けることはできない。"}, {"text": "失え", "is_correct": false, "explanation": "命令形。「、」で続けると命令の意味になり、この文には合わない。"}, {"text": "失わない", "is_correct": false, "explanation": "否定形。ここは肯定の過去の出来事を中止で続ける文なので合わない。"}], "correct_form": "失い", "base_form": "失う", "form_label": "連用形", "sentence_index": 7, "explanations": {"失い": "連用形。「、」で文を中止する形で、「食欲を失い、」と続く。", "失わ": "未然形。「、」で続けることはできない。", "失え": "命令形。「、」で続けると命令の意味になり、この文には合わない。", "失わない": "否定形。ここは肯定の過去の出来事を中止で続ける文なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36383, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "得る", "is_correct": true, "explanation": "失うの対義語。全財産を失う⇔得るで対応する。"}, {"text": "作る", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}, {"text": "笑う", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}, {"text": "歌う", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}], "correct_answer": "得る", "explanations": {"得る": "失うの対義語。全財産を失う⇔得るで対応する。", "作る": "失うと対義の関係にない動詞。", "笑う": "失うと対義の関係にない動詞。", "歌う": "失うと対義の関係にない動詞。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36383, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "得る", "is_correct": true, "explanation": "失うの対義語。取引先を失う⇔得るで対応する。"}, {"text": "読む", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}, {"text": "走る", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}, {"text": "寝る", "is_correct": false, "explanation": "失うと対義の関係にない動詞。"}], "correct_answer": "得る", "explanations": {"得る": "失うの対義語。取引先を失う⇔得るで対応する。", "読む": "失うと対義の関係にない動詞。", "走る": "失うと対義の関係にない動詞。", "寝る": "失うと対義の関係にない動詞。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36383, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "もっていたものが、なんらかの理由でじぶんのものではなくなること。", "primary_collocate": null, "pronunciation": "うしなう", "ipa": "ɯɕinaɯ", "syllable_count": 4, "sentences": [{"text": "会社が倒産して、父は仕事を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "会社[かいしゃ]が倒産[とうさん]して、父[ちち]は仕事[しごと]を失[うしな]った。", "sentence_source": "generated"}, {"text": "火事で家を失った家族が、学校に避難している。", "target_word": "失った", "complexity_tier": "T3", "furigana": "火事[かじ]で家[いえ]を失[うしな]った家族[かぞく]が、学校[がっこう]に避難[ひなん]している。", "sentence_source": "generated"}, {"text": "戦争で多くの人が家族を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "戦争[せんそう]で多[おお]くの人[ひと]が家族[かぞく]を失[うしな]った。", "sentence_source": "generated"}, {"text": "彼は株で失敗して、全財産を失ってしまった。", "target_word": "失って", "complexity_tier": "T3", "furigana": "彼[かれ]は株[かぶ]で失敗[しっぱい]して、全財産[ぜんざいさん]を失[うしな]ってしまった。", "sentence_source": "generated"}, {"text": "選手はけがで、試合に出る機会を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "選手[せんしゅ]はけがで、試合[しあい]に出[で]る機会[きかい]を失[うしな]った。", "sentence_source": "generated"}, {"text": "洪水で畑を失った農家が、国に助けを求めた。", "target_word": "失った", "complexity_tier": "T3", "furigana": "洪水[こうずい]で畑[はたけ]を失[うしな]った農家[のうか]が、国[くに]に助[たす]けを求[もと]めた。", "sentence_source": "generated"}, {"text": "彼女は事故で夫を失い、一人で子どもを育てた。", "target_word": "失い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は事故[じこ]で夫[おっと]を失[うしな]い、一人[ひとり]で子[こ]どもを育[そだ]てた。", "sentence_source": "generated"}, {"text": "負けたチームは、優勝する権利を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "負[ま]けたチームは、優勝[ゆうしょう]する権利[けんり]を失[うしな]った。", "sentence_source": "generated"}, {"text": "町は地震で、大切な古い建物を失った。", "target_word": "失った", "complexity_tier": "T3", "furigana": "町[まち]は地震[じしん]で、大切[たいせつ]な古[ふる]い建物[たてもの]を失[うしな]った。", "sentence_source": "generated"}, {"text": "会社は大きな取引先を失い、売り上げが減った。", "target_word": "失い", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は大[おお]きな取引先[とりひきさき]を失[うしな]い、売[う]り上[あ]げが減[へ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "失う", "label": "終止形"}, {"form": "失い", "label": "連用形"}, {"form": "失わない", "label": "否定形"}, {"form": "失って", "label": "テ形"}, {"form": "失った", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "仕事・家・財産・家族など、持っていた大切なものが、事故や災害などの理由で自分のものでなくなる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36383, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失った", "is_correct": true, "explanation": "「仕事を失った」は、仕事がなくなる意味で文に合う。"}, {"text": "読んだ", "is_correct": false, "explanation": "「仕事を読んだ」は意味が成り立たず、ここには入らない。"}, {"text": "食べた", "is_correct": false, "explanation": "「仕事を食べた」は動詞と目的語が合わず、不自然。"}, {"text": "眠った", "is_correct": false, "explanation": "眠るは目的語を取らないので「仕事を眠った」は成り立たない。"}], "explanations": {"失った": "「仕事を失った」は、仕事がなくなる意味で文に合う。", "読んだ": "「仕事を読んだ」は意味が成り立たず、ここには入らない。", "食べた": "「仕事を食べた」は動詞と目的語が合わず、不自然。", "眠った": "眠るは目的語を取らないので「仕事を眠った」は成り立たない。"}, "sentence_index": 0, "correct_answer": "失った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボーナスで新しい車を失った。", "explanation": "ここは〈買う〉の意味。失うは、もっていたものが自分のものでなくなる意味なので、買ったばかりのものには使わない。"}, {"text": "友だちの名前を、ついに失った。", "explanation": "ここは〈忘れる〉の意味。失うは手元のものがなくなる意味で、名前を覚えていない場面には使わない。"}, {"text": "ずっと欲しかった絵画を、ようやく自分のものにする前に失った。", "explanation": "ここは〈手に入れる〉の意味。失うは、もともと持っていたものが消える意味なので、まだ手にしていないものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36383, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失い", "is_correct": true, "explanation": "連用形。「夫を失い、」と中止の形で続き、文に合う。"}, {"text": "眠り", "is_correct": false, "explanation": "眠るは目的語を取らないので「夫を眠り」は成り立たない。"}, {"text": "笑い", "is_correct": false, "explanation": "笑うは目的語を取らないので「夫を笑い」は成り立たない。"}, {"text": "泣き", "is_correct": false, "explanation": "泣くは目的語を取らないので「夫を泣き」は成り立たない。"}], "explanations": {"失い": "連用形。「夫を失い、」と中止の形で続き、文に合う。", "眠り": "眠るは目的語を取らないので「夫を眠り」は成り立たない。", "笑い": "笑うは目的語を取らないので「夫を笑い」は成り立たない。", "泣き": "泣くは目的語を取らないので「夫を泣き」は成り立たない。"}, "sentence_index": 6, "correct_answer": "失い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社は大きな取引先を探して、ついに失った。", "explanation": "ここは〈見つける〉の意味。失うは手元にあったものがなくなる意味で、探し当てたものには使わない。"}, {"text": "会社は新しい社員を雇って、人手を失った。", "explanation": "ここは〈増やす〉の意味。失うは手元のものが減る意味で、人手を増やす場面には使わない。"}, {"text": "新しい機械を注文して、すぐに失った。", "explanation": "ここは〈受け取る〉の意味。失うは持っていたものがなくなる意味で、注文した品が手元に届く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36383, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洪水で家を失いた人々が、体育館に集まっている。", "corrected_sentence": "洪水で家を失った人々が、体育館に集まっている。", "error_description": "「人々」を修飾する過去の連体形は「失った」。「失いた」は誤りで、正しくは「失った」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "失った", "is_correct": true, "explanation": "過去・連体形。「家族」を修飾して「家を失った家族」となり文に合う。"}, {"text": "失い", "is_correct": false, "explanation": "連用形。名詞を修飾できないので「家を失い家族」は誤り。"}, {"text": "失って", "is_correct": false, "explanation": "テ形。名詞「家族」を修飾できないので誤り。"}, {"text": "失おう", "is_correct": false, "explanation": "意志形。名詞を修飾できないので誤り。"}], "correct_form": "失った", "base_form": "失う", "form_label": "過去・連体形", "sentence_index": 1, "explanations": {"失った": "過去・連体形。「家族」を修飾して「家を失った家族」となり文に合う。", "失い": "連用形。名詞を修飾できないので「家を失い家族」は誤り。", "失って": "テ形。名詞「家族」を修飾できないので誤り。", "失おう": "意志形。名詞を修飾できないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36383, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地震で店の看板を失いて、お客さんが減った。", "corrected_sentence": "地震で店の看板を失って、お客さんが減った。", "error_description": "テ形は「失って」。「失いて」は誤った活用で、正しくは「失って」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "失った", "is_correct": true, "explanation": "過去形。「権利を失った」は既に起きた出来事を表し、文に合う。"}, {"text": "失う", "is_correct": false, "explanation": "終止形で非過去。既に起きた出来事を表せないので合わない。"}, {"text": "失わない", "is_correct": false, "explanation": "否定形。「負けた」という事実と矛盾するので合わない。"}, {"text": "失わせた", "is_correct": false, "explanation": "使役形。「失わせた」は他者に失わせる意味になり、文の主語と合わない。"}], "correct_form": "失った", "base_form": "失う", "form_label": "過去形", "sentence_index": 7, "explanations": {"失った": "過去形。「権利を失った」は既に起きた出来事を表し、文に合う。", "失う": "終止形で非過去。既に起きた出来事を表せないので合わない。", "失わない": "否定形。「負けた」という事実と矛盾するので合わない。", "失わせた": "使役形。「失わせた」は他者に失わせる意味になり、文の主語と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36384, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「警察」が主語となり、取り戻す動作の主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「警察」を取り戻す対象にしてしまい、主語の位置に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すので、取り戻す主体を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、主語の位置には入らず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「警察」が主語となり、取り戻す動作の主体を示す。", "を": "「を」は目的語を示すので、「警察」を取り戻す対象にしてしまい、主語の位置に合わない。", "に": "「に」は相手や場所を示すので、取り戻す主体を表せない。", "へ": "「へ」は方向を示すので、主語の位置には入らず文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36384, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「明かり」を目的語として示す。取り戻す対象を表すので正しい。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すので、取り戻す対象を表せない。"}, {"text": "の", "is_correct": false, "explanation": "所有や修飾を示すだけで、目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すので、取り戻す対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「明かり」を目的語として示す。取り戻す対象を表すので正しい。", "と": "並列や相手を示すので、取り戻す対象を表せない。", "の": "所有や修飾を示すだけで、目的語にはならない。", "より": "比較を示すので、取り戻す対象を表せない。"}, "error_tags": {"と": "並列・相手", "の": "所有・修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36384, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "なくしたものを、もういちど じぶんのものに すること。", "primary_collocate": null, "pronunciation": "とりもどす", "ipa": "toɾimodosɯ", "syllable_count": 5, "sentences": [{"text": "失くした自信を取り戻すために、毎日少しずつ練習しました。", "target_word": "取り戻す", "complexity_tier": "T3", "furigana": "失[な]くした自信[じしん]を取[と]り戻[もど]すために、毎日[まいにち]少[すこ]しずつ練習[れんしゅう]しました。", "sentence_source": "generated"}, {"text": "泥棒に盗まれたかばんを、警察が取り戻してくれた。", "target_word": "取り戻して", "complexity_tier": "T3", "furigana": "泥棒[どろぼう]に盗[ぬす]まれたかばんを、警察[けいさつ]が取[と]り戻[もど]してくれた。", "sentence_source": "generated"}, {"text": "病気が治って、やっと元気を取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "病気[びょうき]が治[なお]って、やっと元気[げんき]を取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "遅れた分を取り戻そうと、彼は夜遅くまで勉強した。", "target_word": "取り戻そう", "complexity_tier": "T3", "furigana": "遅[おく]れた分[ぶん]を取[と]り戻[もど]そうと、彼[かれ]は夜遅[よるおそ]くまで勉強[べんきょう]した。", "sentence_source": "generated"}, {"text": "前半に負けていたチームは、後半に落ち着きを取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "前半[ぜんはん]に負[ま]けていたチームは、後半[こうはん]に落[お]ち着[つ]きを取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "友達に貸したままの本を取り戻したいが、連絡がつかない。", "target_word": "取り戻したい", "complexity_tier": "T3", "furigana": "友達[ともだち]に貸[か]したままの本[ほん]を取[と]り戻[もど]したいが、連絡[れんらく]がつかない。", "sentence_source": "generated"}, {"text": "彼女は笑顔を取り戻し、また学校に通い始めた。", "target_word": "取り戻し", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は笑顔[えがお]を取[と]り戻[もど]し、また学校[がっこう]に通[かよ]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "昨日、停電が終わり、町は夜の明かりを取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "昨日[きのう]、停電[ていでん]が終[お]わり、町[まち]は夜[よる]の明[あか]りを取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "失った信頼を取り戻すのは、簡単ではありません。", "target_word": "取り戻す", "complexity_tier": "T3", "furigana": "失[うしな]った信頼[しんらい]を取[と]り戻[もど]すのは、簡単[かんたん]ではありません。", "sentence_source": "generated"}, {"text": "旅行から帰って、普段の生活のリズムを取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "旅行[りょこう]から帰[かえ]って、普段[ふだん]の生活[せいかつ]のリズムを取[と]り戻[もど]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り戻す", "label": "終止形"}, {"form": "取り戻した", "label": "過去形"}, {"form": "取り戻して", "label": "て形"}, {"form": "取り戻さない", "label": "否定形"}, {"form": "取り戻そう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "なくした物・気持ち・時間などをもう一度自分のものにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36384, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り戻す", "is_correct": true, "explanation": "「ために」の前は辞書形。「失くした自信を取り戻すために」で目的を表し、文の意味が通る。"}, {"text": "取り戻した", "is_correct": false, "explanation": "過去形は「ために」に続けられない。目的を表すには辞書形が必要。"}, {"text": "取り戻して", "is_correct": false, "explanation": "て形では「ために」に続かず、目的を表す文型が成り立たない。"}, {"text": "取り戻せ", "is_correct": false, "explanation": "命令形は文末でしか使えず、「ために」の前には置けない。"}], "explanations": {"取り戻す": "「ために」の前は辞書形。「失くした自信を取り戻すために」で目的を表し、文の意味が通る。", "取り戻した": "過去形は「ために」に続けられない。目的を表すには辞書形が必要。", "取り戻して": "て形では「ために」に続かず、目的を表す文型が成り立たない。", "取り戻せ": "命令形は文末でしか使えず、「ために」の前には置けない。"}, "sentence_index": 0, "correct_answer": "取り戻す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大型台風で、町は一晩で大きな被害を取り戻した。", "explanation": "ここは〈受ける〉の意味。取り戻すは一度持っていた物を再び得る意味なので、新たに受けた被害には合わない。"}, {"text": "宝くじで初めて大金を取り戻した。", "explanation": "ここは〈手に入れる〉の意味。取り戻すは一度持っていた物を再び得ることなので、初めて得る大金には合わない。"}, {"text": "ケーキから卵の殻を取り戻した。", "explanation": "ここは〈取り除く〉の意味。取り戻すは自分が失った物を再び得る意味なので、いらない物を除く場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36384, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り戻し", "is_correct": true, "explanation": "連用形。「、」で文を続け、「また学校に通い始めた」とつなぐ。"}, {"text": "取り戻そう", "is_correct": false, "explanation": "意向形。「〜しよう」の意味になり、過去の出来事を述べる文と合わない。"}, {"text": "取り戻せる", "is_correct": false, "explanation": "可能形。「取り戻せる」の意味になり、笑顔を取り戻した事実とつながらない。"}, {"text": "取り戻させる", "is_correct": false, "explanation": "使役形。誰かに取り戻させる意味になり、文の主語の動作と合わない。"}], "explanations": {"取り戻し": "連用形。「、」で文を続け、「また学校に通い始めた」とつなぐ。", "取り戻そう": "意向形。「〜しよう」の意味になり、過去の出来事を述べる文と合わない。", "取り戻せる": "可能形。「取り戻せる」の意味になり、笑顔を取り戻した事実とつながらない。", "取り戻させる": "使役形。誰かに取り戻させる意味になり、文の主語の動作と合わない。"}, "sentence_index": 6, "correct_answer": "取り戻し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "留学して、新しい言葉を取り戻した。", "explanation": "ここは〈身につける〉の意味。取り戻すは以前持っていた物を再び得る意味なので、初めて覚える言葉には合わない。"}, {"text": "彼の一言が、大きな誤解を取り戻した。", "explanation": "ここは〈招く〉の意味。取り戻すは自分のものを再び持つ意味で、誤解は自分の持ち物ではないので使えない。"}, {"text": "仲間と話し合い、新しい流行を取り戻した。", "explanation": "ここは〈生み出す〉の意味。取り戻すは以前あった物を再び得る意味なので、新しく生まれる流行には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36384, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "財布を盗まれたが、友人が財布を取り戻しくれた。", "corrected_sentence": "財布を盗まれたが、友人が財布を取り戻してくれた。", "error_description": "「取り戻して」の「て」が抜けている。「〜てくれた」に続くので、て形の「取り戻して」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り戻して", "is_correct": true, "explanation": "て形。「〜てくれた」につながる形で、動作を続けて述べる。"}, {"text": "取り戻さない", "is_correct": false, "explanation": "否定形。「〜てくれた」とはつながらず、文の意味が通らない。"}, {"text": "取り戻したい", "is_correct": false, "explanation": "願望形。話し手の希望を表すので、「〜てくれた」の前には置けない。"}, {"text": "取り戻し", "is_correct": false, "explanation": "連用形。「くれた」に直接つながらず、文として成り立たない。"}], "correct_form": "取り戻して", "base_form": "取り戻す", "form_label": "て形", "sentence_index": 1, "explanations": {"取り戻して": "て形。「〜てくれた」につながる形で、動作を続けて述べる。", "取り戻さない": "否定形。「〜てくれた」とはつながらず、文の意味が通らない。", "取り戻したい": "願望形。話し手の希望を表すので、「〜てくれた」の前には置けない。", "取り戻し": "連用形。「くれた」に直接つながらず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36384, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は落とした鍵に取り戻して、家に入った。", "corrected_sentence": "兄は落とした鍵を取り戻して、家に入った。", "error_description": "「取り戻す」の対象は「を」で示す。「鍵に」の「に」は誤りで、「鍵を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り戻した", "is_correct": true, "explanation": "過去形。「町は…取り戻した」と、完了した事実を述べる。"}, {"text": "取り戻す", "is_correct": false, "explanation": "終止形。現在の意味になり、完了した出来事を述べる文と合わない。"}, {"text": "取り戻せ", "is_correct": false, "explanation": "命令形。文末で命令になり、事実を述べる文には合わない。"}, {"text": "取り戻そう", "is_correct": false, "explanation": "意向形。「〜しよう」の意味になり、事実を述べる文と合わない。"}], "correct_form": "取り戻した", "base_form": "取り戻す", "form_label": "過去形", "sentence_index": 7, "explanations": {"取り戻した": "過去形。「町は…取り戻した」と、完了した事実を述べる。", "取り戻す": "終止形。現在の意味になり、完了した出来事を述べる文と合わない。", "取り戻せ": "命令形。文末で命令になり、事実を述べる文には合わない。", "取り戻そう": "意向形。「〜しよう」の意味になり、事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36385, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「信頼」を目的語として示す。取り戻す対象を表すので正しい。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すので、取り戻す対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すので、ここでは目的語を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、取り戻す対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "「信頼」を目的語として示す。取り戻す対象を表すので正しい。", "に": "相手や場所を示すので、取り戻す対象を表せない。", "で": "場所や手段を示すので、ここでは目的語を表せない。", "へ": "方向を示すので、取り戻す対象には使えない。"}, "error_tags": {"に": "相手・場所", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36385, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「にぎわい」を目的語として示す。取り戻す対象を表すので正しい。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すので、取り戻す対象を表せない。"}, {"text": "の", "is_correct": false, "explanation": "所有や修飾を示すだけで、目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すので、取り戻す対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「にぎわい」を目的語として示す。取り戻す対象を表すので正しい。", "と": "並列や相手を示すので、取り戻す対象を表せない。", "の": "所有や修飾を示すだけで、目的語にはならない。", "より": "比較を示すので、取り戻す対象を表せない。"}, "error_tags": {"と": "並列・相手", "の": "所有・修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36385, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "失ったものや、以前の状態を再び自分のものにすること。取り返す。", "primary_collocate": null, "pronunciation": "とりもどす", "ipa": "toɾimodosɯ", "syllable_count": 5, "sentences": [{"text": "彼は事故のあと、少しずつ体力を取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "彼[かれ]は事故[じこ]のあと、少[すこ]しずつ体力[たいりょく]を取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "会社は新商品で、失った市場の信頼を取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新商品[しんしょうひん]で、失[うしな]った市場[しじょう]の信頼[しんらい]を取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "選手は一点差まで追いつき、試合の流れを取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "選手[せんしゅ]は一点差[いってんさ]まで追[お]いつき、試合[しあい]の流[なが]れを取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "長い雨のあと、公園は明るさを取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "長[なが]い雨[あめ]のあと、公園[こうえん]は明[あか]るさを取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "母は手術から回復し、食欲を取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "母[はは]は手術[しゅじゅつ]から回復[かいふく]し、食欲[しょくよく]を取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "店主は、奪われた財布を犯人から取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "店主[てんしゅ]は、奪[うば]われた財布[さいふ]を犯人[はんにん]から取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "彼女は冷静さを取り戻して、もう一度話し始めた。", "target_word": "取り戻して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は冷静[れいせい]さを取[と]り戻[もど]して、もう一度[いちど]話[はな]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "昨年の祭りで、村は昔のにぎわいを取り戻した。", "target_word": "取り戻した", "complexity_tier": "T3", "furigana": "昨年[さくねん]の祭[まつ]りで、村[むら]は昔[むかし]のにぎわいを取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "睡眠不足の分を取り戻すため、週末はゆっくり寝た。", "target_word": "取り戻す", "complexity_tier": "T3", "furigana": "睡眠不足[すいみんぶそく]の分[ぶん]を取[と]り戻[もど]すため、週末[しゅうまつ]はゆっくり寝[ね]た。", "sentence_source": "generated"}, {"text": "政府は景気を取り戻すために、新しい政策を発表した。", "target_word": "取り戻す", "complexity_tier": "T3", "furigana": "政府[せいふ]は景気[けいき]を取[と]り戻[もど]すために、新[あたら]しい政策[せいさく]を発表[はっぴょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り戻す", "label": "終止形"}, {"form": "取り戻した", "label": "過去形"}, {"form": "取り戻して", "label": "て形"}, {"form": "取り戻さない", "label": "否定形"}, {"form": "取り戻そう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "失った物や以前の状態を再び自分のものにする、取り返す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36385, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り戻した", "is_correct": true, "explanation": "過去形。事故のあとに回復した事実を述べる文に合う。"}, {"text": "取り戻し", "is_correct": false, "explanation": "連用形。文を言い切れず、文末として成り立たない。"}, {"text": "取り戻そう", "is_correct": false, "explanation": "意向形。「〜しよう」の意味になり、回復を述べる事実と合わない。"}, {"text": "取り戻せ", "is_correct": false, "explanation": "命令形。文末で命令になり、回復を述べる文には合わない。"}], "explanations": {"取り戻した": "過去形。事故のあとに回復した事実を述べる文に合う。", "取り戻し": "連用形。文を言い切れず、文末として成り立たない。", "取り戻そう": "意向形。「〜しよう」の意味になり、回復を述べる事実と合わない。", "取り戻せ": "命令形。文末で命令になり、回復を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "取り戻した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨で濡れた服を、ドライヤーで取り戻した。", "explanation": "ここは〈乾かす〉の意味。取り戻すは一度持っていた物を再び得る意味なので、濡れた服を乾かす場面には合わない。"}, {"text": "古いタイヤを新品に取り戻した。", "explanation": "ここは〈取り換える〉の意味。取り戻すは自分の物を再び自分のものにする意味なので、古い物を新品に替える場面には合わない。"}, {"text": "ガラスのコップを、新しく注文して取り戻した。", "explanation": "ここは〈注文する〉の意味。取り戻すは一度持っていた物を再び得る意味なので、新しく頼む物には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36385, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り戻して", "is_correct": true, "explanation": "て形。「〜て、もう一度話し始めた」と動作をつなぐ。"}, {"text": "取り戻したい", "is_correct": false, "explanation": "願望形。希望の意味になり、話し始めた事実と合わない。"}, {"text": "取り戻さない", "is_correct": false, "explanation": "否定形。「取り戻さない、もう一度」と続かず、文の意味が通らない。"}, {"text": "取り戻せる", "is_correct": false, "explanation": "可能形。「取り戻せる」の意味になり、話し始めた事実とつながらない。"}], "explanations": {"取り戻して": "て形。「〜て、もう一度話し始めた」と動作をつなぐ。", "取り戻したい": "願望形。希望の意味になり、話し始めた事実と合わない。", "取り戻さない": "否定形。「取り戻さない、もう一度」と続かず、文の意味が通らない。", "取り戻せる": "可能形。「取り戻せる」の意味になり、話し始めた事実とつながらない。"}, "sentence_index": 6, "correct_answer": "取り戻して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先輩は新人の失敗を取り戻した。", "explanation": "ここは〈起こす〉の意味。取り戻すは一度持っていた物を再び得る意味なので、起こしてしまった失敗には合わない。"}, {"text": "村人は新しい橋を取り戻した。", "explanation": "ここは〈建てる〉の意味。取り戻すは以前あった物を再び得る意味なので、初めて造る橋には合わない。"}, {"text": "彼女は雨で濡れた髪を、タオルで取り戻した。", "explanation": "ここは〈拭く〉の意味。取り戻すは一度持っていた物を再び得る意味なので、濡れた髪を拭く場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36385, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "チームは相手に奪われた主導権を取り戻しした。", "corrected_sentence": "チームは相手に奪われた主導権を取り戻した。", "error_description": "「取り戻しした」の「し」が余分。過去形は「取り戻した」で、「取り戻し」に「した」は続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り戻した", "is_correct": true, "explanation": "過去形。市場の信頼を回復した完了の事実を述べる。"}, {"text": "取り戻して", "is_correct": false, "explanation": "て形。文を言い切れず、文末として成り立たない。"}, {"text": "取り戻そう", "is_correct": false, "explanation": "意向形。「〜しよう」の意味になり、事実を述べる文と合わない。"}, {"text": "取り戻し", "is_correct": false, "explanation": "連用形。文を言い切れず、文末として成り立たない。"}], "correct_form": "取り戻した", "base_form": "取り戻す", "form_label": "過去形", "sentence_index": 1, "explanations": {"取り戻した": "過去形。市場の信頼を回復した完了の事実を述べる。", "取り戻して": "て形。文を言い切れず、文末として成り立たない。", "取り戻そう": "意向形。「〜しよう」の意味になり、事実を述べる文と合わない。", "取り戻し": "連用形。文を言い切れず、文末として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36385, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "選手は負傷から立ち直り、自信に取り戻した。", "corrected_sentence": "選手は負傷から立ち直り、自信を取り戻した。", "error_description": "「取り戻す」の対象は「を」で示す。「自信に」の「に」は誤りで、「自信を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り戻した", "is_correct": true, "explanation": "過去形。昔のにぎわいを回復した完了の事実を述べる。"}, {"text": "取り戻す", "is_correct": false, "explanation": "終止形。現在の意味になり、完了した出来事を述べる文と合わない。"}, {"text": "取り戻せ", "is_correct": false, "explanation": "命令形。文末で命令になり、事実を述べる文には合わない。"}, {"text": "取り戻そう", "is_correct": false, "explanation": "意向形。「〜しよう」の意味になり、事実を述べる文と合わない。"}], "correct_form": "取り戻した", "base_form": "取り戻す", "form_label": "過去形", "sentence_index": 7, "explanations": {"取り戻した": "過去形。昔のにぎわいを回復した完了の事実を述べる。", "取り戻す": "終止形。現在の意味になり、完了した出来事を述べる文と合わない。", "取り戻せ": "命令形。文末で命令になり、事実を述べる文には合わない。", "取り戻そう": "意向形。「〜しよう」の意味になり、事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36386, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「行動を始める」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「行動に始める」は成り立たず、ここには入らない。"}, {"text": "と", "is_correct": false, "explanation": "「行動と始める」は助詞が合わず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「行動の始めた」とつながらず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「行動を始める」の目的語を示す。", "に": "「行動に始める」は成り立たず、ここには入らない。", "と": "「行動と始める」は助詞が合わず、不自然。", "の": "「行動の始めた」とつながらず、不自然。"}, "error_tags": {"に": "位置・方向", "と": "並列・引用", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
