INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36386, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体を動かして何かをすること。", "primary_collocate": null, "pronunciation": "こうどう", "ipa": "koːdoː", "syllable_count": 4, "sentences": [{"text": "山の中では、暗くなる前に行動を終えたほうがいい。", "target_word": "行動", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]では、暗[くら]くなる前[まえ]に行動[こうどう]を終[お]えたほうがいい。", "sentence_source": "generated"}, {"text": "朝早くから行動を始めたので、昼には頂上に着いた。", "target_word": "行動", "complexity_tier": "T3", "furigana": "朝早[あさはや]くから行動[こうどう]を始[はじ]めたので、昼[ひる]には頂上[ちょうじょう]に着[つ]いた。", "sentence_source": "generated"}, {"text": "足をけがしてしまい、自由に行動できない。", "target_word": "行動", "complexity_tier": "T3", "furigana": "足[あし]をけがしてしまい、自由[じゆう]に行動[こうどう]できない。", "sentence_source": "generated"}, {"text": "二人一組で行動すれば、道に迷っても安心だ。", "target_word": "行動", "complexity_tier": "T3", "furigana": "二人一組[ふたりひとくみ]で行動[こうどう]すれば、道[みち]に迷[まよ]っても安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "夜は危ないので、一人で行動してはいけない。", "target_word": "行動", "complexity_tier": "T3", "furigana": "夜[よる]は危[あぶ]ないので、一人[ひとり]で行動[こうどう]してはいけない。", "sentence_source": "generated"}, {"text": "子どもは元気で、一日中活発に行動している。", "target_word": "行動", "complexity_tier": "T3", "furigana": "子[こ]どもは元気[げんき]で、一日中[いちにちじゅう]活発[かっぱつ]に行動[こうどう]している。", "sentence_source": "generated"}, {"text": "観光客は、ガイドの指示に従って行動した。", "target_word": "行動", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]は、ガイド[がいど]の指示[しじ]に従[したが]って行動[こうどう]した。", "sentence_source": "generated"}, {"text": "地震の後は、あわてずに落ち着いて行動してください。", "target_word": "行動", "complexity_tier": "T3", "furigana": "地震[じしん]の後[あと]は、あわてずに落[お]ち着[つ]いて行動[こうどう]してください。", "sentence_source": "generated"}, {"text": "雪が深くて、思うように行動できなかった。", "target_word": "行動", "complexity_tier": "T3", "furigana": "雪[ゆき]が深[ふか]くて、思[おも]うように行動[こうどう]できなかった。", "sentence_source": "generated"}, {"text": "動物は夜になると行動を始めるものが多い。", "target_word": "行動", "complexity_tier": "T3", "furigana": "動物[どうぶつ]は夜[よる]になると行動[こうどう]を始[はじ]めるものが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行動", "label": "基本形"}, {"form": "行動する", "label": "終止形"}, {"form": "行動した", "label": "過去形"}, {"form": "行動しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "体を動かして移動したり活動したりすること。動き回る・活動する意味。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: けがし (Zipf 2.18)']::text[], '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36386, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行動", "is_correct": true, "explanation": "「行動を終えた」は、体を動かす活動を終える意味で文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を終えた」は不自然で、体を動かす活動を指せない。"}, {"text": "空気", "is_correct": false, "explanation": "「空気を終えた」は意味が成り立たず、ここには入らない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温を終えた」は動詞と合わず、文脈にも合わない。"}], "explanations": {"行動": "「行動を終えた」は、体を動かす活動を終える意味で文に合う。", "天気": "「天気を終えた」は不自然で、体を動かす活動を指せない。", "空気": "「空気を終えた」は意味が成り立たず、ここには入らない。", "体温": "「体温を終えた」は動詞と合わず、文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "行動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は車を行動して、高速道路に入った。", "explanation": "ここは〈運転〉の意味。行動は体を動かして何かをすることを指し、車を操作する場面には使わない。"}, {"text": "店の前には、開店前から長い行動ができていた。", "explanation": "ここは〈行列〉の意味。行動は人が動くことを指し、順番に並んだ人の列を表す場面には使わない。"}, {"text": "夜はぐっすり行動した。", "explanation": "ここは〈眠る〉の意味。行動は動き回ることなので、眠る状態とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36386, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行動", "is_correct": true, "explanation": "「ガイドの指示に従って行動した」は、指示に応じて動く意味で文に合う。"}, {"text": "湿度", "is_correct": false, "explanation": "「指示に従って湿度した」は成り立たず、ここには入らない。"}, {"text": "眠気", "is_correct": false, "explanation": "「指示に従って眠気した」は動詞と合わず、不自然。"}, {"text": "残高", "is_correct": false, "explanation": "「指示に従って残高した」は意味が成り立たない。"}], "explanations": {"行動": "「ガイドの指示に従って行動した」は、指示に応じて動く意味で文に合う。", "湿度": "「指示に従って湿度した」は成り立たず、ここには入らない。", "眠気": "「指示に従って眠気した」は動詞と合わず、不自然。", "残高": "「指示に従って残高した」は意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "行動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ご飯を炊いて、おかずを行動した。", "explanation": "ここは〈作る〉の意味。行動は体を動かして活動することで、料理を作る意味では使わない。"}, {"text": "来週は学校で文化祭の行動がある。", "explanation": "ここは〈行事〉の意味。行動は人が体を動かして何かをすることで、学校の催しを指す場面では使わない。"}, {"text": "テーブルを拭いて、床を行動した。", "explanation": "ここは〈掃除する〉の意味。行動は活動を指すので、掃除する場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36386, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪が降る前に行動に始めたので、無事に町へ着いた。", "corrected_sentence": "雪が降る前に行動を始めたので、無事に町へ着いた。", "error_description": "「始める」の目的語は「を」で示す。「に」は誤りで、正しくは「行動を始めた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36386, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪道では、あわてずに落ち着いて行動しってください。", "corrected_sentence": "雪道では、あわてずに落ち着いて行動してください。", "error_description": "「行動してください」の「して」が正しい。「しって」は誤った活用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36387, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「行動が大切だ」の主語を示し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「行動を大切だ」は助詞が合わず、「大切だ」は「が」を取る。"}, {"text": "に", "is_correct": false, "explanation": "「行動に大切だ」は成り立たず、ここには入らない。"}, {"text": "で", "is_correct": false, "explanation": "「行動で大切だ」は手段の意味になり、文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「行動が大切だ」の主語を示し、文に合う。", "を": "「行動を大切だ」は助詞が合わず、「大切だ」は「が」を取る。", "に": "「行動に大切だ」は成り立たず、ここには入らない。", "で": "「行動で大切だ」は手段の意味になり、文に合わない。"}, "error_tags": {"を": "目的語", "に": "位置・方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36387, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「行動に移す」で、実行へ移る方向を示し文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「行動が移す」は主語と動詞が合わず誤り。"}, {"text": "と", "is_correct": false, "explanation": "「行動と移す」は並列の助詞として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「行動の移す」とつながらず、不自然。"}], "correct_answer": "に", "explanations": {"に": "「行動に移す」で、実行へ移る方向を示し文に合う。", "が": "「行動が移す」は主語と動詞が合わず誤り。", "と": "「行動と移す」は並列の助詞として成り立たない。", "の": "「行動の移す」とつながらず、不自然。"}, "error_tags": {"が": "主語", "と": "並列・引用", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36387, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "考えや気持ちに基づいて体を動かして何かをすること。", "primary_collocate": null, "pronunciation": "こうどう", "ipa": "koːdoː", "syllable_count": 4, "sentences": [{"text": "彼は自分の考えに従って、責任ある行動をとった。", "target_word": "行動", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の考[かんが]えに従[したが]って、責任[せきにん]ある行動[こうどう]をとった。", "sentence_source": "generated"}, {"text": "気持ちを伝えるには、言葉より行動が大切だ。", "target_word": "行動", "complexity_tier": "T3", "furigana": "気持[きも]ちを伝[つた]えるには、言葉[ことば]より行動[こうどう]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "怒りにまかせた行動を、あとで後悔した。", "target_word": "行動", "complexity_tier": "T3", "furigana": "怒[いか]りにまかせた行動[こうどう]を、あとで後悔[こうかい]した。", "sentence_source": "generated"}, {"text": "先生は、生徒の行動をいつも温かく見守っている。", "target_word": "行動", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の行動[こうどう]をいつも温[あたた]かく見守[みまも]っている。", "sentence_source": "generated"}, {"text": "思いやりのある行動が、周りの人を笑顔にした。", "target_word": "行動", "complexity_tier": "T3", "furigana": "思[おも]いやりのある行動[こうどう]が、周[まわ]りの人[ひと]を笑顔[えがお]にした。", "sentence_source": "generated"}, {"text": "よく考えてから行動しないと、失敗するかもしれない。", "target_word": "行動", "complexity_tier": "T3", "furigana": "よく考[かんが]えてから行動[こうどう]しないと、失敗[しっぱい]するかもしれない。", "sentence_source": "generated"}, {"text": "彼女の行動には、いつも強い信念が感じられる。", "target_word": "行動", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の行動[こうどう]には、いつも強[つよ]い信念[しんねん]が感[かん]じられる。", "sentence_source": "generated"}, {"text": "目標を決めたら、すぐに行動に移すことが大切だ。", "target_word": "行動", "complexity_tier": "T3", "furigana": "目標[もくひょう]を決[き]めたら、すぐに行動[こうどう]に移[うつ]すことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼は友達を助けたい一心で、危険な行動に出た。", "target_word": "行動", "complexity_tier": "T3", "furigana": "彼[かれ]は友達[ともだち]を助[たす]けたい一心[いっしん]で、危険[きけん]な行動[こうどう]に出[で]た。", "sentence_source": "generated"}, {"text": "約束を守るのは、信頼される人の行動だ。", "target_word": "行動", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]るのは、信頼[しんらい]される人[ひと]の行動[こうどう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行動", "label": "基本形"}, {"form": "行動する", "label": "終止形"}, {"form": "行動した", "label": "過去形"}, {"form": "行動しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "考え・気持ち・信念に基づいてとる振る舞いや実際の行い。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7452f0ad-e6c5-4fca-833f-b9ebe183e766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36387, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行動", "is_correct": true, "explanation": "「責任ある行動をとった」は、考えに基づく振る舞いを表し文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "「責任ある雨をとった」は意味が成り立たず、ここには入らない。"}, {"text": "霧", "is_correct": false, "explanation": "「責任ある霧をとった」は不自然で、文脈にも合わない。"}, {"text": "海", "is_correct": false, "explanation": "「責任ある海をとった」は意味が成り立たない。"}], "explanations": {"行動": "「責任ある行動をとった」は、考えに基づく振る舞いを表し文に合う。", "雨": "「責任ある雨をとった」は意味が成り立たず、ここには入らない。", "霧": "「責任ある霧をとった」は不自然で、文脈にも合わない。", "海": "「責任ある海をとった」は意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "行動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日、規則正しい行動を送っている。", "explanation": "ここは〈生活〉の意味。行動は振る舞いや実際に動くことを指し、暮らしそのものを送る場面には使わない。"}, {"text": "警察は犯人の行動を捜している。", "explanation": "ここは〈行方〉の意味。行動は振る舞いを指し、居場所を捜す場面には使わない。"}, {"text": "彼女の行動は、少し曇っていた。", "explanation": "ここは〈表情〉の意味。行動は振る舞いを指し、顔に表れる気持ちの様子は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36387, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行動", "is_correct": true, "explanation": "「彼女の行動には、いつも強い信念が感じられる」は、振る舞いを表し文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「彼女の天気には」は成り立たず、ここには入らない。"}, {"text": "体温", "is_correct": false, "explanation": "「彼女の体温には信念が感じられる」は意味が成り立たない。"}, {"text": "残高", "is_correct": false, "explanation": "「彼女の残高には信念が感じられる」は成り立たず、ここには入らない。"}], "explanations": {"行動": "「彼女の行動には、いつも強い信念が感じられる」は、振る舞いを表し文に合う。", "天気": "「彼女の天気には」は成り立たず、ここには入らない。", "体温": "「彼女の体温には信念が感じられる」は意味が成り立たない。", "残高": "「彼女の残高には信念が感じられる」は成り立たず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "行動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行の計画を行動した。", "explanation": "ここは〈立てる〉の意味。行動は振る舞いや実行を指し、計画を立てる意味にはならない。"}, {"text": "試験の結果を行動した。", "explanation": "ここは〈発表する〉の意味。行動は振る舞いを指し、結果を知らせる意味では使わない。"}, {"text": "本を読んだ感想を行動した。", "explanation": "ここは〈書く〉の意味。行動は振る舞いを指し、感想を文章にする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36387, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "相手の信頼を得るには、説明より行動を大切だ。", "corrected_sentence": "相手の信頼を得るには、説明より行動が大切だ。", "error_description": "「大切だ」は「が」で主語を示す。「を」は誤りで、正しくは「行動が大切だ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36387, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達の一言で、思わず行動いた。", "corrected_sentence": "友達の一言で、思わず行動した。", "error_description": "過去形は「行動した」。「行動いた」は誤った活用で、正しくは「行動した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d172743-96a2-4dee-9fb1-a2bf7b36ebc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
