INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36388, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「かかわる」が取る助詞で、「会社の根幹にかかわる決定」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「かかわる」は目的語をとらないので、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、関係を表す「かかわる」とは合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す助詞で、かかわる対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「かかわる」が取る助詞で、「会社の根幹にかかわる決定」と自然につながる。", "を": "「かかわる」は目的語をとらないので、「を」は合わない。", "へ": "方向を表す助詞で、関係を表す「かかわる」とは合わない。", "で": "手段や場所を表す助詞で、かかわる対象を示せない。"}, "error_tags": {"を": "object", "へ": "direction", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36388, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事のいちばん大事な部分", "primary_collocate": null, "pronunciation": "こんかん", "ipa": "koŋkaɴ", "syllable_count": 4, "sentences": [{"text": "計画の根幹が変わると、全体を作り直す必要がある。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "計画[けいかく]の根幹[こんかん]が変[か]わると、全体[ぜんたい]を作[つく]り直[なお]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "この制度の根幹は、だれでも平等に学べることだ。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "この制度[せいど]の根幹[こんかん]は、だれでも平等[びょうどう]に学[まな]べることだ。", "sentence_source": "generated"}, {"text": "家族にとって、信頼は関係の根幹だ。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "家族[かぞく]にとって、信頼[しんらい]は関係[かんけい]の根幹[こんかん]だ。", "sentence_source": "generated"}, {"text": "問題の根幹を見つけないと、同じ失敗をくり返す。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "問題[もんだい]の根幹[こんかん]を見[み]つけないと、同[おな]じ失敗[しっぱい]をくり返[かえ]す。", "sentence_source": "generated"}, {"text": "細かい部分は直せるが、根幹だけは変えられない。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "細[こま]かい部分[ぶぶん]は直[なお]せるが、根幹[こんかん]だけは変[か]えられない。", "sentence_source": "generated"}, {"text": "水は、農業という産業の根幹を支えている。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "水[みず]は、農業[のうぎょう]という産業[さんぎょう]の根幹[こんかん]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "彼の説明は長かったが、根幹だけなら二行で言えた。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "彼[かれ]の説明[せつめい]は長[なが]かったが、根幹[こんかん]だけなら二行[にぎょう]で言[い]えた。", "sentence_source": "generated"}, {"text": "会社の根幹にかかわる決定なので、社長が自分で決めた。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の根幹[こんかん]にかかわる決定[けってい]なので、社長[しゃちょう]が自分[じぶん]で決[き]めた。", "sentence_source": "generated"}, {"text": "新しい機械を入れても、仕事の根幹は変わらない。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]を入[い]れても、仕事[しごと]の根幹[こんかん]は変[か]わらない。", "sentence_source": "generated"}, {"text": "根幹がしっかりしていれば、小さな変更では揺らがない。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "根幹[こんかん]がしっかりしていれば、小[ちい]さな変更[へんこう]では揺[ゆ]らがない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根幹", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事・計画・仕組みの中で最も大切な部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36388, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根幹", "is_correct": true, "explanation": "計画の中で最も大切な部分が変わるから全体を作り直す必要がある、という文脈に合う。"}, {"text": "季節", "is_correct": false, "explanation": "「計画の季節が変わる」は意味が通らず、計画の大切な部分を表さない。"}, {"text": "靴下", "is_correct": false, "explanation": "「計画の靴下が変わる」は意味が通らず、計画の中心を表さない。"}, {"text": "体温", "is_correct": false, "explanation": "計画には体温がなく、文として成り立たない。"}], "explanations": {"根幹": "計画の中で最も大切な部分が変わるから全体を作り直す必要がある、という文脈に合う。", "季節": "「計画の季節が変わる」は意味が通らず、計画の大切な部分を表さない。", "靴下": "「計画の靴下が変わる」は意味が通らず、計画の中心を表さない。", "体温": "計画には体温がなく、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "根幹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は根幹が強く、何時間作業を続けても疲れない。", "explanation": "ここは〈根気〉の意味。根幹は物事の中心部分を指し、人の粘り強さには使わない。"}, {"text": "ろうそくの根幹が溶けて、火が消えた。", "explanation": "ここは〈根元〉の意味。根幹は物事の大切な部分で、物の下端を指す根元とは違うので合わない。"}, {"text": "机の根幹が折れて、本が散らばった。", "explanation": "ここは〈脚〉の意味。根幹は抽象的な大切な部分で、机の部位には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36388, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根幹", "is_correct": true, "explanation": "説明の中で最も大切な部分だけなら二行で言える、という文脈に合う。"}, {"text": "財布", "is_correct": false, "explanation": "「財布だけなら二行で言えた」は意味が通らない。"}, {"text": "写真", "is_correct": false, "explanation": "説明の内容を指す文脈に、写真は合わない。"}, {"text": "体重", "is_correct": false, "explanation": "説明の長さを言う文脈で、体重は不自然で意味が通らない。"}], "explanations": {"根幹": "説明の中で最も大切な部分だけなら二行で言える、という文脈に合う。", "財布": "「財布だけなら二行で言えた」は意味が通らない。", "写真": "説明の内容を指す文脈に、写真は合わない。", "体重": "説明の長さを言う文脈で、体重は不自然で意味が通らない。"}, "sentence_index": 6, "correct_answer": "根幹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は根幹があり、どんな困難にも負けない。", "explanation": "ここは〈根性〉の意味。根幹は物事の中心部分で、人の気力を表さない。"}, {"text": "ケーキの根幹にイチゴを一つ乗せた。", "explanation": "ここは〈頂点〉の位置。根幹は物事の大切な核で、飾りを置く場所には使わない。"}, {"text": "店の根幹に新しい看板を掛けた。", "explanation": "ここは〈壁面〉の位置。根幹は抽象的な中心部分で、物を掛ける場所には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36388, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は制度の根幹を関わる仕事をしている。", "corrected_sentence": "彼女は制度の根幹に関わる仕事をしている。", "error_description": "「関わる」は助詞「に」を取る。誤り：根幹を（助詞）。正しい形：根幹に。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36388, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "税制の根幹を変わった。", "corrected_sentence": "税制の根幹が変わった。", "error_description": "「変わる」は自動詞で、主語に「が」を取る。誤り：根幹を（助詞）。正しい形：根幹が。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
