INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36389, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「根幹の考え方」と、名詞をつなぐ「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「根幹を考え方」は目的語の形にならず、文の意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「根幹に考え方」は名詞同士をつなげず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「根幹で考え方」は手段の意味になり、名詞をつなげない。"}], "correct_answer": "の", "explanations": {"の": "「根幹の考え方」と、名詞をつなぐ「の」が正しい。", "を": "「根幹を考え方」は目的語の形にならず、文の意味が通らない。", "に": "「根幹に考え方」は名詞同士をつなげず、意味が通らない。", "で": "「根幹で考え方」は手段の意味になり、名詞をつなげない。"}, "error_tags": {"を": "object", "に": "target", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36389, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の基礎となる、中心的な部分や考え方", "primary_collocate": null, "pronunciation": "こんかん", "ipa": "koŋkaɴ", "syllable_count": 4, "sentences": [{"text": "この学校の教育の根幹には、「自分で考える力」を育てる考えがある。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "この学校[がっこう]の教育[きょういく]の根幹[こんかん]には、「自分[じぶん]で考[かんが]える力[ちから]」を育[そだ]てる考[かんが]えがある。", "sentence_source": "generated"}, {"text": "民主主義の根幹は、一人ひとりの意見を大切にすることだ。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "民主主義[みんしゅしゅぎ]の根幹[こんかん]は、一人[ひとり]ひとりの意見[いけん]を大切[たいせつ]にすることだ。", "sentence_source": "generated"}, {"text": "憲法は国の根幹をなす法律だ。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "憲法[けんぽう]は国[くに]の根幹[こんかん]をなす法律[ほうりつ]だ。", "sentence_source": "generated"}, {"text": "二つの会社は、仕事の進め方の根幹にある考え方が違う。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]は、仕事[しごと]の進[すす]め方[かた]の根幹[こんかん]にある考[かんが]え方[かた]が違[ちが]う。", "sentence_source": "generated"}, {"text": "研究の根幹となる理論を、まず理解しておこう。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の根幹[こんかん]となる理論[りろん]を、まず理解[りかい]しておこう。", "sentence_source": "generated"}, {"text": "彼の人生の根幹には、いつも母の言葉があった。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "彼[かれ]の人生[じんせい]の根幹[こんかん]には、いつも母[はは]の言葉[ことば]があった。", "sentence_source": "generated"}, {"text": "約束を守ることは、商売の根幹だと祖父は教えた。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]ることは、商売[しょうばい]の根幹[こんかん]だと祖父[そふ]は教[おし]えた。", "sentence_source": "generated"}, {"text": "根幹の考え方がちがうと、いくら話し合っても意見が合わない。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "根幹[こんかん]の考[かんが]え方[かた]がちがうと、いくら話[はな]し合[あ]っても意見[いけん]が合[あ]わない。", "sentence_source": "generated"}, {"text": "その事件は、社会の根幹を揺るがした。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "その事件[じけん]は、社会[しゃかい]の根幹[こんかん]を揺[ゆ]るがした。", "sentence_source": "generated"}, {"text": "基本方針は、この会社の根幹であり、簡単には変えない。", "target_word": "根幹", "complexity_tier": "T3", "furigana": "基本方針[きほんほうしん]は、この会社[かいしゃ]の根幹[こんかん]であり、簡単[かんたん]には変[か]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根幹", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "制度・思想・活動の土台となる中心的な考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36389, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根幹", "is_correct": true, "explanation": "学校の教育の中で、考える力を育てる中心的な考えを指すので文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「教育の天気」は意味が通らず、教育の中心的な考えを表さない。"}, {"text": "靴下", "is_correct": false, "explanation": "「教育の靴下」は意味が通らず、教育の中心的な考えを表さない。"}, {"text": "体重", "is_correct": false, "explanation": "教育に体重を当てはめる文脈はなく、意味が通らない。"}], "explanations": {"根幹": "学校の教育の中で、考える力を育てる中心的な考えを指すので文脈に合う。", "天気": "「教育の天気」は意味が通らず、教育の中心的な考えを表さない。", "靴下": "「教育の靴下」は意味が通らず、教育の中心的な考えを表さない。", "体重": "教育に体重を当てはめる文脈はなく、意味が通らない。"}, "sentence_index": 0, "correct_answer": "根幹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は根幹が強く、毎日の練習を休まない。", "explanation": "ここは〈根性〉の意味。根幹は物事の中心部分で、人の粘り強さを表す語ではないので合わない。"}, {"text": "鍋の根幹にふたをした。", "explanation": "ここは〈口〉の位置。根幹は抽象的な大切な部分で、物にふたをする場所の名前には使わないので合わない。"}, {"text": "この靴の根幹がすり減ってきた。", "explanation": "ここは〈底〉の意味。根幹は抽象的な中心部分で、靴の部位には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36389, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根幹", "is_correct": true, "explanation": "約束を守ることが商売の大切な基礎だ、という文脈に合う。"}, {"text": "寝相", "is_correct": false, "explanation": "「商売の寝相」は意味が通らず、商売の基礎を表さない。"}, {"text": "体重", "is_correct": false, "explanation": "商売に体重を当てはめる文脈はなく、意味が通らない。"}, {"text": "財布", "is_correct": false, "explanation": "「商売の財布」は商売の基礎という意味にならない。"}], "explanations": {"根幹": "約束を守ることが商売の大切な基礎だ、という文脈に合う。", "寝相": "「商売の寝相」は意味が通らず、商売の基礎を表さない。", "体重": "商売に体重を当てはめる文脈はなく、意味が通らない。", "財布": "「商売の財布」は商売の基礎という意味にならない。"}, "sentence_index": 6, "correct_answer": "根幹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一家の根幹が働いている。", "explanation": "ここは〈大黒柱〉の意味。根幹は物事の中心部分で、家計を支える人は指さない。"}, {"text": "ドアの根幹を握って、ゆっくり開けた。", "explanation": "ここは〈取っ手〉の意味。根幹は物事の中心部分で、扉の部品の名前には使わないので合わない。"}, {"text": "自転車の根幹を磨いて、ぴかぴかにした。", "explanation": "ここは〈ハンドル〉の意味。根幹は物事の中心部分で、乗り物の操作部分の名前には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36389, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その提案は教育の根幹で触れている。", "corrected_sentence": "その提案は教育の根幹に触れている。", "error_description": "「触れる」は助詞「に」を取る。誤り：根幹で（助詞）。正しい形：根幹に。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36389, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の根幹考え方を見直す必要がある。", "corrected_sentence": "会社の根幹の考え方を見直す必要がある。", "error_description": "「根幹」と「考え方」の間に、連体修飾を表す「の」が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
