INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36390, 3, 'prompt1_core', '{"pos": "接続詞", "semantic_class": "function", "definition": "二つのことをくらべるときに使う接続詞。", "primary_collocate": null, "pronunciation": "いっぽう", "ipa": "ippoː", "syllable_count": 4, "sentences": [{"text": "兄は運動が得意だ。一方、弟は絵を描くのが得意だ。", "target_word": "一方", "complexity_tier": "T3", "furigana": "兄[あに]は運動[うんどう]が得意[とくい]だ。一方[いっぽう]、弟[おとうと]は絵[え]を描[か]くのが得意[とくい]だ。", "sentence_source": "generated"}, {"text": "昼はとても暑かった。一方、夜はかなり寒かった。", "target_word": "一方", "complexity_tier": "T3", "furigana": "昼[ひる]はとても暑[あつ]かった。一方[いっぽう]、夜[よる]はかなり寒[さむ]かった。", "sentence_source": "generated"}, {"text": "姉は肉が好きだ。一方、妹は魚しか食べない。", "target_word": "一方", "complexity_tier": "T3", "furigana": "姉[あね]は肉[にく]が好[す]きだ。一方[いっぽう]、妹[いもうと]は魚[さかな]しか食[た]べない。", "sentence_source": "generated"}, {"text": "この店は安い。一方、あの店は少し高いが品物がいい。", "target_word": "一方", "complexity_tier": "T3", "furigana": "この店[みせ]は安[やす]い。一方[いっぽう]、あの店[みせ]は少[すこ]し高[たか]いが品物[しなもの]がいい。", "sentence_source": "generated"}, {"text": "東京は人が多い。一方、田舎は静かだ。", "target_word": "一方", "complexity_tier": "T3", "furigana": "東京[とうきょう]は人[ひと]が多[おお]い。一方[いっぽう]、田舎[いなか]は静[しず]かだ。", "sentence_source": "generated"}, {"text": "山田さんはよく話す。一方、田中さんはあまり話さない。", "target_word": "一方", "complexity_tier": "T3", "furigana": "山田[やまだ]さんはよく話[はな]す。一方[いっぽう]、田中[たなか]さんはあまり話[はな]さない。", "sentence_source": "generated"}, {"text": "この地域は夏に雨が多い。一方、冬は雪がほとんど降らない。", "target_word": "一方", "complexity_tier": "T3", "furigana": "この地域[ちいき]は夏[なつ]に雨[あめ]が多[おお]い。一方[いっぽう]、冬[ふゆ]は雪[ゆき]がほとんど降[ふ]らない。", "sentence_source": "generated"}, {"text": "紙の本は手で触れて読める。一方、電子書籍はどこでも持ち歩ける。", "target_word": "一方", "complexity_tier": "T3", "furigana": "紙[かみ]の本[ほん]は手[て]で触[ふ]れて読[よ]める。一方[いっぽう]、電子書籍[でんししょせき]はどこでも持[も]ち歩[ある]ける。", "sentence_source": "generated"}, {"text": "父は朝型の人だ。一方、母は夜遅くまで起きている。", "target_word": "一方", "complexity_tier": "T3", "furigana": "父[ちち]は朝型[あさがた]の人[ひと]だ。一方[いっぽう]、母[はは]は夜遅[よるおそ]くまで起[お]きている。", "sentence_source": "generated"}, {"text": "この国の北は寒い。一方、南は一年中暖かい。", "target_word": "一方", "complexity_tier": "T3", "furigana": "この国[くに]の北[きた]は寒[さむ]い。一方[いっぽう]、南[みなみ]は一年中[いちねんじゅう]暖[あたた]かい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一方", "label": "基本形"}, {"form": "一方で", "label": "助詞付き形"}], "register": "neutral", "sense_fingerprint": "二つの事を対比して述べる接続詞（一方、〜）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: 持ち歩ける (Zipf 2.16)']::text[], '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36390, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一方", "is_correct": true, "explanation": "対比の接続詞。兄の得意分野と弟の得意分野を対照的に並べるので、ここに入る。"}, {"text": "だから", "is_correct": false, "explanation": "原因から結果を導く語。兄が運動が得意でも、そこから弟の絵の得意さは出てこないので合わない。"}, {"text": "例えば", "is_correct": false, "explanation": "具体例を挙げる語。前の文の例を示す流れではないので、弟の話の前には合わない。"}, {"text": "なぜなら", "is_correct": false, "explanation": "理由を後から説明する語。兄の得意さの理由を述べていないので、ここでは意味が通らない。"}], "explanations": {"一方": "対比の接続詞。兄の得意分野と弟の得意分野を対照的に並べるので、ここに入る。", "だから": "原因から結果を導く語。兄が運動が得意でも、そこから弟の絵の得意さは出てこないので合わない。", "例えば": "具体例を挙げる語。前の文の例を示す流れではないので、弟の話の前には合わない。", "なぜなら": "理由を後から説明する語。兄の得意さの理由を述べていないので、ここでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "一方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この道は一方だから、車は逆向きに進めない。", "explanation": "ここは〈一方通行〉の〈一方〉（一方向だけ）の意味。二つを比べる〈一方〉とは別の語義で、道の向きには使わない。"}, {"text": "この映画は一方見たことがある。", "explanation": "ここは〈一度〉の意味。回数を表すのは〈一度〉で、〈一方〉は二つを比べる語なので回数には使えない。"}, {"text": "会議は長く続いた。一方、明日の天気はどうですか。", "explanation": "ここは〈ところで〉の意味。話題を変えるときに〈ところで〉を使い、〈一方〉は比べる二つの事柄があるときだけ使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36390, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一方", "is_correct": true, "explanation": "対比の接続詞。雨の多い夏と雪の少ない冬を対照的に並べるので、ここに入る。"}, {"text": "それとも", "is_correct": false, "explanation": "選択を問いかける語。平叙文の二つ目の文の前には入らず、ここでは意味が通らない。"}, {"text": "さて", "is_correct": false, "explanation": "話題を新しく切り替える語。前の文の内容と並べる流れではないので合わない。"}, {"text": "すなわち", "is_correct": false, "explanation": "前の内容を言い換える語。夏の雨の話を冬の雪で言い換える関係にはならないので合わない。"}], "explanations": {"一方": "対比の接続詞。雨の多い夏と雪の少ない冬を対照的に並べるので、ここに入る。", "それとも": "選択を問いかける語。平叙文の二つ目の文の前には入らず、ここでは意味が通らない。", "さて": "話題を新しく切り替える語。前の文の内容と並べる流れではないので合わない。", "すなわち": "前の内容を言い換える語。夏の雨の話を冬の雪で言い換える関係にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "一方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼と一方出かけた。", "explanation": "ここは〈一緒に〉の意味。人と同じ行動をともにする意味は〈一緒に〉で、〈一方〉は二つを比べる語なので合わない。"}, {"text": "彼は一方背が高い。", "explanation": "ここは〈一番〉の意味。最上を表すのは〈一番〉で、〈一方〉は二つの対比なので最上は表せない。"}, {"text": "彼は質問に一方答えなかった。", "explanation": "ここは〈一切〉の意味。否定を強めて〈全く〜ない〉を表すのは〈一切〉で、〈一方〉は否定を強められない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36390, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は暑い。一方の、冬は寒い。", "corrected_sentence": "夏は暑い。一方、冬は寒い。", "error_description": "「一方の」は後ろに名詞を続ける形で、ここでは名詞がないまま読点が来ているのが誤り。接続詞の「一方、」と読点で続けるのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36390, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この村は夏に雨が少ない。一方的、冬は雪が多い。", "corrected_sentence": "この村は夏に雨が少ない。一方、冬は雪が多い。", "error_description": "〈一方的〉は形容動詞で、この位置では文を続けられない。接続詞の〈一方、〉に直すと、夏と冬を対比する正しい文になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36392, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「対話を通して」の「を」は、通すものを表す正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「対話に通して」は通す対象として成り立たず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「対話で通して」は手段の意味になるが、「通す」の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「対話が通して」は主語の形になるが、「通して」の対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「対話を通して」の「を」は、通すものを表す正しい助詞。", "に": "「対話に通して」は通す対象として成り立たず、意味が通らない。", "で": "「対話で通して」は手段の意味になるが、「通す」の対象を示せない。", "が": "「対話が通して」は主語の形になるが、「通して」の対象として成り立たない。"}, "error_tags": {"に": "target", "で": "means", "が": "subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36392, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36392, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二人が話し合うこと", "primary_collocate": null, "pronunciation": "たいわ", "ipa": "taiwa", "syllable_count": 3, "sentences": [{"text": "親と子の対話の時間を、毎晩少しでも作りたい。", "target_word": "対話", "complexity_tier": "T3", "furigana": "親[おや]と子[こ]の対話[たいわ]の時間[じかん]を、毎晩[まいばん]少[すこ]しでも作[つく]りたい。", "sentence_source": "generated"}, {"text": "先生と生徒の対話を通して、問題の答えが見えてきた。", "target_word": "対話", "complexity_tier": "T3", "furigana": "先生[せんせい]と生徒[せいと]の対話[たいわ]を通[とお]して、問題[もんだい]の答[こた]えが見[み]えてきた。", "sentence_source": "generated"}, {"text": "二人の対話は夜おそくまで続いた。", "target_word": "対話", "complexity_tier": "T3", "furigana": "二人[ふたり]の対話[たいわ]は夜[よる]おそくまで続[つづ]いた。", "sentence_source": "generated"}, {"text": "けんかをした後、まず対話をして誤解を解いた。", "target_word": "対話", "complexity_tier": "T3", "furigana": "けんかをした後[あと]、まず対話[たいわ]をして誤解[ごかい]を解[と]いた。", "sentence_source": "generated"}, {"text": "外国人の友達との対話で、英語の力がのびた。", "target_word": "対話", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]の友達[ともだち]との対話[たいわ]で、英語[えいご]の力[ちから]がのびた。", "sentence_source": "generated"}, {"text": "対話が足りないので、夫婦の気持ちがすれ違っている。", "target_word": "対話", "complexity_tier": "T3", "furigana": "対話[たいわ]が足[た]りないので、夫婦[ふうふ]の気持[きも]ちがすれ違[ちが]っている。", "sentence_source": "generated"}, {"text": "この本は、老人と少年の対話の形で書かれている。", "target_word": "対話", "complexity_tier": "T3", "furigana": "この本[ほん]は、老人[ろうじん]と少年[しょうねん]の対話[たいわ]の形[かたち]で書[か]かれている。", "sentence_source": "generated"}, {"text": "話すだけでなく、相手の話を聞くことが対話の基本だ。", "target_word": "対話", "complexity_tier": "T3", "furigana": "話[はな]すだけでなく、相手[あいて]の話[はなし]を聞[き]くことが対話[たいわ]の基本[きほん]だ。", "sentence_source": "generated"}, {"text": "二つの国の代表が対話を重ね、ようやく合意した。", "target_word": "対話", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]の代表[だいひょう]が対話[たいわ]を重[かさ]ね、ようやく合意[ごうい]した。", "sentence_source": "generated"}, {"text": "授業では、ペアで対話の練習をした。", "target_word": "対話", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]では、ペアで対話[たいわ]の練習[れんしゅう]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対話", "label": "基本形"}, {"form": "対話する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "向かい合った二人が言葉を交わして話し合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36392, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対話", "is_correct": true, "explanation": "親と子が言葉を交わす時間を指すので、「親と子の対話の時間」として自然。"}, {"text": "解散", "is_correct": false, "explanation": "「親と子の解散の時間」は意味が通らず、言葉を交わす意味にならない。"}, {"text": "脱退", "is_correct": false, "explanation": "「親と子の脱退の時間」は不自然で、話し合いを表さない。"}, {"text": "解体", "is_correct": false, "explanation": "「親と子の解体の時間」は意味が通らず、言葉のやり取りを表さない。"}], "explanations": {"対話": "親と子が言葉を交わす時間を指すので、「親と子の対話の時間」として自然。", "解散": "「親と子の解散の時間」は意味が通らず、言葉を交わす意味にならない。", "脱退": "「親と子の脱退の時間」は不自然で、話し合いを表さない。", "解体": "「親と子の解体の時間」は意味が通らず、言葉のやり取りを表さない。"}, "sentence_index": 0, "correct_answer": "対話"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "けんかをした後、二人は対話で勝負をつけた。", "explanation": "ここは〈対決〉の意味。勝負をつけるのは対決で、話し合いの対話には使わない。"}, {"text": "川の対話に家が建っている。", "explanation": "ここは〈対岸〉の意味。対話は人と人の話し合いで、川の向こう岸の位置は指さないので合わない。"}, {"text": "この作業の対話として、一万円を受け取った。", "explanation": "ここは〈対価〉の意味。報酬は対価と言い、話し合いの対話は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36392, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対話", "is_correct": true, "explanation": "老人と少年が言葉を交わす形で書かれている、という文脈に合う。"}, {"text": "購入", "is_correct": false, "explanation": "「購入の形で書かれている」は意味が通らず、文章の形式を表さない。"}, {"text": "配達", "is_correct": false, "explanation": "「配達の形で書かれている」は不自然で、書き方の形式を表さない。"}, {"text": "解約", "is_correct": false, "explanation": "「解約の形で書かれている」は意味が通らず、文章の形式にならない。"}], "explanations": {"対話": "老人と少年が言葉を交わす形で書かれている、という文脈に合う。", "購入": "「購入の形で書かれている」は意味が通らず、文章の形式を表さない。", "配達": "「配達の形で書かれている」は不自然で、書き方の形式を表さない。", "解約": "「解約の形で書かれている」は意味が通らず、文章の形式にならない。"}, "sentence_index": 6, "correct_answer": "対話"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨は、暖かい空気と冷たい空気の対話で降る。", "explanation": "ここは〈対流〉の意味。空気の循環は対流で、人同士の話し合いの対話は使わない。"}, {"text": "彼は店で対話を済ませて外に出た。", "explanation": "ここは〈会計〉の意味。支払いを済ませるのは会計で、対話は話し合いを表す。"}, {"text": "この研究の対話は子どもだ。", "explanation": "ここは〈対象〉の意味。研究で調べる相手は対象で、対話は話し合いを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
