INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36394, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「場が凍りついた」の「が」は、凍りつくものを表す正しい主語の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「場を凍りついた」は、自動詞「凍りつく」に目的語を付けるので成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「場へ凍りついた」は方向を表し、凍りつく主体を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「場と凍りついた」は共同の相手を表し、文の主体にならない。"}], "correct_answer": "が", "explanations": {"が": "「場が凍りついた」の「が」は、凍りつくものを表す正しい主語の助詞。", "を": "「場を凍りついた」は、自動詞「凍りつく」に目的語を付けるので成り立たない。", "へ": "「場へ凍りついた」は方向を表し、凍りつく主体を示せない。", "と": "「場と凍りついた」は共同の相手を表し、文の主体にならない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "companion"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36394, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が集まっているところの、その場所やようす。", "primary_collocate": null, "pronunciation": "ば", "ipa": "ba", "syllable_count": 1, "sentences": [{"text": "彼の冗談で、緊張していた場が一気になごんだ。", "target_word": "場", "complexity_tier": "T3", "furigana": "彼[かれ]の冗談[じょうだん]で、緊張[きんちょう]していた場[ば]が一気[いっき]になごんだ。", "sentence_source": "generated"}, {"text": "新人にも意見を言える場をつくることが大切だ。", "target_word": "場", "complexity_tier": "T3", "furigana": "新人[しんじん]にも意見[いけん]を言[い]える場[ば]をつくることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "場の空気を読んで、静かに座っていた。", "target_word": "場", "complexity_tier": "T3", "furigana": "場[ば]の空気[くうき]を読[よ]んで、静[しず]かに座[すわ]っていた。", "sentence_source": "generated"}, {"text": "先生は生徒たちが自由に話せる場を用意した。", "target_word": "場", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]たちが自由[じゆう]に話[はな]せる場[ば]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "パーティーの場で、彼は初めて社長に会った。", "target_word": "場", "complexity_tier": "T3", "furigana": "パーティーの場[ば]で、彼[かれ]は初[はじ]めて社長[しゃちょう]に会[あ]った。", "sentence_source": "generated"}, {"text": "その場にいた全員が、彼女の歌に拍手を送った。", "target_word": "場", "complexity_tier": "T3", "furigana": "その場[ば]にいた全員[ぜんいん]が、彼女[かのじょ]の歌[うた]に拍手[はくしゅ]を送[おく]った。", "sentence_source": "generated"}, {"text": "祭りでは、太鼓の音が響いて場が盛り上がった。", "target_word": "場", "complexity_tier": "T3", "furigana": "祭[まつ]りでは、太鼓[たいこ]の音[おと]が響[ひび]いて場[ば]が盛[も]り上[あ]がった。", "sentence_source": "generated"}, {"text": "失礼な発言のせいで、場が凍りついた。", "target_word": "場", "complexity_tier": "T3", "furigana": "失礼[しつれい]な発言[はつげん]のせいで、場[ば]が凍[こお]りついた。", "sentence_source": "generated"}, {"text": "公の場では、言葉づかいに気をつけたほうがいい。", "target_word": "場", "complexity_tier": "T3", "furigana": "公[おおやけ]の場[ば]では、言葉[ことば]づかいに気[き]をつけたほうがいい。", "sentence_source": "generated"}, {"text": "地域の人が集まる場として、この公民館は長く使われている。", "target_word": "場", "complexity_tier": "T3", "furigana": "地域[ちいき]の人[ひと]が集[あつ]まる場[ば]として、この公民館[こうみんかん]は長[なが]く使[つか]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "場", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が集まる場所と、そこに漂う雰囲気やようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: contains vocabulary far above tier T1: 言葉づかい (Zipf 2.33)']::text[], '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36394, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "場", "is_correct": true, "explanation": "人が集まるところの雰囲気を指すので、冗談で緊張がほぐれた場として自然。"}, {"text": "帽子", "is_correct": false, "explanation": "「緊張していた帽子が一気になごんだ」は意味が通らない。"}, {"text": "答案", "is_correct": false, "explanation": "「緊張していた答案がなごんだ」は、雰囲気を表す文脈に合わない。"}, {"text": "通帳", "is_correct": false, "explanation": "「緊張していた通帳がなごんだ」は意味が通らない。"}], "explanations": {"場": "人が集まるところの雰囲気を指すので、冗談で緊張がほぐれた場として自然。", "帽子": "「緊張していた帽子が一気になごんだ」は意味が通らない。", "答案": "「緊張していた答案がなごんだ」は、雰囲気を表す文脈に合わない。", "通帳": "「緊張していた通帳がなごんだ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の場は、試合が中止になる。", "explanation": "ここは〈場合〉の意味。場は人が集まる場所や状況を指し、条件を表す用法では使わないので合わない。"}, {"text": "ペンキ屋が、壁の場を塗った。", "explanation": "ここは〈面〉の意味。場は場所や状況を指し、物の表面は面と言うので合わない。"}, {"text": "雨宿りの鳥が、木の場に巣を作った。", "explanation": "ここは〈枝〉の意味。場は場所や状況を指し、木の部分の名前には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36394, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "場", "is_correct": true, "explanation": "太鼓の音で場の雰囲気が盛り上がった、という文脈に合う。"}, {"text": "地図", "is_correct": false, "explanation": "「地図が盛り上がった」は意味が通らず、雰囲気の変化を表さない。"}, {"text": "切手", "is_correct": false, "explanation": "「切手が盛り上がった」は不自然で、祭りの雰囲気を表さない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布が盛り上がった」は意味が通らず、場の雰囲気を表さない。"}], "explanations": {"場": "太鼓の音で場の雰囲気が盛り上がった、という文脈に合う。", "地図": "「地図が盛り上がった」は意味が通らず、雰囲気の変化を表さない。", "切手": "「切手が盛り上がった」は不自然で、祭りの雰囲気を表さない。", "財布": "「財布が盛り上がった」は意味が通らず、場の雰囲気を表さない。"}, "sentence_index": 6, "correct_answer": "場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市の北には、大きな場が三つ建っている。", "explanation": "ここは〈工場〉の意味。場は人が集まる場所や状況を指し、製造の施設は工場と言うので合わない。"}, {"text": "彼は会社で重要な場にある。", "explanation": "ここは〈立場〉の意味。場は場所や状況を指し、社会的な位置は立場と言うので合わない。"}, {"text": "今年は、米の場がさらに上がった。", "explanation": "ここは〈相場〉の意味。場は場所や状況を指し、値段の動きには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36394, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の場を意見を言った。", "corrected_sentence": "会議の場で意見を言った。", "error_description": "「場で」は場所を表す。誤り：場を（助詞）。「言った」の前には場所を示す「で」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36394, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その場を静まり返った。", "corrected_sentence": "その場が静まり返った。", "error_description": "「静まり返る」は自動詞で、主語に「が」を取る。誤り：場を（助詞）。正しい形：場が。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36398, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乱れる", "is_correct": true, "explanation": "「整う」の対義語。きちんとしていた状態が崩れる意味で、整うと反対の状態を表す。"}, {"text": "増える", "is_correct": false, "explanation": "数や量が多くなる意味で、「整う」の反対の状態を表さない。"}, {"text": "届く", "is_correct": false, "explanation": "物が目的地に着く意味で、「整う」と対になる関係ではない。"}, {"text": "見える", "is_correct": false, "explanation": "視覚に入る意味で、「整う」と対になる関係ではない。"}], "correct_answer": "乱れる", "explanations": {"乱れる": "「整う」の対義語。きちんとしていた状態が崩れる意味で、整うと反対の状態を表す。", "増える": "数や量が多くなる意味で、「整う」の反対の状態を表さない。", "届く": "物が目的地に着く意味で、「整う」と対になる関係ではない。", "見える": "視覚に入る意味で、「整う」と対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36398, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乱れる", "is_correct": true, "explanation": "「整う」の対義語。きちんとしていた状態が崩れる意味で、整うと反対の状態を表す。"}, {"text": "始まる", "is_correct": false, "explanation": "物事が起こり始める意味で、「整う」と対になる関係ではない。"}, {"text": "進む", "is_correct": false, "explanation": "前へ動く、物事が進む意味で、「整う」と対になる関係ではない。"}, {"text": "光る", "is_correct": false, "explanation": "明るく輝く意味で、「整う」と対になる関係ではない。"}], "correct_answer": "乱れる", "explanations": {"乱れる": "「整う」の対義語。きちんとしていた状態が崩れる意味で、整うと反対の状態を表す。", "始まる": "物事が起こり始める意味で、「整う」と対になる関係ではない。", "進む": "前へ動く、物事が進む意味で、「整う」と対になる関係ではない。", "光る": "明るく輝く意味で、「整う」と対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36398, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ばらばらだったものが、うまく合わさって、ちょうどいい状態になる。", "primary_collocate": null, "pronunciation": "ととのう", "ipa": "totonoɯ", "syllable_count": 4, "sentences": [{"text": "髪をとかすと、乱れていた前髪がきれいに整った。", "target_word": "整った", "complexity_tier": "T3", "furigana": "髪[かみ]をとかすと、乱[みだ]れていた前髪[まえがみ]がきれいに整[ととの]った。", "sentence_source": "generated"}, {"text": "走ったあとは、少し休むと呼吸が整ってくる。", "target_word": "整って", "complexity_tier": "T3", "furigana": "走[はし]ったあとは、少[すこ]し休[やす]むと呼吸[こきゅう]が整[ととの]ってくる。", "sentence_source": "generated"}, {"text": "彼女は目鼻立ちが整っていて、写真でもとても映える。", "target_word": "整って", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は目鼻立[めはなだ]ちが整[ととの]っていて、写真[しゃしん]でもとても映[は]える。", "sentence_source": "generated"}, {"text": "本棚の本を順番に並べ直したら、部屋が整って気持ちがいい。", "target_word": "整って", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の本[ほん]を順番[じゅんばん]に並[なら]べ直[なお]したら、部屋[へや]が整[ととの]って気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "整った字で書かれた手紙を読んで、丁寧な人だと思った。", "target_word": "整った", "complexity_tier": "T3", "furigana": "整[ととの]った字[じ]で書[か]かれた手紙[てがみ]を読[よ]んで、丁寧[ていねい]な人[ひと]だと思[おも]った。", "sentence_source": "generated"}, {"text": "庭の木を切りそろえたので、形がきれいに整った。", "target_word": "整った", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]を切[き]りそろえたので、形[かたち]がきれいに整[ととの]った。", "sentence_source": "generated"}, {"text": "ばらばらだった音がやっと整い、きれいな和音になった。", "target_word": "整い", "complexity_tier": "T3", "furigana": "ばらばらだった音[おと]がやっと整[ととの]い、きれいな和音[わおん]になった。", "sentence_source": "generated"}, {"text": "文章の順序を入れかえたら、話の流れが整って読みやすくなった。", "target_word": "整って", "complexity_tier": "T4", "furigana": "文章[ぶんしょう]の順序[じゅんじょ]を入[い]れかえたら、話[はなし]の流[なが]れが整[ととの]って読[よ]みやすくなった。", "sentence_source": "generated"}, {"text": "一晩ぐっすり眠ったら、崩れていた体調が整った。", "target_word": "整った", "complexity_tier": "T3", "furigana": "一晩[ひとばん]ぐっすり眠[ねむ]ったら、崩[くず]れていた体調[たいちょう]が整[ととの]った。", "sentence_source": "generated"}, {"text": "古い城下町には、整った町並みが今も残っている。", "target_word": "整った", "complexity_tier": "T3", "furigana": "古[ふる]い城下町[じょうかまち]には、整[ととの]った町並[まちな]みが今[いま]も残[のこ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "整う", "label": "終止形"}, {"form": "整い", "label": "連用形"}, {"form": "整わ", "label": "未然形"}, {"form": "整えば", "label": "仮定形"}, {"form": "整った", "label": "タ形"}, {"form": "整って", "label": "テ形"}], "register": "標準", "sense_fingerprint": "整う|乱れていたものがそろい、きれいな形や状態になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36398, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整った", "is_correct": true, "explanation": "タ形で、「前髪がきれいに整った」と状態が完成したことを表す。正しい。"}, {"text": "整わ", "is_correct": false, "explanation": "未然形で「整わない」の形でしか使えず、文末に置けない。"}, {"text": "整え", "is_correct": false, "explanation": "命令形で、文末に置くと命令になり、描写の文に合わない。"}, {"text": "整えた", "is_correct": false, "explanation": "「整える」の過去形で他動詞のため、主語が前髪では「前髪をきれいに整えた」と言う必要がある。"}], "explanations": {"整った": "タ形で、「前髪がきれいに整った」と状態が完成したことを表す。正しい。", "整わ": "未然形で「整わない」の形でしか使えず、文末に置けない。", "整え": "命令形で、文末に置くと命令になり、描写の文に合わない。", "整えた": "「整える」の過去形で他動詞のため、主語が前髪では「前髪をきれいに整えた」と言う必要がある。"}, "sentence_index": 0, "correct_answer": "整った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "霧が出て、遠くの山が整った。", "explanation": "ここは〈かすむ〉の意味。見えにくくぼやける様子で、ばらばらのものがうまく合わさる「整う」とは合わない。"}, {"text": "客が整ったので、会場の入り口を開けた。", "explanation": "ここは〈揃う〉の意味。人が集まってそろうことは「揃う」で表し、「整う」は乱れていたものが整うことに使う。"}, {"text": "テーブルの上で、コーヒーが整った。", "explanation": "ここは〈こぼれる〉の意味。液体がこぼれて広がる様子で、きれいにまとまる「整う」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36398, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整い", "is_correct": true, "explanation": "連用形で、「やっと整い、」と読点の前で文を続ける。正しい。"}, {"text": "整わ", "is_correct": false, "explanation": "未然形で、読点の前で文を続けられず「音が整わ、」とは言えない。"}, {"text": "整えて", "is_correct": false, "explanation": "「整える」のテ形。他動詞で、音が主語では使えない。"}, {"text": "整える", "is_correct": false, "explanation": "「整える」の終止形。目的語を取る他動詞で、「音が整える」は不自然。"}], "explanations": {"整い": "連用形で、「やっと整い、」と読点の前で文を続ける。正しい。", "整わ": "未然形で、読点の前で文を続けられず「音が整わ、」とは言えない。", "整えて": "「整える」のテ形。他動詞で、音が主語では使えない。", "整える": "「整える」の終止形。目的語を取る他動詞で、「音が整える」は不自然。"}, "sentence_index": 6, "correct_answer": "整い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨ざらしの鉄の門が整った。", "explanation": "ここは〈さびる〉の意味。金属が傷んでいく変化で、きれいにそろう「整う」とは合わない。"}, {"text": "水を入れると、ふくろが整った。", "explanation": "ここは〈ふくらむ〉の意味。空気や水で体積が増える様子で、ばらばらのものがきれいに合わさる「整う」とは合わない。"}, {"text": "床いっぱいに、おもちゃが整った。", "explanation": "ここは〈散らばる〉の意味。ばらばらに広がる様子で、そろえる「整う」とは反対なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36398, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机の上の本が、きれいに整いていた。", "corrected_sentence": "机の上の本が、きれいに整っていた。", "error_description": "連用形「整い」に「ていた」を付けた形は誤り。「整う」の「ていた」の形は「整っていた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "整って", "is_correct": true, "explanation": "テ形で、「整ってくる」の形になり、状態が変化していく過程を表す。正しい。"}, {"text": "整った", "is_correct": false, "explanation": "タ形で、「整ったくる」とは続かない。"}, {"text": "整わ", "is_correct": false, "explanation": "未然形で、「整わくる」の形にならない。"}, {"text": "整え", "is_correct": false, "explanation": "命令形で、「整えくる」の形にならない。"}], "correct_form": "整って", "base_form": "整う", "form_label": "テ形（「整ってくる」）", "sentence_index": 1, "explanations": {"整って": "テ形で、「整ってくる」の形になり、状態が変化していく過程を表す。正しい。", "整った": "タ形で、「整ったくる」とは続かない。", "整わ": "未然形で、「整わくる」の形にならない。", "整え": "命令形で、「整えくる」の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36398, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引き出しの文房具を、きれいに整った。", "corrected_sentence": "引き出しの文房具が、きれいに整った。", "error_description": "「整う」は自動詞なので、主語「文房具」には「が」を付ける。「を」にすると誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "整って", "is_correct": true, "explanation": "テ形で、「整って読みやすくなった」と後ろに続けられる。正しい。"}, {"text": "整わない", "is_correct": false, "explanation": "未然形に「ない」が付いた否定形で、「読みやすくなった」の前に続けると文の意味が通らない。"}, {"text": "整わず", "is_correct": false, "explanation": "否定の連用形で、「整わないで」の意味になり、読みやすくなったという結果と逆の内容になる。"}, {"text": "整え", "is_correct": false, "explanation": "命令形で、「話の流れが整え、」と続けると命令になり、読みやすくなった結果の文と合わない。"}], "correct_form": "整って", "base_form": "整う", "form_label": "テ形（「整って読みやすくなった」）", "sentence_index": 7, "explanations": {"整って": "テ形で、「整って読みやすくなった」と後ろに続けられる。正しい。", "整わない": "未然形に「ない」が付いた否定形で、「読みやすくなった」の前に続けると文の意味が通らない。", "整わず": "否定の連用形で、「整わないで」の意味になり、読みやすくなったという結果と逆の内容になる。", "整え": "命令形で、「話の流れが整え、」と続けると命令になり、読みやすくなった結果の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
