INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36399, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36399, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "必要な条件が満たされたり、物事がきちんとまとまったりして、望ましい状態になる。", "primary_collocate": null, "pronunciation": "ととのう", "ipa": "totonoɯ", "syllable_count": 4, "sentences": [{"text": "やがて準備が整い、彼は勢いよく扉を押し開ける。", "target_word": "整い", "complexity_tier": "T3", "furigana": "やがて準備[じゅんび]が整[ととの]い、彼[かれ]は勢[いきお]いよく扉[とびら]を押[お]し開[あ]ける。", "sentence_source": "mined"}, {"text": "受け入れの体制が整うまで、新入社員の配属は来月に延期された。", "target_word": "整う", "complexity_tier": "T4", "furigana": "受[う]け入[い]れの体制[たいせい]が整[ととの]うまで、新入社員[しんにゅうしゃいん]の配属[はいぞく]は来月[らいげつ]に延期[えんき]された。", "sentence_source": "generated"}, {"text": "条件が整えば、すぐに工事を始めることができます。", "target_word": "整えば", "complexity_tier": "T3", "furigana": "条件[じょうけん]が整[ととの]えば、すぐに工事[こうじ]を始[はじ]めることができます。", "sentence_source": "generated"}, {"text": "試合の準備が整ったので、選手たちはグラウンドに出ていった。", "target_word": "整った", "complexity_tier": "T3", "furigana": "試合[しあい]の準備[じゅんび]が整[ととの]ったので、選手[せんしゅ]たちはグラウンドに出[で]ていった。", "sentence_source": "generated"}, {"text": "留学するための環境が整っていて、安心して勉強に集中できた。", "target_word": "整って", "complexity_tier": "T3", "furigana": "留学[りゅうがく]するための環境[かんきょう]が整[ととの]っていて、安心[あんしん]して勉強[べんきょう]に集中[しゅうちゅう]できた。", "sentence_source": "generated"}, {"text": "食事の用意が整いましたので、どうぞお席にお着きください。", "target_word": "整い", "complexity_tier": "T3", "furigana": "食事[しょくじ]の用意[ようい]が整[ととの]いましたので、どうぞお席[せき]にお着[つ]きください。", "sentence_source": "generated"}, {"text": "設備はすっかり整った。", "target_word": "整った", "complexity_tier": "T3", "furigana": "設備[せつび]はすっかり整[ととの]った。", "sentence_source": "generated"}, {"text": "契約を結ぶ条件がまだ整っていないため、署名は見送られた。", "target_word": "整って", "complexity_tier": "T4", "furigana": "契約[けいやく]を結[むす]ぶ条件[じょうけん]がまだ整[ととの]っていないため、署名[しょめい]は見送[みおく]られた。", "sentence_source": "generated"}, {"text": "議論する場が整うのを待って、委員長は静かに会議を始めた。", "target_word": "整う", "complexity_tier": "T4", "furigana": "議論[ぎろん]する場[ば]が整[ととの]うのを待[ま]って、委員長[いいんちょう]は静[しず]かに会議[かいぎ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "出発の支度がすっかり整ったのに、雨が強くて家を出られない。", "target_word": "整った", "complexity_tier": "T3", "furigana": "出発[しゅっぱつ]の支度[したく]がすっかり整[ととの]ったのに、雨[あめ]が強[つよ]くて家[いえ]を出[で]られない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "整う", "label": "終止形"}, {"form": "整い", "label": "連用形"}, {"form": "整わ", "label": "未然形"}, {"form": "整えば", "label": "仮定形"}, {"form": "整った", "label": "タ形"}, {"form": "整って", "label": "テ形"}], "register": "標準", "sense_fingerprint": "整う|条件や準備が満たされ、物事が望ましい状態になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36399, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整い", "is_correct": true, "explanation": "連用形で、読点の前で文を続けられる。「準備が整い、彼は…」の形として正しい。"}, {"text": "整わ", "is_correct": false, "explanation": "未然形で「整わない」の形でしか使えず、読点の前で文が成り立たない。"}, {"text": "整え", "is_correct": false, "explanation": "命令形で、文を切ると命令になり、この文の流れに合わない。"}, {"text": "整えて", "is_correct": false, "explanation": "「整える」のテ形。「整える」は他動詞で、「準備が整えて」の形では成り立たない。"}], "explanations": {"整い": "連用形で、読点の前で文を続けられる。「準備が整い、彼は…」の形として正しい。", "整わ": "未然形で「整わない」の形でしか使えず、読点の前で文が成り立たない。", "整え": "命令形で、文を切ると命令になり、この文の流れに合わない。", "整えて": "「整える」のテ形。「整える」は他動詞で、「準備が整えて」の形では成り立たない。"}, "sentence_index": 0, "correct_answer": "整い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、夕日が海に整った。", "explanation": "ここは〈沈む〉の意味。太陽が水平線の下へ下がる様子で、必要な条件が満たされる「整う」とは言えない。"}, {"text": "寝る前に、部屋の明かりが整った。", "explanation": "ここは〈消える〉の意味。明かりが無くなることで、条件や準備が満たされる「整う」とは合わない。"}, {"text": "壊れた電子レンジが整った。", "explanation": "ここは〈直る〉の意味。壊れたものが修理されて元に戻ることは「直る」で、条件が満たされる「整う」では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36399, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整った", "is_correct": true, "explanation": "タ形で、文末の「設備はすっかり整った。」と言い切る。正しい。"}, {"text": "整えば", "is_correct": false, "explanation": "仮定形で、文末に置くと「整えば。」となり文が終わらない。"}, {"text": "整って", "is_correct": false, "explanation": "テ形で、文末に置くと「整って。」となり文が終わらない。"}, {"text": "整い", "is_correct": false, "explanation": "連用形で、文末に置くと「整い。」となり文が終わらない。"}], "explanations": {"整った": "タ形で、文末の「設備はすっかり整った。」と言い切る。正しい。", "整えば": "仮定形で、文末に置くと「整えば。」となり文が終わらない。", "整って": "テ形で、文末に置くと「整って。」となり文が終わらない。", "整い": "連用形で、文末に置くと「整い。」となり文が終わらない。"}, "sentence_index": 6, "correct_answer": "整った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "探していた鍵が整った。", "explanation": "ここは〈見つかる〉の意味。探し物が見つかることは「見つかる」で表し、条件や準備が満たされる「整う」では言えない。"}, {"text": "授業の前に、子どもたちが整った。", "explanation": "ここは〈騒ぐ〉の意味。大きな声を出す様子で、条件や準備が満たされる「整う」とは合わない。"}, {"text": "焼きすぎて、パンが整った。", "explanation": "ここは〈焦げる〉の意味。焼きすぎて黒くなる変化で、望ましい状態に整うとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36399, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "準備が整わったら、すぐに出発しましょう。", "corrected_sentence": "準備が整ったら、すぐに出発しましょう。", "error_description": "「整わ」（未然形）に「った」をつけた形は誤り。「整う」の過去形は「整った」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "整う", "is_correct": true, "explanation": "終止形・連体形。「整うまで」の形で「まで」に続くので正しい。"}, {"text": "整った", "is_correct": false, "explanation": "タ形で、「整ったまで」とは続かず、完了の意味になる。"}, {"text": "整わ", "is_correct": false, "explanation": "未然形で、「整わまで」と続かない。"}, {"text": "整えば", "is_correct": false, "explanation": "仮定形で、「整えばまで」と続かない。"}], "correct_form": "整う", "base_form": "整う", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"整う": "終止形・連体形。「整うまで」の形で「まで」に続くので正しい。", "整った": "タ形で、「整ったまで」とは続かず、完了の意味になる。", "整わ": "未然形で、「整わまで」と続かない。", "整えば": "仮定形で、「整えばまで」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36399, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "委員会の準備を整ったので、会議を始めます。", "corrected_sentence": "委員会の準備が整ったので、会議を始めます。", "error_description": "「整う」は自動詞なので、主語「準備」には「が」を付ける。「を」は他動詞「整える」の目的語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "整って", "is_correct": true, "explanation": "テ形。「整っていない」の形で、「ていない」に続くので正しい。"}, {"text": "整い", "is_correct": false, "explanation": "連用形で、「整いていない」とは続かない。"}, {"text": "整え", "is_correct": false, "explanation": "命令形で、「整う」の形としては「整っていない」にならない。"}, {"text": "整わない", "is_correct": false, "explanation": "未然形に「ない」が付いた形で、「整わないていない」とは続かない。"}], "correct_form": "整って", "base_form": "整う", "form_label": "テ形（「整っていない」）", "sentence_index": 7, "explanations": {"整って": "テ形。「整っていない」の形で、「ていない」に続くので正しい。", "整い": "連用形で、「整いていない」とは続かない。", "整え": "命令形で、「整う」の形としては「整っていない」にならない。", "整わない": "未然形に「ない」が付いた形で、「整わないていない」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36400, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「時計は」で、祖父からもらった時計を主題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「時計を」は目的語を示すが、「動いている」は目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「時計に」は対象・方向を示すが、「正しく動いている」の文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「時計で」は手段を示すが、「正しく動いている」に手段を当てはめると不自然。"}], "correct_answer": "は", "explanations": {"は": "正解。「時計は」で、祖父からもらった時計を主題として示す。", "を": "「時計を」は目的語を示すが、「動いている」は目的語を取らないので合わない。", "に": "「時計に」は対象・方向を示すが、「正しく動いている」の文脈に合わない。", "で": "「時計で」は手段を示すが、「正しく動いている」に手段を当てはめると不自然。"}, "error_tags": {"を": "目的語", "に": "対象・方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36400, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「時計が」で、進んでいる主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「時計と」は並列・同伴を示し、「進んでいた」の主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「時計へ」は方向を示すが、時計が進んでいる状態を表す文には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「時計から」は起点を示すが、時計自体が進んでいる文脈と合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「時計が」で、進んでいる主語を示す。", "と": "「時計と」は並列・同伴を示し、「進んでいた」の主語として成り立たない。", "へ": "「時計へ」は方向を示すが、時計が進んでいる状態を表す文には合わない。", "から": "「時計から」は起点を示すが、時計自体が進んでいる文脈と合わない。"}, "error_tags": {"と": "並列・同伴", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36400, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "時間を見るための道具です。", "primary_collocate": null, "pronunciation": "とけい", "ipa": "tokeː", "syllable_count": 3, "sentences": [{"text": "駅で時計を見ると、電車の時間まであと五分だった。", "target_word": "時計", "complexity_tier": "T3", "furigana": "駅[えき]で時計[とけい]を見[み]ると、電車[でんしゃ]の時間[じかん]まであと五分[ごふん]だった。", "sentence_source": "generated"}, {"text": "祖父からもらった時計は、今も正しく動いている。", "target_word": "時計", "complexity_tier": "T3", "furigana": "祖父[そふ]からもらった時計[とけい]は、今[いま]も正[ただ]しく動[うご]いている。", "sentence_source": "generated"}, {"text": "時計が止まっていたので、遅刻したと思って走った。", "target_word": "時計", "complexity_tier": "T3", "furigana": "時計[とけい]が止[と]まっていたので、遅刻[ちこく]したと思[おも]って走[はし]った。", "sentence_source": "generated"}, {"text": "部屋に時計がないと、時間がわからなくて不便だ。", "target_word": "時計", "complexity_tier": "T3", "furigana": "部屋[へや]に時計[とけい]がないと、時間[じかん]がわからなくて不便[ふべん]だ。", "sentence_source": "generated"}, {"text": "試験の間、時計を机の上に置いてもいいですか。", "target_word": "時計", "complexity_tier": "T3", "furigana": "試験[しけん]の間[あいだ]、時計[とけい]を机[つくえ]の上[うえ]に置[お]いてもいいですか。", "sentence_source": "generated"}, {"text": "この時計は電池を換えれば、まだ使える。", "target_word": "時計", "complexity_tier": "T3", "furigana": "この時計[とけい]は電池[でんち]を換[か]えれば、まだ使[つか]える。", "sentence_source": "generated"}, {"text": "時計の針が十二時をさしたとき、花火が上がった。", "target_word": "時計", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]が十二時[じゅうにじ]をさしたとき、花火[はなび]が上[あ]がった。", "sentence_source": "generated"}, {"text": "友達の時計が進んでいたため、約束の時間より早く着いた。", "target_word": "時計", "complexity_tier": "T3", "furigana": "友達[ともだち]の時計[とけい]が進[すす]んでいたため、約束[やくそく]の時間[じかん]より早[はや]く着[つ]いた。", "sentence_source": "generated"}, {"text": "時計を見ながら、料理ができるまで待った。", "target_word": "時計", "complexity_tier": "T3", "furigana": "時計[とけい]を見[み]ながら、料理[りょうり]ができるまで待[ま]った。", "sentence_source": "generated"}, {"text": "小さい子に、時計の読み方を教えている。", "target_word": "時計", "complexity_tier": "T3", "furigana": "小[ちい]さい子[こ]に、時計[とけい]の読[よ]み方[かた]を教[おし]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時計", "label": "基本形"}], "register": "plain", "sense_fingerprint": "時間を確かめるための道具一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36400, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夕焼け", "is_correct": false, "explanation": "夕焼けを見ても電車の時間はわからず、「電車の時間まであと五分」という文脈に合わない。"}, {"text": "時計", "is_correct": true, "explanation": "正解。駅で時刻を確かめる道具として「時計を見る」が自然に入る。"}, {"text": "猫", "is_correct": false, "explanation": "猫を見て電車の時間がわかるはずがなく、文が成り立たない。"}, {"text": "日付", "is_correct": false, "explanation": "日付を見ても電車まであと何分かはわからず、時刻を確かめる文脈と合わない。"}], "explanations": {"夕焼け": "夕焼けを見ても電車の時間はわからず、「電車の時間まであと五分」という文脈に合わない。", "時計": "正解。駅で時刻を確かめる道具として「時計を見る」が自然に入る。", "猫": "猫を見て電車の時間がわかるはずがなく、文が成り立たない。", "日付": "日付を見ても電車まであと何分かはわからず、時刻を確かめる文脈と合わない。"}, "sentence_index": 0, "correct_answer": "時計"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱があるかと思い、時計で体温を確かめた。", "explanation": "ここは〈体温計〉の意味。時計は時刻を見る道具なので、体温は測れない。"}, {"text": "朝起きてから、時計で体重を量った。", "explanation": "ここは〈体重計〉の意味。時計では体重は量れないので合わない。"}, {"text": "授業の時計は九十分だ。", "explanation": "ここは〈時間〉の意味。時計は道具で、長さを表す「九十分」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36400, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌", "is_correct": false, "explanation": "「歌の針」は成り立たず、針を持つ道具の文脈に合わない。"}, {"text": "時計", "is_correct": true, "explanation": "正解。「時計の針」が十二時をさすという、道具の針を指す文脈に合う。"}, {"text": "雲", "is_correct": false, "explanation": "「雲の針」は意味が通らず、針が十二時をさす文脈と合わない。"}, {"text": "電池", "is_correct": false, "explanation": "電池には針がなく、「電池の針が十二時をさした」は成り立たない。"}], "explanations": {"歌": "「歌の針」は成り立たず、針を持つ道具の文脈に合わない。", "時計": "正解。「時計の針」が十二時をさすという、道具の針を指す文脈に合う。", "雲": "「雲の針」は意味が通らず、針が十二時をさす文脈と合わない。", "電池": "電池には針がなく、「電池の針が十二時をさした」は成り立たない。"}, "sentence_index": 6, "correct_answer": "時計"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外に出て時計で気温を確かめたら、三十度だった。", "explanation": "ここは〈温度計〉の意味。時計は時刻を示す道具で、気温は示せないので合わない。"}, {"text": "病院で時計を使って血圧を測った。", "explanation": "ここは〈血圧計〉の意味。時計では血圧は測れないので合わない。"}, {"text": "お風呂上がりに時計で体脂肪を測った。", "explanation": "ここは〈体脂肪計〉の意味。時計で体脂肪は測れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36400, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、時計に見てから家を出る。", "corrected_sentence": "毎朝、時計を見てから家を出る。", "error_description": "「時計」に続く助詞が「に」になっている。見る対象は「を」で示すのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36400, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電池が切れたので、時計を直しもらった。", "corrected_sentence": "電池が切れたので、時計を直してもらった。", "error_description": "「直して」の「て」が抜けている。「直してもらう」の形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36401, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「時計が」で、朝七時を知らせる主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「時計を」は目的語で、「朝七時を知らせた」と並ぶと目的語が二つになり文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「時計と」は並列を示し、「知らせた」の主語として文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「時計から」は起点を示し、知らせる主体として主語になる文脈に合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「時計が」で、朝七時を知らせる主語を示す。", "を": "「時計を」は目的語で、「朝七時を知らせた」と並ぶと目的語が二つになり文が崩れる。", "と": "「時計と」は並列を示し、「知らせた」の主語として文が成り立たない。", "から": "「時計から」は起点を示し、知らせる主体として主語になる文脈に合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36401, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「時計が」で、五分遅れていた主語を示す。"}, {"text": "で", "is_correct": false, "explanation": "「時計で」は手段・場所を示し、「遅れていた」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「時計と」は並列を示し、「遅れていた」の主語として文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「時計の」は所有・修飾を示し、「遅れていた」の主語にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "正解。「時計が」で、五分遅れていた主語を示す。", "で": "「時計で」は手段・場所を示し、「遅れていた」の主語にはならない。", "と": "「時計と」は並列を示し、「遅れていた」の主語として文が成り立たない。", "の": "「時計の」は所有・修飾を示し、「遅れていた」の主語にならず不自然。"}, "error_tags": {"で": "手段・場所", "と": "並列", "の": "所有・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36401, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "現在の時刻を知るために、壁にかけたり、机の上に置いたりして使う道具。", "primary_collocate": null, "pronunciation": "とけい", "ipa": "tokeː", "syllable_count": 3, "sentences": [{"text": "居間の壁に、大きな時計がかかっている。", "target_word": "時計", "complexity_tier": "T3", "furigana": "居間[いま]の壁[かべ]に、大[おお]きな時計[とけい]がかかっている。", "sentence_source": "generated"}, {"text": "机の上の時計が、朝七時を知らせた。", "target_word": "時計", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の時計[とけい]が、朝[あさ]七時[しちじ]を知[し]らせた。", "sentence_source": "generated"}, {"text": "新しい家に引っ越して、まず壁に時計をかけた。", "target_word": "時計", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]に引[ひ]っ越[こ]して、まず壁[かべ]に時計[とけい]をかけた。", "sentence_source": "generated"}, {"text": "時計の音がうるさくて、夜なかなか眠れない。", "target_word": "時計", "complexity_tier": "T3", "furigana": "時計[とけい]の音[おと]がうるさくて、夜[よる]なかなか眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "教室の前の時計を見て、授業が終わる時間を確かめた。", "target_word": "時計", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の前[まえ]の時計[とけい]を見[み]て、授業[じゅぎょう]が終[お]わる時間[じかん]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "玄関に時計を置くと、出かける前に時刻がわかる。", "target_word": "時計", "complexity_tier": "T3", "furigana": "玄関[げんかん]に時計[とけい]を置[お]くと、出[で]かける前[まえ]に時刻[じこく]がわかる。", "sentence_source": "generated"}, {"text": "古い時計が三時を打つと、犬が起きた。", "target_word": "時計", "complexity_tier": "T3", "furigana": "古[ふる]い時計[とけい]が三時[さんじ]を打[う]つと、犬[いぬ]が起[お]きた。", "sentence_source": "generated"}, {"text": "時計が五分遅れていたので、合わせ直した。", "target_word": "時計", "complexity_tier": "T3", "furigana": "時計[とけい]が五分[ごふん]遅[おく]れていたので、合[あ]わせ直[なお]した。", "sentence_source": "generated"}, {"text": "駅の柱に立つ時計の下で、友達を待った。", "target_word": "時計", "complexity_tier": "T3", "furigana": "駅[えき]の柱[はしら]に立[た]つ時計[とけい]の下[した]で、友達[ともだち]を待[ま]った。", "sentence_source": "generated"}, {"text": "机の上に時計があるので、勉強の時間を計りやすい。", "target_word": "時計", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に時計[とけい]があるので、勉強[べんきょう]の時間[じかん]を計[はか]りやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時計", "label": "基本形"}], "register": "plain", "sense_fingerprint": "壁にかけたり机に置いたりして使う、時刻を知る道具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36401, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌", "is_correct": false, "explanation": "「壁に大きな歌がかかっている」は意味が通らず、掛ける物の文脈に合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は壁にかけるものではなく、「大きな雨がかかっている」は成り立たない。"}, {"text": "時計", "is_correct": true, "explanation": "正解。居間の壁に掛けてある道具として自然に入る。"}, {"text": "夕飯", "is_correct": false, "explanation": "夕飯は壁にかけるものではなく、「大きな夕飯がかかっている」は成り立たない。"}], "explanations": {"歌": "「壁に大きな歌がかかっている」は意味が通らず、掛ける物の文脈に合わない。", "雨": "雨は壁にかけるものではなく、「大きな雨がかかっている」は成り立たない。", "時計": "正解。居間の壁に掛けてある道具として自然に入る。", "夕飯": "夕飯は壁にかけるものではなく、「大きな夕飯がかかっている」は成り立たない。"}, "sentence_index": 0, "correct_answer": "時計"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱があるかと思い、時計で体温を確かめた。", "explanation": "ここは〈体温計〉の意味。時計は時刻を見る道具なので、体温は測れない。"}, {"text": "風呂上がりに、時計で体重を量った。", "explanation": "ここは〈体重計〉の意味。時計では体重は量れないので合わない。"}, {"text": "会議の時計は一時間だった。", "explanation": "ここは〈時間〉の意味。時計は道具で、長さを表す「一時間」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36401, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電池", "is_correct": false, "explanation": "「古い電池が三時を打つ」は成り立たず、時を打つ道具の文脈に合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は時を打たないので、「古い雲が三時を打つ」は意味が通らない。"}, {"text": "時計", "is_correct": true, "explanation": "正解。古い時計が時を打つと犬が起きた、という文脈に合う。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は時を打たないので、「古い鍋が三時を打つ」は成り立たない。"}], "explanations": {"電池": "「古い電池が三時を打つ」は成り立たず、時を打つ道具の文脈に合わない。", "雲": "雲は時を打たないので、「古い雲が三時を打つ」は意味が通らない。", "時計": "正解。古い時計が時を打つと犬が起きた、という文脈に合う。", "鍋": "鍋は時を打たないので、「古い鍋が三時を打つ」は成り立たない。"}, "sentence_index": 6, "correct_answer": "時計"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外に出て、時計で気温を確かめた。", "explanation": "ここは〈温度計〉の意味。時計は時刻を示す道具で、気温は示せないので合わない。"}, {"text": "血圧が高いので、時計で血圧を測った。", "explanation": "ここは〈血圧計〉の意味。時計では血圧は測れないので合わない。"}, {"text": "体脂肪を減らしたいので、時計で体脂肪を量った。", "explanation": "ここは〈体脂肪計〉の意味。時計で体脂肪は量れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36401, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝る前に、時計が枕元に置く。", "corrected_sentence": "寝る前に、時計を枕元に置く。", "error_description": "「時計」に続く助詞が「が」になっている。置く対象は「を」で示すのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36401, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机の上に時計を置いると、勉強の時間を計りやすい。", "corrected_sentence": "机の上に時計を置くと、勉強の時間を計りやすい。", "error_description": "「置く」の活用が誤っている。「置くと」が正しい。「置いる」という形はないので「置いると」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36402, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「針が来た」の主語を示す。来るのは針なので「が」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「来る」は目的語をとらないので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「針に六のところに来る」は到達先の形にならず、主語が来る文の意味に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「針で来る」は手段の意味になり、針が動いて来る文の形に合わない。"}], "correct_answer": "が", "explanations": {"が": "「針が来た」の主語を示す。来るのは針なので「が」が合う。", "を": "「来る」は目的語をとらないので、「を」は合わない。", "に": "「針に六のところに来る」は到達先の形にならず、主語が来る文の意味に合わない。", "で": "「針で来る」は手段の意味になり、針が動いて来る文の形に合わない。"}, "error_tags": {"を": "目的語", "に": "到達点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36402, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「針が三時をさす」の主語を示す。さすのは針なので「が」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「針を三時をさす」は目的語が二つ重なり、針を主語にする形に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「針に三時をさす」は到達先の形になり、さすのは針だという文意に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「針の三時をさす」は所有の形になり、針が三時をさす意味にならない。"}], "correct_answer": "が", "explanations": {"が": "「針が三時をさす」の主語を示す。さすのは針なので「が」が合う。", "を": "「針を三時をさす」は目的語が二つ重なり、針を主語にする形に合わない。", "に": "「針に三時をさす」は到達先の形になり、さすのは針だという文意に合わない。", "の": "「針の三時をさす」は所有の形になり、針が三時をさす意味にならない。"}, "error_tags": {"を": "目的語", "に": "到達点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36402, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "時計の文字盤の上で、時間をしめす細いもの。", "primary_collocate": null, "pronunciation": "はり", "ipa": "haɾi", "syllable_count": 2, "sentences": [{"text": "時計の針が十二時をさしている。", "target_word": "針", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]が十二時[じゅうにじ]をさしている。", "sentence_source": "generated"}, {"text": "長い針が六のところに来たら、授業が終わる。", "target_word": "針", "complexity_tier": "T3", "furigana": "長[なが]い針[はり]が六[ろく]のところに来[き]たら、授業[じゅぎょう]が終[お]わる。", "sentence_source": "generated"}, {"text": "短い針は時間、長い針は分をしめす。", "target_word": "針", "complexity_tier": "T3", "furigana": "短[みじか]い針[はり]は時間[じかん]、長[なが]い針[はり]は分[ふん]をしめす。", "sentence_source": "generated"}, {"text": "時計の針が止まっていたので、電池を取りかえた。", "target_word": "針", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]が止[と]まっていたので、電池[でんち]を取[と]りかえた。", "sentence_source": "generated"}, {"text": "針の動きをじっと見ていると、時間が長く感じる。", "target_word": "針", "complexity_tier": "T3", "furigana": "針[はり]の動[うご]きをじっと見[み]ていると、時間[じかん]が長[なが]く感[かん]じる。", "sentence_source": "generated"}, {"text": "朝、目が覚めると針は七時を過ぎていた。", "target_word": "針", "complexity_tier": "T3", "furigana": "朝[あさ]、目[め]が覚[さ]めると針[はり]は七時[しちじ]を過[す]ぎていた。", "sentence_source": "generated"}, {"text": "この時計は針が大きくて、遠くからでも見やすい。", "target_word": "針", "complexity_tier": "T3", "furigana": "この時計[とけい]は針[はり]が大[おお]きくて、遠[とお]くからでも見[み]やすい。", "sentence_source": "generated"}, {"text": "針が三時をさすと、おやつの時間になる。", "target_word": "針", "complexity_tier": "T3", "furigana": "針[はり]が三時[さんじ]をさすと、おやつの時間[じかん]になる。", "sentence_source": "generated"}, {"text": "弟は時計の針を指でさして、時間を読んでいた。", "target_word": "針", "complexity_tier": "T3", "furigana": "弟[おとうと]は時計[とけい]の針[はり]を指[ゆび]でさして、時間[じかん]を読[よ]んでいた。", "sentence_source": "generated"}, {"text": "時計が五分遅れていたので、針を手で動かして合わせた。", "target_word": "針", "complexity_tier": "T3", "furigana": "時計[とけい]が五分[ごふん]遅[おく]れていたので、針[はり]を手[て]で動[うご]かして合[あ]わせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "針", "label": "基本形"}, {"form": "針の", "label": "連体形(の)"}, {"form": "針が", "label": "主格(が)"}], "register": "neutral", "sense_fingerprint": "針: 時計の文字盤で時間を示す細い針(はり)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 取りかえ (Zipf 1.48)']::text[], '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36402, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "針", "is_correct": true, "explanation": "「針が十二時をさしている」の主語で、時刻を示す時計の針として合う。"}, {"text": "数字", "is_correct": false, "explanation": "数字は文字盤に書かれたもので、時刻をさす部品ではない。"}, {"text": "日付", "is_correct": false, "explanation": "日付は時計では示さず、時刻をさす主語にならない。"}, {"text": "文字", "is_correct": false, "explanation": "文字は時刻をさすものではなく、この文の主語として意味が通らない。"}], "explanations": {"針": "「針が十二時をさしている」の主語で、時刻を示す時計の針として合う。", "数字": "数字は文字盤に書かれたもので、時刻をさす部品ではない。", "日付": "日付は時計では示さず、時刻をさす主語にならない。", "文字": "文字は時刻をさすものではなく、この文の主語として意味が通らない。"}, "sentence_index": 0, "correct_answer": "針"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時計の針を強く押して、ライトをつけた。", "explanation": "ここは〈ボタン〉の意味。押すのはボタンで、時計の針は押して操作するものではない。"}, {"text": "先生の針に従って、勉強の計画を立てた。", "explanation": "ここは〈指針〉の意味。従うのは指針や手本で、針ではない。"}, {"text": "会社は今年の針を変えることにした。", "explanation": "ここは〈方針〉の意味。変えるのは方針で、針ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36402, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "針", "is_correct": true, "explanation": "「この時計は針が大きくて、遠くからでも見やすい」の主語で、時計の部品として合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は時・分・秒を表す部品ではなく、腕時計の文脈に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は時計の部品ではなく、時・分・秒を表す役割を持たない。"}, {"text": "歯車", "is_correct": false, "explanation": "歯車は動力を伝える部品で、時・分・秒を示す役割は担わない。"}], "explanations": {"針": "「この時計は針が大きくて、遠くからでも見やすい」の主語で、時計の部品として合う。", "窓": "窓は時・分・秒を表す部品ではなく、腕時計の文脈に合わない。", "紙": "紙は時計の部品ではなく、時・分・秒を表す役割を持たない。", "歯車": "歯車は動力を伝える部品で、時・分・秒を示す役割は担わない。"}, "sentence_index": 6, "correct_answer": "針"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は針の上に数字が並んでいて、遠くからでも読みやすい。", "explanation": "ここは〈文字盤〉の意味。数字が並ぶのは文字盤で、針には数字はない。"}, {"text": "船は針を北へ変えて、港へ向かった。", "explanation": "ここは〈針路〉の意味。船の進む道すじは針路で、針だけでは意味が通らない。"}, {"text": "ものさしの針を数えて、長さを測った。", "explanation": "ここは〈目盛り〉の意味。数えるのは目盛りで、ものさしに針はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36402, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "時計の針に九時をさしている。", "corrected_sentence": "時計の針が九時をさしている。", "error_description": "「さす」は主語に「が」をとる。「針に」は誤りで、正しくは「針が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
