INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36403, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「針を動かす」の目的語を示す。動かすのは針なので「を」が合う。"}, {"text": "に", "is_correct": false, "explanation": "「針に動かす」は動作の相手や到達点の形になり、目的語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「針と動かす」は並列の形になり、動かす対象を示さない。"}, {"text": "へ", "is_correct": false, "explanation": "「針へ動かす」は方向の形になり、目的語の役を果たさない。"}], "correct_answer": "を", "explanations": {"を": "「針を動かす」の目的語を示す。動かすのは針なので「を」が合う。", "に": "「針に動かす」は動作の相手や到達点の形になり、目的語を示せない。", "と": "「針と動かす」は並列の形になり、動かす対象を示さない。", "へ": "「針へ動かす」は方向の形になり、目的語の役を果たさない。"}, "error_tags": {"に": "到達点", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36403, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「針の先」の連体修飾で、針が持つ先端を示す。"}, {"text": "を", "is_correct": false, "explanation": "「針を先が曲がっていた」は目的語の形になり、先が曲がるという文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「針に先が曲がっていた」は到達の形になり、先の状態を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「針と先が曲がっていた」は並列になり、針の先の状態を示せない。"}], "correct_answer": "の", "explanations": {"の": "「針の先」の連体修飾で、針が持つ先端を示す。", "を": "「針を先が曲がっていた」は目的語の形になり、先が曲がるという文に合わない。", "に": "「針に先が曲がっていた」は到達の形になり、先の状態を示せない。", "と": "「針と先が曲がっていた」は並列になり、針の先の状態を示せない。"}, "error_tags": {"を": "目的語", "に": "到達点", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36403, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "時計の文字盤上で、時刻を指し示すための細長い部品。", "primary_collocate": null, "pronunciation": "はり", "ipa": "haɾi", "syllable_count": 2, "sentences": [{"text": "時計の針は、中心の軸に取り付けられている。", "target_word": "針", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]は、中心[ちゅうしん]の軸[じく]に取[と]り付[つ]けられている。", "sentence_source": "generated"}, {"text": "針を動かす小さな部品が、時計の中に入っている。", "target_word": "針", "complexity_tier": "T3", "furigana": "針[はり]を動[うご]かす小[ちい]さな部品[ぶひん]が、時計[とけい]の中[なか]に入[はい]っている。", "sentence_source": "generated"}, {"text": "秒を示す針は細くて、かんたんに曲がってしまう。", "target_word": "針", "complexity_tier": "T3", "furigana": "秒[びょう]を示[しめ]す針[はり]は細[ほそ]くて、かんたんに曲[ま]がってしまう。", "sentence_source": "generated"}, {"text": "修理屋は時計の針を外して、文字盤をきれいにした。", "target_word": "針", "complexity_tier": "T3", "furigana": "修理屋[しゅうりや]は時計[とけい]の針[はり]を外[はず]して、文字盤[もじばん]をきれいにした。", "sentence_source": "generated"}, {"text": "針が文字盤にぶつかって、時刻が正しく読めなくなった。", "target_word": "針", "complexity_tier": "T3", "furigana": "針[はり]が文字盤[もじばん]にぶつかって、時刻[じこく]が正[ただ]しく読[よ]めなくなった。", "sentence_source": "generated"}, {"text": "時計の針には光る塗料が塗られ、暗い所でも時刻がわかる。", "target_word": "針", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]には光[ひか]る塗料[とりょう]が塗[ぬ]られ、暗[くら]い所[ところ]でも時刻[じこく]がわかる。", "sentence_source": "generated"}, {"text": "この腕時計は針が三本あり、時・分・秒を表す。", "target_word": "針", "complexity_tier": "T3", "furigana": "この腕時計[うでどけい]は針[はり]が三本[さんぼん]あり、時[じ]・分[ふん]・秒[びょう]を表[あらわ]す。", "sentence_source": "generated"}, {"text": "針の先が曲がっていたので、時刻が正確に読めない。", "target_word": "針", "complexity_tier": "T3", "furigana": "針[はり]の先[さき]が曲[ま]がっていたので、時刻[じこく]が正確[せいかく]に読[よ]めない。", "sentence_source": "generated"}, {"text": "駅の大きな時計は、針の長さが一メートル近くある。", "target_word": "針", "complexity_tier": "T3", "furigana": "駅[えき]の大[おお]きな時計[とけい]は、針[はり]の長[なが]さが一[いち]メートル近[ちか]くある。", "sentence_source": "generated"}, {"text": "時計の針は、電気の力で一定の速さで回る。", "target_word": "針", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]は、電気[でんき]の力[ちから]で一定[いってい]の速[はや]さで回[まわ]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "針", "label": "基本形"}, {"form": "針の", "label": "連体形(の)"}, {"form": "針が", "label": "主格(が)"}], "register": "neutral", "sense_fingerprint": "針: 時計の時刻を指し示す細長い部品(はり)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
