INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36404, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「むしろ」は、前の話と反対のことを言いたいときに使う言葉です。", "primary_collocate": null, "pronunciation": "むしろ", "ipa": "mɯɕiɾo", "syllable_count": 3, "sentences": [{"text": "失敗しても、彼は落ち込むどころか、むしろ笑っていた。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても、彼[かれ]は落[お]ち込[こ]むどころか、むしろ笑[わら]っていた。", "sentence_source": "generated"}, {"text": "運動は疲れるものだと思っていたが、むしろ元気になった。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "運動[うんどう]は疲[つか]れるものだと思[おも]っていたが、むしろ元気[げんき]になった。", "sentence_source": "generated"}, {"text": "雨は嫌いだと思われがちですが、私はむしろ好きです。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "雨[あめ]は嫌[きら]いだと思[おも]われがちですが、私[わたし]はむしろ好[す]きです。", "sentence_source": "generated"}, {"text": "薬を飲んだのに、熱は下がらず、むしろ上がってしまった。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだのに、熱[ねつ]は下[さ]がらず、むしろ上[あ]がってしまった。", "sentence_source": "generated"}, {"text": "彼は私を責めなかった。むしろ、ありがとうと言ってくれた。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]を責[せ]めなかった。むしろ、ありがとうと言[い]ってくれた。", "sentence_source": "generated"}, {"text": "迷惑だなんて思っていません。むしろ、うれしいです。", "target_word": "むしろ", "complexity_tier": "T2", "furigana": "迷惑[めいわく]だなんて思[おも]っていません。むしろ、うれしいです。", "sentence_source": "generated"}, {"text": "忙しいと思ったが、今日はむしろ暇だった。", "target_word": "むしろ", "complexity_tier": "T2", "furigana": "忙[いそが]しいと思[おも]ったが、今日[きょう]はむしろ暇[ひま]だった。", "sentence_source": "generated"}, {"text": "注意されて、彼はやる気をなくすどころか、むしろ燃えていた。", "target_word": "むしろ", "complexity_tier": "T4", "furigana": "注意[ちゅうい]されて、彼[かれ]はやる気[き]をなくすどころか、むしろ燃[も]えていた。", "sentence_source": "generated"}, {"text": "心配しないでください。むしろ、これはいい機会です。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "心配[しんぱい]しないでください。むしろ、これはいい機会[きかい]です。", "sentence_source": "generated"}, {"text": "この店は安いと聞いたが、実際はむしろ高かった。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "この店[みせ]は安[やす]いと聞[き]いたが、実際[じっさい]はむしろ高[たか]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "むしろ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "前の内容や予想と反対の事実を述べる副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36404, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "むしろ", "is_correct": true, "explanation": "『落ち込むどころか、むしろ笑っていた』と予想に反する事実を導く『むしろ』が正しい。"}, {"text": "決して", "is_correct": false, "explanation": "『決して』は後ろに否定の述語が必要な語。『笑っていた』と肯定で結ぶ文には合わない。"}, {"text": "まるで", "is_correct": false, "explanation": "『まるで』は『〜ようだ』の比喩を作る語で、この事実を述べる文には入らない。"}, {"text": "どうして", "is_correct": false, "explanation": "『どうして』は疑問の語で、断定の平叙文には合わない。"}], "explanations": {"むしろ": "『落ち込むどころか、むしろ笑っていた』と予想に反する事実を導く『むしろ』が正しい。", "決して": "『決して』は後ろに否定の述語が必要な語。『笑っていた』と肯定で結ぶ文には合わない。", "まるで": "『まるで』は『〜ようだ』の比喩を作る語で、この事実を述べる文には入らない。", "どうして": "『どうして』は疑問の語で、断定の平叙文には合わない。"}, "sentence_index": 0, "correct_answer": "むしろ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "思ったとおり、むしろ電車は混んでいた。", "explanation": "ここは〈やはり〉の意味。むしろは予想に反する事実を述べる語なので、予想どおりの場面には使えない。"}, {"text": "会議は、むしろ十時ちょうどに始まった。", "explanation": "ここは〈ちょうど〉の意味。むしろは予想に反する事実を述べる語で、時刻がぴったり合うことは示せない。"}, {"text": "いよいよ試合がむしろ始まった。", "explanation": "ここは〈いよいよ〉の意味。むしろは対比の語で、ついにその時が来たという意味は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36404, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "むしろ", "is_correct": true, "explanation": "『忙しいと思ったが、今日はむしろ暇だった』と予想と逆の事実を示す『むしろ』が正しい。"}, {"text": "もし", "is_correct": false, "explanation": "『もし』は条件の語で、『〜たら』『〜ば』が続く必要があり、ここでは文が成立しない。"}, {"text": "いちいち", "is_correct": false, "explanation": "『いちいち』は同じ動作を一つずつ繰り返す意味で、『暇だった』という状態には合わない。"}, {"text": "たとえ", "is_correct": false, "explanation": "『たとえ』は『〜ても』で仮定を表す語で、『暇だった』と言い切る文には続かない。"}], "explanations": {"むしろ": "『忙しいと思ったが、今日はむしろ暇だった』と予想と逆の事実を示す『むしろ』が正しい。", "もし": "『もし』は条件の語で、『〜たら』『〜ば』が続く必要があり、ここでは文が成立しない。", "いちいち": "『いちいち』は同じ動作を一つずつ繰り返す意味で、『暇だった』という状態には合わない。", "たとえ": "『たとえ』は『〜ても』で仮定を表す語で、『暇だった』と言い切る文には続かない。"}, "sentence_index": 6, "correct_answer": "むしろ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卒業式の日が、むしろ来た。", "explanation": "ここは〈いよいよ〉の意味。むしろは対比を示す語で、その時が来たという意味は表せない。"}, {"text": "雨がむしろ止んだ。", "explanation": "ここは〈たちまち〉の意味。むしろは対比を示す語で、すぐに起きた速さは表せない。"}, {"text": "何日も待って、むしろ返事が来た。", "explanation": "ここは〈ようやく〉の意味。むしろは比べて後者を選ぶ語で、長く待った末に来たという意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36404, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降ったのに、彼女はむしろに元気だった。", "corrected_sentence": "雨が降ったのに、彼女はむしろ元気だった。", "error_description": "「むしろ」は副詞なので、後ろに助詞「に」を付けない。正しくは「むしろ元気だった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36404, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宿題は少ないどころか、むしろ少なかった。", "corrected_sentence": "宿題は少ないどころか、むしろ多かった。", "error_description": "正しくは『多かった』。『どころか』は予想との逆を述べる形で、『少ない』と同じ内容を『むしろ』で重ねると対比が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
