INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36405, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「寧ろ」は、二つのことを比べて、後者の方がより適切だと思う気持ちを表す副詞です。", "primary_collocate": null, "pronunciation": "むしろ", "ipa": "mɯɕiɾo", "syllable_count": 3, "sentences": [{"text": "数字を見るより、むしろ現場を歩いて確かめるほうが大切だ。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "数字[すうじ]を見[み]るより、むしろ現場[げんば]を歩[ある]いて確[たし]かめるほうが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "私は夏よりも、むしろ冬のほうが好きです。", "target_word": "むしろ", "complexity_tier": "T2", "furigana": "私[わたし]は夏[なつ]よりも、むしろ冬[ふゆ]のほうが好[す]きです。", "sentence_source": "generated"}, {"text": "この仕事は難しいというより、むしろ時間がかかるだけです。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "この仕事[しごと]は難[むずか]しいというより、むしろ時間[じかん]がかかるだけです。", "sentence_source": "generated"}, {"text": "彼は怒っているのではなく、むしろ悲しんでいるのだと思います。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[おこ]っているのではなく、むしろ悲[かな]しんでいるのだと思[おも]います。", "sentence_source": "generated"}, {"text": "高い服を買うくらいなら、むしろ貯金したほうがいい。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "高[たか]い服[ふく]を買[か]うくらいなら、むしろ貯金[ちょきん]したほうがいい。", "sentence_source": "generated"}, {"text": "雨の日は、出かけるよりむしろ家で本を読みたい。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、出[で]かけるよりむしろ家[いえ]で本[ほん]を読[よ]みたい。", "sentence_source": "generated"}, {"text": "彼女は有名というより、むしろ地元で愛されている人だ。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は有名[ゆうめい]というより、むしろ地元[じもと]で愛[あい]されている人[ひと]だ。", "sentence_source": "generated"}, {"text": "無理に説明するより、むしろ黙っているほうが誠実だと思う。", "target_word": "むしろ", "complexity_tier": "T4", "furigana": "無理[むり]に説明[せつめい]するより、むしろ黙[だま]っているほうが誠実[せいじつ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "彼の意見は間違いではなく、むしろ正しいくらいだ。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は間違[まちが]いではなく、むしろ正[ただ]しいくらいだ。", "sentence_source": "generated"}, {"text": "車で行くより、むしろ電車のほうが早く着きます。", "target_word": "むしろ", "complexity_tier": "T3", "furigana": "車[くるま]で行[い]くより、むしろ電車[でんしゃ]のほうが早[はや]く着[つ]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "むしろ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "二つを比べて後者の方が適切だと述べる副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36405, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "むしろ", "is_correct": true, "explanation": "『AよりむしろB』の形で、後者を選ぶ『むしろ』が入る。"}, {"text": "決して", "is_correct": false, "explanation": "『決して』は後ろに否定の述語が必要な語。『大切だ』と肯定で結ぶ文には合わない。"}, {"text": "まるで", "is_correct": false, "explanation": "『まるで』は『〜ようだ』の比喩を作る語で、比べて選ぶ文には入らない。"}, {"text": "どうして", "is_correct": false, "explanation": "『どうして』は疑問を表す語で、断定の平叙文には合わない。"}], "explanations": {"むしろ": "『AよりむしろB』の形で、後者を選ぶ『むしろ』が入る。", "決して": "『決して』は後ろに否定の述語が必要な語。『大切だ』と肯定で結ぶ文には合わない。", "まるで": "『まるで』は『〜ようだ』の比喩を作る語で、比べて選ぶ文には入らない。", "どうして": "『どうして』は疑問を表す語で、断定の平叙文には合わない。"}, "sentence_index": 0, "correct_answer": "むしろ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "何時間も待って、むしろバスが来た。", "explanation": "ここは〈ようやく〉の意味。むしろは二つを比べて後者を選ぶ語で、長く待ってやっと来たという安堵は表せない。"}, {"text": "会議は、むしろ十時ちょうどに始まった。", "explanation": "ここは〈ちょうど〉の意味。むしろは比べて選ぶ語で、時刻がぴったり合うことは示せない。"}, {"text": "縁側に、むしろを広げて昼寝した。", "explanation": "ここは〈筵（むしろ）〉の意味。寧ろは副詞で、敷物の名詞としては使えないので、この文脈では意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36405, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "むしろ", "is_correct": true, "explanation": "『AというよりむしろB』の形で、Bを選ぶ『むしろ』が正しい。"}, {"text": "いちいち", "is_correct": false, "explanation": "『いちいち』は同じ動作を一つずつ繰り返す意味で、『愛されている人だ』という状態には合わない。"}, {"text": "たとえ", "is_correct": false, "explanation": "『たとえ』は『〜ても』で仮定を表す語で、この断定文には続かない。"}, {"text": "さっさと", "is_correct": false, "explanation": "『さっさと』は素早く行う動作を表す語で、状態を示す『愛されている』とは合わない。"}], "explanations": {"むしろ": "『AというよりむしろB』の形で、Bを選ぶ『むしろ』が正しい。", "いちいち": "『いちいち』は同じ動作を一つずつ繰り返す意味で、『愛されている人だ』という状態には合わない。", "たとえ": "『たとえ』は『〜ても』で仮定を表す語で、この断定文には続かない。", "さっさと": "『さっさと』は素早く行う動作を表す語で、状態を示す『愛されている』とは合わない。"}, "sentence_index": 6, "correct_answer": "むしろ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財布には、むしろ一円しか残っていない。", "explanation": "ここは〈たった〉の意味。むしろは比べて後者を選ぶ語で、わずかしかないことを強調する働きはない。"}, {"text": "試合の日が、むしろ来た。", "explanation": "ここは〈いよいよ〉の意味。むしろは比べて選ぶ語で、待っていた時が来たという意味は表せない。"}, {"text": "長い時間がたち、むしろ雨がやんだ。", "explanation": "ここは〈やがて〉の意味。むしろは比べて選ぶ語で、時間の経過で自然に起きたことは示せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36405, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は泣いたのではなく、むしろに笑っていた。", "corrected_sentence": "彼女は泣いたのではなく、むしろ笑っていた。", "error_description": "正しくは『むしろ笑っていた』。副詞の『むしろ』に助詞『に』は付かないので、『むしろに』は文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36405, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの映画は面白いというより、むしろに考えさせられる。", "corrected_sentence": "あの映画は面白いというより、むしろ考えさせられる。", "error_description": "副詞の『むしろ』に助詞『に』は付かない。正しくは『むしろ考えさせられる』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36406, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「解釈を深めた」で、深める対象を示す「を」。文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「解釈に深めた」は対象を示せず、「深める」と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「解釈へ深めた」は方向を示すが、解釈は深める先にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「解釈と深めた」は並列や引用の意味になり、深める対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「解釈を深めた」で、深める対象を示す「を」。文に合う。", "に": "「解釈に深めた」は対象を示せず、「深める」と結びつかない。", "へ": "「解釈へ深めた」は方向を示すが、解釈は深める先にならず不自然。", "と": "「解釈と深めた」は並列や引用の意味になり、深める対象を示せない。"}, "error_tags": {"を": "対象", "に": "相手", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36406, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「解釈ができる」で、可能の文の主語を示す「が」。文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「解釈をできる」は「できる」の主語を表せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「解釈にできる」は場所や対象を示すが、可能の文の主語としては不自然。"}, {"text": "と", "is_correct": false, "explanation": "「解釈とできる」は並列の意味になり、可能の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「解釈ができる」で、可能の文の主語を示す「が」。文に合う。", "を": "「解釈をできる」は「できる」の主語を表せず、文が成り立たない。", "に": "「解釈にできる」は場所や対象を示すが、可能の文の主語としては不自然。", "と": "「解釈とできる」は並列の意味になり、可能の主語を示せない。"}, "error_tags": {"が": "主語", "を": "対象", "に": "位置", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36406, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事について、人がとらえた意味や考え方。", "primary_collocate": null, "pronunciation": "かいしゃく", "ipa": "kaiɕaku", "syllable_count": 4, "sentences": [{"text": "この詩は、読む人によって解釈が違う。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "この詩[し]は、読[よ]む人[ひと]によって解釈[かいしゃく]が違[ちが]う。", "sentence_source": "generated"}, {"text": "彼は、その言葉の解釈を深めた。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "彼[かれ]は、その言葉[ことば]の解釈[かいしゃく]を深[ふか]めた。", "sentence_source": "generated"}, {"text": "彼の言葉を、私は別の解釈で受け取った。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]を、私[わたし]は別[べつ]の解釈[かいしゃく]で受[う]け取[と]った。", "sentence_source": "generated"}, {"text": "夢の解釈は、本によってさまざまだ。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "夢[ゆめ]の解釈[かいしゃく]は、本[ほん]によってさまざまだ。", "sentence_source": "generated"}, {"text": "事実は一つだが、解釈は人の数だけある。", "target_word": "解釈", "complexity_tier": "T4", "furigana": "事実[じじつ]は一[ひと]つだが、解釈[かいしゃく]は人[ひと]の数[かず]だけある。", "sentence_source": "generated"}, {"text": "その絵は、見る人の解釈にまかされている。", "target_word": "解釈", "complexity_tier": "T4", "furigana": "その絵[え]は、見[み]る人[ひと]の解釈[かいしゃく]にまかされている。", "sentence_source": "generated"}, {"text": "友だちと解釈が違って、議論になった。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "友[とも]だちと解釈[かいしゃく]が違[ちが]って、議論[ぎろん]になった。", "sentence_source": "generated"}, {"text": "物語の結末は、いろいろな解釈ができる。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "物語[ものがたり]の結末[けつまつ]は、いろいろな解釈[かいしゃく]ができる。", "sentence_source": "generated"}, {"text": "彼は規則を自分に都合よく解釈する。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "彼[かれ]は規則[きそく]を自分[じぶん]に都合[つごう]よく解釈[かいしゃく]する。", "sentence_source": "generated"}, {"text": "昔の文章は、解釈が難しい。", "target_word": "解釈", "complexity_tier": "T2", "furigana": "昔[むかし]の文章[ぶんしょう]は、解釈[かいしゃく]が難[むずか]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解釈", "label": "基本形"}, {"form": "解釈する", "label": "辞書形(する動詞)"}, {"form": "解釈した", "label": "過去形"}, {"form": "解釈できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "物事や言葉・作品について、人がとらえた意味や考え(受け取り方としての解釈)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: まかさ (Zipf 2.37)']::text[], '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36406, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解釈", "is_correct": true, "explanation": "「解釈が違う」は、読む人によって受け取り方が異なるという意味になり、文に合う。"}, {"text": "時刻", "is_correct": false, "explanation": "「時刻が違う」は時間のずれを表し、詩の読み方について述べる文脈に合わない。"}, {"text": "材質", "is_correct": false, "explanation": "「材質が違う」は物の素材を表し、詩を読む話題とは関係がない。"}, {"text": "身長", "is_correct": false, "explanation": "「身長が違う」は人の体の長さを表し、詩の読まれ方とは結びつかない。"}], "explanations": {"解釈": "「解釈が違う」は、読む人によって受け取り方が異なるという意味になり、文に合う。", "時刻": "「時刻が違う」は時間のずれを表し、詩の読み方について述べる文脈に合わない。", "材質": "「材質が違う」は物の素材を表し、詩を読む話題とは関係がない。", "身長": "「身長が違う」は人の体の長さを表し、詩の読まれ方とは結びつかない。"}, "sentence_index": 0, "correct_answer": "解釈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壊れた椅子を解釈して直した。", "explanation": "ここは〈修理する〉の意味。解釈は物事の意味を受け取ることで、物を直す場面では使わない。"}, {"text": "ろうそくを解釈して、火をつけた。", "explanation": "ここは〈点火〉の意味。解釈は内容の意味を説明することで、火を灯す動作には使わない。"}, {"text": "母は、冷蔵庫を解釈して、毎週点検した。", "explanation": "ここは〈点検〉の意味。解釈は意味を説明することで、機械の状態を調べる点検とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36406, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解釈", "is_correct": true, "explanation": "「解釈が違って、議論になった」は、意味の受け取り方の違いが争いになる意味で、文に合う。"}, {"text": "身長", "is_correct": false, "explanation": "「身長が違って、議論になった」は体の違いを表し、友だちとの話し合いの流れとは合わない。"}, {"text": "残高", "is_correct": false, "explanation": "「残高が違って、議論になった」は金銭の数字の話になり、文脈が変わってしまう。"}, {"text": "体温", "is_correct": false, "explanation": "「体温が違って、議論になった」は意味が通らず、議論の原因としても成り立たない。"}], "explanations": {"解釈": "「解釈が違って、議論になった」は、意味の受け取り方の違いが争いになる意味で、文に合う。", "身長": "「身長が違って、議論になった」は体の違いを表し、友だちとの話し合いの流れとは合わない。", "残高": "「残高が違って、議論になった」は金銭の数字の話になり、文脈が変わってしまう。", "体温": "「体温が違って、議論になった」は意味が通らず、議論の原因としても成り立たない。"}, "sentence_index": 6, "correct_answer": "解釈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は汚れた白いシャツを解釈して、庭に干した。", "explanation": "ここは〈洗濯〉の意味。解釈は意味を説明することで、衣類を洗う作業には使わない。"}, {"text": "夕食の解釈が遅れた。", "explanation": "ここは〈準備〉の意味。解釈は意味を考えることで、食事の支度には使わない。"}, {"text": "庭の草の解釈が大変だ。", "explanation": "ここは〈草取り〉の意味。解釈は物事の意味を考えることで、草を抜く作業とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36406, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その歌は、聴く人によって解釈を違う。", "corrected_sentence": "その歌は、聴く人によって解釈が違う。", "error_description": "「違う」は主語に「が」を取るので、「解釈を」は誤り。正しくは「解釈が違う」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36406, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は昔の手紙の意味を解釈た、私に読んで聞かせた。", "corrected_sentence": "祖母は昔の手紙の意味を解釈して、私に読んで聞かせた。", "error_description": "「解釈する」の動詞の形は「解釈して」。「解釈た」はする動詞の活用として誤りで、正しくは「解釈して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
